        }
        local function runCmd(t)
                local cmd, rest = t:match("^%?(%w+)%s*(.*)$")
                cmd = string.lower(tostring(cmd or ""))
                if cmd == "help" then cmd = "cmds" end
                local e = CMDS[cmd]
                if not e then notifyLocal("Staff", "Unknown command - type  ?cmds") return end
                local ok, res = pcall(e[3], rest or "")
                notifyLocal("Staff", ok and tostring(res or "Done.") or "That command hit an error.")
        end
        local lastSend = 0
        local function doSend()
                local txt = tostring(box.Text or ""):gsub("^%s+",""):gsub("%s+$","")
                if txt == "" then return end
                if IS_MOD and txt:sub(1,1) == "?" then box.Text = "" runCmd(txt) return end
                local myLow = string.lower(me.Name)
                local mts = tonumber(MODSTATE.mu[myLow] or MODSTATE.mu[string.lower(me.DisplayName or "")] or 0) or 0
                if mts > os.time() then box.Text = "" notifyLocal("Live Chat","You are muted by staff for another "..math.ceil((mts-os.time())/60).." min.") return end
                if #txt > 120 then txt = string.sub(txt,1,120) end
                if not IS_MOD and (tonumber(MODSTATE.lk) or 0) == 1 then box.Text = "" notifyLocal("Live Chat","Chat is locked by staff right now.") return end
                if (tonumber(MODSTATE.ne[myLow] or 0) or 0) <= os.time() then txt = emojify(txt) end
                local cool = IS_MOD and 2 or math.max(2, tonumber(MODSTATE.sl) or 0)
                if tick()-lastSend < cool then notifyLocal("Live Chat","Slow down a little"..(cool > 2 and ("  (slowmode "..cool.."s)") or "")..".") return end
                lastSend = tick()
                local rule = scanText(txt)
                if rule then
                        box.Text = ""
                        notifyLocal("AI Mod","Message blocked ("..rule..") and reported to staff.")
                        reportMsg(me.Name, me.UserId, txt, rule, "blocked before send")
                        return
                end
                box.Text = ""
                local c = readKey(KEY) or {}
                c[#c+1] = { u=me.Name, id=me.UserId, t=TIER, g=GAME, m=txt, ts=os.time(), md=IS_MOD and 1 or nil }
                while #c > 20 do table.remove(c,1) end
                cache = c; writeKey(KEY, c); render()
        end
        send.MouseButton1Click:Connect(doSend)
        box.FocusLost:Connect(function(enter) if enter then doSend() end end)

        -- ---- warn delivery (relay -> popup notification, NOT chat) ----
        _G.__DreamWarnSend = function(target, msg, kind)
                local w = readKey(WKEY) or {}
                w[#w+1] = { to=tostring(target), m=tostring(msg), by=me.Name, ts=os.time(), k=kind }
                while #w > 10 do table.remove(w,1) end
                writeKey(WKEY, w)
                if kind == nil or kind == "w" then   -- real warnings land in the tracker
                        local l = readKey(LKEY) or {}
                        l[#l+1] = { to=tostring(target), m=tostring(msg), by=me.Name, ts=os.time() }
                        while #l > 40 do table.remove(l,1) end
                        writeKey(LKEY, l)
                end
                return true
        end
        local boot = os.time()
        local shownW = {}
        local function handleWarn(x)
                if type(x) ~= "table" then return end
                local id = tostring(x.ts or 0)..string.lower(tostring(x.to or ""))..tostring(x.k or "w")
                if shownW[id] then return end
                shownW[id] = true
                local tgt = string.lower(tostring(x.to or ""))
                if tgt ~= "*" and tgt ~= string.lower(me.Name) then return end
                if (tonumber(x.ts) or 0) < boot - 60 then return end  -- ignore anything from before this session
                local kind = tostring(x.k or "w")
                local head1, cAcc, cBg, nTitle
                if kind == "a" then head1="ANNOUNCEMENT  ("..tostring(x.by or "staff")..")" cAcc=Color3.fromRGB(90,160,255) cBg=Color3.fromRGB(14,20,32) nTitle="ANNOUNCEMENT"
                elseif kind == "d" then head1="DM FROM STAFF  ("..tostring(x.by or "?")..")" cAcc=Color3.fromRGB(180,150,255) cBg=Color3.fromRGB(22,18,34) nTitle="Staff DM"
                elseif kind == "n" then notifyLocal("Message from staff", tostring(x.m)) return
                else head1="WARNING FROM STAFF  ("..tostring(x.by or "?")..")" cAcc=Color3.fromRGB(255,80,80) cBg=Color3.fromRGB(30,16,18) nTitle="ADMIN WARNING" end
                notifyLocal(nTitle, tostring(x.m))
                pcall(function()
                        local card = Instance.new("Frame")
                        card.Size = UDim2.new(0,380,0,110); card.Position = UDim2.new(0.5,-190,0.22,0)
                        card.BackgroundColor3 = cBg; card.Parent = gui
                        local c=Instance.new("UICorner") c.CornerRadius=UDim.new(0,12) c.Parent=card
                        local st=Instance.new("UIStroke") st.Color=cAcc st.Thickness=2 st.Parent=card
                        local t1=Instance.new("TextLabel") t1.Size=UDim2.new(1,-20,0,30) t1.Position=UDim2.new(0,10,0,10)
                        t1.BackgroundTransparency=1 t1.Font=Enum.Font.GothamBold t1.TextSize=16
                        t1.TextColor3=cAcc t1.Text=head1 t1.Parent=card
                        local t2=Instance.new("TextLabel") t2.Size=UDim2.new(1,-20,0,56) t2.Position=UDim2.new(0,10,0,44)
                        t2.BackgroundTransparency=1 t2.Font=Enum.Font.Gotham t2.TextSize=13 t2.TextWrapped=true
                        t2.TextColor3=Color3.fromRGB(235,220,222) t2.Text=tostring(x.m) t2.Parent=card
                        task.delay(7, function() pcall(function() card:Destroy() end) end)
                end)
        end

        -- ---- poll loop ----
        local lastJson = ""
        local reported = {}
        while true do
                task.wait(4)
                if not gui.Parent then break end
                local w = readKey(WKEY)
                if w then for _,x in ipairs(w) do handleWarn(x) end end
                local ms = readKey(MKEY)
                if type(ms) == "table" then
                        MODSTATE.mu = (type(ms.mu)=="table" and ms.mu) or {}
                        MODSTATE.ne = (type(ms.ne)=="table" and ms.ne) or {}
                        MODSTATE.sl = tonumber(ms.sl) or 0
                        MODSTATE.lk = tonumber(ms.lk) or 0
                        MODSTATE.bw = (type(ms.bw)=="table" and ms.bw) or {}
                        MODSTATE.tt = (type(ms.tt)=="table" and ms.tt) or {}
                        pcall(function() _G.__DreamTitleOv = MODSTATE.tt end)
                end
                local myL = string.lower(me.Name)
                local mts2 = tonumber(MODSTATE.mu[myL] or 0) or 0
                if mts2 > os.time() and mts2 ~= lastMuteNotif then lastMuteNotif = mts2 notifyLocal("Live Chat","A staff member muted you for "..math.ceil((mts2-os.time())/60).." min.") end
                local c = readKey(KEY)
                if c then
                        local j = ""
                        pcall(function() j = HttpService:JSONEncode(c) end)
                        if j ~= lastJson then
                                lastJson = j
                                cache = c
                                if win.Visible then render() else btn.Text = "CHAT  •" end
                                -- mods auto-report NEW flagged messages that slipped into the feed
                                if IS_MOD then
                                        for _,m in ipairs(c) do
                                                if type(m)=="table" and (tonumber(m.ts) or 0) >= boot then
                                                        local rid = tostring(m.ts or 0)..tostring(m.u or "")
                                                        if not reported[rid] then
                                                                local rule = scanText(m.m)
                                                                if rule then reported[rid]=true reportMsg(m.u, m.id, m.m, rule, "seen in feed") end
                                                        end
                                                end
                                        end
                                end
                        end
                end
        end
end)
-- ═══ END LIVE CHAT ═══



_G.VX_HUB_READY = false

-- ═══════════════════ RESET EVERY STICKY FLAG THIS RUN INHERITS ═══════════════════
-- _G SURVIVES BETWEEN EXECUTIONS. Timestamps are self-healing (an old tick is simply in the past), but the
-- BOOLEANS are not - they stay exactly as the previous run left them, forever.
--
-- This is why "nothing black flashes any more, not even M1 BF". A dash chain sets _G.VX_BF_BORROWED = true and
-- only clears it from a task.delay 0.55s later. Re-execute the hub inside that window - or have the previous
-- run replaced while a chain was in flight - and the flag arrives at the new run stuck TRUE with
-- VX_BF_BORROW_USED already spent. The engine's first two lines then read:
--     if _G.VX_BF_BORROWED then if (_G.VX_BF_BORROW_USED or 0) > 0 then return end ... end
-- so EVERY animation returns immediately and no windup is ever seen again, on any mode, for the rest of the
-- session. Nothing in the file reset it: vxbfStop clears it, but only when you actively switch a mode off.
-- Seed the lot at load so a fresh execution is always a fresh state. Cheap, and it closes a whole bug class.
_G.VX_BF_BORROWED   = false
_G.VX_BF_BORROW_USED = 0
_G.VX_BF_CHAINCLICK = 0
_G.VX_BF_TRIG3      = 0       -- chain-trigger press stamp; never inherit one from a previous run
_G.VX_BF_DASHANIM   = 0
_G.VX_BFAPI_ON      = false   -- the engine re-arms itself from the GUI toggles a moment later
_G.VX_M1BF_ON       = false
_G.VX_SYNTH_CLICK   = 0       -- a stale "this click was ours" mark suppresses your real clicks
_G.VX_HOOK_COUNT    = 0       -- combo position the finisher rewrite counts from
_G.VX_HOOK_LASTCLICK = 0
_G.VX_AIR_HOOK      = false   -- auto-air rewrite; a stale true would air-cast every move on a fresh run
_G.VX_SLAM_FLAG     = false   -- mirrors of the finisher toggles, read by the M1 rewrite hook. MUST be seeded:
_G.VX_UPPER_FLAG    = false   -- a stale true here would rewrite every M1 into a finisher on a fresh run.
_G.VX_INJ_KEYS      = {}      -- same, for keys
_G.VX_FINISHER_T    = 0
_G.VX_UPPER_T       = 0       -- last uppercut; the Cursed Strike assist arms off this and only this
_G.VX_DOWN_T        = 0       -- last down slam (same __namecall observer stamps it); Todo Drop uses it
_G.VX_SIDEASSIST_ON = false   -- read by the Dash-rewrite hook; sticky true would hijack every dash on a fresh run
_G.VX_BF_CHAINDRIVE = 0
_G.VX_CHAINFLASH_WINDOW = 0   -- the chain-flash listener only presses inside this window
_G.VX_BF_PRESS_T    = 0       -- last flash press; the air-hook and Auto Cancel keep their hands off its cast
-- ═══ CHAIN TRACER ═══ Every stage of a Black Flash chain records itself here, and 1.6s after the chain
-- starts the whole trace is printed AND copied to the clipboard as one line. "still no black flash" has
-- survived six fixes because every diagnosis was reasoned instead of observed - this makes the next report
-- observational: the trace names the first stage that never happened.
_G.VX_BF_TRACE = {};_G.VX_TRACE_T0=nil
_G.VX_TRACE = function(tag)
        local trace=_G.VX_BF_TRACE
        if type(trace)~="table" or not _G.VX_TRACE_T0 then return end
        if #trace>=40 then return end
        trace[#trace+1]=string.format("%s@%.3f",tostring(tag):sub(1,140),tick()-_G.VX_TRACE_T0)
end
_G.VX_TRACE_BEGIN = function(mode)
        _G.VX_TRACE_T0=tick();_G.VX_BF_TRACE={"chain["..tostring(mode).."]"}
end
_G.VX_SLOT_MOVE     = {}      -- learned key->move map; stale entries from the LAST character would cast their moves
_G.VX_MOVE_RE       = _G.VX_MOVE_RE or {}   -- learned move->remote map (instances die with the rig on their own)
_G.VX_TOTAL_MOVE_T  = 0
_G.VX_LAUNCHING     = 0
_G.VX_CROW_FLYING   = 0
-- WATCHDOG for the same flag WITHIN a run. A borrow is meant to last ~0.55s and is handed back from a
-- task.delay; if that callback is ever lost (an error on the way to it, a respawn, the mode switched
-- mid-chain) the engine goes deaf for the rest of the session with every toggle still reading "on". Nothing
-- legitimately holds a borrow for 2s, so anything older than that is a leak and gets released.
task.spawn(function()
        while true do
                task.wait(0.5)
                if _G.VX_BF_BORROWED and tick() - (tonumber(_G.VX_BF_BORROW_T) or 0) > 2.0 then
                        _G.VX_BF_BORROWED = false; _G.VX_BF_BORROW_USED = 0
                        if _G.VX_BFAPI_SET then pcall(function() _G.VX_BFAPI_SET(_G.VX_BFAPI_WANT == true) end) end
                        if _G.VX_BF_DEBUG then print("[BF] borrow leaked - released by the watchdog") end
                end
        end
end)

-- (Removed the duplicate VX_DreamCircle button — the GUI's own logo toggle button, which uses the Dream logo
--  image LOGO_ID = 82151574125055, is the single one now.)

-- ===================== SHARED STATE (the GUI flips these; the modules read them) =====================
-- (BlockFlags is gone. Auto Block was rebuilt from scratch further down the file and is driven by one
--  toggle through AutoBlockApi; there is nothing left to share through a flag table.)
local BFApi    -- forward-declared: Auto Black Flash control API (assigned in its module below)
local ChainApi -- forward-declared: BF Chain control API (assigned in its module below)

-- ============================================================
-- One streamed humanoid index serves players and nested training dummies alike.
do
    local indexed=setmetatable({}, {__mode="k"})
    local function add(obj)
        if obj:IsA("Humanoid") and obj.Parent and obj.Parent:IsA("Model") then indexed[obj.Parent]=obj end
    end
    for _,obj in ipairs(workspace:GetDescendants()) do add(obj) end
    workspace.DescendantAdded:Connect(add)
    workspace.DescendantRemoving:Connect(function(obj) if obj:IsA("Humanoid") then indexed[obj.Parent]=nil end end)
    _G.VX_LIVING_MODELS=function()
        local out={}
        for model,h in pairs(indexed) do
            if model.Parent and model:IsDescendantOf(workspace) and h.Parent==model and h.Health>0 and model:FindFirstChild("HumanoidRootPart") then out[#out+1]=model end
        end
        return out
    end
end

-- MODULE: AUTO BLACK FLASH -- one follow-up per observed windup.
do
    local previous=_G.VXBF2
    if previous then
        for _,name in ipairs({"setEnabled","setSideAssist","setBackAssist"}) do
            if previous[name] then pcall(previous[name],false) end
        end
    end
    if _G.VX_BFAPI_DESTROY then pcall(_G.VX_BFAPI_DESTROY)
    elseif _G.VX_BFAPI_SET then pcall(_G.VX_BFAPI_SET,false) end
    local engineLive=true
    local player=game:GetService("Players").LocalPlayer
    local VIM=game:GetService("VirtualInputManager")
    local UIS=game:GetService("UserInputService")
    -- ═══ r14: THE BEATS ARE THE USER'S OWN PROVEN NUMBERS ═══ The engine had 0.34-0.36s on these five
    -- windup ids; the user's uploaded Autoblackflash.lua (their working auto-BF) presses at 0.19-0.20s on the
    -- SAME ids. Every timed follow-up was therefore landing ~0.15s PAST the conversion window - the game took
    -- the press as a fresh Divergent Fist (Side Dash / Back Dash / M1 chains "still does divergent fist") or
    -- nothing landed at all ("sometimes the black flash just doesn't work", worse on a laggy machine).
    -- Values are now byte-for-byte the user's script: 0.19, and 0.20 on 72475960800126.
    local triggers={ ["100962226150441"]=0.19,["95852624447551"]=0.19,
        ["74145636023952"]=0.19,["72475960800126"]=0.20,["123171106092050"]=0.19 }
    -- the real Q-dash animation tails (used by the re-arm quiet test so a re-press can never land into a
    -- live dash and cancel it = the "dash a slight bit then snap back" rubber-band)
    local DASH_TAILS={ ["75203303352791"]=true,["117223862448096"]=true,["110978068388232"]=true }
    local enabled,offset,cooldown=false,0,0.45
    local generation,pending,chain=0,nil,nil
    local count,lastSwing,lastFire=0,-math.huge,-math.huge
    local hooked=setmetatable({}, {__mode="k"})
    local seen=setmetatable({}, {__mode="k"})
    local hookAll
    local function rig()
        local folder=workspace:FindFirstChild("Characters")
        return (folder and folder:FindFirstChild(player.Name)) or player.Character
    end
    local function live(body)
        local h=body and body:FindFirstChildOfClass("Humanoid")
        return engineLive and body==rig() and h and h.Health>0 and not UIS:GetFocusedTextBox()
    end
    local function nearEnemy()
        local c=rig(); local r=c and c:FindFirstChild("HumanoidRootPart")
        if not r then return false end
        for _,m in ipairs(_G.VX_LIVING_MODELS()) do
            local er=m:FindFirstChild("HumanoidRootPart")
            if m~=c and m.Name~=player.Name and er and (er.Position-r.Position).Magnitude<=math.clamp(tonumber(_G.VX_BF_RANGE) or 9,1,20) then return true end
        end
        return false
    end
    local function cancel()
        generation+=1; pending=nil; if chain and chain.sent==nil then chain.sent=false end; chain=nil; count=0
        _G.VX_BF_BORROWED=false; _G.VX_BF_CHAINDRIVE=0
    end
    local function press()
        local key=Enum.KeyCode.Three
        if UIS:GetFocusedTextBox() or _G.VX_KEY_BLOCKED and _G.VX_KEY_BLOCKED(key) then return false end
        _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[key]=tick()+0.25
        _G.VX_BF_PRESS_T=tick()
        local ok=pcall(function()
            VIM:SendKeyEvent(false,key,false,game)
            VIM:SendKeyEvent(true,key,false,game); task.wait(0.045)
        end)
        pcall(function() VIM:SendKeyEvent(false,key,false,game) end)
        return ok
    end
    local function onAnim(track,fromEvent)
        local now=tick(); local request=chain and now<=chain.expires and chain or nil
        if request and request.existing and request.existing[track] then
            local prior=request.existing[track]
            local phase=tonumber(track.TimePosition) or 0
            local restarted=request.started and (phase+0.03<prior.phase or prior.stopped and track.IsPlaying)
            prior.phase=phase;prior.stopped=not track.IsPlaying
            if not fromEvent and not restarted then return end
            request.existing[track]=nil;seen[track]=nil
        end
        if not enabled and not request then return end
        if seen[track] and now-seen[track]<0.12 or not live(rig()) then return end
        if now<(tonumber(_G.VX_COMBAT_SUPPRESS_BF) or 0) or now<(tonumber(_G.VX_BF_DASHANIM) or 0) then return end
        local id=tostring(track.Animation and track.Animation.AnimationId or ""):match("%d+")
        local beat=id and triggers[id]
        if pending then
            if beat and pending.kind=="m1" then pending=nil else return end
        end
        if not beat then
            if request or not enabled or not (_G.VX_M1_IDS and _G.VX_M1_IDS[id]) then return end
            if now-(tonumber(_G.VX_LAST_HUMAN_CLICK) or 0)>0.5 or not nearEnemy() or now-lastSwing<0.12 then return end
            if now-lastSwing>1.2 then count=0 end
            lastSwing=now; count+=1
            if count<1 then return end
            count=0
            if now-lastFire<cooldown or _G.VX_BF_PRESSKEY=="Never" then return end
            local ticket={generation=generation,body=rig(),kind="m1"}; pending=ticket
            task.delay(0.28,function()
                if pending~=ticket then return end
                pending=nil
                -- ═══ r15: A LIVE CHAIN OWNS THE ENGINE - OUR DELAYED ARM MUST NOT STEAL IT ═══ "on the second
                -- time it does divergent fist." The click that armed this task often happened just before you
                -- triggered the chain; at +0.28s this fired MID-CAST: ArmChain() replaced the running request
                -- (generation+1, chain=new token), the conversion press already scheduled for the old request
                -- saw chain~=request and refused to send, and the windup completed untouched - a plain
                -- Divergent Fist, almost always on the SECOND chain (right after a flash, while you are still
                -- clicking). If a chain is armed or casting now, this swing's auto-flash simply does not
                -- happen - the conversion already in flight wins.
                if chain then return end
                if ticket.generation~=generation or not enabled or not live(ticket.body) or not nearEnemy() then return end
                if tick()<(tonumber(_G.VX_COMBAT_SUPPRESS_BF) or 0) then return end
                local token=BFApi.ArmChain(); BFApi.StartChain(token)
            end)
            return
        end
        if _G.VX_BF_PRESSKEY=="Never" or not request and now-lastFire<cooldown then return end
        if request and (not request.started or request.used) then return end
        -- ═══ r15: A LATE-SEEN WINDUP STILL GETS ITS PRESS ═══ the old +0.12s grace refused to press when the
        -- track was observed a few frames late (reused cached tracks, missed events) - and a REFUSED press is
        -- a guaranteed plain Divergent Fist while a late press can still land inside the game's window. The
        -- grace is now tripled; beyond it the press genuinely cannot convert anything.
        if (tonumber(track.TimePosition) or 0)>beat+offset+0.30 then return end
        seen[track]=now
        local ticket={generation=generation,body=rig(),request=request,hardExpires=now+3}; pending=ticket
        if request then
            request.observed=true
            if _G.VX_TRACE then _G.VX_TRACE("windup:"..tostring(id)..":phase="..string.format("%.3f",tonumber(track.TimePosition) or 0)..":speed="..string.format("%.2f",tonumber(track.Speed) or 1)..(fromEvent and ":event" or ":poll")) end
        end
        local speed=tonumber(track.Speed) or 1
        local phase=tonumber(track.TimePosition) or 0
        -- The supplied AutoBlackFlash.lua waits a fixed time after AnimationPlayed.
        -- Try that method only for the reported chain modes and actual events; a track
        -- first seen by polling still needs phase-based timing. Teleport stays unchanged.
        local refMode=request and fromEvent and (request.mode=="Back Dash" or request.mode=="Side Dash"
            or request.mode=="Jump" or request.mode=="M1") and (request.mode=="Back Dash" or _G.VX_BF_CHAIN_TIMING~="Phase")
        local fixedDue=refMode and now+math.max(0,beat+offset) or nil
        local dueAt=fixedDue or now+math.max(0,(beat-phase)/math.max(speed,0.05)+offset)
        if request then request.expires=math.max(request.expires,math.min(request.hardExpires,dueAt+0.15)) end
        task.spawn(function()
            while pending==ticket do
                if not live(ticket.body) or tick()>ticket.hardExpires or request and tick()>request.expires then break end
                if not track.IsPlaying then break end
                -- Animation speed can change or pause after AnimationPlayed. Re-read its actual phase.
                local currentSpeed=tonumber(track.Speed) or 1
                if currentSpeed>0 then
                    local remaining=fixedDue and (fixedDue-tick()) or (beat-(tonumber(track.TimePosition) or 0))/currentSpeed+offset
                    if remaining<=0 then break end
                    if request then request.expires=math.max(request.expires,math.min(request.hardExpires,tick()+remaining+0.15)) end
                end
                if fixedDue and currentSpeed>0 then
                    task.wait(math.max(0,fixedDue-tick()))
                else task.wait() end
            end
            if pending~=ticket or ticket.generation~=generation then return end
            pending=nil
            if not live(ticket.body) or tick()>ticket.hardExpires or not request and not enabled then return end
            if not track.IsPlaying or (tonumber(track.Speed) or 1)<=0 then
                _G.VX_BF_LASTMSG="windup stopped before follow-up"
                if request then BFApi.CancelChain(request) end
                return
            end
            -- ═══ r15: THE PRESS IS NEVER VETOED BY A REPLACED CHAIN ═══ chain~=request used to abort the
            -- scheduled conversion whenever anything re-armed the engine inside the 0.19s window - that
            -- abort IS the "second time it does divergent fist". The request's own used/expiry flags are the
            -- only honest limits now, matching the user's proven script, which never drops a press.
            if request and (request.used or tick()>request.expires) then return end
            if request and request.validate and not request.validate() then
                _G.VX_BF_LASTMSG="target left selected rear position"
                if _G.VX_TRACE then _G.VX_TRACE("followup-rejected:range-or-rear") end
                BFApi.CancelChain(request);return
            end
            if not request and not nearEnemy() then return end
            if tick()<(tonumber(_G.VX_COMBAT_SUPPRESS_BF) or 0) then return end
            -- r14: the frame-stall ABORT is gone. A 0.12s stall used to cancel the follow-up outright,
            -- which GUARANTEES a plain Divergent Fist ("sometimes the black flash doesn't work - maybe it's my
            -- computer"). A late press can still land inside the game's window; cancelling never does. Send it.
            if request then request.used=true end
            lastFire=tick(); _G.VX_BF_LAST_FIRE=lastFire
            local sent=press()
            if request and _G.VX_TRACE then _G.VX_TRACE(sent and "followup-key-sent:hit-unconfirmed" or "followup-key-blocked") end
            if request then request.sent=sent; if chain==request then chain=nil end end
            _G.VX_BF_LASTMSG=sent and "animation-timed follow-up sent; hit unconfirmed" or "follow-up blocked"
        end)
    end
    hookAll=function()
        if not engineLive then return end
        for _,body in pairs({rig(),player.Character}) do
            local h=body and body:FindFirstChildOfClass("Humanoid")
            local a=h and h:FindFirstChildOfClass("Animator")
            if a and not hooked[a] then
                hooked[a]=a.AnimationPlayed:Connect(function(track) if body==rig() or body==player.Character then onAnim(track,true) end end)
            end
        end
    end
    BFApi={
        SetEnabled=function(v) if enabled~=(v==true) then cancel() end; enabled=v==true; _G.VX_BFAPI_ON=enabled; if enabled then hookAll() end end,
        IsEnabled=function() return enabled end,
        SetCooldown=function(v) cooldown=math.clamp(tonumber(v) or cooldown,0.1,2) end,
        SetTimingOffset=function(v) offset=math.clamp(tonumber(v) or 0,-0.12,0.4) end,
        SetDebugUnknownAnimations=function() end,
        AddTrigger=function(id,delay) id=tostring(id):match("%d+"); if not id or type(delay)~="number" then return false end; triggers[id]=math.clamp(delay,0,1); return true end,
        RemoveTrigger=function(id) id=tostring(id):match("%d+"); if id then triggers[id]=nil end end,
        ArmChain=function(validate,mode)
            hookAll(); generation+=1; pending=nil; count=0
            chain={expires=tick()+1.8,hardExpires=tick()+3,used=false,validate=validate,body=rig(),mode=mode}
            if mode then
                chain.existing=setmetatable({}, {__mode="k"})
                for _,body in pairs({rig(),player.Character}) do
                    local h=body and body:FindFirstChildOfClass("Humanoid")
                    local a=h and h:FindFirstChildOfClass("Animator")
                    if a then for _,track in ipairs(a:GetPlayingAnimationTracks()) do chain.existing[track]={phase=tonumber(track.TimePosition) or 0,stopped=not track.IsPlaying} end end
                end
            end
            return chain
        end,
        StartChain=function(token)
            if token~=chain or token.started or token.used or tick()>token.expires or not live(token.body) then return false end
            if _G.VX_BF_PRESSKEY=="Never" or not nearEnemy() or token.validate and not token.validate() then return false end
            token.started=true; token.startedAt=tick(); token.castSeq=tonumber(_G.VX_BF_CAST_SEQ) or 0
            if _G.VX_TRACE then _G.VX_TRACE("initial-key-request") end
            local sent=press()
            if not sent then BFApi.CancelChain(token); return false end
            task.spawn(function()
                -- r15: 0.6 -> 0.8s: a re-armed cast (first 3 eaten at +0.34s) can start its windup as late as
                -- ~0.5s on a laggy machine; the watcher must still be alive to rescue a missed event for it.
                local deadline=tick()+0.8
                local rearm=0
                repeat
                    if chain~=token or token.used or not live(token.body) then return end
                    hookAll()
                    for _,body in pairs({rig(),player.Character}) do
                        local h=body and body:FindFirstChildOfClass("Humanoid")
                        local a=h and h:FindFirstChildOfClass("Animator")
                        if a then for _,track in ipairs(a:GetPlayingAnimationTracks()) do
                            local id=tostring(track.Animation and track.Animation.AnimationId or ""):match("%d+")
                            if triggers[id] and track.IsPlaying and track.TimePosition<=triggers[id]+offset+0.06 then onAnim(track) end
                        end end
                    end
                    if token.observed then return end
                    -- ═══ r13: ONE RE-PRESS WHEN THE FIRST PRESS WAS EATEN ═══ "side dash / back dash still do
                    -- divergent fist". A 3 pressed into the tail of a real Q dash gets swallowed by the game: no
                    -- cast, no windup, nothing for the engine to time the flash press off - the watcher used to
                    -- just expire ("no supported windup observed") and whatever came out late was a plain
                    -- Divergent Fist. If by +0.26s NOTHING from the windup tables is animating, the first press
                    -- really was eaten - press 3 once more. Gated on "quiet" so a merely LATE (buffered) cast
                    -- is never double-fired: if its windup is already up, we let the normal timer handle it.
                    if rearm==0 and tick()-token.startedAt>0.34 then
                        local quiet=true
                        for _,body in pairs({rig(),player.Character}) do
                            local h=body and body:FindFirstChildOfClass("Humanoid")
                            local a=h and h:FindFirstChildOfClass("Animator")
                            if a then for _,track in ipairs(a:GetPlayingAnimationTracks()) do
                                local id=tostring(track.Animation and track.Animation.AnimationId or ""):match("%d+")
                                if track.IsPlaying and (triggers[id] or DASH_TAILS[id] or (_G.VX_M1_IDS and _G.VX_M1_IDS[id])) then quiet=false end
                            end end
                        end
                        local castObserved=(tonumber(_G.VX_BF_CAST_SEQ) or 0)~=token.castSeq
                        if quiet and not castObserved and (not token.validate or token.validate()) then
                            rearm=1
                            _G.VX_BF_LASTMSG="first 3 was eaten (dash tail); re-pressing"
                            if _G.VX_TRACE then _G.VX_TRACE("initial-key-retry:no-windup") end
                            press()
                        end
                    end
                    task.wait()
                until tick()>=deadline
            end)
            -- No blind second cast: only an observed cast windup schedules the follow-up.
            task.spawn(function()
                while chain==token and not token.used and tick()<=token.expires do task.wait() end
                if chain==token and not token.used then
                    _G.VX_BF_LASTMSG=token.observed and "windup never reached its timing window" or "no supported windup observed; no extra cast sent"
                    if _G.VX_TRACE then _G.VX_TRACE(token.observed and "windup-timeout" or "windup-not-observed") end
                    BFApi.CancelChain(token)
                end
            end)
            return true
        end,
        CancelChain=function(token) if not token or token==chain then cancel() end end,
        Reconnect=function() for _,c in pairs(hooked) do c:Disconnect() end; table.clear(hooked); cancel(); hookAll(); return true end,
        Status=function() return {enabled=enabled,pending=pending~=nil,lastFire=lastFire,message=_G.VX_BF_LASTMSG} end,
    }
    _G.VX_BFAPI_SET=BFApi.SetEnabled; _G.VX_BF_RESETCOUNT=function() count=0 end
    local respawnConnection=player.CharacterAdded:Connect(function() cancel(); task.defer(hookAll) end)
    _G.VX_BFAPI_DESTROY=function()
        engineLive=false; enabled=false; cancel()
        respawnConnection:Disconnect()
        for _,connection in pairs(hooked) do connection:Disconnect() end
        table.clear(hooked)
    end
    hookAll(); task.spawn(function() while engineLive do pcall(hookAll); task.wait(0.5) end end)
end

-- MODULE: AUTO BF CHAIN  (ULTIMATE BACK-LOCK BF CHAIN; standalone GUI stripped)
-- ============================================================
do
