local ItemsApi, SkillsApi, InvisApi, ParkourApi, TPApi, M1ComboApi, CounterApi, LockOnApi, AutoUltApi, AntiAfkApi, NoclipApi, FarmApi, SpeedApi, FlyApi, PlayerEspApi, DashApi, TrainApi, DrinkApi, AntiStunApi, AntiRagdollApi, SideDashApi, EvasiveApi, AntiDomainApi, ResetApi, InfJumpApi, AntiCounterApi, AutoAdaptApi, JumpHeadApi, AntiBlackHoleApi, CrowUltApi, CrowHitApi, AutoDomainAdaptApi, HeadUltApi, RikaSwordApi, SlamApi, GokuApi, HollowApi, VisualApi, AimAssistApi, RemoveTreesApi, GojoTpApi, ReversalRedApi, ControlDummyApi, DesyncFreezeApi, TargetApi, AutoQTEApi, MahitoGrabApi

-- EVERY character's M1 anim id (user-captured) - set EARLY so Head of Hei / Goku M1 / Side Dash all detect a real M1 regardless of module load order
do
        local ids = {}
        for _, id in ipairs({
                -- FULL per-character M1 capture (user-provided, every character):
                "127851700400958","72548435296350","84547415708554",                        -- Gojo
                "95295463826732","105077924973072","124862357369335",                       -- Vessel
                "94588892125071","97868312130612","140588454098230",                        -- Restless Gambler
                "75337033003776","138489871864252","96185406489877",                        -- Ten Shadows
                "126277739156443","99710481887795","121322029260156",                       -- Perfection
                "119042572747325",                                                          -- Blood Manipulator (uniques)
                "96327114254575","107029561762376","117831239064143",                       -- Switcher
                "133936641185614","122573730331631","82400997593751",                       -- Defense Attorney
                "133240987753043","130806585141471","131967150738931",                      -- Cursed Partners
                "98783064085844","85148168523745","108686045412945",                        -- Puppet Master
                "101283990868172","108708446862011","77583711129628",                       -- Head of Hei
                "84359513001979","79436586236026","102285403332509",                        -- Salaryman
                "89537672683114",                                                           -- Disaster Plants
                "116910683335467","92698956945928",                                         -- True Cannon (uniques)
                "139479927693015","85068785050521","79086910454958","108027796023968",      -- Locust
                "131909724908049","72575786212990","119248903710146",                       -- Star Rage
                "82881042739459","125689391910002","84080901810314","139833047658617",      -- Mangaka
                "133447840605824","113963875117859","138196552148011",                      -- Lucky Coward
                "105961366724096","86519781516542","123591522021548",                       -- Black Death
                "78418813242411","114985590391235","108449614447004",                       -- Crow (MeiMei)
                "120133391090244","9443519528",                                             -- legacy extras
        }) do ids[id] = true end
        _G.VX_M1_IDS = ids
        -- real-M1 detection: the anim id ALONE false-fires (a walk anim id is in the list) and clicks alone false-fire (GUI clicks).
        -- A REAL M1 = a listed anim id playing right after a LEFT CLICK. Both together = can't miss, can't false-fire.
        local UIS = game:GetService("UserInputService")
        local LPc = game:GetService("Players").LocalPlayer
        _G.VX_LAST_CLICK = 0
        _G.VX_LAST_HUMAN_CLICK = 0   -- same stamp, minus the clicks the hub injects itself (see the shared poll below)
        UIS.InputBegan:Connect(function(input) if input.UserInputType == Enum.UserInputType.MouseButton1 then _G.VX_LAST_CLICK = tick() end end)
        pcall(function() LPc:GetMouse().Button1Down:Connect(function() _G.VX_LAST_CLICK = tick() end) end)

        -- ═══ SHARED REAL-M1 DETECTOR (_G.VX_ON_M1) ═══════════════════════════════════════════════════════════════
        -- THE GAME SINKS THE M1 CLICK. InputBegan and Mouse.Button1Down fire for GUI/empty clicks but NOT for a real
        -- attack click, which is why every feature bound to them silently never ran (Auto Uppercut, Auto Down Slam).
        -- The only reliable detector is polling the raw button state and catching the rising edge - the same trick
        -- the working Black Flash engine uses. One poll here, and any module can subscribe.
        do
                local RSm = game:GetService("RunService")
                local UISm = game:GetService("UserInputService")
                -- RE-EXECUTE SAFETY: _G survives between runs. Keeping the old subscriber table would leave DEAD closures
                -- from the previous script instance registered, and guarding the poll on a sticky flag meant the poll was
                -- never re-created on a second run - so every subscriber (Down Slam, Uppercut, M1 Chain) silently stopped
                -- working the moment you re-executed. Always start fresh and always reconnect.
                if _G.VX_M1_POLL_CONN then pcall(function() _G.VX_M1_POLL_CONN:Disconnect() end) end
                if _G.VX_KEY_POLL_CONN then pcall(function() _G.VX_KEY_POLL_CONN:Disconnect() end) end
                _G.VX_M1_SUBS = {}
                _G.VX_M1_SUB = function(key, fn)            -- subscribe: VX_M1_SUB("uppercut", myHandler); pass nil to remove
                -- NB: NOT named VX_ON_M1 - that global already exists later in the file as a zero-arg click stamper.
                        if type(key) ~= "string" then return end
                        _G.VX_M1_SUBS[key] = (type(fn) == "function") and fn or nil
                end
                _G.VX_KEY_SUBS = {}
                _G.VX_ON_KEY = function(key, fn)           -- subscribe: VX_ON_KEY("autoair", function(kc) ... end)
                        if type(key) ~= "string" then return end
                        _G.VX_KEY_SUBS[key] = (type(fn) == "function") and fn or nil
                end
                -- ═══ SLOT LEARNING, HALF 1 ═══ Stamp which number key YOU pressed (injected keys excluded - our own
                -- synthetic presses must not teach the map). The namecall hook pairs this stamp with the move the game
                -- casts right after, giving the REAL key->move mapping with no GetChildren-order assumption. It is a
                -- permanent subscriber, so the key poll below always has at least one consumer.
                _G.VX_ON_KEY("slotlearn", function(kc)
                        local injK = _G.VX_INJ_KEYS
                        if injK and injK[kc] and tick() < injK[kc] then return end
                        local map = { [Enum.KeyCode.One] = 1, [Enum.KeyCode.Two] = 2, [Enum.KeyCode.Three] = 3, [Enum.KeyCode.Four] = 4 }
                        local n = map[kc]
                        if n then _G.VX_LASTNUM_KEY = { n = n, t = tick() } end
                end)
                do
                        local WATCH = { Enum.KeyCode.One, Enum.KeyCode.Two, Enum.KeyCode.Three, Enum.KeyCode.Four,
                                Enum.KeyCode.R, Enum.KeyCode.Space, Enum.KeyCode.Q, Enum.KeyCode.E, Enum.KeyCode.G }
                        local wasKey = {}
                        _G.VX_KEY_POLL_CONN = RSm.RenderStepped:Connect(function()
                                -- ═══ LAG ═══ This used to run 9 pcall-wrapped IsKeyDown calls EVERY FRAME, FOREVER, gated on
                                -- nothing - so the hub cost CPU at 60Hz even with every single feature switched off. Two fixes:
                                -- bail immediately when nothing is subscribed, and drop the per-key pcall for one pcall around
                                -- the whole sweep (a pcall in a hot path allocates every call).
                                if next(_G.VX_KEY_SUBS) == nil then return end
                                if UISm:GetFocusedTextBox() then return end
                                pcall(function()
                                        for _, kc in ipairs(WATCH) do
                                                local down = UISm:IsKeyDown(kc)
                                                if down and not wasKey[kc] then
                                                        for _, fn in pairs(_G.VX_KEY_SUBS) do task.spawn(function() pcall(fn, kc) end) end
                                                end
                                                wasKey[kc] = down
                                        end
                                end)
                        end)
                end
                do
                        local wasDown = false
                        _G.VX_M1_POLL_CONN = RSm.RenderStepped:Connect(function()
                                -- Same treatment as the key poll: skip entirely when nothing consumes M1 events AND no flash
                                -- engine is armed. _G.VX_BFAPI_ON covers the Black Flash engine, which needs the click stamp
                                -- even when it has no M1 subscriber of its own.
                                if next(_G.VX_M1_SUBS) == nil and not _G.VX_BFAPI_ON then return end
                                local ok, down = pcall(function() return UISm:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) end)
                                if not ok then return end
                                if down and not UISm:GetFocusedTextBox() then
                                        -- ═══ THE ONE THAT BROKE EVERYTHING ═══ A recorder capture settled this: JJS advances the M1
                                        -- combo while you HOLD the button. One click held for 1.38s produced FOUR swings ~0.35s apart.
                                        -- This stamp used to live inside `down and not wasDown` - the rising edge only - so swings 2,
                                        -- 3 and 4 landed 0.41s / 0.76s / 1.12s after the last stamp, and every gate that asks "did
                                        -- they click recently" (the Black Flash engine's 0.5s test, the combo module's 0.40s
                                        -- realM1Now) answered NO. Only the first swing of a held combo ever counted. That single line
                                        -- is both "auto uppercut/down slam don't work" and "it doesn't black flash".
                                        -- Button still down = still attacking, so the stamp stays fresh while it is held.
                                        _G.VX_LAST_CLICK = tick()
                                        -- ═══ AND A SEPARATE STAMP THAT EXCLUDES OUR OWN CLICKS ═══ VirtualInputManager clicks are
                                        -- visible to IsMouseButtonPressed, so the line above cannot tell an injected click from
                                        -- yours - and every gate in the file that asks "was that really the player?" reads it. The
                                        -- Black Flash engine's re-click therefore refreshed it, its follow-up swing looked like a
                                        -- fresh player M1, flashed, re-clicked... a loop that only stops when nobody is in range.
                                        -- _G.VX_SYNTH_CLICK is already set by every injector immediately before it clicks, so this
                                        -- stamp simply skips those windows.
                                        if tick() >= (tonumber(_G.VX_SYNTH_CLICK) or 0) then _G.VX_LAST_HUMAN_CLICK = tick() end
                                        -- SUBSCRIBERS stay on the rising edge: they are per-click actions and must not repeat every
                                        -- frame. A click WE injected stamps the timing above but never re-enters them.
                                        if not wasDown and tick() >= (tonumber(_G.VX_SYNTH_CLICK) or 0) then
                                                for _, fn in pairs(_G.VX_M1_SUBS) do task.spawn(function() pcall(fn) end) end
                                        end
                                end
                                wasDown = down
                        end)
                end
        end
        _G.VX_IS_M1 = function(track)
                if not track or not track.Animation then return false end
                local id = tostring(track.Animation.AnimationId):match("%d+")
                if not (id and _G.VX_M1_IDS[id]) then return false end
                -- HUMAN click: an injected re-click also produces a real M1 swing, and counting that as "a real M1"
                -- is what lets a flash feed the next flash for as long as somebody is standing near you.
                return tick() - (_G.VX_LAST_HUMAN_CLICK or 0) < 0.4   -- anim + a click within 0.4s = a real M1 swing
        end
end

-- ═══ MOUSE HEALTH WATCHDOG ═══ "for some reason I can't click or use my mouse... when I turn auto downslam,
-- I can't click. When I turn auto uppercut, I can't click. I can still use my moves, but I just can't click."
-- Every mouse click this script sends is press + release a few hundredths of a second apart, but ONE lost
-- release (an executor hiccup, a respawn mid-click) leaves the LEFT BUTTON HELD DOWN - and a held button
-- turns every later click into a drag attempt: nothing clicks, and it feels exactly like "my mouse is broken"
-- while the keyboard keeps working. The watchdog: if the button reports held for 5 straight seconds - no real
-- player holds LMB that long in a fighting game - it force-sends the missing release. Self-heals any module's
-- lost release in under half a second of it mattering.
do
        local UISm2 = game:GetService("UserInputService")
        local VIMm2 = game:GetService("VirtualInputManager")
        local heldSince
        task.spawn(function()
                while true do
                        task.wait(0.5)
                        local ok, down = pcall(function() return UISm2:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) end)
                        if ok and down then
                                if not heldSince then heldSince = tick() end
                                if tick() - heldSince > 5 then
                                        pcall(function()
                                                local cam = workspace.CurrentCamera; local vp = cam and cam.ViewportSize
                                                VIMm2:SendMouseButtonEvent((vp and vp.X/2) or 400, (vp and vp.Y/2) or 300, 0, false, game, 0)
                                        end)
                                        heldSince = nil
                                end
                        else
                                heldSince = nil
                        end
                end
        end)
end

-- ═══ NETWORK OWNERSHIP CLAIM (the REAL root cause of "teleport sets me back" / "jump teleports instead of
-- jumping" / uppercut&downslam never registering) ═══ Every CFrame/AssemblyLinearVelocity write in this whole
-- file (doBackstab's snap, the teleport glide, the uppercut jump-velocity, downslam's fall-velocity check) is
-- COSMETIC unless the CLIENT owns network ownership of the HumanoidRootPart's assembly. If the SERVER owns it
-- simulation silently reverts on its next replication tick — which is EXACTLY "sets me back" and "the server
-- never sees me as airborne so uppercut/downslam won't trigger". This was never claimed anywhere in the file.
-- Claiming it is a standard, well-established exploit technique (SetNetworkOwner) and, when the executor's
-- security context permits it, makes every physics write in this hub actually stick server-side.
-- NO-OP now: the old SetNetworkOwner loop (called every 2s across all body parts) is a server-only API
-- and was very likely what tripped the anti-cheat into 267-kicking you ("your script kicks, mine doesn't").
-- The teleport doesn't need it anymore — the bypass blocks the set-back report instead. Kept as an empty
-- function so every existing call site is a harmless no-op.
local function vxClaimOwnership() end
_G.VX_CLAIMOWN = vxClaimOwnership
-- Shared anti-setback teleport BYPASS: JJS snaps you back if a single frame moves you faster than
-- maxSpeed*dt, so instead of one big jump we step to the target in capped per-frame hops that stay under
-- that limit. VX_TP_SPEED is the studs-per-frame step and safeTeleport reads it directly, so lowering the
-- TP Step slider genuinely makes the teleport gentler if a server still sets you back.
local VX_TP_SPEED = 60   -- studs PER FRAME (back-compat local; the LIVE value the glide reads is _G.VX_TP_SPEED)
_G.VX_TP_SPEED  = tonumber(_G.VX_TP_SPEED) or 60      -- studs/frame the glide steps in (lower = gentler if a server still sets you back)
_G.VX_TP_METHOD = _G.VX_TP_METHOD or "Glide"            -- FIX: Changed default from "Instant" to "Glide" for public-server safety
-- game updates -> teleports set back). Try the known path first, else search for any RemoteEvent named
local vxACRemote = nil
local vxACStamp = 0
task.spawn(function() while true do task.wait(20); vxACRemote = nil; vxACStamp = 0 end end)   -- "TP works ~1min then stops": the game swaps the remote instance; drop the cache every 20s so we re-find the live one
local function vxResolveAC()
        if vxACRemote and vxACRemote.Parent then return vxACRemote end
        local RS = game:GetService("ReplicatedStorage")
        local k = RS:FindFirstChild("Knit"); k = k and k:FindFirstChild("Knit"); k = k and k:FindFirstChild("Services")
        if vxACStamp < 0 and tick() + vxACStamp < 20 then return nil end   -- negative cache: the remote is destroyed (our default); do not rescan all of ReplicatedStorage on every pass
        local svc = k and k:FindFirstChild("AntiCheatService"); local re = svc and svc:FindFirstChild("RE"); re = re and re:FindFirstChild("Teleport")
        -- Skip OUR OWN dummy. The real remote is replaced by a tagged stand-in by default; firing
        -- that is pure noise, so the AC pass has to cleanly no-op instead of pretending it announced anything.
        if re and re:IsA("RemoteEvent") and not re:GetAttribute("VX_Dummy") then vxACRemote = re; return re end
        for _, d in ipairs(RS:GetDescendants()) do
                if d:IsA("RemoteEvent") and not d:GetAttribute("VX_Dummy") and string.lower(d.Name) == "teleport" and string.find(string.lower(d:GetFullName()), "anticheat") then vxACRemote = d; return d end
        end
        vxACStamp = -tick()   -- remember the miss (see the negative cache above)
        return nil
end
local vxTeleLastActive = 0  -- last time a teleport actually moved you; the safety loop uses it to know when NO teleport is running
local function vxACPass()
        vxTeleLastActive = tick()
        local re = vxResolveAC()
        if re then pcall(function() re:FireServer(workspace:GetServerTimeNow()) end) end
end
_G.VX_ACPASS = vxACPass
local vxTeleGen = 0  -- overlap guard: each teleport takes the next number; a newer one supersedes older holds so rapid teleports (Rika sword) do not fight over your CFrame or leave PlatformStand stuck on (frozen)
-- SAFETY: never leave you stuck in PlatformStand (the "frozen after teleport" pose in the screenshot).
-- Once no teleport has touched you for ~0.4s, force PlatformStand OFF so you can ALWAYS move again.
-- Forward-declared ON PURPOSE: the respawn reset and the collision sweeper below both live ABOVE the noclip
-- helpers, and Lua upvalue capture is LEXICAL - declaring these later would make every reference above a
-- GLOBAL (always nil), so the guards would silently never fire.
local vxNoclipParts
local vxLockChar          -- the rig a teleport hold belongs to; a respawn voids the hold
local vxLastPinPass = 0   -- throttle for the AC pass fired by the re-pin
local VX_NOTIFY   -- the GUI assigns this = its toast fn; forward-declared so teleport code above can use it
task.spawn(function()
        local Players = game:GetService("Players"); local LP = Players.LocalPlayer
        while true do
                task.wait(0.3)
                if tick() - vxTeleLastActive > 0.4 then
                        local chs = workspace:FindFirstChild("Characters"); local c = (chs and chs:FindFirstChild(LP.Name)) or LP.Character
                        local h = c and c:FindFirstChildOfClass("Humanoid")
                        if h and h.PlatformStand then pcall(function() h.PlatformStand = false end) end
                        -- COLLISION SWEEPER: vxNoclipOff bails on a generation mismatch, and the Instant branch never
                        -- noclipped at all - so a superseded glide could leave every part CanCollide=false permanently.
                        -- 1.2s (not 0.4) because vxACPass bumps vxTeleLastActive at ~3Hz during flight; a tighter window
                        -- could restore collisions MID-FLIGHT and slam you into the wall the noclip existed to pass.
                        -- If a flight died mid-way the in-flight flag would stay set and permanently disable the position
                        -- lock. Nothing has moved you for >1.2s here, so nothing can still be in flight.
                        if _G.VX_TP_INFLIGHT and tick() - vxTeleLastActive > 1.2 then _G.VX_TP_INFLIGHT = false end
                        if vxNoclipParts and tick() - vxTeleLastActive > 1.2 then
                                for _, v in ipairs(vxNoclipParts) do pcall(function() v.CanCollide = true end) end
                                vxNoclipParts = nil
                        end
                end
        end
end)
-- TELEPORT = zero-lag bypass. The isolated anti-cheat bypass at the TOP of this file already destroyed the AC
-- remotes and disabled the anti/detect scripts (and re-applies on respawn), so the server has no channel to
-- reject a move: a single PivotTo just sticks. A throttled Heartbeat lock re-pins you if the server nudges you.
-- vxGlide / vxTeleportHard stay as thin wrappers so every call site (locations, players, slots) routes here.

local vxTeleportLock = false
local vxCurrentTargetCF = nil
-- SINGLE position lock (the rubberband fix): this Heartbeat is now the ONLY thing holding you after a
-- teleport. The old version ALSO ran a second while-loop inside safeTeleport doing the same job -- the two
-- fought over your CFrame/velocity every frame and the physics engine ping-ponged you between the target
-- and where the server thought you were. And it zeroed your velocity EVERY frame for the whole hold, which
-- froze you in place if you tried to walk/dash right after landing. Now: re-pin ONLY when the server shoves
-- you (>3 studs), never touch velocity per-frame.
-- No post-teleport position pin. Server corrections are never countered by another snap.
-- A RESPAWN VOIDS EVERY HOLD (nothing used to do this - and with Instant Respawn on, a new rig exists a
-- fraction of a second after death, squarely inside every 2-5s hold).
game:GetService("Players").LocalPlayer.CharacterAdded:Connect(function()
        vxTeleportLock = false
        vxCurrentTargetCF = nil
        vxLockChar = nil
        vxNoclipParts = nil          -- recorded parts belong to the DEAD rig
        vxTeleGen = vxTeleGen + 1    -- supersede any in-flight leg and any pending release timer
        _G.VX_TELEPORTING = false
end)
local isTeleporting = false
local function vxMyChar()
        -- ORDER MATTERS: the JJS body lives under workspace.Characters, and LP.Character can point at a stale/decoy
        -- rig. Resolving LP.Character FIRST meant safeTeleport moved the wrong model — the teleport "did nothing"
        -- because your real body never left. Every other resolver in this file is Characters-first; now so is this.
        local LP = game:GetService("Players").LocalPlayer
        local chs = workspace:FindFirstChild("Characters")
        local c = chs and chs:FindFirstChild(LP.Name)
        if c and c:FindFirstChild("HumanoidRootPart") then return c end
        return LP.Character or c
end
-- AC acknowledge: only fire the REAL remote. The bypass at the top of the file replaces the AC remotes with
-- dummies tagged VX_Dummy -- the old version happily fired the dummy, which does nothing, so the server never
-- got the acknowledgement.
local function vxACAck()
        pcall(function()
                local k = game:GetService("ReplicatedStorage"):FindFirstChild("Knit")
                k = k and k:FindFirstChild("Knit"); k = k and k:FindFirstChild("Services")
                local svc = k and k:FindFirstChild("AntiCheatService")
                local re = svc and svc:FindFirstChild("RE"); re = re and re:FindFirstChild("Teleport")
                if re and not re:GetAttribute("VX_Dummy") then
                        re:FireServer(workspace:GetServerTimeNow())
                end
        end)
end
-- Hard write: PivotTo ONLY (the fling fix). Setting hrp.CFrame first snapped the joints, then PivotTo moved
-- the whole model AGAIN -- the double write made constraints spasm and flung/jittered you. One PivotTo moves
-- everything coherently. Unseat/unanchor first so the write can't be silently overridden.
function vxHardWrite(char, hrp, cf)
        pcall(function()
                local hum = char:FindFirstChildOfClass("Humanoid")
                if hum then
                        -- Read this BEFORE clearing it, or the downed check below is testing a value we just zeroed.
                        local wasDowned = hum.PlatformStand == true
                        hum.Sit = false
                        if hum.PlatformStand then hum.PlatformStand = false end
                        if wasDowned then return end
                        -- Only when ACTUALLY ragdolled. Re-issuing this on every re-pin frame pinned the humanoid in a
                        -- getting-up transition for the whole hold.
                        local st = hum:GetState()
                        if st == Enum.HumanoidStateType.Physics or st == Enum.HumanoidStateType.Ragdoll or st == Enum.HumanoidStateType.FallingDown then
                                -- ═══ AND DO NOT WRITE ═══ Forcing GettingUp and then PivotTo-ing anyway is what pinned you in
                                -- the get-up transition: every re-pin restarted it, so the animation never completed and you
                                -- lay there until the hold expired, then the last write snapped you back. Force the state, and
                                -- then leave the body alone this frame - being downed is the game's call, not ours to override.
                                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                                return
                        end
                end
                local seatWeld = hrp:FindFirstChild("SeatWeld"); if seatWeld then seatWeld:Destroy() end
                if not _G.VX_TP_ANCHORING then hrp.Anchored = false end
                -- PIVOT MUST BE THE HRP. PivotTo moves the model's WorldPivot; if PrimaryPart is nil the HRP lands at
                -- an offset, and the re-pin (which measures HRP vs target) then never converges - it re-writes every
                -- frame for the whole hold. That reads exactly as "Instant did nothing / I jitter".
                if char.PrimaryPart ~= hrp then pcall(function() char.PrimaryPart = hrp end) end
                -- Measure the move BEFORE the write - afterwards hrp.Position already equals the target.
                local delta = cf.Position - hrp.Position
                local dist = delta.Magnitude
                char:PivotTo(cf)
                if (hrp.Position - cf.Position).Magnitude > 0.5 then hrp.CFrame = cf end   -- pivot still missed: correct it
                -- DO NOT ZERO VELOCITY, and do not leave it inert either. A large position change on one frame with
                -- velocity reading exactly 0,0,0 is impossible physics and the server's own simulation reverts it. The
                -- recorder data is explicit: the writes that STUCK carried real momentum in the direction travelled.
                -- So hand the server a velocity that agrees with the move it just saw.
                if dist > 1 then
                        hrp.AssemblyLinearVelocity = delta.Unit * math.clamp(dist * 2, 16, 60)
                end
        end)
end
-- FLIGHT PATH CHECK: is the straight line to the target blocked by anything solid (a building)?
local function vxRouteClear(a, b)
        local d = b - a
        if d.Magnitude < 1 then return true end
        local ok, hit = pcall(function()
                local rp = RaycastParams.new()
                rp.FilterType = Enum.RaycastFilterType.Exclude
                local ig = { workspace.CurrentCamera }
                local c = vxMyChar(); if c then ig[#ig + 1] = c end
                local chars = workspace:FindFirstChild("Characters"); if chars then ig[#ig + 1] = chars end
                rp.FilterDescendantsInstances = ig
                rp.RespectCanCollide = true
                return workspace:Raycast(a, d, rp)
        end)
        -- BUG: this used to be `return ok and hit == nil`, so a pcall FAILURE reported "route blocked" — which forced
        -- the 400-stud up-and-dive detour on a perfectly clear line. A raycast error must never cause a detour.
        if not ok then return true end
        return hit == nil
end
-- VELOCITY FLIGHT (the TP method that works): instead of writing CFrames at the target, we push the character
-- there with plain physics VELOCITY every frame — the server watches you MOVE, so there is nothing to reject.
-- Collisions are turned off on your own parts for the flight (restored after) so walls/floors can't stop you,
-- and when the straight line is blocked by a building we fly UP 400 studs first, then dive to the target.
-- Returns when you're within 3 studs (or the safety timeout fires — then we hard-write and let the lock hold).
-- SHARED noclip save-list: with two overlapping teleports (Rika-sword spam), the OLD leg used to restore
-- collisions mid-flight of the NEW one — and the new leg had recorded nothing (parts were already off), so
-- you ended solid in a wall or permanently noclipped. One shared list: first leg records, only the CURRENT
-- teleport's landing restores, superseded legs leave it alone.
vxNoclipParts = nil
local function vxNoclipOn()
        vxNoclipParts = vxNoclipParts or {}
        local c = vxMyChar()
        if c then for _,v in ipairs(c:GetDescendants()) do
            if v:IsA("BasePart") and v.CanCollide then
                if not table.find(vxNoclipParts,v) then vxNoclipParts[#vxNoclipParts+1]=v end
                v.CanCollide=false
            end
        end end
end
local function vxNoclipOff(myGen)
        if myGen ~= vxTeleGen then return end            -- a newer teleport is still flying; it restores when IT lands
        if vxNoclipParts then for _, v in ipairs(vxNoclipParts) do pcall(function() v.CanCollide = true end) end end
        vxNoclipParts = nil
end
local function vxVelocityLeg(targetPos, speed, myGen)
        vxNoclipOn()
        local c = vxMyChar()
        local h0 = c and c:FindFirstChild("HumanoidRootPart")
        local t0 = tick()
        local timeout = (h0 and (targetPos - h0.Position).Magnitude or 400) / speed * 2 + 2
        while tick() - t0 < timeout do
                if myGen ~= vxTeleGen then break end                          -- superseded by a newer teleport
                vxNoclipOn()
                local cc = vxMyChar(); local hrp = cc and cc:FindFirstChild("HumanoidRootPart")
                if not hrp then break end
                local dist = targetPos - hrp.Position
                if dist.Magnitude < 3 then break end
                hrp.AssemblyLinearVelocity = (dist.Magnitude > 0.01) and (dist.Unit * speed) or Vector3.zero
                -- lock OFF while flying: on a low-FPS client you cover >3 studs between frames, and the lock's re-pin
                -- (which also zeroes velocity) would fight the flight. The flight self-corrects anyway — it re-aims from
                -- wherever you are every frame — and the landing hard-write re-engages the lock at the exact target.
                vxCurrentTargetCF = nil
                if math.floor((tick() - t0) * 10) % 3 == 0 then vxACPass() end
                task.wait()
        end
        -- (THE "teleport broken" BUG: this used to restore a `changed` list that no longer exists after the shared
        -- noclip-list refactor — ipairs(nil) ERRORED here at the end of EVERY leg, so the landing hard-write never ran
        -- and collisions never restored. vxNoclipOff is the correct restore: only the current teleport's landing
        -- restores; a superseded leg leaves the shared list for the newer teleport.)
        vxNoclipOff(myGen)
        local cc = vxMyChar(); local hrp = cc and cc:FindFirstChild("HumanoidRootPart")
        if hrp then pcall(function() hrp.AssemblyLinearVelocity = Vector3.zero end) end
end
-- Teleport = THE GLIDE METHOD (default). Instead of one impossible-speed snap, we walk the server to the target
-- in small believable hops and fire the anti-cheat "I teleported legitimately" pass on each hop -- the SAME
-- trick that makes it stick even when a server's AC is still alive. Two things made the old stepping useless and
-- are fixed here: (1) the Heartbeat lock re-pinned you to the FINAL target every frame, so it snapped instead of
-- gliding -- now the lock target MOVES WITH the glide (it reinforces each hop instead of fighting it); (2) no AC
-- pass was fired during the move -- now every few hops we fire it so the server accepts the motion. VX_TP_METHOD
-- picks Glide (default) / Instant / Auto; VX_TP_SPEED is the hop size (lower = gentler if a server still resists).
local function safeTeleport(targetCFrame, holdTime)
        local char = vxMyChar()
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp or typeof(targetCFrame) ~= "CFrame" then return false end
        vxTeleGen = vxTeleGen + 1
        local gen = vxTeleGen
        isTeleporting = true; vxTeleportLock = false; vxCurrentTargetCF = nil
        _G.VX_TP_INFLIGHT = true
        local ok, err = pcall(function()
            -- r13: "Auto" is now honest - short hops pivot straight (nothing for a server to dislike at combat
            -- range), long trips take the glide leg (believable velocity + AC acks, the shape a server accepts).
            local method = _G.VX_TP_METHOD
            local dist = (targetCFrame.Position - hrp.Position).Magnitude
            if method == "Glide" or (method ~= "Instant" and method ~= "Anchor" and dist > 60) then
                vxVelocityLeg(targetCFrame.Position,math.clamp(tonumber(_G.VX_TP_VEL) or 60,30,90),gen)
            else
                char:PivotTo(targetCFrame)
            end
            task.wait(math.clamp(tonumber(holdTime) or 0.35,0.2,0.6))
        end)
        if gen ~= vxTeleGen then return false end
        vxNoclipOff(gen)
        isTeleporting = false; vxTeleportLock = false; vxCurrentTargetCF = nil
        _G.VX_TP_INFLIGHT = false
        local current = vxMyChar()
        local r = current and current:FindFirstChild("HumanoidRootPart")
        local arrived = ok and current == char and r and (r.Position-targetCFrame.Position).Magnitude <= 8
        _G.VX_TP_LAST_RESULT = arrived and "position observed" or "movement rejected or interrupted"
        if not arrived then warn("[DreamHub Teleport] "..tostring(err or _G.VX_TP_LAST_RESULT)) end
        return arrived == true
end
local function vxGlide(target, onArrive, holdTime)
        local c = vxMyChar(); local r = c and c:FindFirstChild("HumanoidRootPart")
        if not r then return false end
        local cf = typeof(target) == "CFrame" and target or CFrame.new(target)*r.CFrame.Rotation
        local arrived = safeTeleport(cf,holdTime)
        if arrived and onArrive then pcall(onArrive) end
        return arrived
end

-- ═══ THE GAME'S OWN "TELEPORT TO PLAYER" ═══ Your capture, from the private-server menu:
--     DebugService.RE.Debug:FireServer("Go", <Player>)
-- In a private server the SERVER moves you - no CFrame writes, no anti-cheat conversation, no snapback,
-- because it is the game's own feature. So every teleport-to-a-PLAYER tries this first and only falls back
-- to the write-based teleport when the remote does not move us (public servers just ignore it).
local function vxDebugGo(plr)
        if typeof(plr) ~= "Instance" or not plr:IsA("Player") then return false end
        local k = game:GetService("ReplicatedStorage"):FindFirstChild("Knit")
        k = k and k:FindFirstChild("Knit"); k = k and k:FindFirstChild("Services")
        local d = k and k:FindFirstChild("DebugService")
        local re = d and d:FindFirstChild("RE"); re = re and re:FindFirstChild("Debug")
        if not re then return false end
        local before
        do local c = vxMyChar(); local h = c and c:FindFirstChild("HumanoidRootPart"); before = h and h.Position end
        local ok = pcall(function() re:FireServer("Go", plr) end)
        if not ok then return false end
        task.wait(0.35)
        local c = vxMyChar(); local h = c and c:FindFirstChild("HumanoidRootPart")
        local tc = plr.Character; local th = tc and tc:FindFirstChild("HumanoidRootPart")
        if h and th and (h.Position - th.Position).Magnitude < 25 then return true end
        if h and before and (h.Position - before).Magnitude > 15 then return true end   -- it moved us somewhere real
        return false
end
_G.VX_TP_TO_PLAYER = function(plr, fallbackCf)
        if vxDebugGo(plr) then return true end
        local dest = fallbackCf
        if not dest then
                local tc = plr and plr.Character; local th = tc and tc:FindFirstChild("HumanoidRootPart")
                dest = th and (th.CFrame * CFrame.new(0, 0, 3))
        end
        if dest then return safeTeleport(dest, 0.6) == true end
        return false
end
local function vxTeleportHard(dest, holdTime)
        if typeof(dest) == "CFrame" then safeTeleport(dest, holdTime or 0.6); return end
        local hrp
        do local c = vxMyChar(); hrp = c and c:FindFirstChild("HumanoidRootPart") end   -- Characters-FIRST (LP.Character can be a stale/decoy rig)
        local cf = hrp and (CFrame.new(dest) * hrp.CFrame.Rotation) or CFrame.new(dest)
        safeTeleport(cf, holdTime or 0.6)
end

-- Fire a Knit service RemoteEvent by name. Resolves the path fresh each call so it survives character
-- switches / lazy loading, and silently no-ops if the remote is not present (e.g. wrong character).
local VX_DEBUG = false
-- (VX_NOTIFY is forward-declared near the teleport state so earlier code can use it too)
local vxDbgGui, vxDbgLabel
local function vxLog(msg)  -- prints to console AND shows an on-screen line (top-left) when Debug is on - so you can SEE what fires
        if not VX_DEBUG then return end
        pcall(function() print("[Vaultix] " .. tostring(msg)) end)
        if not vxDbgLabel then
                pcall(function()
                        vxDbgGui = Instance.new("ScreenGui"); vxDbgGui.Name = "VX_DBG"; vxDbgGui.ResetOnSpawn = false; vxDbgGui.IgnoreGuiInset = true; vxDbgGui.DisplayOrder = 99999
                        vxDbgGui.Parent = (gethui and gethui()) or game:GetService("CoreGui")
                        vxDbgLabel = Instance.new("TextLabel"); vxDbgLabel.Size = UDim2.fromOffset(480, 24); vxDbgLabel.Position = UDim2.fromOffset(12, 12)
                        vxDbgLabel.BackgroundColor3 = Color3.fromRGB(8, 8, 10); vxDbgLabel.BackgroundTransparency = 0.2; vxDbgLabel.BorderSizePixel = 0
                        vxDbgLabel.Font = Enum.Font.Code; vxDbgLabel.TextSize = 14; vxDbgLabel.TextColor3 = Color3.fromRGB(120, 235, 140)
                        vxDbgLabel.TextXAlignment = Enum.TextXAlignment.Left; vxDbgLabel.Text = ""; vxDbgLabel.Parent = vxDbgGui
                end)
        end
        if vxDbgLabel then pcall(function() vxDbgLabel.Text = " [VX] " .. tostring(msg); vxDbgLabel.Visible = true end) end
end
local function vxSetDebug(b) VX_DEBUG = b == true; if vxDbgLabel then pcall(function() vxDbgLabel.Visible = VX_DEBUG end) end if VX_DEBUG then vxLog("debug ON") end end
-- REMOTE RESOLVER — RESILIENT + CACHED. Every remote-based feature (Side Dash, Auto Skills, Uppercut/Downslam,
-- Dash, Counter…) fires through here. The old code ONLY looked at the exact path
-- ReplicatedStorage.Knit.Knit.Services.<service>.RE.<reName>; if a game update renamed "Knit"/"Services"/"RE" or
-- moved the service, EVERY one of those features silently no-op'd (this was the shared root cause of "side dash /
-- auto skills / uppercut do nothing"). Now we: (1) try the exact path, (2) fall back to searching RS for a service
-- folder of that name holding the remote, (3) fall back to ANY RemoteEvent named reName under a service-named
-- ancestor, and cache whatever we find so the search runs at most once per (service,reName).
local _knitRoot
local function knitServices()
        if _knitRoot and _knitRoot.Parent then return _knitRoot end
        local RS = game:GetService("ReplicatedStorage")
        local k = RS:FindFirstChild("Knit"); k = k and k:FindFirstChild("Knit"); _knitRoot = k and k:FindFirstChild("Services")
        return _knitRoot
end
local _reCache = {}
local function resolveRemote(service, reName)
        local key = service .. "\0" .. reName
        local cached = _reCache[key]
        if cached and cached.Parent then return cached end
        local RS = game:GetService("ReplicatedStorage")
        -- 1) exact captured path
        local svc = knitServices() and knitServices():FindFirstChild(service)
        if svc then
                local container = svc:FindFirstChild("RE") or svc:FindFirstChild("RemoteEvents") or svc:FindFirstChild("Remotes") or svc
                local re = container and container:FindFirstChild(reName)
                if re and re:IsA("RemoteEvent") then _reCache[key] = re; return re end
        end
        -- 2) any folder named <service> anywhere in RS that holds the remote (renamed/moved Knit tree)
        local found
        pcall(function()
                for _, d in ipairs(RS:GetDescendants()) do
                        if d:IsA("RemoteEvent") and d.Name == reName then
                                local anc = d.Parent
                                while anc and anc ~= RS do
                                        if anc.Name == service then found = d; return end
                                        anc = anc.Parent
                                end
                        end
                end
        end)
        if found then _reCache[key] = found; return found end
        -- 3) last resort: the FIRST RemoteEvent named reName anywhere (covers a fully-flattened remote tree)
        pcall(function()
                for _, d in ipairs(RS:GetDescendants()) do
                        if d:IsA("RemoteEvent") and d.Name == reName then found = d; return end
                end
        end)
        if found then _reCache[key] = found end
        return found
end
local function fireKnit(service, reName, ...)
        local re = resolveRemote(service, reName)
        if not re then vxLog("NOT FOUND " .. tostring(service) .. ".RE." .. tostring(reName)); if VX_DEBUG and VX_NOTIFY then VX_NOTIFY("NOT FOUND: " .. tostring(service) .. "." .. tostring(reName), false) end return false end
        local ok, err = pcall(re.FireServer, re, ...)  -- fire-and-forget: ok=true only means SENT, not that the server accepted
        vxLog((ok and "sent " or ("ERR " .. tostring(err) .. " ")) .. service .. "." .. reName)
        if VX_DEBUG and not ok and VX_NOTIFY then VX_NOTIFY("ERROR firing " .. service .. "." .. reName, false) end
        return ok
end

-- Known JJS playable characters (each = <Name>Service). Used to read an enemy's character name for ESP and to
-- auto-pick which Service.Activated to fire for Down Slam / Uppercut without a dropdown.
local CHAR_NAMES = { "Itadori", "Gojo", "Hakari", "Megumi", "Mahito", "Choso", "Todo", "Hiromi", "Yuta", "Mechamaru", "Naoya", "Nanami", "Hanami", "Ryu", "Locust", "Yuki", "Charles", "Haruta", "MeiMei", "Kurourushi", "Sukuna" }
local CHAR_SET = {}
for _, n in ipairs(CHAR_NAMES) do CHAR_SET[n] = true end
local function detectCharName(model)  -- find a value/child on a character model that names a known character
        if not model then return nil end
        local found
        pcall(function()
                for _, d in ipairs(model:GetDescendants()) do
                        if d:IsA("StringValue") and CHAR_SET[d.Value] then found = d.Value; return end
                        if CHAR_SET[d.Name] and not d:IsA("BasePart") then found = d.Name; return end
                end
        end)
        return found
end
local function vxMyChar()  -- your live body (JJS keeps it under workspace.Characters)
        local LP = game:GetService("Players").LocalPlayer
        local chs = workspace:FindFirstChild("Characters")
        return (chs and chs:FindFirstChild(LP.Name)) or LP.Character
end
-- ═══ WHICH SERVICE IS MINE ═══ Down Slam / Uppercut fire <Char>Service.RE.Activated("Down"/"Up"), so we
-- must land on the RIGHT service. Guessing from a character name is unreliable, so we SCAN instead:
--   1) match a move in your Moveset to the service that owns it (captured names, most reliable)
--   2) match a detected character name
--   3) scan every service under Knit.Services and take one whose name matches a token on your character
-- Then we verify the candidate actually HAS RE.Activated before returning it.
local MOVE_TO_CHARSVC = {         -- move you own  ->  the character service that owns your M1 chain
        ["cursedstrikes"] = "Itadori",  ["divergentfist"] = "Itadori",  ["blackflash"] = "Itadori",
        ["lapseblue"]     = "Gojo",     ["twofoldkick"]   = "Gojo",     ["reversalred"] = "Gojo",  ["hollowpurple"] = "Gojo",
        ["nue"]           = "Megumi",   ["rabbitescape"]  = "Megumi",   ["divinedog"]   = "Megumi", ["toad"] = "Megumi",
        ["roughenergy"]   = "Hakari",   ["gamble"]        = "Hakari",
        ["flowingredscale"] = "Choso",  ["piercingblood"] = "Choso",    ["bloodedge"]   = "Choso",  ["supernova"] = "Choso",
        ["crushingjaws"]  = "Locust",   ["wingthrow"]     = "Locust",   ["clever"]      = "Locust",
        ["idletransfiguration"] = "Mahito", ["polymorphicsoul"] = "Mahito",
        ["crow"]          = "MeiMei",   ["blackbird"]     = "MeiMei",
        ["worldcutting"]  = "Toji",     ["playfulcloud"]  = "Toji",     ["inverted"]    = "Toji",
        ["rika"]          = "Yuta",     ["truelove"]      = "Yuta",
        -- Todo, from the user's captures. He NEEDS to be here rather than left to the scan below: his four moves
        -- each own a real <Move>Service with RE.Activated (SwiftKickService, BruteForceService, PebbleThrowService,
        -- ElbowDropService), so the name scan happily matched "SwiftKickService" off his own Moveset and fired
        -- Down/Up at a MOVE service. Listing him here means step 1 answers TodoService and the scan is never reached.
        ["swiftkick"]     = "Todo",     ["bruteforce"]    = "Todo",     ["pebblethrow"] = "Todo", ["elbowdrop"] = "Todo",
}
local function vxNorm(x) return (string.gsub(string.lower(tostring(x or "")), "[^%a%d]", "")) end
local function vxServicesFolder()
        local k = game:GetService("ReplicatedStorage"):FindFirstChild("Knit")
        k = k and k:FindFirstChild("Knit")
        return k and k:FindFirstChild("Services")
end
local function vxSvcHasActivated(name)
        local svcs = vxServicesFolder(); if not svcs then return false end
        local s = svcs:FindFirstChild(name); local re = s and s:FindFirstChild("RE")
        return (re and re:FindFirstChild("Activated")) and true or false
end
local function vxMyCharSvc()  -- which <Char>Service to fire for M1 / Down / Up
        local c = vxMyChar()
        -- 1) MOVESET MATCH (most reliable: your moves are unique to your character)
        if c then
                local mv = c:FindFirstChild("Moveset")
                if mv then
                        for _, m in ipairs(mv:GetChildren()) do
                                local who = MOVE_TO_CHARSVC[vxNorm(m.Name)]
                                if who and vxSvcHasActivated(who .. "Service") then
                                        if _G.VX_M1_DEBUG then print("[M1COMBO] service via move '" .. m.Name .. "' -> " .. who .. "Service") end
                                        return who .. "Service"
                                end
                        end
                end
        end
        -- 2) DETECTED CHARACTER NAME
        local n = detectCharName(c)
        if n and vxSvcHasActivated(n .. "Service") then
                if _G.VX_M1_DEBUG then print("[M1COMBO] service via character name -> " .. n .. "Service") end
                return n .. "Service"
        end
        -- 3) SCAN: any service whose name appears on your character (model/humanoid/moveset text)
        local svcs = vxServicesFolder()
        if svcs and c then
                local hay = vxNorm(c.Name)
                local hum = c:FindFirstChildOfClass("Humanoid"); if hum then hay = hay .. vxNorm(hum.DisplayName) end
                local mv = c:FindFirstChild("Moveset")
                -- ═══ A MOVE SERVICE IS NOT A CHARACTER SERVICE ═══ hay includes your Moveset names, and several moves
                -- own a service of their own with RE.Activated - so this scan would match "SwiftKickService" off Todo's
                -- own move list and hand Down/Up to the wrong remote entirely. Remember the move names and refuse any
                -- candidate whose base name IS one of them.
                local isMoveName = {}
                if mv then for _, m in ipairs(mv:GetChildren()) do local nm = vxNorm(m.Name); hay = hay .. nm; isMoveName[nm] = true end end
                for _, sv in ipairs(svcs:GetChildren()) do
                        local base = sv.Name:gsub("Service$", "")
                        if #base >= 4 and not isMoveName[vxNorm(base)] and string.find(hay, vxNorm(base), 1, true) and vxSvcHasActivated(sv.Name) then
                                if _G.VX_M1_DEBUG then print("[M1COMBO] service via scan -> " .. sv.Name) end
                                return sv.Name
                        end
                end
        end
        if _G.VX_M1_DEBUG then print("[M1COMBO] NO service resolved for your character") end
        return nil
end

-- ═══════════════════ A MOVE'S SERVICE IS DERIVABLE FROM ITS NAME ═══════════════════
-- Every capture the user has ever sent follows one rule, and nothing in this file was using it:
--     Moveset["Swift Kick"]    -> SwiftKickService.RE.Activated(move)
--     Moveset["Brute Force"]   -> BruteForceService.RE.Activated(move)
--     Moveset["Reserve Balls"] -> ReserveBallService.RE.Activated(move)          <- note the plural drops
--     Moveset["Shutter Doors"] -> ShutterDoorService.RE.Activated(move, target)  <- and again
-- i.e. take the move's own name, remove the spaces, add "Service". That is why the character-select dropdown
-- filled up with CursedBash / DecisiveStrike / ElbowRush: those are not characters, they are one service per
-- MOVE, and there are hundreds of them.
-- Deriving the name means Auto Air and anything else that casts a move never has to GUESS a service again -
-- which is what "auto air dont work" has been every single time: a hardcoded guess like RoughEnergyService or
-- CrushJawService that simply does not exist, failing silently.
local function vxSingular(s)          -- "Reserve Balls" -> "ReserveBall"; the game names services in singular
        s = tostring(s):gsub("%s+", "")
        return (s:gsub("s$", ""))
end
local function vxMoveService(moveName)
        if not moveName or moveName == "" then return nil end
        local svcs = vxServicesFolder(); if not svcs then return nil end
        local plain = tostring(moveName):gsub("%s+", "")
        -- 1) the exact name, 2) the singular, 3) a normalised sweep for anything else (casing, punctuation)
        for _, cand in ipairs({ plain .. "Service", vxSingular(moveName) .. "Service" }) do
                local s = svcs:FindFirstChild(cand)
                if s and s:FindFirstChild("RE") then return cand end
        end
        local wantA, wantB = vxNorm(plain), vxNorm(vxSingular(moveName))
        for _, sv in ipairs(svcs:GetChildren()) do
                local base = sv.Name:match("^(.-)Service$")
                if base then
                        local nb = vxNorm(base)
                        if (nb == wantA or nb == wantB) and sv:FindFirstChild("RE") then return sv.Name end
                end
        end
        return nil
end
-- Cast one of YOUR moves the way the captures do: the move's own service, with the Moveset entry as the
-- first argument, plus anything else the capture passed (Shutter Doors also takes the target character).
-- Returns true only if a remote was actually found and fired.
local function vxCastMove(moveName, ...)
        local c = vxMyChar()
        local rigs = { c }
        local lp = game:GetService("Players").LocalPlayer
        if lp.Character and lp.Character ~= c then rigs[#rigs + 1] = lp.Character end
        local obj, moveSlot
        for _, rig in ipairs(rigs) do
                local mv = rig and rig:FindFirstChild("Moveset")
                if mv then
                        local kids = mv:GetChildren()
                        for i, m in ipairs(kids) do
                                if m.Name == moveName or vxNorm(m.Name) == vxNorm(moveName) then obj = m; moveSlot = i break end
                        end
                        if obj then break end
                end
        end
        if not obj then
                if _G.VX_MOVE_DEBUG then print("[DreamHub Move] you do not own '" .. tostring(moveName) .. "'") end
                return false
        end
        -- ═══ IF THE REMOTE CANNOT BE RESOLVED, PRESS THE KEY ═══ A move the game gives you is always castable
        -- by its slot key, whatever the service is called. Falling back to that is the difference between "the
        -- assist does nothing" and "the assist casts the move" on every character whose services we cannot name.
        local function pressSlotKey()
                local KC = { Enum.KeyCode.One, Enum.KeyCode.Two, Enum.KeyCode.Three, Enum.KeyCode.Four }
                if not (moveSlot and KC[moveSlot]) then return false end
                _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[KC[moveSlot]] = tick() + 0.4
                _G.VX_INJECT_UNTIL = tick() + 0.4
                pcall(function()
                        local VIM = game:GetService("VirtualInputManager")
                        VIM:SendKeyEvent(true, KC[moveSlot], false, game); task.wait(0.05); VIM:SendKeyEvent(false, KC[moveSlot], false, game)
                end)
                if _G.VX_MOVE_DEBUG then print("[DreamHub Move] pressed slot " .. moveSlot .. " for '" .. tostring(obj.Name) .. "'") end
                return true
        end
        -- ═══ THE LEARNED REMOTE BEATS EVERY GUESS ═══ If the game itself has cast this move once this session,
        -- the namecall hook recorded the exact remote it used. Fire that and skip the name derivation entirely -
        -- this is the only path with zero assumptions in it.
        do
                local lr = _G.VX_MOVE_RE and _G.VX_MOVE_RE[obj.Name]
                if lr and lr.Parent then
                        local extraL = table.pack(...)
                        _G.VX_HUB_CAST = tick() + 0.25
                        local okL = pcall(function() lr:FireServer(obj, table.unpack(extraL, 1, extraL.n)) end)
                        if _G.VX_MOVE_DEBUG then print("[DreamHub Move] learned remote " .. (okL and "fired " or "FAILED ") .. "for " .. obj.Name) end
                        if okL then return true end
                end
        end
        local svcName = vxMoveService(obj.Name) or vxMoveService(moveName)
        if not svcName then
                -- _G.VX_NO_KEYFALLBACK: set by the universal AIR path, where the key press that got us here IS the
                -- cast - pressing it again just re-casts the ground version on top of our airborne one.
                if _G.VX_NO_KEYFALLBACK then return false end
                if _G.VX_MOVE_DEBUG then print("[DreamHub Move] no service for '" .. tostring(obj.Name) .. "' - pressing its key instead") end
                return pressSlotKey()
        end
        local svcs = vxServicesFolder()
        local re = svcs and svcs:FindFirstChild(svcName)
        re = re and re:FindFirstChild("RE"); re = re and re:FindFirstChild("Activated")
        if not re then
                -- This used to `return false` in silence - the most likely failure of the whole function, and it
                -- produced no key press, no remote, no message. Now it says so and still tries the key.
                if _G.VX_MOVE_DEBUG then print("[DreamHub Move] " .. svcName .. " exists but has no RE.Activated - key fallback") end
                if _G.VX_NO_KEYFALLBACK then return false end
                return pressSlotKey()
        end
        local extra = table.pack(...)
        -- Announce the cast, so Auto Cancel does not block the hub's own moves. Auto Cancel exists to swallow a
        -- MISCLICK; a move the hub deliberately fired is never a misclick.
        _G.VX_HUB_CAST = tick() + 0.25
        local ok = pcall(function() re:FireServer(obj, table.unpack(extra, 1, extra.n)) end)
        if _G.VX_MOVE_DEBUG then print("[DreamHub Move] " .. (ok and "fired " or "FAILED ") .. svcName .. ".RE.Activated(" .. obj.Name .. ")") end
        if not ok then return pressSlotKey() end
        return true
end
_G.VX_CAST_MOVE = vxCastMove    -- shared: Auto Air, Auto Hakari and anything else that casts by name

-- Black Flash timing is owned by BFApi; chains request a single swing.
-- ═══════════════════════ THE DASH IS A REMOTE ═══════════════════════
-- Your capture:
--     MovementService.RE.Dash:FireServer("Right")
-- This changes everything about the dash features. Every dash in this hub up to now was either a simulated
-- Q key press (which the game can ignore, and which competes with your own real presses) or a hand-rolled
-- arc of CFrame writes (which is what "the side dash animation is weird" has always been - the game plays
-- no dash clip at all while your body slides along a curve we invented).
-- Firing the game's own Dash remote is neither: the SERVER dashes you. Real animation, real distance, real
-- cooldown, nothing for the anti-cheat to disagree with, and nothing of ours fighting it.
local function vxDash(dir)
        local svcs = vxServicesFolder(); if not svcs then return false end
        local mv = svcs:FindFirstChild("MovementService")
        local re = mv and mv:FindFirstChild("RE"); re = re and re:FindFirstChild("Dash")
        if not re then
                if _G.VX_MOVE_DEBUG then print("[DreamHub Dash] MovementService.RE.Dash not found") end
                return false
        end
        dir = tostring(dir or "Right")
        _G.VX_HUB_DASH = tick() + 0.2   -- ours: the Dash-rewrite hook must not touch a direction we chose ourselves
        local ok = pcall(function() re:FireServer(dir) end)
        if _G.VX_MOVE_DEBUG then print("[DreamHub Dash] " .. (ok and "fired " or "FAILED ") .. "Dash(" .. dir .. ")") end
        return ok
end
_G.VX_DASH = vxDash

-- ═══════════════════════ ONE BUTTON THAT ANSWERS "WHY DOESN'T ANYTHING WORK" ═══════════════════════
-- Every round of this has been me reasoning about the code and you testing blind, and that loop is not
-- converging. This runs the ACTUAL resolution step of each broken feature - the same lookups the features
-- themselves do - and reports what it found. It fires no remotes and presses no keys, so it is safe to run
-- standing still in a lobby.
-- The report is printed to F9, shown on screen, AND copied to your clipboard, so it is one button and one
-- paste rather than a screenshot of a console.
_G.VX_DIAG = function()
        local L = {}
        local function add(s) L[#L + 1] = tostring(s) end
        local function yn(v) return v and "YES" or "NO" end

        add("===== DREAM HUB DIAGNOSTIC =====")

        -- 1) can we see the game's remotes at all? everything except teleport depends on this
        local svcs = vxServicesFolder()
        add("Knit Services folder: " .. yn(svcs ~= nil))
        if svcs then
                local n = 0
                for _ in ipairs(svcs:GetChildren()) do n = n + 1 end
                add("  services visible: " .. n)
        else
                add("  ^ THIS ALONE BREAKS: uppercut, auto air, twofold, hakari, swap, block")
        end

        -- 2) which rig are we on, and can we read the moveset the move remotes need
        local chs = workspace:FindFirstChild("Characters")
        local wRig = chs and chs:FindFirstChild(game:GetService("Players").LocalPlayer.Name)
        local pRig = game:GetService("Players").LocalPlayer.Character
        add("rig in workspace.Characters: " .. yn(wRig ~= nil) .. " | LocalPlayer.Character: " .. yn(pRig ~= nil))
        local mvRig, mv
        for _, r in ipairs({ wRig, pRig }) do
                local m = r and r:FindFirstChild("Moveset")
                if m then mvRig, mv = r, m break end
        end
        add("Moveset found: " .. yn(mv ~= nil) .. (mvRig and ("  (on " .. (mvRig == wRig and "workspace rig" or "LocalPlayer.Character") .. ")") or ""))
        local moveNames = {}
        if mv then for _, m in ipairs(mv:GetChildren()) do moveNames[#moveNames + 1] = m.Name end end
        add("  moves: " .. (#moveNames > 0 and table.concat(moveNames, ", ") or "NONE"))

        -- 3) every move resolved to the service the cast actually needs. This is the exact lookup Auto Air and
        --    Twofold do, so a NO here is precisely why they do nothing.
        if #moveNames > 0 then
                add("move -> service:")
                for _, nm in ipairs(moveNames) do
                        local sv = vxMoveService(nm)
                        add("  " .. nm .. "  ->  " .. (sv or ("MISSING (looked for " .. (nm:gsub("%s+", "")) .. "Service)")))
                end
        end

        -- 4) the character service - this is what the uppercut and down slam fire
        local okSvc, mySvc = pcall(vxMyCharSvc)
        add("my character service: " .. tostring(okSvc and mySvc or "ERROR"))
        if svcs and okSvc and mySvc then
                local s = svcs:FindFirstChild(mySvc); local re = s and s:FindFirstChild("RE")
                add("  RE.Activated: " .. yn(re and re:FindFirstChild("Activated") ~= nil))
        end

        -- 5) the other named remotes features depend on
        local function has(svc, re)
                if not svcs then return "no services folder" end
                local s = svcs:FindFirstChild(svc); local r = s and s:FindFirstChild("RE")
                if not s then return "no " .. svc end
                if not r then return svc .. " has no RE" end
                return yn(r:FindFirstChild(re) ~= nil)
        end
        add("BlockService.Activated: " .. has("BlockService", "Activated"))
        add("TodoService.RightActivated: " .. has("TodoService", "RightActivated"))
        add("JoinService.Change: " .. has("JoinService", "Change"))
        add("MovementService.Dash: " .. has("MovementService", "Dash"))

        -- 6) the flash engine's live state - the four things that decide whether a swing becomes a flash
        add("BF engine armed: " .. yn(_G.VX_BFAPI_ON == true)
                .. " | borrowed: " .. yn(_G.VX_BF_BORROWED == true)
                .. " | after N M1s: " .. tostring(_G.VX_BF_AFTER or 1))
        add("BF last flash: " .. (_G.VX_BF_LAST_FIRE and string.format("%.1fs ago", tick() - _G.VX_BF_LAST_FIRE) or "never this session"))
        add("BF last status: "..tostring(_G.VX_BF_LASTMSG or "no chain outcome yet"))
        add("BF local trace: "..table.concat(_G.VX_BF_TRACE or {}," | "))
        add("Finisher last status: "..tostring(_G.VX_FINISHER_STATUS or "no finisher outcome yet"))
        add("M1 packet hook: "..yn(_G.VX_M1HOOK_ON==true).." | basic remote observed: "..yn(_G.VX_OBSERVED_BASIC_RE~=nil))
        add("last human click age: "..string.format("%.2f",tick()-(tonumber(_G.VX_LAST_HUMAN_CLICK) or 0)).." s")
        add("captured M1 ids include mine: " .. yn((function()
                if not mvRig then return false end
                local h = mvRig:FindFirstChildOfClass("Humanoid")
                local a = h and h:FindFirstChildOfClass("Animator")
                if not a then return false end
                local ok, tracks = pcall(function() return a:GetPlayingAnimationTracks() end)
                if not ok then return false end
                for _, tr in ipairs(tracks) do
                        local oid, id = pcall(function() return string.match(tostring(tr.Animation.AnimationId), "%d+") end)
                        if oid and id and _G.VX_M1_IDS and _G.VX_M1_IDS[id] then return true end
                end
                return false
        end)()) .. "  (NO is expected on newer characters - the universal fallback covers it)")

        -- 7) teleport
        add("teleport method: " .. tostring(_G.VX_TP_METHOD or "Glide") .. " | speed: " .. tostring(_G.VX_TP_VEL or 90))
        local myR = wRig and wRig:FindFirstChild("HumanoidRootPart") or (pRig and pRig:FindFirstChild("HumanoidRootPart"))
        add("my HumanoidRootPart: " .. yn(myR ~= nil) .. (myR and ("  at " .. string.format("%.0f, %.0f, %.0f", myR.Position.X, myR.Position.Y, myR.Position.Z)) or ""))

        add("tier: " .. tostring(_G.__DreamTier or "?") .. " | executor clipboard: " .. yn(typeof(setclipboard) == "function"))
        add("===== END =====")

        local report = table.concat(L, "\n")
        pcall(function() print("\n" .. report) end)
        pcall(function() if setclipboard then setclipboard(report) end end)
        if VX_NOTIFY then VX_NOTIFY("Diagnostic copied to clipboard - paste it to me", true) end
        return report
end
local function vxClientDash(dir, speed, dur)  -- a REAL velocity dash relative to facing; guarantees visible motion even if the Dash remote is validation-only
        local char = vxMyChar(); local hrp = char and char:FindFirstChild("HumanoidRootPart"); if not hrp then return end
        local cf = hrp.CFrame
        local vmap = { Right = cf.RightVector, Left = -cf.RightVector, Front = cf.LookVector, Back = -cf.LookVector }
        local v = (vmap[dir] or cf.LookVector) * (speed or 95)
        task.spawn(function()
                local t0 = tick()
                while tick() - t0 < (dur or 0.13) do
                        pcall(function() hrp.AssemblyLinearVelocity = Vector3.new(v.X, math.min(hrp.AssemblyLinearVelocity.Y, 0), v.Z) end)  -- FLAT dash: never add upward velocity (no more "jump high"/glide up), still lets you fall
                        task.wait()
                end
        end)
end

-- MODULE: ITEM ESP + AUTO GRAB  (workspace.Items)
do
        local Players = game:GetService("Players")
        local LP = Players.LocalPlayer
        local espOn, grabOn, grabFilter, espFilter = false, false, "Any", "Any"
        local seasonalESP={C4=false,RPG=false}
        local espFolder = Instance.new("Folder")
        espFolder.Name = "VX_ItemESP"
        pcall(function() espFolder.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
        if not espFolder.Parent then espFolder.Parent = LP:WaitForChild("PlayerGui") end
        local boards = {}

        local containerNames={Items=true,Drops=true,ItemDrops=true,Pickups=true,Loot=true,WorldItems=true,
            DroppedItems=true,Collectables=true,Collectibles=true,Throwable=true,Throwables=true,Weapons=true,Tools=true}
        local containers=setmetatable({}, {__mode="k"})
        local tools=setmetatable({}, {__mode="k"})
        local seasonalLoose=setmetatable({}, {__mode="k"})
        -- Seed selectable names even before drops spawn, then extend from live assets.
        -- Catalog reference: https://bloxodes.com/wiki/jujutsu-shenanigans/items (checked 2026-10-17).
        local catalog={}
        for _,name in ipairs({"Soda","Jet Black","Coin","Gun","Playful Cloud","Transfigured Flesh",
            "Voice Recorder","Hazenoki's Eye","Sniper","Transfigured Human","Tinted Glasses","TNT",
            "Banana Peel","Naginata","Bowling Ball","Snowball","Crowbar","Nepcard","Broom",
            "Flashlight","Tiantui Star's Blade","Arayashiki","C4","RPG"}) do catalog[name]=true end
        local function displayName(m)
            local name=m:GetAttribute("ItemName") or m:GetAttribute("DisplayName")
            return type(name)=="string" and name~="" and name or m.Name
        end
        local function itemPart(m)
            if m:IsA("BasePart") then return m end
            if m:IsA("Model") and m.PrimaryPart then return m.PrimaryPart end
            return m:FindFirstChildWhichIsA("BasePart",true)
        end
        local function index(obj)
            if containerNames[obj.Name] and (obj:IsA("Folder") or obj:IsA("Model")) then containers[obj]=true end
            if obj:IsA("Tool") then tools[obj]=true; catalog[displayName(obj)]=true end
            local n=tostring(obj.Name):lower():gsub("[^%w]","")
            if (n=="c4" or n=="rpg") and (obj:IsA("BasePart") or obj:IsA("Model") or obj:IsA("Tool")) then seasonalLoose[obj]=true end
        end
        local replicated=game:GetService("ReplicatedStorage")
        for _,base in ipairs({workspace,replicated}) do
            for _,obj in ipairs(base:GetDescendants()) do index(obj) end
            base.DescendantAdded:Connect(index)
        end
        local function carried(m)
            local p=m.Parent
            while p and p~=workspace do
                if p:IsA("Model") and p:FindFirstChildOfClass("Humanoid") then return true end
                p=p.Parent
            end
            return false
        end
        local function allItems(includeTemplates)
            local out,seen={},{}
            local function add(m)
                if seen[m] or not m.Parent or not itemPart(m) then return end
                seen[m]=true; catalog[displayName(m)]=true
                if m:IsDescendantOf(workspace) and not carried(m) or includeTemplates and m:IsDescendantOf(replicated) then out[#out+1]=m end
            end
            local function children(folder,depth)
                if depth>5 then return end
                for _,m in ipairs(folder:GetChildren()) do
                    if m:IsA("Folder") or m:IsA("Model") and not itemPart(m) then children(m,depth+1)
                    elseif m:IsA("Model") or m:IsA("Tool") or m:IsA("BasePart") then add(m) end
                end
            end
            for f in pairs(containers) do if f.Parent and (f:IsDescendantOf(workspace) or includeTemplates and f:IsDescendantOf(replicated)) then children(f,0) end end
            for tool in pairs(tools) do add(tool) end
            for item in pairs(seasonalLoose) do add(item) end
            local roots={}
            for _,m in ipairs(out) do
                local p=m.Parent; local nested=false
                while p and p~=workspace and p~=replicated do
                    if seen[p] then nested=true; break end
                    p=p.Parent
                end
                if not nested then roots[#roots+1]=m end
            end
            return roots
        end
        local function matches(m,filter)
            if filter=="Any" then return true end
            local name=displayName(m)
            local function normalized(s) return s:lower():gsub("[^%w]","") end
            local wanted=normalized(filter)
            local raw=normalized(tostring(m.Name))
            return normalized(name)==wanted or raw==wanted
                or filter=="Sniper" and (name:lower():find("sniper",1,true)~=nil or raw:find("sniper",1,true)~=nil)
        end
        local function espWanted(m)
            return espOn and matches(m,espFilter)
                or seasonalESP.C4 and matches(m,"C4")
                or seasonalESP.RPG and matches(m,"RPG")
        end
        local function itemNames()
            allItems(true)
            local names={}; for name in pairs(catalog) do names[#names+1]=name end
            table.sort(names,function(a,b) return a:lower()<b:lower() end)
            table.insert(names,1,"Any"); return names
        end

        local function myChar() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end  -- JJS body lives under workspace.Characters (LP.Character lags = grab did nothing)
        local function myHRP() local c = myChar(); return c and (c:FindFirstChild("HumanoidRootPart") or c:FindFirstChildWhichIsA("BasePart")) end
        local function clearESP() for m, o in pairs(boards) do if o then if o.bb then o.bb:Destroy() end if o.hl then o.hl:Destroy() end end end boards = {} end
        local function buildESP()
                clearESP()
                for _, m in ipairs(allItems(false)) do
                        -- ═══ PICK WHAT GETS HIGHLIGHTED ═══ "add an option where they can pick which items
                        -- that they want to highlight." espFilter names ONE item type (or "Any"); everything
                        -- else gets no board at all.
                        if espWanted(m) then
                        local part = itemPart(m)
                        if part then
                                        -- ═══ LOOKS LIKE THE GAME'S OWN ITEM TRACKER, NOT AN ESP ═══ "make the item ESP
                                        -- more better for visualize. It look kind of AI, you know, you can just tell." The old
                                        -- dark rounded PILL with the gold stroke screamed overlay. This is what a clean
                                        -- game HUD label looks like: just the item name and distance, soft white text with a
                                        -- thin dark outline, a tiny marker dot, and it FADES with distance - no box, no
                                        -- background, nothing to point at.
                                        local bb = Instance.new("BillboardGui")
                                        bb.Adornee = part; bb.Size = UDim2.fromOffset(120, 18); bb.AlwaysOnTop = true; bb.StudsOffset = Vector3.new(0, 1.6, 0); bb.MaxDistance = 250; bb.Parent = espFolder
                                        local row = Instance.new("Frame"); row.Size = UDim2.fromScale(1, 1); row.BackgroundTransparency = 1; row.Parent = bb
                                        local list = Instance.new("UIListLayout"); list.FillDirection = Enum.FillDirection.Horizontal; list.VerticalAlignment = Enum.VerticalAlignment.Center; list.HorizontalAlignment = Enum.HorizontalAlignment.Center; list.Padding = UDim.new(0, 4); list.SortOrder = Enum.SortOrder.LayoutOrder; list.Parent = row
                                        local dot = Instance.new("Frame"); dot.LayoutOrder = 1; dot.Size = UDim2.fromOffset(4, 4); dot.BackgroundColor3 = Color3.fromRGB(255, 255, 255); dot.BackgroundTransparency = 0.25; dot.BorderSizePixel = 0; dot.Parent = row
                                        Instance.new("UICorner", dot).CornerRadius = UDim.new(1, 0)
                                        local lbl = Instance.new("TextLabel"); lbl.LayoutOrder = 2; lbl.AutomaticSize = Enum.AutomaticSize.X; lbl.Size = UDim2.new(0, 0, 1, 0); lbl.BackgroundTransparency = 1; lbl.Font = Enum.Font.GothamMedium; lbl.TextSize = 12; lbl.TextColor3 = Color3.fromRGB(240, 240, 244); lbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0); lbl.TextStrokeTransparency = 0.62; lbl.TextXAlignment = Enum.TextXAlignment.Left; lbl.Text = displayName(m); lbl.Parent = row
                                        boards[m] = { bb = bb, hl = nil, lbl = lbl, dot = dot, name = displayName(m) }
                        end
                        end
                end
        end
        task.spawn(function()
                while true do task.wait(0.4)
                        if espOn or seasonalESP.C4 or seasonalESP.RPG then
                                local wanted={}; local changed=false
                                for _,m in ipairs(allItems(false)) do if espWanted(m) then wanted[m]=true; if not boards[m] then changed=true end end end
                                for m in pairs(boards) do if not wanted[m] then changed=true end end
                                if changed then buildESP() end

                                local hrp = myHRP()
                                for m, o in pairs(boards) do
                                        if not (m and m.Parent) then if o.bb then o.bb:Destroy() end if o.hl then o.hl:Destroy() end boards[m] = nil
                                        else local part = itemPart(m)
                                                if part and o.lbl and hrp then
                                                        local dist = math.floor((part.Position - hrp.Position).Magnitude)
                                                        o.lbl.Text = o.name .. (((matches(m,"C4") or matches(m,"RPG")) and _G.VX_HOLIDAY_DISTANCE==false) and "" or ("  " .. dist .. " studs"))
                                                        -- fade with distance: far items melt into the world instead of hovering as bright tags
                                                        local fade = math.clamp((dist - 60) / 190, 0, 0.55)
                                                        o.lbl.TextTransparency = fade
                                                        o.lbl.TextStrokeTransparency = 0.62 + fade * 0.7
                                                        if o.dot then o.dot.BackgroundTransparency = 0.25 + fade end
                                                end
                                        end
                                end
                        elseif next(boards) then clearESP() end
                end
        end)
        task.spawn(function()
                local VIM = game:GetService("VirtualInputManager")
                while true do task.wait(0.5)
                        if grabOn then
                                local items = allItems(false); local hrp = myHRP()
                                if hrp then
                                        local bestModel, bestPart, bd
                                        for _, m in ipairs(items) do
                                                if matches(m,grabFilter) then
                                                        local part = itemPart(m)
                                                        if part then local d = (part.Position - hrp.Position).Magnitude; if not bd or d < bd then bestModel, bestPart, bd = m, part, d end end
                                                end
                                        end
                                        if bestPart then
                                                if bd and bd > 5 then vxGlide(bestPart.Position + Vector3.new(0, 2, 0)); task.wait(0.85) end  -- glide ONTO the item first
                                                local me = myChar()
                                                if me then
                                                        -- JJS items pick up by touch OR a ProximityPrompt OR the E key - do all three to be safe
                                                        if typeof(firetouchinterest) == "function" then
                                                                for _, ip in ipairs((bestModel and bestModel:GetDescendants()) or { bestPart }) do
                                                                        if ip:IsA("BasePart") then
                                                                                for _, mp in ipairs(me:GetChildren()) do
                                                                                        if mp:IsA("BasePart") then pcall(function() firetouchinterest(mp, ip, 0); firetouchinterest(mp, ip, 1) end) end
                                                                                end
                                                                        end
                                                                end
                                                        end
                                                        if typeof(fireproximityprompt) == "function" and bestModel then
                                                                for _, dpp in ipairs(bestModel:GetDescendants()) do if dpp:IsA("ProximityPrompt") then pcall(function() fireproximityprompt(dpp) end) end end
                                                        end
                                                        pcall(function() VIM:SendKeyEvent(true, Enum.KeyCode.E, false, game); task.wait(0.05); VIM:SendKeyEvent(false, Enum.KeyCode.E, false, game) end)
                                                end
                                        end
                                end
                        end
                end
        end)
        ItemsApi = {
                setESP = function(v) espOn = v == true; buildESP() end,
                setSeasonalESP = function(name,v)
                    if seasonalESP[name]~=nil then seasonalESP[name]=v==true;buildESP() end
                end,
                teleportItem = function(name)
                    local hrp=myHRP();if not hrp then return false end
                    local best,dist
                    for _,m in ipairs(allItems(false)) do
                        local part=matches(m,name) and itemPart(m)
                        if part then local d=(part.Position-hrp.Position).Magnitude
                            if not dist or d<dist then best,dist=part,d end
                        end
                    end
                    if not best then if VX_NOTIFY then VX_NOTIFY("No "..tostring(name).." item found",false) end;return false end
                    return vxGlide(best.Position+Vector3.new(0,2,0))
                end,
                setESPFilter = function(name)
                        if type(name) == "table" then name = name[1] end
                        name = name or "Any"
                        if name ~= espFilter then espFilter = name; if espOn then buildESP() end end
                end,
                setGrab = function(v) grabOn = v == true end,
                setFilter = function(name) if type(name) == "table" then name = name[1] end grabFilter = name or "Any" end,
                names = itemNames,
        }
end

-- ============================================================
-- MODULE: TARGET  (type a username -> TP / bring item / auto-farm / view / kills / throw trash)
-- ============================================================
do
    local Players = game:GetService("Players")
    local VIM = game:GetService("VirtualInputManager")
    local RunService = game:GetService("RunService")
    local LP = Players.LocalPlayer
    local targetName = ""
    local farmOn, viewOn = false, false
    local savedCamSubj = nil
    local function myChar() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
    local function myHRP() local c = myChar(); return c and (c:FindFirstChild("HumanoidRootPart") or c:FindFirstChildWhichIsA("BasePart")) end
    local function partOf(m) return m and (m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart or m:FindFirstChildWhichIsA("BasePart")) end
    -- resolve the typed name (case-insensitive, partial) to a Player + their live character model
    -- ═══ CLICK THE PLAYER = TARGET THE PLAYER ═══ "All you gotta do, just click the player and then it will
    -- just go and attack for you without you doing nothing." A Lock Target (click an enemy) drives this when
    -- no name is typed.
    local function resolve()
        if targetName == "" then
            local g = _G.VX_LOCK; local lt = (g and g.get) and g.get() or nil
            if lt and lt.Parent and lt:FindFirstChildOfClass("Humanoid") then
                local lplr = Players:FindFirstChild(lt.Name)
                return lplr, lt
            end
            return nil, nil
        end
        local low = string.lower(targetName)
        local plr
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP and (string.lower(p.Name) == low or string.lower(p.DisplayName) == low) then plr = p; break end
        end
        if not plr then for _, p in ipairs(Players:GetPlayers()) do if p ~= LP and (string.find(string.lower(p.Name), low, 1, true) or string.find(string.lower(p.DisplayName), low, 1, true)) then plr = p; break end end end
        if not plr then return nil, nil end
        local chs = workspace:FindFirstChild("Characters")
        local mdl = (chs and chs:FindFirstChild(plr.Name)) or plr.Character
        return plr, mdl
    end
    local function faceTo(pos) local r = myHRP(); if r and pos then pcall(function() r.CFrame = CFrame.lookAt(r.Position, Vector3.new(pos.X, r.Position.Y, pos.Z)) end) end end
    -- read the target's move cooldowns from their Moveset (each move often carries a CD attribute or a Debounce)
    local function readCooldowns(mdl)
        local out = {}
        local mv = mdl and mdl:FindFirstChild("Moveset")
        if mv then for _, m in ipairs(mv:GetChildren()) do
            local cd = m:GetAttribute("Cooldown") or m:GetAttribute("CD") or (m:GetAttribute("Debounce") and "on CD")
            out[#out + 1] = m.Name .. (cd and (": " .. tostring(cd)) or ": ready")
        end end
        return out
    end
    local function usedUlt(mdl, plr)
        -- awakening shows up as an attribute/tag or an "Awakened"/"Domain" object; best-effort read
        if mdl then
            for _, a in ipairs({ "Awakened", "Awakening", "Ult", "Ultimate", "Domain" }) do
                if mdl:GetAttribute(a) then return true end
            end
            if mdl:FindFirstChild("Domain") or mdl:FindFirstChild("Awakened") then return true end
        end
        return false
    end
    -- REAL CLICK on a world part: fire its ClickDetector directly (the reliable path), and ALSO aim a real
    -- mouse click at its on-screen position so click-scripted pickups that need a genuine click get one.
    local function clickOn(obj)
        local part = obj:IsA("BasePart") and obj or partOf(obj)
        if not part then return end
        pcall(function()
            if typeof(fireclickdetector) == "function" then
                local holder = obj:IsA("Model") and obj or part
                for _, cd in ipairs(holder:GetDescendants()) do if cd:IsA("ClickDetector") then fireclickdetector(cd) end end
                local cd = part:FindFirstChildOfClass("ClickDetector"); if cd then fireclickdetector(cd) end
            end
        end)
        pcall(function()
            local cam = workspace.CurrentCamera
            local sp, on = cam:WorldToViewportPoint(part.Position)
            if on then VIM:SendMouseButtonEvent(sp.X, sp.Y, 0, true, game, 0); task.wait(0.04); VIM:SendMouseButtonEvent(sp.X, sp.Y, 0, false, game, 0) end
        end)
    end
    -- did the pickup actually happen? you're holding a Tool, OR the item vanished / got welded onto you
    local function holdingSomething(item)
        local me = myChar()
        if me and me:FindFirstChildOfClass("Tool") then return true end
        if item and (not item.Parent or (me and item:IsDescendantOf(me))) then return true end
        return false
    end
    -- pick THIS item up and make sure it took: TP onto it, then CLICK it (detector + real mouse click) + touch
    -- + prompt + E, and verify; up to 3 tries before giving up. Returns true only when the pickup really landed.
    local function grabThis(best)
        local part = best:IsA("BasePart") and best or partOf(best)
        if not part then return false end
        vxTeleportHard(part.Position + Vector3.new(0, 2, 0), 1.2); task.wait(0.6)
        for _ = 1, 3 do
            local me = myChar()
            if me and typeof(firetouchinterest) == "function" then
                for _, ip in ipairs(best:IsA("Model") and best:GetDescendants() or { best }) do
                    if ip:IsA("BasePart") then
                        for _, mp in ipairs(me:GetChildren()) do
                            if mp:IsA("BasePart") then pcall(function() firetouchinterest(mp, ip, 0); firetouchinterest(mp, ip, 1) end) end
                        end
                    end
                end
            end
            if typeof(fireproximityprompt) == "function" and best:IsA("Model") then
                for _, dpp in ipairs(best:GetDescendants()) do
                    if dpp:IsA("ProximityPrompt") then pcall(function() fireproximityprompt(dpp) end) end
                end
            end
            clickOn(best)
            pcall(function() VIM:SendKeyEvent(true, Enum.KeyCode.E, false, game); task.wait(0.05); VIM:SendKeyEvent(false, Enum.KeyCode.E, false, game) end)
            task.wait(0.3)
            if holdingSomething(best) then return true end
        end
        return holdingSomething(best)
    end
    local function grabNearestItem(filter)   -- pick up an item (filter name or "Any"), returns true if grabbed
        local hrp = myHRP(); if not hrp then return false end
        local best, bd
        -- roots to search: Map.Destructible.Throwable FIRST (resolved inline — itemsFolder() lives in the ITEMS
        -- do-block and is NOT visible here; the old pcall(itemsFolder) was silently calling nil), then fallbacks
        local roots = {}
        for _, base in ipairs({ workspace:FindFirstChild("Map"), workspace }) do
            if base then local d = base:FindFirstChild("Destructible"); local t = d and d:FindFirstChild("Throwable"); if t then roots[#roots+1] = t end end
        end
        local mp = workspace:FindFirstChild("Map")
        for _, base in ipairs({ mp, workspace }) do
            if base then for _, fn in ipairs({ "Destructible", "Throwable", "Items", "Drops", "Loot" }) do
                local f = base:FindFirstChild(fn); if f then roots[#roots+1] = f end
            end end
        end
        for _, f in ipairs(roots) do
            for _, m in ipairs(f:GetDescendants()) do
                if (m:IsA("Model") or m:IsA("BasePart")) and (filter == "Any" or filter == nil or m.Name == filter) then
                    local part = m:IsA("BasePart") and m or partOf(m)
                    if part then local d = (part.Position - hrp.Position).Magnitude; if not bd or d < bd then best, bd = m, d end end
                end
            end
            if best then break end
        end
        if not best then return false end
        return grabThis(best)
    end
    -- AUTO FARM the target: TP behind + M1 loop
    task.spawn(function()
        while true do
            if farmOn then
                local _, mdl = resolve(); local tr = partOf(mdl)
                if tr and tr.Parent then
                    vxTeleportHard(tr.Position - (tr.CFrame.LookVector * 4) + Vector3.new(0, 0.5, 0), 0.5)
                    faceTo(tr.Position)
                    pcall(function()
                        local cam = workspace.CurrentCamera; local vp = (cam and cam.ViewportSize) or Vector2.new(1280, 720)
                        local cx, cy = vp.X / 2, vp.Y / 2   -- click SCREEN CENTER (0,0 was hitting the GUI corner = no M1)
                        VIM:SendMouseButtonEvent(cx, cy, 0, true, game, 0); task.wait(0.04); VIM:SendMouseButtonEvent(cx, cy, 0, false, game, 0)
                    end)
                    task.wait(0.28)
                else task.wait(0.4) end
            else task.wait(0.25) end
        end
    end)
    -- VIEW the target (spectate camera)
    task.spawn(function()
        while true do
            if viewOn then
                local _, mdl = resolve(); local h = mdl and mdl:FindFirstChildOfClass("Humanoid")
                local cam = workspace.CurrentCamera
                if cam and h then if savedCamSubj == nil then savedCamSubj = cam.CameraSubject end pcall(function() cam.CameraSubject = h end) end
                task.wait(0.3)
            else task.wait(0.3) end
        end
    end)
    -- FLOATING INFO CARD: the menu's Label element can't live-update on this UI lib ("I don't see their info"),
    -- so the target's profile shows on its OWN card: avatar, name, HP bar, ult, kills. Appears while a name is
    -- typed and a match exists; disappears when the box is cleared.
    local card = {}
    local function buildCard()
        if card.gui and card.gui.Parent then return end
        local g = Instance.new("ScreenGui"); g.Name = "VX_TargetCard"; g.ResetOnSpawn = false; g.IgnoreGuiInset = true; g.DisplayOrder = 9500
        pcall(function() g.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
        if not g.Parent then g.Parent = LP:WaitForChild("PlayerGui") end
        local f = Instance.new("Frame"); f.AnchorPoint = Vector2.new(1, 0); f.Position = UDim2.new(1, -14, 0, 96)
        f.Size = UDim2.fromOffset(240, 104); f.BackgroundColor3 = Color3.fromRGB(12, 12, 14); f.BackgroundTransparency = 0.04; f.BorderSizePixel = 0; f.Parent = g
        Instance.new("UICorner", f).CornerRadius = UDim.new(0, 10)
        local acc = (typeof(_G.VX_ACCENT) == "Color3") and _G.VX_ACCENT or Color3.fromRGB(220, 30, 40)
        local st = Instance.new("UIStroke"); st.Color = acc; st.Thickness = 1.3; st.Transparency = 0.2; st.Parent = f
        -- title bar
        local ttl = Instance.new("TextLabel"); ttl.BackgroundTransparency = 1; ttl.Position = UDim2.fromOffset(12, 6); ttl.Size = UDim2.new(1, -24, 0, 14)
        ttl.Font = Enum.Font.GothamBold; ttl.TextSize = 11; ttl.TextColor3 = acc; ttl.TextXAlignment = Enum.TextXAlignment.Left; ttl.Text = "TARGET INFO"; ttl.Parent = f
        local av = Instance.new("ImageLabel"); av.Position = UDim2.fromOffset(10, 26); av.Size = UDim2.fromOffset(44, 44); av.BackgroundColor3 = Color3.fromRGB(24, 24, 28); av.BorderSizePixel = 0; av.Parent = f
        Instance.new("UICorner", av).CornerRadius = UDim.new(1, 0)
        local nm = Instance.new("TextLabel"); nm.BackgroundTransparency = 1; nm.Position = UDim2.fromOffset(62, 26); nm.Size = UDim2.new(1, -70, 0, 16)
        nm.Font = Enum.Font.GothamBold; nm.TextSize = 12; nm.TextColor3 = Color3.fromRGB(240, 240, 244); nm.TextXAlignment = Enum.TextXAlignment.Left; nm.TextTruncate = Enum.TextTruncate.AtEnd; nm.Parent = f
        local meta = Instance.new("TextLabel"); meta.BackgroundTransparency = 1; meta.Position = UDim2.fromOffset(62, 43); meta.Size = UDim2.new(1, -70, 0, 14)
        meta.Font = Enum.Font.Gotham; meta.TextSize = 11; meta.TextColor3 = Color3.fromRGB(175, 175, 182); meta.TextXAlignment = Enum.TextXAlignment.Left; meta.Parent = f
        local hpBg = Instance.new("Frame"); hpBg.Position = UDim2.fromOffset(62, 61); hpBg.Size = UDim2.new(1, -74, 0, 8); hpBg.BackgroundColor3 = Color3.fromRGB(30, 30, 34); hpBg.BorderSizePixel = 0; hpBg.Parent = f
        Instance.new("UICorner", hpBg).CornerRadius = UDim.new(1, 0)
        local hpF = Instance.new("Frame"); hpF.Size = UDim2.fromScale(1, 1); hpF.BackgroundColor3 = Color3.fromRGB(90, 220, 100); hpF.BorderSizePixel = 0; hpF.Parent = hpBg
        Instance.new("UICorner", hpF).CornerRadius = UDim.new(1, 0)
        local hpT = Instance.new("TextLabel"); hpT.BackgroundTransparency = 1; hpT.Position = UDim2.fromOffset(12, 78); hpT.Size = UDim2.new(1, -20, 0, 16)
        hpT.Font = Enum.Font.Gotham; hpT.TextSize = 11; hpT.TextColor3 = Color3.fromRGB(210, 210, 216); hpT.TextXAlignment = Enum.TextXAlignment.Left; hpT.Parent = f
        card = { gui = g, frame = f, av = av, nm = nm, meta = meta, hpF = hpF, hpT = hpT, avFor = nil }
    end
    task.spawn(function()
        while true do
            task.wait(0.5)
            pcall(function()
                -- Card is ON by default (the in-GUI labels can't live-update on this UI lib). Set
                -- _G.VX_TARGET_CARD=false before the loadstring to hide it.
                if _G.VX_TARGET_CARD == false then if card.gui then card.gui.Enabled = false end return end
                if targetName == "" then if card.gui then card.gui.Enabled = false end return end
                local plr, mdl = resolve()
                if not plr then if card.gui then card.gui.Enabled = false end return end
                buildCard(); card.gui.Enabled = true
                local h = mdl and mdl:FindFirstChildOfClass("Humanoid")
                local hp, mx = (h and math.floor(h.Health) or 0), (h and math.floor(h.MaxHealth) or 100)
                card.nm.Text = plr.DisplayName .. " (@" .. plr.Name .. ")"
                local ls = plr:FindFirstChild("leaderstats"); local kills = "?"
                if ls then for _, s in ipairs(ls:GetChildren()) do if s.Name:lower():find("kill") then kills = tostring(s.Value) break end end end
                -- FRIENDS: fetch the count once per target (async + cached; harmless if the API is rate-limited)
                if card.friendsFor ~= plr.UserId then
                    card.friendsFor = plr.UserId; card.friends = "..."
                    task.spawn(function()
                        local ok, pages = pcall(function() return Players:GetFriendsAsync(plr.UserId) end)
                        if ok and pages then
                            local n = 0
                            pcall(function() while true do for _ in ipairs(pages:GetCurrentPage()) do n += 1 end; if pages.IsFinished then break end; pages:AdvanceToNextPageAsync() end end)
                            card.friends = tostring(n)
                        else card.friends = "?" end
                    end)
                end
                card.meta.Text = "Ult: " .. (usedUlt(mdl, plr) and "USED" or "no") .. "   Kills: " .. kills .. "   Friends: " .. tostring(card.friends or "...")
                card.hpF.Size = UDim2.fromScale(math.clamp(hp / math.max(mx, 1), 0, 1), 1)
                card.hpF.BackgroundColor3 = (hp / math.max(mx, 1)) > 0.5 and Color3.fromRGB(90, 220, 100) or ((hp / math.max(mx, 1)) > 0.25 and Color3.fromRGB(235, 200, 70) or Color3.fromRGB(230, 70, 70))
                card.hpT.Text = "HP " .. hp .. " / " .. mx
                if card.avFor ~= plr.UserId then
                    card.avFor = plr.UserId
                    task.spawn(function() local ok, u = pcall(function() return Players:GetUserThumbnailAsync(plr.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size100x100) end); if ok and u then card.av.Image = u end end)
                end
            end)
        end
    end)
    TargetApi = {
        setName = function(n) targetName = tostring(n or "") end,
        tpTo = function()
            local plr, mdl = resolve()
            -- Private server: the game's own "Go" teleport (DebugService) moves you server-side - use it
            -- whenever the target is a real Player; the write-based teleport stays as the fallback.
            if plr and _G.VX_TP_TO_PLAYER and _G.VX_TP_TO_PLAYER(plr) then return end
            local tr = partOf(mdl)
            if tr then vxTeleportHard(tr.Position - (tr.CFrame.LookVector * 4) + Vector3.new(0, 1, 0), 2)
            elseif VX_NOTIFY then VX_NOTIFY("Target not found", false) end
        end,
        bringItem = function(filter)
            task.spawn(function()
                if grabNearestItem(filter) then
                    task.wait(0.15)
                    local _, mdl = resolve(); local tr = partOf(mdl)
                    if tr then vxTeleportHard(tr.Position + Vector3.new(0, 1, 0), 2) end   -- the held item comes with you
                elseif VX_NOTIFY then VX_NOTIFY("No item to bring", false) end
            end)
        end,
        throwTrash = function()
            task.spawn(function()
                -- STEP 1 — GET TRASH IN HAND (verified, not assumed): grab a loose Trash item; if there is none,
                -- find the nearest TRASH CAN and CLICK IT (detector + a real mouse click on it) to get trash out,
                -- then grab that. grabThis/grabNearestItem only return true when you're actually holding it.
                local got = grabNearestItem("Trash")
                if not got then
                    local hrp = myHRP()
                    local can, cd
                    if hrp then
                        for _, m in ipairs(workspace:GetDescendants()) do
                            if (m:IsA("Model") or m:IsA("BasePart")) then
                                local n = string.lower(m.Name)
                                if n:find("trash", 1, true) and (n:find("can", 1, true) or n:find("bin", 1, true) or m:FindFirstChildWhichIsA("ClickDetector", true)) then
                                    local p = m:IsA("BasePart") and m or partOf(m)
                                    if p then local d = (p.Position - hrp.Position).Magnitude; if not cd or d < cd then can, cd = m, d end end
                                end
                            end
                        end
                    end
                    if can then
                        local p = can:IsA("BasePart") and can or partOf(can)
                        if p then vxTeleportHard(p.Position + Vector3.new(0, 2, 0), 1.2); task.wait(0.5) end
                        clickOn(can)   -- click ON the trash can to get the trash out
                        pcall(function() VIM:SendKeyEvent(true, Enum.KeyCode.E, false, game); task.wait(0.05); VIM:SendKeyEvent(false, Enum.KeyCode.E, false, game) end)
                        task.wait(0.5)
                        got = grabNearestItem("Trash") or holdingSomething(nil)
                    end
                end
                if not got then if VX_NOTIFY then VX_NOTIFY("No trash found (checked loose trash + trash cans)", false) end return end
                -- STEP 2 — THROW IT AT THE TARGET: TP in front, face them, M1 at SCREEN CENTER (a 0,0 click hits
                -- the GUI corner and throws nothing — same fix the Auto Farm click needed).
                task.wait(0.2)
                local _, mdl = resolve(); local tr = partOf(mdl)
                if not tr then if VX_NOTIFY then VX_NOTIFY("Holding trash, but the target wasn't found", false) end return end
                vxTeleportHard(tr.Position - (tr.CFrame.LookVector * 5) + Vector3.new(0, 1, 0), 1.5); task.wait(0.35)
                faceTo(tr.Position)
                pcall(function()
                    local cam = workspace.CurrentCamera; local vp = (cam and cam.ViewportSize) or Vector2.new(1280, 720)
                    local cx, cy = vp.X / 2, vp.Y / 2
                    VIM:SendMouseButtonEvent(cx, cy, 0, true, game, 0); task.wait(0.05); VIM:SendMouseButtonEvent(cx, cy, 0, false, game, 0)
                end)
            end)
        end,
        setFarm = function(v) farmOn = v == true end,
        setView = function(v)
            viewOn = v == true
            if not viewOn then local cam = workspace.CurrentCamera; if cam and savedCamSubj then pcall(function() cam.CameraSubject = savedCamSubj end) end; savedCamSubj = nil end
        end,
        kills = function()
            local plr = resolve()
            if not plr then return "N/A" end
            local ls = plr:FindFirstChild("leaderstats")
            for _, nm in ipairs({ "Kills", "Wins", "KOs", "Kill" }) do local s = ls and ls:FindFirstChild(nm); if s then return tostring(s.Value) end end
            return "0"
        end,
        info = function()
            local plr, mdl = resolve()
            if not plr then return { found = false } end
            local h = mdl and mdl:FindFirstChildOfClass("Humanoid")
            return {
                found = true,
                name = plr.DisplayName .. " (@" .. plr.Name .. ")",
                userId = plr.UserId,
                health = h and math.floor(h.Health) or 0,
                maxHealth = h and math.floor(h.MaxHealth) or 100,
                ult = usedUlt(mdl, plr),
                cooldowns = readCooldowns(mdl),
            }
        end,
    }
end

-- ============================================================
-- MODULE: AUTO QTE CLICK  (Higuruma "Final Judgment" / Deadly Sentencing)
-- When you're judged, a QTE appears (buttons Confess / Silence / Denial, 3s timer; no answer = Silence auto-picked
-- and that's the losing outcome). This auto-clicks your chosen answer the instant the QTE shows, at Click Delay.
-- Also handles any generic mash-button QTE that pops in PlayerGui.
-- ============================================================
do
    local Players = game:GetService("Players")
    local VIM = game:GetService("VirtualInputManager")
    local LP = Players.LocalPlayer
    local enabled, choice, clickDelay = false, "Silence", 0
    local qteCPS, qteTapGap = 45, 0.02   -- Final Judgment key-sequence solver: presses/sec + down->up gap (both slider-set)
    local WANT = { "confess", "silence", "denial" }   -- the Deadly Sentencing options
    -- PC answers with KEYS (W / A / D), one per option; clicking the button is the MOBILE path only.
    -- Default map matches the on-screen layout (left/up/right); remap via the dropdowns if the game differs.
    local KEYMAP = { confess = Enum.KeyCode.A, silence = Enum.KeyCode.W, denial = Enum.KeyCode.D }
    local UIS_Q = game:GetService("UserInputService")
    local function clickGuiButton(btn)
        local ap, sz = btn.AbsolutePosition, btn.AbsoluteSize
        local x, y = ap.X + sz.X / 2, ap.Y + sz.Y / 2
        pcall(function() VIM:SendMouseButtonEvent(x, y, 0, true, game, 0); task.wait(0.03); VIM:SendMouseButtonEvent(x, y, 0, false, game, 0) end)
    end
    -- THE REAL ANSWER REMOTES (user captures):
    -- We fire BOTH so it lands regardless of which the current game build uses.
    local ANSWER_NUM = { confess = 3, silence = 2, denial = 1 }
    local function myCharQ() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
    local function fireAnswer(word)
        local n = ANSWER_NUM[word]
        local ok = false
        pcall(function()
            local doms = workspace:FindFirstChild("Domains")
            local dom = doms and doms:FindFirstChild("Domain")
            local re = dom and dom:FindFirstChild("UnreliableRemoteEvent") or (dom and dom:FindFirstChildWhichIsA("UnreliableRemoteEvent")) or (dom and dom:FindFirstChildWhichIsA("RemoteEvent"))
            if re and n then re:FireServer(n); ok = true end
        end)
        pcall(function()   -- per-character confirm remote
            local c = myCharQ(); local cre = c and c:FindFirstChild("RemoteEvent")
            if cre then cre:FireServer(true); ok = true end
        end)
        return ok
    end
    local function pressAnswer(word)
        if fireAnswer(word) then return end   -- remote answered: done (the reliable path)
        local kc = KEYMAP[word]; if not kc then return end
        pcall(function() VIM:SendKeyEvent(true, kc, false, game); task.wait(0.06); VIM:SendKeyEvent(false, kc, false, game) end)
    end
    -- ZERO-LAG detection: NO full PlayerGui sweep (that GetDescendants scan 12x/sec was the "FPS drop when
    -- Final Judgment is on"). We keep a tiny CANDIDATE cache filled by DescendantAdded (cheap, event-driven)
    -- plus one initial sweep, and the loop only checks the handful of cached judgment elements.
    local candidates = setmetatable({}, { __mode = "k" })
    local function consider(d)
        if not (d:IsA("TextButton") or d:IsA("ImageButton") or d:IsA("TextLabel")) then return end
        local txt = string.lower(((d:IsA("TextLabel") or d:IsA("TextButton")) and d.Text or "") .. " " .. d.Name)
        for _, w in ipairs(WANT) do if string.find(txt, w, 1, true) then candidates[d] = w; return end end
    end
    task.spawn(function()
        local pg = LP:WaitForChild("PlayerGui", 10)
        if not pg then return end
        pcall(function() for _, d in ipairs(pg:GetDescendants()) do consider(d) end end)   -- one-time seed
        pg.DescendantAdded:Connect(function(d) task.defer(function() pcall(consider, d) end) end)
    end)
    -- the nil-instance ANSWER remote (user's SimpleSpy capture: a nil-parented RemoteEvent fired with `true`)
    local function fireJudgmentRemote()
        if typeof(getnilinstances) ~= "function" then return end
        pcall(function()
            for _, v in ipairs(getnilinstances()) do
                if v.ClassName == "RemoteEvent" then
                    local n = string.lower(v.Name)
                    if n:find("judg") or n:find("answer") or n:find("choice") or n:find("sentenc") or n:find("court") or n:find("qte") then
                        pcall(function() v:FireServer(true) end)
                    end
                end
            end
        end)
    end
    -- Is a Deadly Sentencing judgment ACTIVE on us? (the domain remote exists = we're in someone's judgment)
    local function judgmentActive()
        local doms = workspace:FindFirstChild("Domains"); local dom = doms and doms:FindFirstChild("Domain")
        if dom and (dom:FindFirstChild("UnreliableRemoteEvent") or dom:FindFirstChildWhichIsA("UnreliableRemoteEvent")) then return true end
        local c = myChar(); if c and c:FindFirstChild("RemoteEvent") then return true end   -- per-char confirm remote present
        for d in pairs(candidates) do if d.Parent and d.Visible then return true end end
        return false
    end
    task.spawn(function()
        local lastFire = 0
        while true do
            if enabled then
                local want = string.lower(choice)
                local picked, anyBtn, anyWord
                for d, w in pairs(candidates) do
                    if d.Parent and d.Visible then anyBtn, anyWord = d, w; if w == want then picked = d end end
                end
                -- Fire when we SEE the option buttons OR when a judgment is simply active (the game may not
                -- expose the option words in PlayerGui) — throttled so we don't spam the remote.
                if (anyBtn or judgmentActive()) and tick() - lastFire > 0.5 then
                    lastFire = tick()
                    local word = picked and want or (anyWord or want)
                    if anyBtn and UIS_Q.TouchEnabled and not UIS_Q.KeyboardEnabled then   -- MOBILE: tap the option
                        local hit = picked or anyBtn
                        if hit:IsA("TextButton") or hit:IsA("ImageButton") then clickGuiButton(hit) end
                    end
                    fireAnswer(word)          -- the real remotes (domain n + per-char true)
                    pressAnswer(word)         -- + W/A/D keys as backup
                    fireJudgmentRemote()      -- + the nil-instance remote as backup
                    task.wait(0.3)
                end
                task.wait(clickDelay > 0 and clickDelay or 0.12)
            else task.wait(0.25) end
        end
    end)
    -- ANTI FINAL JUDGMENT: an enemy Higuruma starts the judgment -> DASH AWAY before it lands (face away + Q + hold S).
    local antiJudge = false
    task.spawn(function()
        local VIMj = game:GetService("VirtualInputManager")
        local lastDodge = 0
        while true do
            if antiJudge then
                local hit = false
                for d in pairs(candidates) do if d.Parent and d.Visible then hit = true break end end   -- judgment UI just showed on us
                if hit and tick() - lastDodge > 2 then
                    lastDodge = tick()
                    pcall(function()
                        local chs = workspace:FindFirstChild("Characters"); local c = (chs and chs:FindFirstChild(LP.Name)) or LP.Character
                        local r = c and c:FindFirstChild("HumanoidRootPart")
                        -- face AWAY from the nearest enemy then dash
                        local nearest
                        if r then local bd for _, m in ipairs((chs and chs:GetChildren()) or {}) do if m.Name ~= LP.Name then local tr = m:FindFirstChild("HumanoidRootPart"); if tr then local dd = (tr.Position - r.Position).Magnitude; if not bd or dd < bd then nearest, bd = tr, dd end end end end end
                        if r and nearest then
                            if _G.VX_ACPASS then _G.VX_ACPASS() end
                            local away = (r.Position - nearest.Position); away = Vector3.new(away.X, 0, away.Z)
                            if away.Magnitude > 0.1 then r.CFrame = CFrame.lookAt(r.Position, r.Position + away.Unit) end
                        end
                        VIMj:SendKeyEvent(true, Enum.KeyCode.W, false, game)
                        VIMj:SendKeyEvent(true, Enum.KeyCode.Q, false, game); task.wait(0.06); VIMj:SendKeyEvent(false, Enum.KeyCode.Q, false, game)
                        task.wait(0.5)
                        VIMj:SendKeyEvent(false, Enum.KeyCode.W, false, game)
                    end)
                end
                task.wait(0.15)
            else task.wait(0.3) end
        end
    end)
    -- ── FINAL JUDGMENT KEY-SEQUENCE SOLVER ─────────────────────────────────────────────────────────────
    -- Some Final Judgment builds don't use Confess/Silence/Denial buttons — they FLASH A SEQUENCE OF KEYS
    -- (digits/letters) you must press fast. This rides the same Auto QTE toggle: it finds the "QTE" GUI, reads
    -- the currently-shown key, and taps it at qteCPS presses/sec. Speed + tap gap are slider-adjustable.
    local QDIGITS = {
        ["0"] = Enum.KeyCode.Zero, ["1"] = Enum.KeyCode.One, ["2"] = Enum.KeyCode.Two, ["3"] = Enum.KeyCode.Three,
        ["4"] = Enum.KeyCode.Four, ["5"] = Enum.KeyCode.Five, ["6"] = Enum.KeyCode.Six, ["7"] = Enum.KeyCode.Seven,
        ["8"] = Enum.KeyCode.Eight, ["9"] = Enum.KeyCode.Nine,
    }
    local function qUpper(s) return type(s) == "string" and string.upper(s) or "" end
    local function qKeyFrom(str)
        str = qUpper(str):gsub("%s+", "")
        if #str ~= 1 then return nil end
        if str:match("%a") then return Enum.KeyCode[str] end
        return QDIGITS[str]
    end
    local cachedQTE
    local function findQTE()
        if cachedQTE and cachedQTE.Parent then return cachedQTE end
        cachedQTE = nil
        local pGui = LP:FindFirstChild("PlayerGui"); if not pGui then return nil end
        for _, g in ipairs(pGui:GetChildren()) do
            if string.find(qUpper(g.Name), "QTE") then
                if not g:IsA("ScreenGui") or g.Enabled then cachedQTE = g; return g end
            end
        end
        for _, d in ipairs(pGui:GetDescendants()) do
            if d:IsA("GuiObject") and string.find(qUpper(d.Name), "QTE") then cachedQTE = d; return d end
        end
        return nil
    end
    local function qShown(o)
        local node = o
        while node and node:IsA("GuiObject") do if node.Visible == false then return false end; node = node.Parent end
        return true
    end
    local function qCurrentKey(qte)
        local best, bestScore
        for _, o in ipairs(qte:GetDescendants()) do
            if (o:IsA("TextLabel") or o:IsA("TextButton")) and o.Visible then
                local key = qKeyFrom(o.Text) or qKeyFrom(o.Name)
                if key and qShown(o) then
                    local opaque = 1 - math.clamp(o.TextTransparency or 0, 0, 1)
                    local score = opaque * 10 + (o.ZIndex or 0)
                    if not bestScore or score > bestScore then bestScore, best = score, key end
                end
            end
        end
        return best
    end
    local function qTap(key)
        pcall(function() VIM:SendKeyEvent(true, key, false, game); task.wait(qteTapGap > 0 and qteTapGap or 0.02); VIM:SendKeyEvent(false, key, false, game) end)
    end
    task.spawn(function()
        local last = 0
        while true do
            if enabled then
                local gap = 1 / math.max(qteCPS, 1)
                if os.clock() - last >= gap then
                    local qte = findQTE()
                    if qte then local key = qCurrentKey(qte); if key then qTap(key); last = os.clock() end end
                end
                task.wait()
            else task.wait(0.25) end
        end
    end)
    AutoQTEApi_setAnti = function(v) antiJudge = v == true end
    AutoQTEApi = {
        set = function(v) enabled = v == true end,
        setChoice = function(c) choice = tostring(c or "Silence") end,
        setDelay = function(v) if type(v) == "number" then clickDelay = v / 100 end end,   -- slider is 0-100 -> 0-1s
        setSpeed = function(v) if type(v) == "number" then qteCPS = math.clamp(v, 1, 120) end end,           -- Final Judgment: presses per second
        setTapGap = function(v) if type(v) == "number" then qteTapGap = math.clamp(v / 1000, 0, 0.2) end end, -- Final Judgment: ms slider -> seconds between down/up
    }
end

-- ============================================================
-- MODULE: VXBF2  — reworked Black Flash chain engine (keybind 3, not E). No GUI; driven by _G.VXBF2 setters.
-- Ported from the user's v13.0 logic, adapted for JJS: bodies live under workspace.Characters, teleports use
-- ============================================================
do
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local UserInputService = game:GetService("UserInputService")
    local VIM = game:GetService("VirtualInputManager")
    local LocalPlayer = Players.LocalPlayer

    local Settings = {
        DashKey = Enum.KeyCode.Q, DashRange = 80, DashCooldown = 0.20,
        SideChoice = "Auto", SideCurveTime = 0.35, SideM1 = true, SideM1Count = 1, SideFaceAfter = true,
        Enabled = false, Mode = "Side Dash", BFKey = Enum.KeyCode.Three,
        -- ═══ REDUCED from 1.35 to 0.5 ═══ The 1.35s cooldown was too long - "M1 BF only works once then never
        -- again" because every other swing in a held combo was rejected. 0.5s matches the reference engine and
        -- lets consecutive M1s in a combo each flash.
        BFCooldown = 0, BFTeleportDist = 3.0, BFM1 = false,
        SideAssist = false, BackAssist = false,
    }
    -- Shared so the finisher assists can perform a REAL, legit dash-in ("dash all the way, in a normal way")
    -- instead of writing your CFrame across the map. One source of truth for which key the game dashes on.
    _G.VX_DASH_KEY = Settings.DashKey
    local AnimationTriggers = {
        -- Restored: Divergent Fist IS the Black Flash input on Itadori (see the engine table).
        ["rbxassetid://100962226150441"] = 0.19,
        ["rbxassetid://95852624447551"] = 0.19,
        ["rbxassetid://74145636023952"] = 0.19, ["rbxassetid://72475960800126"] = 0.20,
        ["rbxassetid://123171106092050"] = 0.19,
    }
    local R = { held = {}, stamp = {}, lastDash = 0, lockTarget = nil, lockKind = nil, lockEnd = 0, bfCD = 0, bfActive = false, curving = false, chainUntil = 0, gen = 0 }
    local WIN = 0.15
    local function status(_) end   -- no-op: don't announce which BF mode fired (hide the mechanism)
    local function acPass() if _G.VX_ACPASS then _G.VX_ACPASS() end end
    local function GetChar() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LocalPlayer.Name)) or LocalPlayer.Character end
    local function GetRoot() local c = GetChar(); return c and c:FindFirstChild("HumanoidRootPart") end
    local function IsAlive() local c = GetChar(); local h = c and c:FindFirstChildOfClass("Humanoid"); return h ~= nil and h.Health > 0 end
    -- R.stamp is PRIVATE to this module. Every other key consumer in the file guards on the SHARED
    -- _G.VX_INJ_KEYS, so without stamping that too, our injected dash key was read as a real player press by
    -- the Dash module - which fired its own MovementService dash (105 studs/s) and played a FORWARD dash clip
    -- straight over a sideways arc. Two movement systems fighting on the same body for 0.15s, with a clip that
    -- does not belong to the mode: that is "the animations are weird / the side dashes are weird".
    local function VKeyDown(k) if not k then return end R.stamp[k] = tick(); _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[k] = tick() + 0.4; if not R.held[k] then R.held[k] = true; VIM:SendKeyEvent(true, k, false, game) end end
    local function VKeyUp(k) if not k then return end _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[k] = tick() + 0.15; if R.held[k] then R.held[k] = nil; VIM:SendKeyEvent(false, k, false, game) end end
    -- ═══ A DASH IS NOT A WINDUP ═══ Every mode taps the real dash key so the game plays its own dash
    -- animation. That animation is Action priority (it has to override walk/run) and it lands right after you
    -- clicked, which is precisely the shape of the flash engine's universal windup fallback - so the engine
    -- read our dash as an M1 and spent the chain's single-shot borrow on it. The real M1 windup arriving a
    -- moment later was then rejected as "already used". Tell the engine to ignore anything for the length of
    -- the dash.
    local function VKeyTap(k, hold)
        if k == Settings.DashKey then _G.VX_BF_DASHANIM = tick() + 0.30 end
        VKeyDown(k); task.wait(hold or 0.05); VKeyUp(k)
    end
    -- A synthetic click CANCELS an in-flight Crow ult, so every scripted click is suppressed while it is out.
    local function VMouseClick()
        if tick() < (tonumber(_G.VX_CROW_FLYING) or 0) then return false end
        _G.VX_SYNTH_CLICK = tick()+0.25
        local vp = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize
        local x,y = vp and vp.X/2 or 400, vp and vp.Y/2 or 300
        local ok = pcall(function() VIM:SendMouseButtonEvent(x,y,0,true,game,0); task.wait(0.03) end)
        local released = pcall(function() VIM:SendMouseButtonEvent(x,y,0,false,game,0) end)
        return ok and released
    end
    local function ReleaseAll() for k in pairs(R.held) do pcall(function() VIM:SendKeyEvent(false, k, false, game) end) end table.clear(R.held) end
    local function markThree() R.stamp[Enum.KeyCode.Three] = tick(); _G.VX_INJECT_UNTIL = tick() + 0.4; _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Three] = tick() + 0.4 end   -- VX_INJECT_UNTIL too: Reversal Red checks only that one, and its R cancels the flash
    -- SAME RULE AS THE ENGINE: the BF key is slot 3, and slot 3 is only Black Flash on the characters that
    -- have Black Flash as an ability. On everyone else this was casting their third move (Trip, on Jawbreaker)
    -- every time a chain wanted a flash. When the character has no such ability we throw the timed re-tap
    -- instead, which is the actual Black Flash mechanic and works on everyone.
    -- Key 3 IS the Black Flash input (see the note in the engine). Always press it; "Never" is the only
    -- opt-out, for anyone who wants the re-click on its own.
    -- ═══ A 3 WITHOUT A WINDUP IS JUST DIVERGENT FIST ═══ "even if I have m1 bf chain or m1 bf off, it
    -- still does divergent fist when I m1." The twin press paths fired 3 on a timer after your click; when
    -- the M1 windup was live at that instant, that press is a Black Flash - when it was not (whiff, dropped
    -- swing, timing skew), the SAME press is a raw Divergent Fist cast. So every timed press now checks a
    -- windup is actually playing first. Flash kept, DF spam gone.
    local function windupLive()
        local ok, res = pcall(function()
            for _, c in ipairs({ GetChar(), LocalPlayer.Character }) do
                local h = c and c:FindFirstChildOfClass("Humanoid")
                local a = h and h:FindFirstChildOfClass("Animator")
                if a then
                    for _, tr in ipairs(a:GetPlayingAnimationTracks()) do
                        if tr.IsPlaying and tr.TimePosition < 0.5 then
                            local id = tostring(tr.Animation.AnimationId)
                            local nid = id:match("%d+")
                            if (nid and _G.VX_M1_IDS and _G.VX_M1_IDS[nid]) or AnimationTriggers[id] then return true end
                        end
                    end
                end
            end
            return false
        end)
        return ok and res or false
    end
    local function pressBF()
        -- ═══ 3 IS ONLY A FLASH IF A WINDUP IS PLAYING ═══ Otherwise the exact same press casts slot 3 raw -
        -- Divergent Fist on Itadori. That is "when I M1 with other modes on it does DivFist even with M1 BF
        -- off". windupLive is the single truth: a real M1 windup on your rig right now. No windup, no press.
        -- The engine's own key-3 is already tied to a windup it SAW; this gate covers every OTHER caller
        -- (the click path, the anim hook, the chain fallback) at one choke point.
        if not windupLive() then
            if _G.VX_BF_DEBUG then print("[DreamHub BF] pressBF skipped - no windup (would be raw slot-3)") end
            return
        end
        if _G.VX_BF_PRESSKEY == "Never" then VMouseClick() return end
        markThree()
        _G.VX_BF_PRESS_T = tick()
        VIM:SendKeyEvent(true, Settings.BFKey, false, game)
        task.wait(0.03)   -- the source script holds it 0.025; long enough to register, short enough not to charge anything
        VIM:SendKeyEvent(false, Settings.BFKey, false, game)
    end
    -- ═══ WHY THE OTHER BF MODES NEVER FLASHED ═══ Black Flash only lands when it is timed onto a CONNECTING M1.
    -- "M1 Chain" works because it triggers off your click, so an M1 is already landing. Side Dash / Back Dash /
    -- Jump / Teleport trigger off key 3, so they pressed 3 with nothing connecting and it just did nothing.
    -- This throws the M1 first and presses 3 in the same window the proven M1-BF path uses (~0.19s after the
    -- swing starts), which is what actually produces the flash.
    -- Rather than guessing a fixed delay, this ARMS the same anim-timed path the working M1-BF uses: it watches
    -- your real M1 animation and presses 3 at the exact frame offset. We just throw the M1 and let that hook do
    -- the timing. R.bfCD is cleared first because the mode functions stamp it on entry, which would otherwise
    -- make the hook's own cooldown check swallow the flash.
    -- Throw the M1 and let the PROVEN engine (BFApi, armed by the Mode dropdown) time the key-3 press off your
    -- real swing animation. We deliberately do NOT press 3 ourselves here — a blind press does nothing, and two
    -- presses would fight. The pressBF fallback only runs if BFApi is unavailable for some reason.
    -- BORROW the flash engine for THIS beat only, then give it straight back. Leaving it armed is what made
    -- every ordinary M1 auto-flash while the user's own "M1 Black Flash" toggle was off. _G.VX_BFAPI_WANT holds
    -- the user's real choice (bfM1On or bfAutoOn); we restore exactly that, never just "on".
    -- ═══ NEVER FLASH BEFORE YOU ARRIVE ═══ "it must not press 3 until it's at the target, no matter how far
    -- they are". The dash can be cut short (target moved, MAXDASH refused, the arc bailed on radius), and the
    -- old code pressed on a fixed delay regardless - so the flash went off from wherever you happened to be.
    -- This blocks the beat until you are genuinely in M1 range, and gives up rather than flashing from range.
    local function arrivedAt(t, maxWait)
        local e = t and t:FindFirstChild("HumanoidRootPart"); if not e then return false end
        local t0 = tick()
        while tick() - t0 < (maxWait or 0.5) do
            local p = GetRoot()
            local ee = t.Parent and t:FindFirstChild("HumanoidRootPart")
            if not (p and ee) then return false end
            if (ee.Position - p.Position).Magnitude <= 9 then return true end   -- inside M1 reach
            task.wait()
        end
        local p = GetRoot()
        local ee = t.Parent and t:FindFirstChild("HumanoidRootPart")
        return (p and ee and (ee.Position - p.Position).Magnitude <= 9) or false
    end
    -- ═══════════ m1ThenBF, REBUILT TO **BE** AUTO BF ═══════════
    -- "use the Auto BF logic and make it BF, it is not that hard." Correct. Auto BF is two things: the engine
    -- is ENABLED, and you throw a REAL M1 - the engine's onAnim then sees the windup and presses 3. That is
    -- ALL it is, and it works. Every failure of the chains came from the machinery I built AROUND that -
    -- borrow guards, STRICT flags, single-shot counters, chainclick windows, token hand-backs - each one
    -- another way for the engine to refuse a swing it would happily have flashed for Auto BF.
    -- So this is gone. A chain now does exactly what you do when Auto BF works: make sure the engine is on,
    -- and throw a genuine M1 (the game's own Activated(false) remote + the click for the animation). The
    -- engine flashes it, because to the engine it is indistinguishable from one of your Auto-BF swings.
    local function m1ThenBF(t,validate,mode)
        if not BFApi or not t or not t.Parent then return false end
        local token=BFApi.ArmChain(validate,mode)
        _G.VX_BF_CHAINCLICK=tick(); _G.VX_BF_CHAINDRIVE=tick()+2
        R.chainUntil=tick()+2
        _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Three]=tick()+0.3
        pcall(function() VIM:SendKeyEvent(false,Enum.KeyCode.Three,false,game) end)
        local gen=R.gen
        if R.gen~=gen then BFApi.CancelChain(token); return false end
        local ok=BFApi.StartChain(token)
        return ok,token
    end
    local function GetClosestTarget(maxD)
        local r=GetRoot(); if not r then return end
        local function valid(m)
            local e=m and m.Parent and m:FindFirstChild("HumanoidRootPart")
            local h=m and m:FindFirstChildOfClass("Humanoid")
            return e and h and h.Health>0 and m~=GetChar() and m.Name~=LocalPlayer.Name and (e.Position-r.Position).Magnitude<=(maxD or 60)
        end
        local g=_G.VX_LOCK; local selected=g and g.get and g.get()
        if valid(selected) then return selected end
        local best,dist=nil,maxD or 60
        for _,m in ipairs(_G.VX_LIVING_MODELS()) do if valid(m) then
            local d=(m.HumanoidRootPart.Position-r.Position).Magnitude
            if d<=dist then best,dist=m,d end
        end end
        return best
    end

    local function aimCameraDir(dir) local cam = workspace.CurrentCamera; if not cam then return end local pos = cam.CFrame.Position; local flat = Vector3.new(dir.X, 0, dir.Z); if flat.Magnitude < 0.01 then return end cam.CFrame = CFrame.new(pos, pos + flat.Unit) end
    local function aimCameraAt(p) local cam = workspace.CurrentCamera; if not cam then return end local pos = cam.CFrame.Position; cam.CFrame = CFrame.new(pos, Vector3.new(p.X, pos.Y, p.Z)) end
    local function faceRootDir(dir) local r = GetRoot(); if not r then return end local flat = Vector3.new(dir.X, 0, dir.Z); if flat.Magnitude < 0.01 then return end acPass(); r.CFrame = CFrame.new(r.Position, r.Position + flat.Unit) end
    local function faceEnemyBack(t)
        local p = GetRoot(); local e = t and t:FindFirstChild("HumanoidRootPart"); if not p or not e then return end
        local fwd = Vector3.new(e.CFrame.LookVector.X, 0, e.CFrame.LookVector.Z)
        if fwd.Magnitude > 0.01 then acPass(); p.CFrame = CFrame.new(e.Position - fwd * 5.2, e.Position) end   -- match the lock's hold distance (was 3 = a visible yank backwards)
    end
    local function autoSide(p, e) local eR = Vector3.new(e.CFrame.RightVector.X, 0, e.CFrame.RightVector.Z); if eR.Magnitude < 0.01 then return -1 end eR = eR.Unit; local off = Vector3.new((p.Position - e.Position).X, 0, (p.Position - e.Position).Z); return (off:Dot(eR) >= 0) and 1 or -1 end
    local function chooseSide(p, e, c) if UserInputService:IsKeyDown(Enum.KeyCode.A) then return -1 end if UserInputService:IsKeyDown(Enum.KeyCode.D) then return 1 end if c == "Left" then return -1 end if c == "Right" then return 1 end return autoSide(p, e) end
    local function smoothTP(pos) local p = GetRoot(); if not p then return end acPass(); p.CFrame = CFrame.new(pos); local cc = GetChar(); if cc then pcall(function() cc:PivotTo(CFrame.new(pos)) end) end end
    -- ALWAYS AIM AT THE BACK: turn your body AND the camera to look at their spine after any approach. Rotation
    -- only — no position write — so it cannot shove them or trip the movement checks.
    local function faceBackOf(t)
        local e = t and t:FindFirstChild("HumanoidRootPart"); if not e then return end
        local p = GetRoot(); if not p then return end
        pcall(function()
            p.CFrame = CFrame.lookAt(p.Position, Vector3.new(e.Position.X, p.Position.Y, e.Position.Z))
        end)
        aimCameraAt(e.Position)
    end
    -- ═══ SOFT FACE: the same settle, but LERPED over a few frames ═══ The single write version squares you to
    -- their spine in ONE frame, and that one-frame snap is exactly the "it just teleports" tell on the Q side
    -- dash assist. This one converges the rotation across ~3 frames (position never moves - the look target is
    -- rebuilt from my own spot every frame, so only the rotation is blended). Reads as a player settling.
    local function faceBackOfSoft(t, frames)
        local e = t and t:FindFirstChild("HumanoidRootPart"); local p = GetRoot()
        if not e or not p then return end
        for _ = 1, (frames or 5) do
            if not (t.Parent and e.Parent and p.Parent) then break end
            pcall(function()
                local goal = CFrame.lookAt(p.Position, Vector3.new(e.Position.X, p.Position.Y, e.Position.Z))
                acPass()
                p.CFrame = p.CFrame:Lerp(goal, 0.5)
            end)
            aimCameraAt(e.Position)
            RunService.Heartbeat:Wait()
        end
    end
    -- ═══ LEGIT DASH TO THE BACK (replaces the old smoothTP+faceEnemyBack teleport) ═══
    -- Presses the REAL dash key so the game plays its own dash animation, then rides the shared anti-fling arc
    -- (_G.VX_ORBIT: per-frame speed cap, collisions off, velocity zeroed, live target tracking) around to their
    -- back. This is a travelled path, not a position write — it reads as a player dashing, never a blink.
    -- opts: duration, endRadius, extraSweep (rad; math.pi*2 = full 360), yArc (jump arc), dir (-1 L / 1 R).
    local MAXDASH=26
    local backAimMode="Center"
    local BF_RANGE=8
    local clickLock,clickedTarget=false,nil
    local chainClick,usedChainClick=0,0
    local chainClickAt=-math.huge
    local function chainHumanClick()
        if tick()-chainClickAt>0.025 then chainClick+=1;chainClickAt=tick() end
    end
    if _G.VX_M1_SUB then _G.VX_M1_SUB("bf-chain-click",chainHumanClick) end
    local function closeBF(t,front)
        local r=GetRoot(); local e=t and t.Parent and t:FindFirstChild("HumanoidRootPart")
        local h=t and t:FindFirstChildOfClass("Humanoid")
        if not r or not e or not h or h.Health<=0 or t==GetChar() then return false end
        local delta=e.Position-r.Position
        if delta.Magnitude>BF_RANGE or math.abs(delta.Y)>4.5 then return false end
        local flat=Vector3.new(delta.X,0,delta.Z)
        return not front or flat.Magnitude<0.1 or flat.Unit:Dot(r.CFrame.LookVector)>0.35
    end
    local function bfTarget(front)
        if clickLock then return closeBF(clickedTarget,front) and clickedTarget or nil end
        local best,dist=nil,BF_RANGE+0.01
        for _,t in ipairs(_G.VX_LIVING_MODELS()) do
            if closeBF(t,front) then
                local d=(t:FindFirstChild("HumanoidRootPart").Position-GetRoot().Position).Magnitude
                if d<dist then best,dist=t,d end
            end
        end
        return best
    end
    UserInputService.InputBegan:Connect(function(input,processed)
        if input.UserInputType==Enum.UserInputType.MouseButton1 and not UserInputService:GetFocusedTextBox()
            and tick()>=(tonumber(_G.VX_SYNTH_CLICK) or 0) then chainHumanClick() end
        if not clickLock or processed or UserInputService:GetFocusedTextBox()
            or input.UserInputType~=Enum.UserInputType.MouseButton1
            or tick()<(tonumber(_G.VX_SYNTH_CLICK) or 0) then return end
        local hit=LocalPlayer:GetMouse().Target
        while hit and hit~=workspace do
            if hit:IsA("Model") and hit:FindFirstChildOfClass("Humanoid") and hit~=GetChar() then
                clickedTarget=hit; _G.VX_BF_LASTMSG="chain target: "..hit.Name; return
            end
            hit=hit.Parent
        end
    end)

    local function atBack(t,maxDistance,center)
        local r=GetRoot(); local e=t and t.Parent and t:FindFirstChild("HumanoidRootPart")
        local h=t and t:FindFirstChildOfClass("Humanoid")
        if not r or not e or not h or h.Health<=0 then return false end
        local delta=r.Position-e.Position
        local flat=Vector3.new(delta.X,0,delta.Z)
        local forward=Vector3.new(e.CFrame.LookVector.X,0,e.CFrame.LookVector.Z)
        if forward.Magnitude<0.01 or math.abs(delta.Y)>4.5 or flat.Magnitude>(maxDistance or 5.5) then return false end
        forward=forward.Unit
        local behind=-flat:Dot(forward)
        local side=math.abs(flat:Dot(Vector3.new(-forward.Z,0,forward.X)))
        if center=="Side" then return behind>=1.8 and side>=0.4 and side<=2.0 end
        -- ═══ r14: CENTER-BACK GATE WIDENED ═══ "with Center Back on it never hits the back." The old
        -- dead-centre test (behind 2.2, side 0.55) only passes on a statue - a target that walks or turns
        -- half a stud mid-dash failed it, the dash timed out "missed back-hit range" and NO cast happened
        -- at all. The engine's own validate still enforces the real flash window at press time; this gate
        -- only has to let a live target through.
        if center then return behind>=1.7 and side<=0.55 end
        return behind>=1.5 and flat.Magnitude>=1.5 and flat.Unit:Dot(forward)<=-0.65
    end

    local function lockBackAim(t,mode,followRear,rearDistance)
        if R.aimCleanup then R.aimCleanup() end
        local camera=workspace.CurrentCamera
        local body=GetChar(); local h=body and body:FindFirstChildOfClass("Humanoid")
        local rotation=camera and camera.CFrame.Rotation
        local autoRotate=h and h.AutoRotate
        local generation=R.gen
        local release
        local function aim()
            local root=GetRoot(); local e=t and t.Parent and t:FindFirstChild("HumanoidRootPart")
            if generation~=R.gen or GetChar()~=body or not IsAlive() or not root or not e then if release then release() end; return end
            local back=e.Position-e.CFrame.LookVector*0.35+Vector3.new(0,0.7,0)
            if mode=="Side" then local f=e.CFrame.LookVector; back+=Vector3.new(-f.Z,0,f.X)*0.7 end
            -- During a rear chain, use ordinary movement briefly to follow a moving target.
            -- It is bounded by the chain lifetime and never writes character position.
            if followRear and h and h.Parent then
                local forward=Vector3.new(e.CFrame.LookVector.X,0,e.CFrame.LookVector.Z)
                if forward.Magnitude>0.01 then
                    local goal=e.Position-forward.Unit*(tonumber(rearDistance) or 2.6)
                    local delta=Vector3.new(goal.X-root.Position.X,0,goal.Z-root.Position.Z)
                    h:Move(delta.Magnitude>(rearDistance and 0.25 or 0.5) and delta.Unit or Vector3.zero,false)
                end
            end
            -- Rotation follows the target while native movement controls position.
            if (Vector3.new(back.X,root.Position.Y,back.Z)-root.Position).Magnitude>0.1 then
                root.CFrame=CFrame.lookAt(root.Position,Vector3.new(back.X,root.Position.Y,back.Z))
            end
            if camera and workspace.CurrentCamera==camera then
                camera.CFrame=CFrame.lookAt(camera.CFrame.Position,back)
                R.sequenceRotation=camera.CFrame.Rotation
            end
        end
        if h then h.AutoRotate=false end
        local cleaned=false
        release=function()
            if cleaned then return end; cleaned=true
            pcall(function() RunService:UnbindFromRenderStep("VX_BackAim") end)
            if h and h.Parent then
                if followRear then h:Move(Vector3.zero,false) end
                h.AutoRotate=autoRotate
            end
            -- Leave the final target-facing view in place when releasing aim ownership.
            if R.aimCleanup==release then R.aimCleanup=nil end
        end
        R.aimCleanup=release
        RunService:BindToRenderStep("VX_BackAim",Enum.RenderPriority.Camera.Value+40,aim)
        aim(); return release
    end
    -- One native Q dash, or one Space hop. Only rotation and native movement input are steered.
    local function dashToBack(t,opts)
        opts=opts or {}
        local root=GetRoot(); local enemy=t and t.Parent and t:FindFirstChild("HumanoidRootPart")
        local body=GetChar(); local h=body and body:FindFirstChildOfClass("Humanoid")
        local camera=workspace.CurrentCamera
        local range=math.clamp(tonumber(opts.range) or MAXDASH,8,50)
        if not root or not enemy or not h or not camera or (root.Position-enemy.Position).Magnitude>range then return false end
        local gen,rotation,autoRotate=R.gen,camera.CFrame.Rotation,h.AutoRotate
        local jump=opts.jump==true
        local side=chooseSide(root,enemy,opts.side or Settings.SideChoice)
        local direction=jump and Enum.KeyCode.W or opts.forward and Enum.KeyCode.W or opts.back and Enum.KeyCode.S or (side<0 and Enum.KeyCode.A or Enum.KeyCode.D)
        local action=jump and Enum.KeyCode.Space or Settings.DashKey
        local bound="VX_NativeDashAim"
        local duration=jump and 0.65 or (opts.legacySide and 0.48 or (opts.settle and 0.80 or 0.55))
        if opts.reach then duration=math.clamp(0.32+math.max(0,(root.Position-enemy.Position).Magnitude-opts.reach)/60,0.40,0.8) end
        local saved,connections,edges={},{},{}
        local function expectEdge(key,pressed)
            if UserInputService:IsKeyDown(key)~=pressed then edges[key]={pressed=pressed,expires=tick()+0.08} end
        end
        local movementKeys={Enum.KeyCode.W,Enum.KeyCode.A,Enum.KeyCode.S,Enum.KeyCode.D}
        local injecting,airborne,accepted,arrived,started=false,false,false,false,false
        local launchAt; local startPosition=root.Position
        local oldSpeed=h.WalkSpeed
        local jumpSpeed=jump and math.max(oldSpeed,40) or nil
        local oldJumpPower,oldJumpHeight=h.JumpPower,h.JumpHeight
        local hopPower=jump and h.UseJumpPower and oldJumpPower>0 and math.min(oldJumpPower,40) or nil
        local hopHeight=jump and not h.UseJumpPower and oldJumpHeight and oldJumpHeight>0 and math.min(oldJumpHeight,4) or nil
        local intent
        if not jump then
            intent={body=body,stage="prepare",direction=direction==Enum.KeyCode.A and "Left" or direction==Enum.KeyCode.D and "Right" or direction==Enum.KeyCode.S and "Back" or "Front",expires=tick()+duration+0.3}
            _G.VX_SIDE_DASH_INTENT=intent
        end
        local function live()
            local targetHum=t.Parent and t:FindFirstChildOfClass("Humanoid")
            return gen==R.gen and GetChar()==body and IsAlive() and targetHum and targetHum.Health>0
                and not UserInputService:GetFocusedTextBox() and (not opts.validate or opts.validate())
        end
        local function reached()
            if opts.reach then return (root.Position-enemy.Position).Magnitude<=math.clamp(opts.reach,4,8) end
            if not atBack(t,opts.legacySide and 3.5 or 4,opts.center) then return false end
            if opts.rearDistance then
                local f=Vector3.new(enemy.CFrame.LookVector.X,0,enemy.CFrame.LookVector.Z)
                local delta=Vector3.new(root.Position.X-enemy.Position.X,0,root.Position.Z-enemy.Position.Z)
                if f.Magnitude<0.01 or -delta:Dot(f.Unit)<opts.rearDistance-0.25 then return false end
            end
            return true
        end
        local function steer()
            if not live() then return end
            root=GetRoot(); enemy=t:FindFirstChild("HumanoidRootPart")
            if not root or not enemy then return end
            local offset=Vector3.new(root.Position.X-enemy.Position.X,0,root.Position.Z-enemy.Position.Z)
            local f=Vector3.new(enemy.CFrame.LookVector.X,0,enemy.CFrame.LookVector.Z)
            if f.Magnitude<0.01 then return end
            f=f.Unit
            local goal=enemy.Position-f*(opts.legacySide and 3 or (tonumber(opts.rearDistance) or 2.6))
            if opts.settle and opts.center~="Side" then
                local ev=enemy.AssemblyLinearVelocity
                local sideAxis=Vector3.new(-f.Z,0,f.X)
                local lead=math.clamp(Vector3.new(ev.X,0,ev.Z):Dot(sideAxis)*0.05,-0.30,0.30)
                goal+=sideAxis*lead
            end
            if opts.center=="Side" then goal+=Vector3.new(-f.Z,0,f.X)*1.2 end
            if opts.reach then goal=enemy.Position end
            local direct=Vector3.new(goal.X-root.Position.X,0,goal.Z-root.Position.Z)
            local desired
            -- Jump crosses OVER the target. Reusing the side-dash tangent made it veer left/right.
            if jump or opts.direct or offset.Magnitude<0.1 then desired=direct
            else
                local radial=offset.Unit
                if opts.reach and offset.Magnitude>8 or (opts.referenceSide and radial:Dot(f)<-0.75) or (not opts.referenceSide and radial:Dot(f)<-0.35) then desired=direct
                else desired=Vector3.new(-radial.Z,0,radial.X)*(opts.referenceSide and -side or side)-radial*math.clamp((offset.Magnitude-3.2)/3,-0.2,1.7) end
            end
            -- Side and M1 approaches keep steering during the remaining native dash.
            -- Other modes retain their existing handoff behavior.
            if (reached() and not opts.settle) or desired.Magnitude<0.1 then h:Move(Vector3.zero,false); return end
            desired=desired.Unit
            local look=desired
            if not jump then
                if direction==Enum.KeyCode.A then look=Vector3.new(-desired.Z,0,desired.X)
                elseif direction==Enum.KeyCode.D then look=Vector3.new(desired.Z,0,-desired.X)
                elseif direction==Enum.KeyCode.S then look=-desired end
            end
            if opts.referenceSide then
                local toward=Vector3.new(enemy.Position.X-root.Position.X,0,enemy.Position.Z-root.Position.Z)
                if toward.Magnitude>0.1 then
                    local blended=look*0.55+toward.Unit*0.45
                    if blended.Magnitude>0.1 then look=blended.Unit end
                end
            end
            camera.CFrame=CFrame.lookAt(camera.CFrame.Position,camera.CFrame.Position+look)
            root.CFrame=CFrame.lookAt(root.Position,root.Position+look)
            -- A refused Q must not become half a second of ordinary strafing.
            if jump or not launchAt or tick()-launchAt<0.04 or accepted then h:Move(desired,false)
            else h:Move(Vector3.zero,false) end
        end
        local ok,err=pcall(function()
            h.AutoRotate=false
            if jumpSpeed then h.WalkSpeed=jumpSpeed end
            if hopPower then h.JumpPower=hopPower end
            if hopHeight then h.JumpHeight=hopHeight end
            for _,key in ipairs(movementKeys) do saved[key]=UserInputService:IsKeyDown(key) end
            local function physical(input,pressed)
                local key=input.KeyCode
                if saved[key]==nil then return end
                local edge=edges[key]
                if edge and tick()<=edge.expires and edge.pressed==pressed then edges[key]=nil;return end
                if not injecting then saved[key]=pressed end
            end
            connections[1]=UserInputService.InputBegan:Connect(function(input) physical(input,true) end)
            connections[2]=UserInputService.InputEnded:Connect(function(input) physical(input,false) end)
            _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {}
            injecting=true
            for _,key in ipairs(movementKeys) do expectEdge(key,false);_G.VX_INJ_KEYS[key]=tick()+0.08; VIM:SendKeyEvent(false,key,false,game) end
            injecting=false
            RunService:BindToRenderStep(bound,Enum.RenderPriority.Camera.Value+5,steer)
            steer()
            expectEdge(direction,true);VKeyDown(direction)
            RunService.RenderStepped:Wait()
            if not jump then RunService.RenderStepped:Wait() end
            if not live() then return end
            -- Space starts immediately; the short native hop supplies its own approach.
            launchAt=tick(); startPosition=root.Position
            if intent then intent.stage="input" end
            _G.VX_INJ_KEYS[action]=tick()+duration+0.2
            if not jump then _G.VX_BF_DASHANIM=tick()+duration end
            VKeyDown(action)
            if jump then h.Jump=true end
            task.wait(jump and 0.025 or 0.045); VKeyUp(action)
            local deadline=launchAt+duration
            local jumpRetryAt=launchAt+0.07
            repeat
                if not live() then return end
                local v=root.AssemblyLinearVelocity
                local speed=Vector3.new(v.X,0,v.Z).Magnitude
                if v.Y>3 or h.FloorMaterial==Enum.Material.Air and root.Position.Y-startPosition.Y>0.25 then airborne=true end
                if jump and not airborne and tick()>=jumpRetryAt and tick()-launchAt<0.30 then
                    jumpRetryAt=tick()+0.07;h.Jump=false
                    VKeyDown(action);h.Jump=true;task.wait(0.025);VKeyUp(action)
                end
                if not jump and speed>math.max(oldSpeed*1.3,24) and (root.Position-startPosition).Magnitude>0.3 then accepted=true end
                local aligned=true
                if opts.settle and opts.center~="Side" then
                    local f=Vector3.new(enemy.CFrame.LookVector.X,0,enemy.CFrame.LookVector.Z)
                    if f.Magnitude>0.01 then
                        f=f.Unit
                        local sideAxis=Vector3.new(-f.Z,0,f.X)
                        local ev=enemy.AssemblyLinearVelocity
                        local lead=math.clamp(Vector3.new(ev.X,0,ev.Z):Dot(sideAxis)*0.05,-0.30,0.30)
                        local offset=Vector3.new(root.Position.X-enemy.Position.X,0,root.Position.Z-enemy.Position.Z):Dot(sideAxis)
                        aligned=math.abs(offset-lead)<=0.15 or tick()-launchAt>=0.65
                    end
                end
                local ready=reached() and aligned and tick()-launchAt>=(jump and 0.06 or 0.12) and (jump and airborne and v.Y<=0 or not jump and accepted)
                -- Do not turn the root toward the target while Q is still carrying it past the rear.
                -- Waiting is bounded by the existing dash deadline and does not inject another dash.
                if ready and (not opts.settle or speed<=math.max(oldSpeed*1.3,24)) then arrived=true; return end
                if tick()-launchAt>(jump and 0.42 or (opts.settle and 0.24 or 0.12)) and (jump and not airborne or not jump and not accepted) then return end
                -- An unsuccessful hop never becomes a ground walk around the opponent.
                -- A head landing is not the ground: keep native forward travel across it, within the same hop.
                if jump and airborne and h.FloorMaterial~=Enum.Material.Air and v.Y<=0 and root.Position.Y-enemy.Position.Y<1.5 then return end
                RunService.Heartbeat:Wait()
            until tick()>=deadline
        end)
        pcall(function() RunService:UnbindFromRenderStep(bound) end)
        pcall(function() VKeyUp(action);expectEdge(direction,false); VKeyUp(direction); h:Move(Vector3.zero,false) end)
        if intent and _G.VX_SIDE_DASH_INTENT==intent then _G.VX_SIDE_DASH_INTENT=nil end
        if jump and h.Parent then
            h.Jump=false
            -- Restore only our own value; a move may have set a different speed.
            if h.WalkSpeed==jumpSpeed then h.WalkSpeed=oldSpeed end
            if hopPower and h.JumpPower==hopPower then h.JumpPower=oldJumpPower end
            if hopHeight and h.JumpHeight==hopHeight then h.JumpHeight=oldJumpHeight end
        end
        if h.Parent then h.AutoRotate=autoRotate end
        arrived=ok and arrived and live() and reached()
        if _G.VX_TRACE and R.bfActive then
            _G.VX_TRACE((jump and "jump" or "dash")..(arrived and ":rear-reached" or ":rear-not-reached"))
            local own=GetRoot();local target=t and t.Parent and t:FindFirstChild("HumanoidRootPart")
            if own and target then
                local f=Vector3.new(target.CFrame.LookVector.X,0,target.CFrame.LookVector.Z)
                local delta=Vector3.new(own.Position.X-target.Position.X,0,own.Position.Z-target.Position.Z)
                if f.Magnitude>0.01 then
                    f=f.Unit;local side=math.abs(delta:Dot(Vector3.new(-f.Z,0,f.X)))
                    _G.VX_TRACE(string.format("rear-depth=%.2f:side-offset=%.2f",-delta:Dot(f),side))
                end
            end
        end
        _G.VX_BF_DASHANIM=0
        -- Keep the last approach view until the hit owns aim; never reset the camera between them.
        if arrived and opts.onReady then
            local callbackOk,value=pcall(opts.onReady)
            started=callbackOk and value==true
            if not callbackOk then ok=false; err=value end
        end
        if not arrived and workspace.CurrentCamera==camera then camera.CFrame=CFrame.new(camera.CFrame.Position)*rotation end
        local restored=false
        local function restoreMovement()
            if restored then return end;restored=true
            for _,connection in ipairs(connections) do connection:Disconnect() end
            if GetChar()==body and not UserInputService:GetFocusedTextBox() then
                for key,held in pairs(saved) do if held then pcall(function() VIM:SendKeyEvent(true,key,false,game) end) end end
            end
            if R.moveCleanup==restoreMovement then R.moveCleanup=nil end
        end
        if arrived and opts.onReady and R.bfActive and gen==R.gen then R.moveCleanup=restoreMovement
        else restoreMovement() end
        if not ok then warn("[DreamHub Movement] "..tostring(err)) end
        if not arrived then _G.VX_BF_LASTMSG=jump and "native hop did not reach rear range" or "native dash did not reach rear range" end
        return arrived,started
    end

    local function tpBehind(t,aimMode)
        local root=GetRoot(); local body=GetChar(); local enemy=t and t.Parent and t:FindFirstChild("HumanoidRootPart")
        if not root or not body or not enemy or (enemy.Position-root.Position).Magnitude>Settings.DashRange then return false end
        local forward=Vector3.new(enemy.CFrame.LookVector.X,0,enemy.CFrame.LookVector.Z)
        if forward.Magnitude<0.01 then return false end
        local pos=enemy.Position-forward.Unit*math.clamp(tonumber(Settings.BFTeleportDist) or 3,2.8,3.5)
        if aimMode=="Side" then pos+=Vector3.new(-forward.Unit.Z,0,forward.Unit.X)*1.2 end
        local gen=R.gen
        body:PivotTo(CFrame.lookAt(Vector3.new(pos.X,root.Position.Y,pos.Z),Vector3.new(enemy.Position.X,root.Position.Y,enemy.Position.Z)))
        for _=1,3 do
            RunService.Heartbeat:Wait()
            if gen~=R.gen or GetChar()~=body or not IsAlive() or not atBack(t,4,aimMode) then
                _G.VX_BF_LASTMSG="teleport rejected or target moved; stopped"; return false
            end
        end
        return true
    end

    -- lock-on: hold you behind the target for the flash window
    -- ═══ THE BF FLING ═══ The back-lock pins you ~3 studs behind the target every frame. The orbit turns your
    -- collisions off for its arc and RESTORES them on exit — so the lock then held a SOLID body overlapping
    -- theirs, and the engine resolves that overlap by blasting both of you apart. That is the fling in every BF
    -- mode. Your collisions now stay OFF for the whole lock and are restored the moment it ends.
    local lockNoclip = nil
    local function lockClipOff()
        if lockNoclip then return end
        lockNoclip = {}
        local c = GetChar(); if not c then return end
        for _, p in ipairs(c:GetDescendants()) do
            if p:IsA("BasePart") and p.CanCollide then lockNoclip[p] = true; pcall(function() p.CanCollide = false end) end
        end
    end
    local function lockClipOn()
        if not lockNoclip then return end
        for p in pairs(lockNoclip) do if p.Parent then pcall(function() p.CanCollide = true end) end end
        lockNoclip = nil
    end
    -- CAMERA-ONLY LOCK. The old bf_back lock wrote your CFrame into the enemy's hitbox every frame; the moment
    -- you M1 or flash, the physics engine resolves that overlap by launching you. No CFrame write here at all
    -- now - the dash already puts you on their back, so the lock just keeps the camera on them.
    RunService.RenderStepped:Connect(function(dt)
        if not R.lockTarget or tick() >= R.lockEnd then
            lockClipOn()
            return
        end
        if R.lockKind == "cam" or R.lockKind == "bf_back" then
            local e = R.lockTarget:FindFirstChild("HumanoidRootPart")
            if e then aimCameraAt(e.Position) end
        end
    end)

    -- SIDE DASH: orbit LEFT around the enemy (proven anti-fling arc _G.VX_ORBIT), soft-lock the camera on them
    -- the whole time, then auto-release (no lingering lock icon). Matches "click Q -> side around left, lock, off".
    -- ═══ HOLD THE BACK FOR A BEAT ═══ "when I do it, it must lock to the back for a sec, make sure it goes
    -- to the back." The arc lands you there, but a target that is walking or turning drifts out of it within
    -- a few frames. This follows their spine for a moment afterwards, so the M1s below actually land behind
    -- them instead of beside them.
    -- Collisions are dropped for the hold and restored on exit - lockClipOff exists for exactly this, and
    -- holding a SOLID body overlapping theirs is what the file's own notes blame for the BF fling.
    -- It follows, it does not blink: the write each frame is a small correction to a position you are already
    -- standing on, which is a different thing from a teleport.
    -- Back aiming owns rotation only; native movement owns position.
    local function abortOwnedSequence(owner)
        if not owner or R.owner~=owner then return end
        R.gen+=1
        if BFApi and BFApi.CancelChain then pcall(BFApi.CancelChain) end
        if R.moveCleanup then pcall(R.moveCleanup) end
        if R.aimCleanup then pcall(R.aimCleanup) end
        pcall(lockClipOn);pcall(ReleaseAll)
        if _G.VX_COMBAT_OWNER==owner then _G.VX_COMBAT_OWNER=nil end
        R.owner=nil;R.bfActive=false;R.curving=false
        R.lockTarget=nil;R.lockKind=nil;R.lockEnd=0
        _G.VX_BF_DASHANIM=0
    end
    local function runSequence(t, body)
        if R.bfActive or R.curving or _G.VX_COMBAT_OWNER or not t then return false end
        local root = GetRoot(); local enemy = t:FindFirstChild("HumanoidRootPart")
        if not root or not enemy or (enemy.Position-root.Position).Magnitude > MAXDASH then return false end
        R.bfActive = true; R.curving = true; R.sequenceRotation=nil
        local owner = {}; _G.VX_COMBAT_OWNER = owner; R.owner=owner
        local gen, character = R.gen, GetChar()
        task.delay(7,function()
            if R.gen==gen and R.owner==owner then
                _G.VX_BF_LASTMSG="stalled chain released; try again"
                abortOwnedSequence(owner)
            end
        end)
        local camera = workspace.CurrentCamera
        local cameraRotation = camera and camera.CFrame.Rotation
        local function live()
            return R.gen == gen and GetChar() == character and IsAlive() and t.Parent ~= nil
        end
        local function pause(seconds)
            local deadline = tick()+seconds
            repeat task.wait() until tick() >= deadline or not live()
            return live()
        end
        local ok, result = pcall(function()
            local vp=camera and camera.ViewportSize
            _G.VX_SYNTH_CLICK=tick()+0.10
            VIM:SendMouseButtonEvent(vp and vp.X/2 or 400,vp and vp.Y/2 or 300,0,false,game,0)
            return body(live,pause)
        end)
        if R.gen~=gen or R.owner~=owner then return false end
        if R.moveCleanup then pcall(R.moveCleanup) end
        local finalRotation=(ok and result==true and workspace.CurrentCamera and workspace.CurrentCamera.CFrame.Rotation) or R.sequenceRotation
        if R.aimCleanup then pcall(R.aimCleanup) end
        if _G.VX_COMBAT_OWNER == owner then _G.VX_COMBAT_OWNER = nil end
        R.owner=nil
        if cameraRotation and workspace.CurrentCamera then
            pcall(function() local c=workspace.CurrentCamera;c.CFrame=CFrame.new(c.CFrame.Position)*(finalRotation or cameraRotation) end)
        end
        if R.gen == gen then
            R.bfActive = false; R.curving = false
            R.lockTarget = nil; R.lockKind = nil; R.lockEnd = 0
            ReleaseAll()
        end
        if not ok then warn("[DreamHub Combat] "..tostring(result)) end
        return ok and result == true
    end
    local function assist(t,back)
        if tick()-R.lastDash<Settings.DashCooldown then return false end
        R.lastDash=tick()
        return runSequence(t,function(live,pause)
            local old=tonumber(_G.VX_COMBAT_SUPPRESS_BF) or 0
            local suppression=tick()+1.2; _G.VX_COMBAT_SUPPRESS_BF=suppression
            local arrived=dashToBack(t,{side="Auto",back=back})
            if _G.VX_COMBAT_SUPPRESS_BF==suppression then _G.VX_COMBAT_SUPPRESS_BF=old end
            if not arrived or not live() then return false end
            lockBackAim(t)
            if not pause(0.04) or not atBack(t,5.5) then return false end
            local sent=VMouseClick(); pause(0.22); return sent
        end)
    end

    -- ═══ r18: SIDE DASH ASSIST - REAL REMOTE DASH, NOT VKEYTAP ═══ "bring side dash assist back, it's bad
    -- and horrible, it just front dashes." The r17 path inherited dashToBack's VKeyDown(Q) - which fired a
    -- SYNTHETIC Q press through CAS, where the SAME priority-3100 VX_SIDE_SEQUENCE binding that owns the
    -- assist's Q trigger sat waiting. Synthetic Q → CAS → requestSide() → SINK. The Q never reached the
    -- game, no side dash, only the residual forward drift = "just front dashes". Fix: fire the captured
    -- Dash remote DIRECTLY with a real direction string ("Left"/"Right") - server-side dash, no
    -- input-injection race. After the dash lands, the proven VX_ORBIT arc wraps you onto the spine point,
    -- the soft lerp faces their back, the click lands. Real side dash, every time.
    -- Restore the Oct 18/19 assist structure: native dash, back aim, one click.
    local function doSideDash(isBF,prog,sideOverride)
        if tick()-R.lastDash<Settings.DashCooldown then return false end
        local target=GetClosestTarget(MAXDASH);if not target then return false end
        R.lastDash=tick()
        return runSequence(target,function(live,pause)
            -- Same single native, steered Q approach as M1 Chain. Retain the selected
            -- A/D direction, hold rear aim while clicking, then release it normally.
            local count=Settings.SideM1Count
            -- Restore the October 18 side-dash curve and short handoff, while retaining
            -- native Q direction routing and safe input cleanup from the newer build.
            local arrived,hit=dashToBack(target,{side=sideOverride or Settings.SideChoice,center="Center",settle=true,referenceSide=true,onReady=function()
                if not live() or UserInputService:GetFocusedTextBox() or not atBack(target,5,"Center") then return false end
                lockBackAim(target,"Center")
                return VMouseClick()
            end})
            if not arrived or not hit then return false end
            for n=2,count do
                -- Click at the usual M1 cadence, cancelling if disabled, the target
                -- dies, or it leaves reach; synthetic clicks cannot retrigger M1 Chain.
                if not pause(0.30) or not live() or UserInputService:GetFocusedTextBox() then return false end
                local enemy=target.Parent and target:FindFirstChild("HumanoidRootPart")
                local hum=target.Parent and target:FindFirstChildOfClass("Humanoid")
                local root=GetRoot()
                if not enemy or not hum or hum.Health<=0 or not root or (enemy.Position-root.Position).Magnitude>5.5 then return false end
                if not VMouseClick() then return false end
            end
            if not pause(0.18) then return false end
            if R.aimCleanup then R.aimCleanup() end
            return true
        end)
    end
    local function doBackDash(isBF)
        -- Restore the attachment's original Back Dash Assist, independently of BF modes.
        if tick()-R.lastDash < Settings.DashCooldown or _G.VX_COMBAT_OWNER then return false end
        local t = GetClosestTarget(MAXDASH)
        return runSequence(t,function(live,pause)
            R.lastDash=tick()
            local e=t and t:FindFirstChild("HumanoidRootPart")
            if not e or not _G.VX_ORBIT then return false end
            -- ═══ r16: THE ORIGINAL 360 IS BACK ═══ "I said only change side black flash, not back dash -
            -- bring the original back dash back." The r15 rebuild is gone; this is the ORIGINAL body again:
            -- one aim, the REAL dash key tap, then the VX_ORBIT 360 slide around them (our collisions off
            -- for the whole move, endBias follows your BF Hit Position setting - dead-centre spine or the
            -- corner of the back), the soft lerp face, then the click. Only the pace changed: 0.36 -> 0.34s.
            pcall(lockClipOff)
            aimCameraAt(e.Position)
            VKeyTap(Settings.DashKey,0.04)
            if not pause(0.06) then pcall(lockClipOn) return false end
            local root=GetRoot(); if root then root.AssemblyLinearVelocity=Vector3.zero end
            local orbitBias = (backAimMode=="Side") and 0.6 or 0
            _G.VX_ORBIT(e,{duration=0.34,endRadius=math.max(Settings.BFTeleportDist,2.2),extraSweep=math.pi*2,endBehind=true,yArc=0,endBias=orbitBias})
            if not live() then pcall(lockClipOn) return false end
            faceBackOfSoft(t,3)
            if not pause(0.05) then pcall(lockClipOn) return false end
            local hit=VMouseClick()
            pcall(lockClipOn)
            return hit
        end)
    end
    -- ═══ REACH, NOT SPINE, FOR THE MID-WINDUP RE-CHECK ═══ cast() demands the full atBack gate BEFORE the
    -- heavy is thrown (positioning must be right), but the chain's validate re-check runs 0.19s LATER -
    -- a target that turned or shuffled a stud in that window failed atBack and the follow-up was REFUSED
    -- ("target left the back-hit window" = the cast stayed a Divergent Fist). The re-check only needs to
    -- know the target is still hittable: alive and inside M1 reach.
    local function inReach(t,maxD)
        local r=GetRoot(); local e=t and t.Parent and t:FindFirstChild("HumanoidRootPart")
        return r~=nil and e~=nil and (e.Position-r.Position).Magnitude<=(maxD or 9)
    end
    local function rearFollowReady(t)
        local r=GetRoot(); local e=t and t.Parent and t:FindFirstChild("HumanoidRootPart")
        local h=t and t:FindFirstChildOfClass("Humanoid")
        if not r or not e or not h or h.Health<=0 then return false end
        local d=r.Position-e.Position
        return Vector3.new(d.X,0,d.Z).Magnitude<=5.5 and math.abs(d.Y)<=4.5
    end
    local function flashSequence(mode,suppliedTarget)
        if tick()-R.bfCD<Settings.BFCooldown then return false end
        local t=suppliedTarget or bfTarget(mode=="M1")
        if not closeBF(t,mode=="M1") then _G.VX_BF_LASTMSG="chain needs a target within 8 studs"; return false end
        return runSequence(t,function(live,pause)
            R.chainUntil=tick()+2.5
            if mode=="M1" then
                local track=R.triggerTrack; R.triggerTrack=nil
                if track then
                    local guard=tick()+0.8
                    local recovered=not track.IsPlaying
                    while live() and not recovered and tick()<guard do
                        local length=tonumber(track.Length) or 0
                        local phase=tonumber(track.TimePosition) or 0
                        local weight=tonumber(track.WeightCurrent)
                        recovered=not track.IsPlaying or length>0 and phase>=length
                            or weight~=nil and weight<=0.02 and phase>=0.08
                        if not recovered then task.wait() end
                    end
                    if not live() or not recovered then _G.VX_BF_LASTMSG="triggering M1 still recovering; Q not spent"; return false end
                    if _G.VX_TRACE then _G.VX_TRACE("m1-recovery-complete") end
                elseif not pause(0.24) then return false end
            end
            if not closeBF(t,false) then return false end
            local token
            local aimMode="Center"
            local function cast()
                if not live() or not atBack(t,5.5,aimMode) then
                    if _G.VX_TRACE then _G.VX_TRACE("cast-rejected:not-rear") end
                    return false
                end
                if _G.VX_TRACE then _G.VX_TRACE("cast:rear-gate-passed") end
                -- Aim stays on the opponent while the game's dash finishes; no view reset and second turn.
                lockBackAim(t,aimMode,true,mode=="Side Dash" and 3.3 or nil)
                -- The rear hit is the native action that can end the dash. Waiting for a velocity
                -- threshold here kept the remaining dash alive and let it carry the player past the target.
                -- Starting the move needs the selected rear lane. Completing an observed windup
                -- needs a live target in reach, so a turn cannot cancel the conversion already in flight.
                if not live() or not atBack(t,5.5,aimMode) then return false end
                local function followGate() return live() and rearFollowReady(t) and (mode~="M1" or atBack(t,5.5,"Center")) end
                _G.VX_COMBAT_SUPPRESS_BF=0
                local sent; sent,token=m1ThenBF(t,followGate,mode)
                if sent then R.bfCD=tick() end
                return sent
            end
            local arrived,started
            local root=GetRoot();local enemy=t and t:FindFirstChild("HumanoidRootPart")
            local hasRoom=mode~="Side Dash" or (root and enemy and (root.Position-enemy.Position).Magnitude>=3.05)
            if mode~="Jump" and hasRoom and atBack(t,3.5,aimMode) then arrived=true; started=cast()
            elseif mode=="Teleport" then arrived=tpBehind(t,aimMode); if arrived then started=cast() end
            else
                arrived,started=dashToBack(t,{jump=mode=="Jump",back=mode=="Back Dash",center=aimMode,rearDistance=mode=="Side Dash" and 3.3 or nil,settle=mode=="Side Dash" or mode=="Back Dash" or mode=="M1",onReady=cast})
            end
            if not live() then if token then BFApi.CancelChain(token) end; return false end
            if not arrived or not started then return false end
            while live() and token and token.sent==nil and tick()<=token.expires do task.wait() end
            local sent=token and token.sent==true
            if token and not token.used then BFApi.CancelChain(token) end
            if sent then pause(0.04) end
            return sent
        end)
    end

    local function doBFTeleport() return flashSequence("Teleport") end
    local function doBFJump() return flashSequence("Jump") end
    local function doBFSideDash() return flashSequence("Side Dash") end
    local function doBFBackDash() return flashSequence("Back Dash") end
    local function targetInChainRange() return bfTarget(Settings.Mode=="M1") end
    local function targetInRange(maxD)   -- wider gate for the Q assist binding: the assist reaches MAXDASH,
        local t = GetClosestTarget(maxD) -- so sinking the press only inside 20 left a 20-26 band where the
        local r = GetRoot(); local e = t and t:FindFirstChild("HumanoidRootPart") -- game's own Q front dash
        if r and e and (r.Position-e.Position).Magnitude <= maxD then return t end -- AND the assist both fired
    end
    local function doBFM1Chain()
        local t = targetInChainRange()
        if t then return flashSequence("M1",t) end
    end


    local function doBlackFlash()
        if not Settings.Enabled or R.bfActive then return end
        local m = Settings.Mode
        if m == "Teleport" then doBFTeleport() elseif m == "Jump" then doBFJump()
        elseif m == "Side Dash" then doBFSideDash() elseif m == "Back Dash" then doBFBackDash()
        elseif m == "M1" then doBFM1Chain() end
    end

    -- One shared animation engine owns M1 BF and chain timing.
    UserInputService.InputBegan:Connect(function(input, _)
        if UserInputService:GetFocusedTextBox() then return end
        -- ═══ THE PHANTOM: "I GO TO A PERSON AND IT M1s AND BLACK FLASHES WITHOUT ME CLICKING THREE" ═══
        -- This handler's only "was that press mine?" test was R.stamp, and R.stamp[Three] is written by exactly
        -- ONE function in the file: markThree(), used only by VXBF2's own pressBF(). The Black Flash ENGINE is
        -- a different module and presses 3 through its own pressKey(), which stamps _G.VX_INJ_KEYS and never
        -- touches R.stamp. So: engine flashes your ordinary M1 -> injects key 3 -> this handler reads it as a
        -- real player tap -> doBlackFlash() -> a full dash chain -> m1ThenBF() injects an M1 you never threw ->
        -- that swing flashes -> key 3 again -> round and round, for as long as somebody is inside DashRange.
        -- That is the phantom M1 + phantom flash, and it is also "the side dashes are weird": those dashes are
        -- unrequested chains. _G.VX_INJ_KEYS is the file's shared injected-key marker; honour it here.
        do local injK = _G.VX_INJ_KEYS; if injK and injK[input.KeyCode] and tick() < injK[input.KeyCode] then return end end
        local st = R.stamp[input.KeyCode]; if st and tick() - st < WIN then return end
        if input.KeyCode == Settings.BFKey and Settings.Enabled and Settings.Mode ~= "M1" and not (_G.VX_NATIVE_THREE and _G.VX_NATIVE_THREE()) then
            -- Handled (and SUNK) by the ContextActionService binding below; reaching here means CAS is not
            -- available on this executor, so fall through and at least run the chain the old way.
            if R.casBound then return end
            -- ═══ YOUR TRIGGER PRESS IS ALSO A CAST ═══ On Itadori, 3 IS Divergent Fist - so the press that
            -- starts a chain also casts it, and that cast's animation is in the engine's trigger table. It
            -- was arriving as a "windup" and SPENDING the chain's single-shot flash before the chain's own M1
            -- ever swung - which is what killed Teleport and Back Dash outright. Stamp the press; the engine
            -- ignores trigger-table ids for 0.6s after it. (Injected 3s bailed above, so this is only ever
            -- a real press that a chain mode consumed - the Auto BF manual flow never stamps it.)
            _G.VX_BF_TRIG3 = tick()
            doBlackFlash(); return
        end
        -- (the CAS route stamps TRIG3 itself - see the binding below this connection)
        -- CLICK path for BF: covers characters whose M1 anim isn't in the database (the anim path can't catch
    -- ═══ THE EVIDENCE SAYS THE "DUPLICATE" PRESS WAS THE ONE LANDING ═══
    -- Last build an agent argued this path was a harmful duplicate: it presses 3 at CLICK+0.14s, before the
    -- engine's animation-timed press, so it "burns Divergent Fist early". I disabled it - and Auto BF, which
    -- you had just confirmed WORKING, went dark. That is a direct causal link, and it fits every other data
    -- point you have given me:
    --     Teleport mode STILL flashes  -> its press comes from m1ThenBF's fallback at CLICK+0.19s
    --     Auto BF worked               -> this path, at CLICK+0.14s
    --     everything animation-timed   -> silent
    -- i.e. presses measured from YOUR CLICK land; presses measured from the windup ANIMATION do not. That
    -- makes sense if the animation event arrives late or a frame or two after the real flash window opens.
    -- So this is not a duplicate to be removed, it is the mechanism. Restored, on the evidence.
    end)

    -- ═══════════ SINK THE TRIGGER PRESS - THE REAL REASON NO CHAIN MODE EVER FLASHED ═══════════
    -- On Itadori, key 3 IS Divergent Fist. The chain trigger above runs from InputBegan, which OBSERVES input
    -- but cannot consume it - so every chain started with the game ALSO casting Divergent Fist at t=0,
    -- putting the move on its real cooldown. The chain then dashed, swung, and the engine pressed 3 at the
    -- perfect moment... onto a move that was already spent. Swing lands, no flash, every time, every mode.
    -- Auto BF never had this problem because it has no trigger press - nothing burnt the slot first.
    -- ContextActionService is the one input API that CAN consume: binding at high priority and returning
    -- Sink marks the press gameProcessed, so the game's own handler ignores it. The move is never cast by
    -- the trigger, the slot is cold when the engine's timed press arrives, and THAT press casts it - as the
    -- flash. Injected presses (the engine's own key 3) are passed through untouched, or we would sink the
    -- very press that makes the flash happen.
    pcall(function()
        local CAS = game:GetService("ContextActionService")
        R.casBound = pcall(function()
            CAS:BindActionAtPriority("VX_BF_TRIGGER", function(_, state, input)
                if state ~= Enum.UserInputState.Begin then return Enum.ContextActionResult.Pass end
                do local injK = _G.VX_INJ_KEYS; if injK and injK[input.KeyCode] and tick() < injK[input.KeyCode] then return Enum.ContextActionResult.Pass end end
                if UserInputService:GetFocusedTextBox() then return Enum.ContextActionResult.Pass end
                if _G.VX_TODO_BF_ON and TodoApi and TodoApi.isTodo and TodoApi.isTodo() then return Enum.ContextActionResult.Pass end
                -- ═══ LOCUST OWNS 3 WHEN ITS RECIPE IS ARMED ═══ with any BF mode selected, this sink consumed
                -- every 3 before the Locust recipe could run - the R spam never fired and Crushing Jaws never
                -- cast ("Locus, now it doesn't even, not working at all"). The native-recipes module raises
                -- _G.VX_NATIVE_THREE while its Locust toggle is on; the press passes through to the game.
                if _G.VX_NATIVE_THREE and _G.VX_NATIVE_THREE() and input.KeyCode == Settings.BFKey then return Enum.ContextActionResult.Pass end
                if not (Settings.Enabled and Settings.Mode ~= "M1" and input.KeyCode == Settings.BFKey) then return Enum.ContextActionResult.Pass end
                _G.VX_BF_TRIG3=tick()
                local automaticOwner=_G.VX_AUTO_FINISHER_OWNER and _G.VX_AUTO_FINISHER_OWNER()
                if automaticOwner and _G.VX_COMBAT_OWNER==automaticOwner and _G.VX_FINISHER_RESET then
                    pcall(_G.VX_FINISHER_RESET)
                end
                if R.bfActive or R.curving or _G.VX_COMBAT_OWNER or tick()-R.bfCD<Settings.BFCooldown then
                    _G.VX_BF_LASTMSG="chain blocked by another active action"
                    return Enum.ContextActionResult.Sink
                end
                if not targetInChainRange() then _G.VX_BF_LASTMSG="no target in chain range"; return Enum.ContextActionResult.Pass end
                R.casSeen = tick()
                _G.VX_BF_TRIG3 = tick()
                if _G.VX_TRACE_BEGIN then _G.VX_TRACE_BEGIN(Settings.Mode) end
                if _G.VX_TRACE then _G.VX_TRACE("3-sunk") end
                task.spawn(doBlackFlash)
                return Enum.ContextActionResult.Sink        -- the game never sees this 3: Divergent Fist stays cold
            end, false, 3000, Settings.BFKey)
        end)
    end)
    LocalPlayer.CharacterAdded:Connect(function()
        if R.owner then abortOwnedSequence(R.owner) else R.gen+=1 end
        R.bfActive=false;R.curving=false;pcall(ReleaseAll)
        if BFApi then BFApi.CancelChain() end
    end)

    -- OFF MEANS OFF: turning a mode off (or switching modes) used to leave the back-lock still running and your
    -- collisions still disabled, so it kept moving you after you thought you had stopped it. This tears
    -- everything down: lock cleared, collisions restored, held keys released, in-flight flags reset.
    local function vxbfStop()
        -- OFF MEANS OFF, INCLUDING WORK ALREADY SCHEDULED. Every chain queues task.delay callbacks (the flash
        -- retry, the engine hand-back). Without a generation stamp those still fire after you switch the mode
        -- off, which is "I turned it off and it still pressed 3".
        if R.owner then abortOwnedSequence(R.owner) else R.gen = (R.gen or 0) + 1 end
        if BFApi and BFApi.CancelChain then BFApi.CancelChain() end
        _G.VX_BF_CHAINDRIVE = 0
        _G.VX_CHAINFLASH_WINDOW = 0
        R.chainUntil = 0
        -- Hand the flash engine back IMMEDIATELY on stop. Waiting for the queued hand-back is what let a mode
        -- you had already switched off keep flashing your next few M1s.
        _G.VX_BF_BORROWED = false; _G.VX_BF_BORROW_USED = 0
        R.chainUntil = 0
        -- "when I turn off m1 chain it needs to be OFF" - hand the engine straight back to whatever the M1
        -- Black Flash / Auto Black Flash toggles actually say, right now, not on a queued timer.
        if _G.VX_BFAPI_SET then pcall(function() _G.VX_BFAPI_SET(_G.VX_BFAPI_WANT == true) end) end
        R.lockTarget = nil; R.lockKind = nil; R.lockEnd = 0
        R.bfActive = false; R.curving = false
        _G.VX_BF_RECLICK = _G.VX_BF_RECLICK_USER ~= false   -- restore the user's re-click setting immediately
        if R.moveCleanup then pcall(R.moveCleanup) end
        if R.aimCleanup then pcall(R.aimCleanup) end
        pcall(lockClipOn)
        pcall(ReleaseAll)
        local p = GetRoot()
        if p then pcall(function() p.AssemblyLinearVelocity = Vector3.zero; p.AssemblyAngularVelocity = Vector3.zero end) end
    end
    -- M1 CHAIN: fires on EVERY real M1 (poll-based detector; the game sinks the click so InputBegan cannot see
    -- it). One M1 -> side dash around them -> black flash. No counting, no waiting for a 3rd swing.
    -- ═══ M1 CHAIN HONOURS "BF After (M1s)" ═══ "if you do two M1s it will do it, one M1 it would do, three
    -- M1s it would do it" - the same selector that governs M1 BF now governs the chain, instead of the chain
    -- firing on every single click. Counted off REAL swings (the animation hook), not clicks, because a held
    -- button produces four swings from one click.
    local chainSwings, chainLastSwing, chainFiredAt = 0, 0, 0
    _G.VX_CHAIN_COUNT = function(observedTrack,retried)
        if not (Settings.Enabled and Settings.Mode == "M1") then return end
        if not retried and (chainClick==usedChainClick or tick()-(tonumber(_G.VX_LAST_HUMAN_CLICK) or 0)>0.40) then
            task.delay(0.04,function() if _G.VX_CHAIN_COUNT then _G.VX_CHAIN_COUNT(observedTrack,true) end end)
            return
        end
        -- ═══ NO CLICK = NO CHAIN ═══ "when I don't even click it glides/TPs around and M1s". This is driven
        -- off the swing counter, and that counter accepts any Action-priority animation for characters whose
        -- M1 ids were never captured - so a dash, an ability, or another module's injected swing all looked
        -- like an M1 and launched a whole chain. _G.VX_LAST_CLICK is stamped only by the real mouse poll, so
        -- requiring a click inside 0.4s means the chain can only ever run off something you actually did.
        if (tick() - (tonumber(_G.VX_LAST_CLICK) or 0)) > 0.40 then
            if _G.VX_BF_DEBUG then print("[DreamHub BF] chain: swing with no real click behind it - ignored") end
            return
        end
        -- And never off OUR OWN injected click (the chain's own M1 would retrigger the chain).
        if tick() < (tonumber(_G.VX_SYNTH_CLICK) or 0) then return end
        if chainClick==usedChainClick or not bfTarget(true) then return end
        local nowT = tick()
        -- ═══ ONE CHAIN PER COMBO ═══ A held click produces FOUR swings ~0.35s apart, and this used to fire a
        -- fresh chain every time the count came round - "one M1 equals three M1s and three black flashes".
        -- After a chain fires, every further swing of the SAME combo is ignored; the window only reopens after
        -- the combo has actually dropped (1.2s of silence, the game's own combo timeout).
        if R.bfActive or R.curving or _G.VX_COMBAT_OWNER or nowT-chainLastSwing<0.12 then return end
        if nowT - chainLastSwing > 1.2 then chainSwings = 0; chainFiredAt=0 end   -- JJS drops a combo at ~1.2s
        chainLastSwing = nowT
        usedChainClick=chainClick
        chainSwings = chainSwings + 1
        local need = 1
        if chainSwings < need then
            if _G.VX_BF_DEBUG then print("[DreamHub BF] chain: swing " .. chainSwings .. "/" .. need) end
            return
        end
        chainSwings = 0
        chainFiredAt = nowT
        R.triggerTrack=observedTrack
        if _G.VX_TRACE_BEGIN then _G.VX_TRACE_BEGIN("M1") end
        if _G.VX_TRACE then _G.VX_TRACE("human-swing-accepted") end
        task.defer(doBFM1Chain)
    end

    _G.VXBF2 = {
        chainEnabled = function() return Settings.Enabled and Settings.Mode == "M1" end,
        setEnabled = function(v) Settings.Enabled = v == true; if Settings.Enabled and _G.VX_REFRESH_COMBO_HOOK then pcall(_G.VX_REFRESH_COMBO_HOOK) end; if not Settings.Enabled then vxbfStop() end end,
        setMode = function(m) if type(m) == "string" then vxbfStop(); Settings.Mode = m end end,   -- Side Dash / Back Dash / Jump / Teleport / M1
        setBFM1 = function(v) Settings.BFM1 = v == true end,
        setAutoBF = function(v) Settings.AutoBF = v == true end,
        setSideAssist = function(v)
            Settings.SideAssist=v==true; _G.VX_SIDEASSIST_ON=false
            if not Settings.SideAssist then vxbfStop() end
            R.lastDash=-math.huge; R.sideSeen=-math.huge
        end,
        setSideM1Count = function(v)
            if type(v)=="table" then v=v[1] end
            local n=tonumber(v)
            if n then Settings.SideM1Count=math.clamp(math.floor(n),1,4) end
        end,
        setBackAssist = function(v) Settings.BackAssist = v == true; if not Settings.BackAssist then vxbfStop() end end,
        setCooldown = function(v) if type(v) == "number" then Settings.BFCooldown = v end end,
        setClickLock = function(v) clickLock=v==true; clickedTarget=nil end,
        setBackAim = function(v) if type(v)=="table" then v=v[1] end; backAimMode=v=="Side of Back" and "Side" or "Center" end,
        setTeleportDist = function(v) if type(v) == "number" then Settings.BFTeleportDist = v end end,
        doSide = function() return doSideDash(false, true) end,
        approach = function(target,back,validate,direct,forward,extra)
            local arrived=dashToBack(target,{side="Left",back=back==true,validate=validate,direct=direct==true,forward=forward==true,range=extra and extra.range,reach=extra and extra.reach,smooth=extra and extra.smooth,speed=extra and extra.speed})
            if arrived then
                lockBackAim(target); task.wait(0.08)
                local camera=workspace.CurrentCamera; local rotation=camera and camera.CFrame.Rotation
                if R.aimCleanup then R.aimCleanup() end
                if rotation and workspace.CurrentCamera==camera then camera.CFrame=CFrame.new(camera.CFrame.Position)*rotation end
            end
            return arrived
        end,   -- programmatic: fires the Dash remote itself
        -- For the Dash-rewrite hook: which way should a dash go to end up behind the nearest target?
        -- nil = no target in range, leave the player's dash alone.
        sideDir = function()
            local t = GetClosestTarget(Settings.DashRange); if not t then return nil end
            local e = t:FindFirstChild("HumanoidRootPart"); if not e then return nil end
            local pr = GetRoot(); if not pr then return nil end
            local fwd = Vector3.new(e.CFrame.LookVector.X, 0, e.CFrame.LookVector.Z)
            if fwd.Magnitude < 0.01 then return "Right" end
            local dest = e.Position - fwd.Unit * 2.5
            return ((dest - pr.Position):Dot(pr.CFrame.RightVector) < 0) and "Left" or "Right"
        end,
        doBack = function() doBackDash(false) end,
    }
    local sideQueued=false
    local function requestSide()
        if not Settings.SideAssist or UserInputService:GetFocusedTextBox() then return false end
        local left=UserInputService:IsKeyDown(Enum.KeyCode.A)
        local right=UserInputService:IsKeyDown(Enum.KeyCode.D)
        if R.held[Enum.KeyCode.Q] or tick()<((_G.VX_INJ_KEYS or {})[Enum.KeyCode.Q] or 0) then return false end
        if _G.VX_GOJO_MODE=="Q Dash" and _G.VX_GOJO_TPBACK_ON then return false end
        if not targetInRange(MAXDASH) then return false end
        if sideQueued or tick()-(R.sideSeen or -math.huge)<0.10 then return true end
        if R.bfActive or R.curving or _G.VX_COMBAT_OWNER or tick()-R.lastDash<Settings.DashCooldown then return false end
        local chosen
        if left~=right then chosen=left and "Left" or "Right"
        else
            local target=targetInRange(MAXDASH);local root=GetRoot()
            local enemy=target and target:FindFirstChild("HumanoidRootPart")
            if not root or not enemy then return false end
            chosen=autoSide(root,enemy)<0 and "Left" or "Right"
        end
        local reservation={body=GetChar(),stage="prepare",direction=chosen,expires=tick()+0.8}
        _G.VX_SIDE_DASH_INTENT=reservation
        R.sideSeen=tick();sideQueued=true
        local generation=R.gen
        task.defer(function()
            local ok,err=pcall(function()
                if Settings.SideAssist and generation==R.gen and not UserInputService:GetFocusedTextBox() then doSideDash(false,true,chosen) end
            end)
            sideQueued=false
            if _G.VX_SIDE_DASH_INTENT==reservation then _G.VX_SIDE_DASH_INTENT=nil end
            if not ok then warn("[DreamHub Side Assist] "..tostring(err)) end
        end)
        return true
    end

    pcall(function()
        game:GetService("ContextActionService"):BindActionAtPriority("VX_SIDE_SEQUENCE",function(_,state)
            if state==Enum.UserInputState.Begin and requestSide() then return Enum.ContextActionResult.Sink end
            return Enum.ContextActionResult.Pass
        end,false,3100,Enum.KeyCode.Q)
    end)
    local function assistKey(key)
        if UserInputService:GetFocusedTextBox() then return end
        if key==Enum.KeyCode.Q then requestSide()
        elseif key==Enum.KeyCode.E and Settings.BackAssist and tick()>((_G.VX_INJ_KEYS or {})[key] or 0) then doBackDash(false) end
    end
    UserInputService.InputBegan:Connect(function(input) assistKey(input.KeyCode) end)
    if _G.VX_ON_KEY then _G.VX_ON_KEY("sideAssist",assistKey) end


end

-- ============================================================
-- MODULE: AUTO MAHITO GRAB ESCAPE  (when Mahito grabs you, spam SPACE to break out)
-- Detects the Mahito grab animation (rbxassetid://72343192576784) playing on ANY nearby character; while it's
-- up, spam the spacebar (the grab-escape QTE) so you mash out automatically.
-- ============================================================
do
    local Players = game:GetService("Players")
    local VIM = game:GetService("VirtualInputManager")
    local LP = Players.LocalPlayer
    local enabled = false
    -- The grab shows a "JUMP TO ESCAPE!" QTE with a fill bar. We mash Space CONTINUOUSLY the WHOLE time that
    -- prompt is on screen (a fixed burst only filled part of the bar). We detect the prompt by its text.
    local function labelSaysEscape(d)
        if not (d:IsA("TextLabel") and d.Visible) then return false end
        local t = string.lower(d.Text or "")
        return (t:find("jump to escape") ~= nil) or (t:find("escape") ~= nil and t:find("jump") ~= nil)
    end
    local function escapePromptUp()
        -- The "JUMP TO ESCAPE!" prompt is a BILLBOARD over the grabbed character (in the world), NOT PlayerGui.
        -- Scan BOTH: your character's billboards (workspace.Characters[you]) + PlayerGui.
        local chs = workspace:FindFirstChild("Characters"); local me = (chs and chs:FindFirstChild(LP.Name)) or LP.Character
        if me then for _, d in ipairs(me:GetDescendants()) do if labelSaysEscape(d) then return true end end end
        local pg = LP:FindFirstChild("PlayerGui")
        if pg then for _, d in ipairs(pg:GetDescendants()) do if labelSaysEscape(d) then return true end end end
        return false
    end
    task.spawn(function()
        while true do
            if enabled and escapePromptUp() then
                pcall(function() VIM:SendKeyEvent(true, Enum.KeyCode.Space, false, game); task.wait(0.015); VIM:SendKeyEvent(false, Enum.KeyCode.Space, false, game) end)
                task.wait(0.03)   -- hammer Space fast until the prompt disappears
            else
                task.wait(0.12)
            end
        end
    end)
    MahitoGrabApi = { set = function(v) enabled = v == true end }
end

-- MODULE: AUTO SKILLS  (press chosen keys 1/2/3/4 on a nearby enemy)
do
        local Players = game:GetService("Players")
        local VIM = game:GetService("VirtualInputManager")
        local LP = Players.LocalPlayer
        local enabled, rate, range = false, 0.4, 30
        local keys = { [1] = false, [2] = false, [3] = false, [4] = false, [5] = false, [6] = false }
        local KC = { [1] = Enum.KeyCode.One, [2] = Enum.KeyCode.Two, [3] = Enum.KeyCode.Three, [4] = Enum.KeyCode.Four, [5] = Enum.KeyCode.R, [6] = Enum.KeyCode.G }
        local function myChar() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end  -- JJS body lives under workspace.Characters
        local function myHRP() local c = myChar(); return c and c:FindFirstChild("HumanoidRootPart") end
        local function nearestEnemyHRP()  -- the NEAREST living enemy in range (correct target, not a stale LP.Character read)
                local hrp = myHRP(); if not hrp then return nil end
                local _g=_G.VX_LOCK; local _lt=(_g and _g.manualActive and _g.manualActive() and _g.get) and _g.get() or nil   -- LOCK TARGET wins over any range scan
                if _lt and _lt.Parent then local _lh=_lt:FindFirstChildOfClass("Humanoid"); local _lr = _lt:FindFirstChild("HumanoidRootPart"); if _lr and (not _lh or _lh.Health > 0) then return _lr end end
                local best, bd
                local function chk(m) if m and m.Name ~= LP.Name and m ~= LP.Character then local h = m:FindFirstChildOfClass("Humanoid"); local r = m:FindFirstChild("HumanoidRootPart"); if h and h.Health > 0 and r then local d = (r.Position - hrp.Position).Magnitude; if d <= range and (not bd or d < bd) then best, bd = r, d end end end end
                for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP then chk(plr.Character) end end
                local chars = workspace:FindFirstChild("Characters"); if chars then for _, m in ipairs(chars:GetChildren()) do chk(m) end end
                return best
        end
        local function faceEnemy(tr) local hrp = myHRP(); if hrp and tr and tr.Parent then pcall(function() hrp.CFrame = CFrame.lookAt(hrp.Position, Vector3.new(tr.Position.X, hrp.Position.Y, tr.Position.Z)) end) end end  -- aim at them so the skill lands on the RIGHT target
        local function press(kc)
                _G.VX_INJECT_UNTIL = tick() + 0.35   -- OUR press: feints / Auto Air / Reversal Red must not chain off it
                _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[kc] = tick() + 0.5
                pcall(function() VIM:SendKeyEvent(true, kc, false, game); task.wait(0.09); VIM:SendKeyEvent(false, kc, false, game) end)  -- longer hold so the game reliably registers the key
        end
        local cycleIdx = 0
        task.spawn(function()
                while true do
                        if enabled then
                                -- PRESS THE KEY NO MATTER WHAT (user: "when I click 1 it clicks 1"). The old enemy-in-30-studs
                                -- gate meant nothing happened unless someone stood next to you = "auto skills don't work".
                                -- If an enemy IS around we still face them first so the cast lands on the right target.
                                local tried = 0
                                repeat cycleIdx = (cycleIdx % 6) + 1; tried = tried + 1 until keys[cycleIdx] or tried >= 6
                                if keys[cycleIdx] then
                                        local tr = nearestEnemyHRP()
                                        if tr then if _G.VX_ACPASS then _G.VX_ACPASS() end faceEnemy(tr); task.wait(0.03) end
                                        press(KC[cycleIdx])
                                end
                                task.wait(rate)
                        else task.wait(0.2) end
                end
        end)
        SkillsApi = {
                setEnabled = function(v)
                        enabled = v == true
                        -- NO auto-default: master ON presses ONLY the skills you toggled (it used to force 1-4 on,
                        -- which pressed 3 etc before you picked anything).
                end,
                setKey = function(n, v)
                        if KC[n] then
                                keys[n] = v == true
                                if v then enabled = true
                                else
                                        local any = false; for i = 1, 6 do if keys[i] then any = true break end end
                                        if not any then enabled = false end   -- last skill toggled OFF -> the system fully stops (OFF means OFF)
                                end
                        end
                end,
                setRate = function(v) if type(v) == "number" then rate = v end end,
        }
end

-- MODULE: INVISIBILITY  (client + replicated transparency, RE-ASSERTED every frame so the game's animations can't un-hide you. You can still move + attack normally.)
do
        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local LP = Players.LocalPlayer
        local on = false
        local parts = {}   -- cached BaseParts of your body (rebuilt on toggle / respawn) so the per-frame re-assert is cheap
        local function bodies()
                local t = {}
                local c1 = LP.Character; if c1 then t[#t + 1] = c1 end
                local chs = workspace:FindFirstChild("Characters"); local c2 = chs and chs:FindFirstChild(LP.Name); if c2 and c2 ~= c1 then t[#t + 1] = c2 end
                return t
        end
        local function rebuild()
                parts = {}
                for _, m in ipairs(bodies()) do
                        for _, p in ipairs(m:GetDescendants()) do if p:IsA("BasePart") then parts[#parts + 1] = p end end
                end
        end
        local function setVis(hidden)
                rebuild()
                for _, p in ipairs(parts) do
                        if p.Name ~= "HumanoidRootPart" then pcall(function() p.Transparency = hidden and 1 or 0 end) end   -- REPLICATED transparency = others can't see you either
                        pcall(function() p.LocalTransparencyModifier = hidden and 1 or 0 end)
                end
                for _, m in ipairs(bodies()) do
                        for _, d in ipairs(m:GetDescendants()) do
                                if d:IsA("Decal") or d:IsA("Texture") then pcall(function() d.Transparency = hidden and 1 or 0 end)
                                elseif d:IsA("BillboardGui") or d:IsA("ParticleEmitter") or d:IsA("Trail") then pcall(function() d.Enabled = not hidden end) end
                        end
                end
        end
        local acc = 0
        RunService.RenderStepped:Connect(function(dt)
                if not on then return end
                acc = acc + (dt or 0.016)
                if acc > 1 then acc = 0; rebuild() end   -- refresh the part list (respawns / gear / transformations add new limbs)
                for _, p in ipairs(parts) do
                        if p.Parent then pcall(function()
                                if p.Name ~= "HumanoidRootPart" then p.Transparency = 1 end   -- RE-ASSERT the REPLICATED transparency every frame: the game can't un-hide you, and OTHERS stay unable to see you
                                p.LocalTransparencyModifier = 1
                        end) end
                end
        end)
        LP.CharacterAdded:Connect(function() task.wait(0.4); if on then setVis(true) end end)   -- re-hide decals / particles after a respawn
        InvisApi = { set = function(v) on = v == true; setVis(on) end }
end

-- MODULE: AUTO PARKOUR  (real parkour anim sequence jump->park->fall->land + wall-climb velocity + the Parkour remote)
do
        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local UIS = game:GetService("UserInputService")
        local LP = Players.LocalPlayer
        local on, last, climbing = false, 0, false
        local ANIMS = { jump = "rbxassetid://134343219970072", parkRight = "rbxassetid://113609963676386", parkLeft = "rbxassetid://94327920127463", fall = "rbxassetid://126572575938378", land = "rbxassetid://97446412066176" }
        local tracks = {}
        local sideTracks = {}   -- declared here so the shared animator-cache invalidator below can clear it
        local function myChar() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
        local function myHRP() local c = myChar(); return c and c:FindFirstChild("HumanoidRootPart") end
        local function animatorOf() local c = myChar(); local h = c and c:FindFirstChildOfClass("Humanoid"); return h and h:FindFirstChildOfClass("Animator") end
        -- ANIMATION CACHE INVALIDATION: a respawn/character swap creates a NEW Animator, and a track loaded on the
        -- old one just silently refuses to play - which is exactly "parkour works but does no animation".
        local trackAnimator = nil
        local function freshAnimator()
                local a = animatorOf()
                if a ~= trackAnimator then trackAnimator = a; table.clear(tracks); table.clear(sideTracks) end
                return a
        end
        local function play(key)
                local a = freshAnimator(); if not a then return end
                local t = tracks[key]
                if not t then local anim = Instance.new("Animation"); anim.AnimationId = ANIMS[key]; local ok, tr = pcall(function() return a:LoadAnimation(anim) end); if ok and tr then t = tr; tracks[key] = tr end end
                if t then pcall(function() t:Play() end) end
        end
        local function exclude()  -- ray filter: your body + EVERY character (an enemy you're fighting must NOT count as a "wall") + effects
                local list = { myChar() }
                for _, plr in ipairs(Players:GetPlayers()) do if plr.Character then list[#list + 1] = plr.Character end end
                local chs = workspace:FindFirstChild("Characters"); if chs then for _, m in ipairs(chs:GetChildren()) do list[#list + 1] = m end end
                local eff = workspace:FindFirstChild("Effects"); if eff then list[#list + 1] = eff end
                return list
        end
        local function wallNear()  -- a REAL wall within reach ahead or to a side (players/enemies excluded)
                local hrp = myHRP(); if not hrp then return false end
                local p = RaycastParams.new(); p.FilterType = Enum.RaycastFilterType.Exclude; p.FilterDescendantsInstances = exclude()
                for _, dir in ipairs({ hrp.CFrame.LookVector, hrp.CFrame.RightVector, -hrp.CFrame.RightVector, -hrp.CFrame.LookVector }) do
                        if workspace:Raycast(hrp.Position, dir * 8, p) then return true end   -- wider reach so a wall is actually detected
                end
                return false
        end
        local function sideTrack(key)  -- looped wall-run track per side (parkLeft / parkRight)
                local a = freshAnimator(); if not a then return nil end
                if sideTracks[key] then return sideTracks[key] end
                local anim = Instance.new("Animation"); anim.AnimationId = ANIMS[key]
                local ok, t = pcall(function() return a:LoadAnimation(anim) end)
                if ok and t then t.Looped = true; sideTracks[key] = t end
                return sideTracks[key]
        end
        local function stopSides() for _, t in pairs(sideTracks) do if t.IsPlaying then pcall(function() t:Stop() end) end end end
        local function forwardWall()  -- a REAL wall DIRECTLY ahead (you're running into it) = climb; players/enemies excluded so fighting doesn't launch you
                local hrp = myHRP(); if not hrp then return false end
                local p = RaycastParams.new(); p.FilterType = Enum.RaycastFilterType.Exclude; p.FilterDescendantsInstances = exclude()
                return workspace:Raycast(hrp.Position, hrp.CFrame.LookVector * 4.5, p) ~= nil
        end
        local function doClimb()
            if climbing or not on then return end
            local character=myChar(); local root=myHRP(); if not root then return end
            climbing=true
            task.spawn(function()
                local ok,err=pcall(function()
                    fireKnit("MovementService","Parkour"); play("jump")
                    local deadline=tick()+0.3
                    while on and character==myChar() and root.Parent and tick()<deadline and forwardWall() do
                        local velocity=root.AssemblyLinearVelocity
                        root.AssemblyLinearVelocity=Vector3.new(velocity.X,44,velocity.Z)
                        task.wait(0.03)
                    end
                    if on and character==myChar() then play("fall") end
                end)
                climbing=false
                if not ok then warn("[DreamHub Climb] "..tostring(err)) end
            end)
        end

        RunService.Heartbeat:Connect(function()
                if not on then return end
                local hrp = myHRP(); if not hrp then return end
                local c = myChar(); local hum = c and c:FindFirstChildOfClass("Humanoid")
                local airborne = hum ~= nil and hum.FloorMaterial == Enum.Material.Air
                local rising = hrp.AssemblyLinearVelocity.Y > 2                            -- you jumped / are going up
                local intoWall = UIS:IsKeyDown(Enum.KeyCode.W) and forwardWall()           -- running INTO a wall on the ground also counts
                -- parkour when airborne/rising near a wall OR running straight into one.
                if ((airborne or rising) and wallNear() or intoWall) and not climbing then
                        -- movement key -> anim (swapped to match in-game: A/going-left uses the right-lean clip, D/going-right uses the left-lean clip)
                        local key = (UIS:IsKeyDown(Enum.KeyCode.A) and "parkRight") or (UIS:IsKeyDown(Enum.KeyCode.D) and "parkLeft") or "parkRight"
                        for k, t in pairs(sideTracks) do if k ~= key and t.IsPlaying then pcall(function() t:Stop() end) end end  -- stop the other side's anim
                        local pt = sideTrack(key); if pt and not pt.IsPlaying then pcall(function() pt:Play() end) end            -- PLAY the anim for your movement direction
                        if forwardWall() then pcall(function() hrp.AssemblyLinearVelocity = Vector3.new(hrp.AssemblyLinearVelocity.X, 34, hrp.AssemblyLinearVelocity.Z) end) end  -- CLIMB only when a wall is directly AHEAD (no launching past side walls)
                        if tick() - last >= 0.35 then last = tick(); fireKnit("MovementService", "Parkour") end
                else
                        stopSides()
                end
        end)
        UIS.InputBegan:Connect(function(input, gpe)
                if on and not UIS:GetFocusedTextBox() and input.KeyCode == Enum.KeyCode.Space and wallNear() then doClimb() end
        end)
        ParkourApi = { set = function(v) on = v == true; if not on then stopSides() end end }
end

-- MODULE: TELEPORT  (anti-setback glide bypass + named JJS locations + saved spots)
do
        local Players = game:GetService("Players")
        local LP = Players.LocalPlayer
        local slots = { nil, nil, nil }
        local SPOTS = {  -- user-saved coordinate spots (ordered so the dropdown keeps this order)
                { "Main Map", Vector3.new(-16.2, 24.4, 14.1) },
                { "Leaderboard", Vector3.new(51.8, 23.6, -96.0) },
                { "Cute", Vector3.new(261.7, 61.8, 467.6) },
                { "Green screen", Vector3.new(292.8, 23.7, 169.2) },
                { "Mall", Vector3.new(76.4, -60.2, -262.6) },
                { "Train", Vector3.new(168.8, -9.7, 158.5) },
                { "Train spawner", Vector3.new(182.3, 0.1, 557.0) },
                { "tze place", Vector3.new(-49.1, 37.6, 255.7) },
                { "Blue buildings", Vector3.new(32.7, 197.1, 136.9) },
                { "sewer", Vector3.new(-88.5, -30.1, -153.5) },
                { "arcade", Vector3.new(244.1, 25.2, -49.2) },
                { "Death (not real death)", Vector3.new(218.3, 24.1, -130.3) },
                { "DEATH", Vector3.new(377.3, -3.9, -113.1) },
                { "BILLBOARD", Vector3.new(-217.5, 55.2, -0.9) },
                { "HOME", Vector3.new(265.3, 73.0, 120.3) },
                { "GET SOME MILK", Vector3.new(-240.9, 28.9, -124.2) },
        }
        local function hrp() local chs = workspace:FindFirstChild("Characters"); local c = (chs and chs:FindFirstChild(LP.Name)) or LP.Character; return c and c:FindFirstChild("HumanoidRootPart") end  -- JJS body lives under workspace.Characters
        local function locate(names)
                for _, nm in ipairs(names) do
                        local obj = workspace:FindFirstChild(nm, true)
                        if obj then
                                if obj:IsA("BasePart") then return obj.Position end
                                local ok, cf = pcall(function() return obj.GetBoundingBox and select(1, obj:GetBoundingBox()) or nil end)
                                if ok and typeof(cf) == "CFrame" then return cf.Position end
                                local ok2, pv = pcall(function() return obj:GetPivot() end)
                                if ok2 and typeof(pv) == "CFrame" then return pv.Position end
                        end
                end
                return nil
        end
        TPApi = {
                setSpeed = function(v) if type(v) == "number" then _G.VX_TP_SPEED = v end end,
                setMethod = function(m) if type(m) == "table" then m = m[1] end _G.VX_TP_METHOD = (m == "Instant" or m == "Glide" or m == "Anchor") and m or "Auto"; _G.VX_TP_USER_METHOD = _G.VX_TP_METHOD end,   -- "Reset" REMOVED: it killed you to get a clean position baseline, which is not a trade worth making
                up = function() local r = hrp(); if r then vxTeleportHard(r.Position + Vector3.new(0, 120, 0), 1.25) end end,
                spawn = function()
                        -- FindFirstChildOfClass is NOT recursive; JJS spawns sit inside workspace.Map, so the old call found
                        -- nothing on most maps and the button silently did nothing.
                        local sp = workspace:FindFirstChildOfClass("SpawnLocation") or workspace:FindFirstChildWhichIsA("SpawnLocation", true)
                        if sp then vxTeleportHard(sp.Position + Vector3.new(0, 4, 0), 1.25)
                        elseif VX_NOTIFY then VX_NOTIFY("No SpawnLocation found on this map", false) end
                end,
                nearest = function()
                        local r = hrp(); if not r then return end
                        local best, bd
                        local function chk(m) if m and m.Name ~= LP.Name and m ~= LP.Character then local h = m:FindFirstChildOfClass("Humanoid"); local rr = m:FindFirstChild("HumanoidRootPart"); if h and h.Health > 0 and rr then local d = (rr.Position - r.Position).Magnitude; if not bd or d < bd then best, bd = rr, d end end end end
                        for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP then chk(plr.Character) end end
                        local chars = workspace:FindFirstChild("Characters"); if chars then for _, m in ipairs(chars:GetChildren()) do chk(m) end end
                        if best then vxTeleportHard(best.Position, 2) end
                end,
                location = function(names) local p = locate(names); if p then vxTeleportHard(p + Vector3.new(0, 5, 0), 1.25) elseif VX_NOTIFY then VX_NOTIFY("Location '" .. tostring(names[1]) .. "' not found", false) end return p ~= nil end,
                save = function(n) local r = hrp(); if r then slots[n] = r.Position end end,
                goto_ = function(n) if slots[n] then vxTeleportHard(slots[n], 1.25) end end,
                spotNames = function() local t = {}; for _, s in ipairs(SPOTS) do t[#t + 1] = s[1] end return t end,
                -- ═══ r13: "LOCATION STILL DID NOT WORK" ═══ Every Location button used to FORCE _G.VX_TP_METHOD =
                -- "Instant" - one raw PivotTo across hundreds of studs, which is exactly the shape a server
                -- rejects (and public servers reject hardest), so the button rubber-banded back and read as
                -- "did nothing". The velocity-glide leg (your method, Glide by default) is the one tuned on the
                -- recorder capture: believable flight, AC ack passes fired en route, arrival verified. Long trips
                -- take a few seconds of flying - that is the trade for actually sticking.
                spot = function(name)
                        for _, s in ipairs(SPOTS) do
                                if s[1] == name then
                                        local dest = s[2] + Vector3.new(0, 4, 0)
                                        local r0 = hrp()
                                        local cf = r0 and (CFrame.new(dest) * r0.CFrame.Rotation) or CFrame.new(dest)
                                        local arrived = safeTeleport(cf, 2)
                                        if not arrived then
                                                -- rejected or interrupted: ONE retry, pinned to the glide leg so a
                                                -- user-pinned "Instant" setting cannot sabotage the second try too.
                                                local prev = _G.VX_TP_METHOD
                                                _G.VX_TP_METHOD = "Glide"
                                                arrived = safeTeleport(cf, 2)
                                                _G.VX_TP_METHOD = prev
                                        end
                                        if arrived then
                                                -- LAND ON THE GROUND, not inside it: raycast down from just above the
                                                -- arrival and settle on the first solid floor. A stale spot Y (map
                                                -- updated, building moved) then still puts you ON something instead
                                                -- of clipping through it and falling.
                                                pcall(function()
                                                        local c = vxMyChar(); local r = c and c:FindFirstChild("HumanoidRootPart")
                                                        if r then
                                                                local rp = RaycastParams.new()
                                                                rp.FilterType = Enum.RaycastFilterType.Exclude
                                                                rp.FilterDescendantsInstances = { c, workspace:FindFirstChild("Characters") or c, workspace.CurrentCamera }
                                                                rp.RespectCanCollide = true
                                                                local hit = workspace:Raycast(r.Position + Vector3.new(0, 8, 0), Vector3.new(0, -40, 0), rp)
                                                                if hit then
                                                                        local snap = CFrame.new(hit.Position + Vector3.new(0, 3.2, 0))
                                                                        if (r.Position - snap.Position).Magnitude < 12 then pcall(function() c:PivotTo(snap) end) end
                                                                end
                                                        end
                                                end)
                                        end
                                        -- F9 console ALWAYS gets the outcome (toasts are silenced by default; a silent
                                        -- fail is exactly how "Location still did not work" felt).
                                        print("[DreamHub Teleport] '" .. tostring(name) .. "': " .. (arrived and "arrived" or "server rejected the move (try TP Method: Glide)"))
                                        if VX_NOTIFY then VX_NOTIFY("Teleport '" .. tostring(name) .. "': " .. (arrived and "arrived" or "server rejected the move (try TP Method: Glide)")) end
                                        return arrived
                                end
                        end
                        if VX_NOTIFY then VX_NOTIFY("Teleport: no saved spot called '" .. tostring(name) .. "'", false) end
                        return false
                end,
                playerNames = function() local t = {}; for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP then t[#t + 1] = plr.Name end end return t end,   -- list other players
                tpPlayer = function(name)  -- teleport just BEHIND a chosen player (setback-resistant)
                        local hrpTarget
                        local plr = name and Players:FindFirstChild(name)
                        -- Private server: the game's own "Go" teleport moves you server-side - try it first for a real Player.
                        if plr and _G.VX_TP_TO_PLAYER and _G.VX_TP_TO_PLAYER(plr) then return true end
                        if plr and plr.Character then hrpTarget = plr.Character:FindFirstChild("HumanoidRootPart") end
                        if not hrpTarget then local chs = workspace:FindFirstChild("Characters"); local mdl = chs and chs:FindFirstChild(name); hrpTarget = mdl and mdl:FindFirstChild("HumanoidRootPart") end
                        if hrpTarget then vxTeleportHard(hrpTarget.Position - hrpTarget.CFrame.LookVector * 4 + Vector3.new(0, 3, 0), 1.25); return true end
                        if VX_NOTIFY then VX_NOTIFY("Player '" .. tostring(name) .. "' not found", false) end
                        return false
                end,
        }
end

-- MODULE: M1 COMBO  (Down Slam / Uppercut for EVERY character)
-- Counts your REAL M1 hits by ANIMATION using the full per-character M1 id database (_G.VX_M1_IDS - all 20
-- fires at the wrong combo step ('auto uppercut no work'). An M1 ANIM only plays when your character
-- actually swings - so hit #3 is exactly when the launcher window is open, on any character.
do
        local Players = game:GetService("Players")
        local UIS = game:GetService("UserInputService")
        local VIM = game:GetService("VirtualInputManager")
        local LP = Players.LocalPlayer
        local mode, lastSwing, count, busy = "Off", 0, 0, false
        -- ═══ "IT SHOULD BE AUTO UPPER CUT AND DOWN SLAM" ═══ These were one dropdown, so you could only ever have
        -- one of them armed. They are independent toggles now and both can run in the same combo: the slam takes
        -- swing 2 (landing on M1 #3) and the uppercut takes its own count, so they do not fight for the same beat.
        -- `mode` is kept only so the old setMode entry point and the test buttons still work.
        local slamFlag, upperFlag = false, false
        local function slamOn()  return slamFlag  or mode == "Down Slam" end
        local function upperOn() return upperFlag or mode == "Uppercut" end
        local needHits = 3   -- chain hits before the launcher fires (slider-adjustable: characters have different chain lengths)
        local function myModel() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
        local function act(arg)
                local svc = vxMyCharSvc()
                if svc then
                        fireKnit(svc, "Activated", arg)
                else
                        for _, c in ipairs(CHAR_NAMES) do fireKnit(c .. "Service", "Activated", arg) end   -- char not detected: hit all 21 - only YOURS exists server-side
                end
        end
        local function realM1()  -- a REAL M1 click at screen center: the game's own input converts held-space M1 -> uptilt / airborne falling M1 -> slam
                -- FACE THE TARGET FIRST. A centre-screen click whiffs entirely if nobody is in front of you, and a
                -- whiffed swing produces no slam/uppercut no matter how the timing is set up.
                pcall(function()
                        local c = myModel(); local hrp = c and c:FindFirstChild("HumanoidRootPart")
                        if not hrp then return end
                        local best, bd
                        local function chk(m)
                                if not m or m.Name == LP.Name or m == LP.Character then return end
                                local r = m:FindFirstChild("HumanoidRootPart"); local hh = m:FindFirstChildOfClass("Humanoid")
                                if r and (not hh or hh.Health > 0) then
                                        local d = (r.Position - hrp.Position).Magnitude
                                        if d < 18 and (not bd or d < bd) then best, bd = r, d end
                                end
                        end
                        for _, pl in ipairs(game:GetService("Players"):GetPlayers()) do if pl ~= LP then chk(pl.Character) end end
                        local chs = workspace:FindFirstChild("Characters"); if chs then for _, m in ipairs(chs:GetChildren()) do chk(m) end end
                        if best then hrp.CFrame = CFrame.lookAt(hrp.Position, Vector3.new(best.Position.X, hrp.Position.Y, best.Position.Z)) end
                end)
                local cam = workspace.CurrentCamera; local v = (cam and cam.ViewportSize) or Vector2.new(800, 600)
                pcall(function() VIM:SendMouseButtonEvent(v.X / 2, v.Y / 2, 0, true, game, 0); task.wait(0.04); VIM:SendMouseButtonEvent(v.X / 2, v.Y / 2, 0, false, game, 0) end)
        end
        local function jump()  -- small BUNNY HOP for the DOWN SLAM (a 50-stud rocket looked obvious)
                _G.VX_LAUNCHING = tick()  -- tell Side Dash (its flat dash clamps Y) to stand down for a moment so it can't cancel this lift
                _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Space] = tick() + 0.5
                local c = myModel()
                local h = c and c:FindFirstChildOfClass("Humanoid"); local hrp = c and c:FindFirstChild("HumanoidRootPart")
                pcall(function() VIM:SendKeyEvent(true, Enum.KeyCode.Space, false, game); task.wait(0.02); VIM:SendKeyEvent(false, Enum.KeyCode.Space, false, game) end)  -- real Space press
                if h then pcall(function() h:ChangeState(Enum.HumanoidStateType.Jumping) end) end                                          -- force jump state
                if hrp then pcall(function() local v = hrp.AssemblyLinearVelocity; hrp.AssemblyLinearVelocity = Vector3.new(v.X, math.max(v.Y, 26), v.Z) end) end  -- nudge to hop height only = natural bunny hop
        end
        -- (Removed: dead duplicate `finisher()`/`note()` from an earlier rewrite — the LIVE trigger below is the only
        -- uppercut/downslam implementation now. Per user spec: UPPERCUT = hold Space + 4 M1s; DOWN SLAM = 3 M1s, jump, M1.)
        -- FULL per-character UPPERCUT M1 database (user-captured): every swing of every character's M1 chain,
        -- so the 3-swing count works on ALL of them. The old DB only had SOME swings per character -> the count
        -- never reached 3 on most characters ('auto uppercut/downslam no work').
        -- NOT captured yet (uppercut coming soon): Crow (Mei Mei), Mangaka, Black Death, Disaster Plants.
        local UPPERCUT_M1 = {
                -- Vessel                Gojo                    Restless
                "95295463826732","105077924973072","124862357369335","134243365075812",
                "127851700400958","72548435296350","84547415708554",
                "94588892125071","97868312130612","140588454098230","109299799610861",
                -- 92966188946988 = the AIRBORNE attack swing, captured from a live recording and previously unknown to
                -- this file at all. In the capture it plays on every air M1 and is always followed by a landing at
                -- ~-42 Y velocity, i.e. it IS the down slam swing. Without it here an airborne M1 counted as no swing,
                -- which is exactly why the armed slam never landed.
                "92966188946988",
                -- Ten Shadows           Perfection              Blood Main
                "75337033003776","138489871864252","96185406489877",
                "126277739156443","99710481887795","121322029260156","98845475810982",
                "119042572747325",
                -- Switcher              Defense Attorney        Cursed Part (Yuta)
                "96327114254575","107029561762376","117831239064143",
                "133936641185614","122573730331631","82400997593751","115586282387431",
                "133240987753043","130806585141471","131967150738931","73456086297777",
                -- Puppet Master         Head of Hei             Salary Man
                "98783064085844","85148168523745","108686045412945",
                "101283990868172","108708446862011","77583711129628","116910683335467",
                "84359513001979","79436586236026","102285403332509","78540777177847",
                -- True Cannon           Locust                  Star Rage             Lucky Coward
                "139479927693015","85068785050521","120133391090244","79086910454958","108027796023968","138196552148011",
                "131909724908049","72575786212990","119248903710146",
                "133447840605824","113963875117859","106282708121342",
        }
        local COMBO_IDS = {}
        for _, id in ipairs(UPPERCUT_M1) do COMBO_IDS[id] = true end
        if _G.VX_M1_IDS then for id in pairs(_G.VX_M1_IDS) do COMBO_IDS[id] = true end end   -- merge with the master DB (never clobber)
        for id in pairs(COMBO_IDS) do if _G.VX_M1_IDS then _G.VX_M1_IDS[id] = true end end   -- and feed the new ids BACK so every module sees them
        -- ═══════════ v5 (user's script, ported FAITHFULLY - this is the version that works) ═══════════
        --   Down: fire "Down" instantly with every M1 (the working path, untouched)
        --   Up  : Space held from the 3rd M1; on the 4th, wait for the game's own M1 to register (0.15s),
        --         THEN fire "Up" — no race, no t=0 fire.
        -- Exactly ONE change from the standalone: no `if gp then return end` (this game marks every M1 click
        -- game-processed, so the standalone's gpe bail would stop it from EVER firing inside the hub).
        -- eating your REAL clicks = "uppercut/downslam not working".
        local Config = {
                Cooldown = 0.12,   -- was 0.30: longer than a JJS swing, so it swallowed every other real M1
                Manual   = nil,
                UpArg          = "Up",
                UpFireDelay    = 0.15,  -- wait for the game's own 4th M1 to register, then fire
                UpFireDelay2   = 0.30,  -- insurance second fire
                M1ResetWindow  = 1.20,  -- clicks farther apart than this reset the combo count
                SpaceHold      = 0.45,  -- Space released this long after the 4th M1
        }
        local V5CharNames = {
                "Itadori", "Gojo", "Hakari", "Megumi", "Mahito", "Choso", "Todo",
                "Hiromi", "Yuta", "Mechamaru", "Naoya", "Nanami", "Hanami", "Ryu",
                "Locust", "Yuki", "Charles", "Haruta", "MeiMei", "Kurourushi", "Sukuna",
        }
        local State = { char = nil, remote = nil, lastFire = 0, m1Count = 0, lastM1 = 0, spaceHeld = false, downHeld = false, spaceToken = nil }
        local function scanFor(container, lowerName)
                if not container then return false end
                for aName, aVal in pairs(container:GetAttributes()) do
                        if string.find(string.lower(aName), lowerName, 1, true)
                                or string.find(string.lower(tostring(aVal)), lowerName, 1, true) then
                                return true
                        end
                end
                return false
        end
        local function detectCharacter()
                if Config.Manual and Config.Manual ~= "" then return Config.Manual end
                local char = myModel()   -- JJS keeps your real body under workspace.Characters; LP.Character is often the wrong rig
                if not char then return nil end
                for _, name in ipairs(V5CharNames) do
                        local ln = string.lower(name)
                        if scanFor(LP, ln) or scanFor(char, ln) then return name end
                        local hum = char:FindFirstChildOfClass("Humanoid")
                        if hum and scanFor(hum, ln) then return name end
                        for _, v in ipairs(char:GetDescendants()) do
                                if string.find(string.lower(v.Name), ln, 1, true) then return name end
                                if (v:IsA("StringValue") or v:IsA("ObjectValue"))
                                        and v.Value and string.find(string.lower(tostring(v.Value)), ln, 1, true) then
                                        return name
                                end
                        end
                end
                return nil
        end
        local function resolveV5Remote()
                State.remote = nil
                if not State.char then return end
                local knit = game:GetService("ReplicatedStorage"):FindFirstChild("Knit")
                knit = knit and knit:FindFirstChild("Knit")
                local services = knit and knit:FindFirstChild("Services")
                local svc = services and services:FindFirstChild(State.char .. "Service")
                local re  = svc and svc:FindFirstChild("RE")
                State.remote = re and re:FindFirstChild("Activated")
        end
        local function refreshDetection()
                local d = detectCharacter()
                if d and d ~= State.char then
                        State.char = d
                        resolveV5Remote()
                elseif State.char and not State.remote then
                        resolveV5Remote()
                end
        end
        local function fireDir(dir)
                -- Fire BOTH the v5-resolved remote AND the hub's per-char resolver (act = your <Char>Service, or all 21
                -- if undetected — only YOURS responds server-side). Guarantees the correct Activated("Down"/"Up") lands
                -- even when v5 character detection misses = "auto down slam / uppercut doesn't work" fix.
                -- EXACT captured shape: <Char>Service.RE.Activated:FireServer("Down") / ("Up") - one string, no nil.
                -- ═══ WHY THIS USED TO GIVE UP TOO EARLY ═══ `fired` was set from pcall(), and pcall succeeds as long as
                -- the CALL did not error. Firing the WRONG character's Activated remote does not error - it is simply
                -- ignored server-side - so a mis-resolved service still set fired = true and the fallbacks below never
                -- ran. pcall tells us "sent", never "accepted". So we now branch on whether we actually RESOLVED your
                -- character, not on whether a send succeeded.
                local svcName = vxMyCharSvc()                     -- scans moveset -> name -> services
                local resolved = false
                local lastRE = nil                                -- which Instance the scanner fired (dedupe vs State.remote)
                if svcName then
                        local svcs = game:GetService("ReplicatedStorage"):FindFirstChild("Knit")
                        svcs = svcs and svcs:FindFirstChild("Knit"); svcs = svcs and svcs:FindFirstChild("Services")
                        local sv = svcs and svcs:FindFirstChild(svcName)
                        local re = sv and sv:FindFirstChild("RE"); re = re and re:FindFirstChild("Activated")
                        if re then
                                resolved = true
                                lastRE = re
                                local ok = pcall(function() re:FireServer(dir) end)
                                if _G.VX_M1_DEBUG or _G.VX_BF_DEBUG then print("[M1COMBO] fired " .. svcName .. '.RE.Activated("' .. dir .. '") -> ' .. tostring(ok)) end
                        end
                end
                -- ═══ PHYSICAL FALLBACK ═══ If NO remote resolved, do the move the way a player does: the direction key
                -- held across a real click. It is slower and cruder than the remote, but it works on a character whose
                -- service we cannot name - which is the whole of "it must work for ALL characters".
                if not resolved and not State.remote then
                        task.spawn(function()
                                local VIMf = game:GetService("VirtualInputManager")
                                local cam = workspace.CurrentCamera
                                local vp = (cam and cam.ViewportSize) or Vector2.new(800, 600)
                                local cx, cy = vp.X / 2, vp.Y / 2
                                local key = (dir == "Up") and Enum.KeyCode.Space or Enum.KeyCode.S
                                if dir == "Down" then
                                        local c = myModel(); local h = c and c:FindFirstChildOfClass("Humanoid")
                                        if h and h.FloorMaterial ~= Enum.Material.Air then h:ChangeState(Enum.HumanoidStateType.Jumping); task.wait(0.08) end
                                end
                                _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[key] = tick() + 0.5
                                _G.VX_SYNTH_CLICK = tick() + 0.3; _G.VX_LAST_HUMAN_CLICK = tick()
                                pcall(function()
                                        VIMf:SendKeyEvent(true, key, false, game); task.wait(0.02)
                                        VIMf:SendMouseButtonEvent(cx, cy, 0, true, game, 0); task.wait(0.05)
                                        VIMf:SendMouseButtonEvent(cx, cy, 0, false, game, 0); task.wait(0.12)
                                        VIMf:SendKeyEvent(false, key, false, game)
                                end)
                                if _G.VX_M1_DEBUG then print("[M1COMBO] no remote for " .. dir .. " - used physical input") end
                        end)
                end
                -- The v5 resolver is a SEPARATE detection path, so fire it too rather than only as a fallback: when the
                -- two disagree one of them is right, and the wrong one is a no-op. Two sends, not eleven.
                -- Only when the two resolvers genuinely DISAGREE. When they land on the same Instance this was a
                -- double send - and for the uppercut's counted 4x burst, 8 arrivals instead of 4 walks the server's
                -- counter straight past the one that launches.
                if State.remote and State.remote ~= lastRE then
                        local ok = pcall(function() State.remote:FireServer(dir) end)
                        if _G.VX_M1_DEBUG or _G.VX_BF_DEBUG then print("[M1COMBO] also fired State.remote (different instance) -> " .. tostring(ok)) end
                end
                if not resolved and not State.remote then
                        -- Nothing identified your character at all. Sweep the real character services - only yours answers,
                        -- and this is the difference between "does nothing" and "works". Set _G.VX_M1_NOSWEEP = true to
                        -- opt out if you would rather it stay quiet than send a burst.
                        -- ═══ SWEEP IS NOW OPT-IN (_G.VX_M1_SWEEP = true) ═══ It fired up to 11 OTHER characters' Activated
                        -- remotes in one frame on every finisher. Firing remotes for characters you do not own is exactly
                        -- the pattern a server anti-cheat flags, and a 267 kick followed a session with it on. Detection
                        -- failing should mean "nothing happens", never "you get kicked".
                        if _G.VX_M1_SWEEP then
                                for _, nm in ipairs({ "Itadori", "Gojo", "Megumi", "Hakari", "Choso", "Locust", "Mahito", "MeiMei", "Toji", "Yuta", "Sukuna" }) do
                                        if vxSvcHasActivated(nm .. "Service") then pcall(function() fireKnit(nm .. "Service", "Activated", dir) end) end
                                end
                        end
                        if _G.VX_M1_DEBUG or _G.VX_BF_DEBUG then print("[M1COMBO] no service resolved - swept the known character services") end
                end
        end
        -- ═══ WHY THE SPACE HOLD IS BACK ═══
        -- Deleting spaceDown() killed the uppercut outright ("dont even work at all"). So the direction is NOT
        -- carried by the remote argument alone: JJS reads your held MOVEMENT KEY at the moment the swing lands and
        -- the remote only names it. Up = Space, Down = S. Both have to be held across the swing.
        -- The actual cause of "it makes me jump when I don't M1" was never the Space press itself - it was
        -- onSwing() firing on animations that were not real M1s (the character-agnostic fallback counts any
        -- Action-priority track). So the press is restored and the TRIGGER is what got tightened: realM1Now()
        -- below requires a genuine click inside 0.4s, and nothing in this module acts without it.
        -- ═══ UP IS W, NOT SPACE ═══ Down Slam works and Uppercut does not, and the ONLY difference between them
        -- was the key each holds: the slam holds S, the uppercut held Space. Space is JUMP, not a direction - so
        -- the uppercut was hopping you instead of naming a direction, which is both why it did nothing and why it
        -- made you jump. S means "down", so the symmetric key for "up" is W. Same shape as the slam now.
        -- ═══ UP IS SPACE, NOT W ═══ W was a symmetry guess off the working Down-Slam-uses-S pattern, and it does
        -- not work. Space is the version that was explicitly confirmed working ("upper cut is good, just don't make
        -- me jump when I don't M1"). The jumping complaint was never the Space press - it was onSwing firing on
        -- animations that were not real M1s, and realM1Now() fixes that at the trigger. So: Space, guarded.
        local function spaceDown()
                if State.spaceHeld then return end
                State.spaceHeld = true
                _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Space] = tick() + 3   -- our own key: Auto Air/feints must ignore it
                VIM:SendKeyEvent(true, Enum.KeyCode.Space, false, game)
        end
        local function spaceUp()
                if not State.spaceHeld then return end
                State.spaceHeld = false
                VIM:SendKeyEvent(false, Enum.KeyCode.Space, false, game)
                pcall(function() VIM:SendKeyEvent(false, Enum.KeyCode.W, false, game) end)   -- release any W an older build left held
        end
        -- ═══ THE UPPERCUT KEY IS NOW YOURS TO PICK ═══ I have guessed at it four times and each guess costs a
        -- test round. keyDown/keyUp hold whichever key the "Uppercut Key" dropdown selects, reusing spaceHeld as
        -- the tracker so the existing stuck-key watchdog covers every option, not just Space.
        local heldUpKey = nil
        local function keyDown(kc)
                if not kc or State.spaceHeld then return end
                State.spaceHeld = true; heldUpKey = kc
                State.lastUp = tick()   -- the watchdog releases a hold still down 1s after THIS stamp; without
                                        -- it the hold was force-released after one 0.25s tick (silent uppercut killer)
                _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[kc] = tick() + 3   -- our own key: Auto Air / feints / the swap triggers must ignore it
                pcall(function() VIM:SendKeyEvent(true, kc, false, game) end)
        end
        local function keyUp(kc)
                kc = kc or heldUpKey
                if not State.spaceHeld then return end
                State.spaceHeld = false
                pcall(function() if kc then VIM:SendKeyEvent(false, kc, false, game) end end)
                heldUpKey = nil
        end
        -- DOWN SLAM / UPPERCUT are decided by your PHYSICAL STATE (airborne / holding space), not by a string
        -- argument. The old path fired Activated("Down"), which JJS does not accept - so nothing happened. Both
        -- modes now reproduce what a real player does with real inputs.
        -- RESTORED to the version that worked: Down Slam fires the real direction remote, Uppercut counts to 4
        -- while holding Space. The bug was never this logic - it was the TRIGGER (InputBegan never fires for a
        -- sunk attack click). The trigger is now the shared poll; the behaviour below is byte-for-byte the
        -- original, so what worked on FREE works again.
        -- ═══ SWING COUNTING IS ANIMATION-DRIVEN, NOT CLICK-DRIVEN ═══
        -- Counting CLICKS is why Uppercut "only worked if I paused": you can click faster than the game swings,
        -- clicks get deduped/dropped by the input paths, and injected clicks from other features add phantom
        -- counts - so the count and the real combo drift apart. The per-character M1 ANIMATION database in this
        -- module (COMBO_IDS, built above) is exact: one entry plays per real landed swing. It was built and then
        -- never read by anything. Now it drives the counter, so 1-2-3-4 always matches what you actually threw.
        local slamArmed = 0   -- set after the hop; YOUR next M1 inside this window is the down slam
        -- ═══ THE ONE GATE THAT MATTERS ═══ Nothing in this module may act unless you REALLY clicked. The animation
        -- path counts any Action-priority track for characters whose M1 ids were never captured, so without this a
        -- dash / ability / hit-reaction animation counted as a swing - and with the Space hold restored that is
        -- literally "it jumps me when I don't M1". _G.VX_LAST_CLICK is stamped by the shared poll on real clicks
        -- only (injected clicks are excluded), so this is the honest "was that you" test.
        local function realM1Now()
                return (tick() - math.max(tonumber(_G.VX_LAST_CLICK) or 0,tonumber(_G.VX_LAST_HUMAN_CLICK) or 0)) < 0.60
        end
        -- DOWN direction = holding S, the same way Up = holding Space. Movement keys never launch you, so this one
        -- needs no extra guard beyond realM1Now().
        local function downDown()
                if State.downHeld then return end
                State.downHeld = true
                _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.S] = tick() + 3
                VIM:SendKeyEvent(true, Enum.KeyCode.S, false, game)
        end
        local function downUp()
                if not State.downHeld then return end
                State.downHeld = false
                VIM:SendKeyEvent(false, Enum.KeyCode.S, false, game)
        end
        local function airborneNow()
                local c0 = myModel(); local h0 = c0 and c0:FindFirstChildOfClass("Humanoid")
                if not h0 then return false end
                -- FloorMaterial is the primary test, but it lags a frame or two after a launch and reads Concrete while
                -- you are already rising. The humanoid STATE flips immediately, so accept either.
                if h0.FloorMaterial == Enum.Material.Air then return true end
                local st = h0:GetState()
                return st == Enum.HumanoidStateType.Freefall or st == Enum.HumanoidStateType.Jumping
        end
        -- Captured ids for the AIRBORNE attack swing. Seeing one of these is proof you just air-M1'd, which is a
        -- down slam regardless of what FloorMaterial happens to say on that frame.
        local AIR_ATTACK_IDS = { ["92966188946988"] = true }
        -- ONE place fires the slam, with ONE cooldown, so the animation path and the raw-click path below cannot
        -- both announce the same slam (that double-fire burned the cooldown and the second one did nothing).
        local function doSlam(why)
                -- 0.30s was SHORTER than the 0.35s spacing of a held combo's swings, so one combo fired this three
                -- times. 1.0s is longer than any single combo and shorter than the game's 1.2s combo drop, so it is
                -- exactly one slam per combo and a genuinely new combo is never blocked.
                if tick() - (State.lastDown or 0) < 1.00 then return false end
                State.lastDown = tick()
                slamArmed = 0
                State.m1Count = 0
                if _G.VX_M1_DEBUG or _G.VX_BF_DEBUG then print("[M1COMBO] DOWN SLAM (" .. tostring(why) .. ")") end
                -- Symmetric with the uppercut: hold the DIRECTION key across the swing and name it on the remote. Firing
                -- the remote alone is what did nothing, exactly as it did for "Up".
                -- ═══ NO KEY AT ALL ═══ S is the BACKWARD movement key, so ANY hold walks you backwards - shortening it
                -- to 0.12s reduced the push but did not remove it, because the press itself is the movement. The remote
                -- is what performs the move: fireDir is the same call that makes the slam land, and it is proven to
                -- reach the server. So the key press was never doing the work, only the pushing. Same reasoning kills
                -- the uppercut's key: Space made you jump, W did nothing, and neither is needed if the remote lands.
                fireDir("Down")
                downUp()   -- release anything an older build left held
                -- Tell the rest of the hub a finisher is in flight. Auto Swap (Total) reads this and refuses to swap
                -- while a slam/uppercut is mid-animation - a swap yanks you to the target and cancels the move.
                _G.VX_FINISHER_T = tick()
                return true
        end
        -- THE RAW-CLICK SLAM PATH. onSwing() is animation-driven, and an AIRBORNE M1 usually plays a different
        -- (or no) track than the ground combo - so after the hop your slam click produced no counted swing and the
        -- slam never fired. That was the whole "down slam is bad" bug. This runs off the actual click instead.
        local function slamOnClick()
                if not slamOn() then return end
                if tick() >= slamArmed then return end
                -- The airborne test is BACK, now that the slam only ever fires off the ground. Without it this path
                -- stayed armed for 1.6s after a slam, so the first click of your NEXT combo - long after you had
                -- landed - sent another grounded "Down" and wiped the combo counter on its way out. airborneNow()
                -- accepts the Freefall/Jumping humanoid state as well as FloorMaterial, so it does not suffer the
                -- one-frame lag the old comment here was worried about.
                if not airborneNow() then return end
                doSlam("armed click")
        end
        -- (The per-click directional sender that lived here is gone: the namecall hook below rewrites the M1
        --  remote itself, which is the same idea done at the only place that cannot be mistimed.)
        -- ═══ THE FINISHERS RIDE BESIDE THE COMBO NOW (round 6 redesign) ═══ The old path REWROTE the 4th
        -- M1 packet into Activated("Up"/"Down") in the namecall hook. Two failures came from that one idea:
        --   1. the rewritten click never swings - so with the toggles on, roughly every 4th click "did
        --      nothing" (and when the finisher whiffed, JJS held the inputs through the dead animation =
        --      "I can't click when auto downslam/uppercut is on");
        --   2. the rewrite needed four clean packets seen by a hook gated on an exact remote match - any
        --      resolver hiccup and the finisher NEVER fired ("doesn't work, even with the target close").
        -- New behaviour, on counted REAL swings (animation hook above), your clicks always untouched:
        --   DOWN SLAM: an air M1 you threw gets Activated("Down") beside it (the game slams only in the
        --              air, exactly the v5 working path); grounded, after the 3rd swing with a target in
        --              reach, slamNow() hops you and completes the slam itself.
        --   UPPERCUT:  Space is held from the 3rd swing (v5's confirmed shape), your 4th M1 launches, and
        --              Activated("Up") fires 0.15s after it as the belt-and-suspenders. Nothing fires when
        --              nobody is in reach - no more finishing into air, no more input lock.
        local function targetWithin(maxD)
                local c = myModel(); local r = c and c:FindFirstChild("HumanoidRootPart")
                if not r then return nil end
                local function dist(m)
                        if not m or not m.Parent or m == c or m.Name == LP.Name then return nil end
                        local e = m:FindFirstChild("HumanoidRootPart"); local h = m:FindFirstChildOfClass("Humanoid")
                        if not e or not h or h.Health <= 0 then return nil end
                        local d = (e.Position - r.Position).Magnitude
                        if d <= maxD then return d end
                        return nil
                end
                local lock = _G.VX_LOCK; local chosen = lock and lock.get and lock.get()
                local best = dist(chosen)
                for _,m in ipairs(_G.VX_LIVING_MODELS()) do local d=dist(m); if d and (not best or d<best) then best=d end end
                for _, pl in ipairs(game:GetService("Players"):GetPlayers()) do if pl ~= LP then local d = dist(pl.Character); if d and (not best or d < best) then best = d end end end
                return best
        end
        _G.VX_BASIC_RE=function()
            local learned=_G.VX_OBSERVED_BASIC_RE
            if learned and learned.body==myModel() and learned.remote and learned.remote.Parent then return learned.remote end
            local services=vxServicesFolder(); local name=vxMyCharSvc()
            local service=services and name and services:FindFirstChild(name)
            local folder=service and service:FindFirstChild("RE")
            return folder and folder:FindFirstChild("Activated")
        end

        _G.VX_NATIVE_FINISHER=function(which,live)
            local c=myModel(); local h=c and c:FindFirstChildOfClass("Humanoid")
            if which~="Down" and which~="Up" then return false end
            if not h or h.Health<=0 or not live() or UIS:GetFocusedTextBox() or _G.VX_FINISHER_INPUT then return false end
            local token={}; _G.VX_FINISHER_INPUT=token
            local remote=which=="Up" and _G.VX_BASIC_RE and _G.VX_BASIC_RE() or nil
            local cam=workspace.CurrentCamera; local vp=cam and cam.ViewportSize
            local x,y=vp and vp.X/2 or 400,vp and vp.Y/2 or 300
            local spaceHeld,mouseHeld,sent=false,false,false
            local downSeen,fourthSeen=false,false;local clickAt;local connection
            local function valid()
                return _G.VX_FINISHER_INPUT==token and myModel()==c and h.Health>0 and live() and not UIS:GetFocusedTextBox()
            end
            local ok,err=pcall(function()
                if which=="Down" then
                    local animator=h:FindFirstChildOfClass("Animator")
                    if animator then connection=animator.AnimationPlayed:Connect(function(track)
                        local id=tostring(track.Animation and track.Animation.AnimationId or ""):match("%d+")
                        if not clickAt then return end
                        if id=="92966188946988" then
                            downSeen=true;fourthSeen=true
                            _G.VX_DOWN_OBSERVED_T=tick();_G.VX_DOWN_T=tick();_G.VX_FINISHER_T=tick()
                        elseif id and _G.VX_M1_IDS and _G.VX_M1_IDS[id] then fourthSeen=true end
                    end) end
                    -- Stop the held native M1 loop BEFORE Space, or its automatic fourth becomes Up.
                    _G.VX_SYNTH_CLICK=tick()+1.0
                    VIM:SendMouseButtonEvent(x,y,0,false,game,0)
                    local root=c:FindFirstChild("HumanoidRootPart")
                    local startY=root and root.Position.Y or 0
                    local wasAir=h.FloorMaterial==Enum.Material.Air
                    local function lifted()
                        return root and (wasAir or h.FloorMaterial==Enum.Material.Air and root.Position.Y-startY>0.35)
                    end
                    if not wasAir then
                        _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {};_G.VX_INJ_KEYS[Enum.KeyCode.Space]=tick()+0.75
                        VIM:SendKeyEvent(true,Enum.KeyCode.Space,false,game);spaceHeld=true
                        local deadline=tick()+0.6
                        repeat
                            if not valid() then return end
                            h.Jump=true;task.wait(0.016)
                        until lifted() or tick()>=deadline
                    end
                    h.Jump=false;VIM:SendKeyEvent(false,Enum.KeyCode.Space,false,game);spaceHeld=false
                    if not valid() or not lifted() then _G.VX_FINISHER_STATUS="native hop refused; no fourth input";return end
                    -- Experimental: a groundslam is an airborne fourth, with jump released.
                    -- Wait until the hop reaches its apex instead of clicking just after takeoff.
                    -- If we land or are cancelled, do not spend an ordinary fourth on the ground.
                    local apexDeadline=tick()+0.45
                    while valid() and h.FloorMaterial==Enum.Material.Air and root
                        and root.AssemblyLinearVelocity.Y> 0 and tick()<apexDeadline do
                        game:GetService("RunService").Heartbeat:Wait()
                    end
                    if not valid() then return end
                    if h.FloorMaterial~=Enum.Material.Air or not root or root.AssemblyLinearVelocity.Y> 0 then
                        _G.VX_FINISHER_STATUS="hop did not reach airborne apex; no fourth input"
                        return
                    end
                else
                    _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {};_G.VX_INJ_KEYS[Enum.KeyCode.Space]=tick()+0.2
                    VIM:SendKeyEvent(true,Enum.KeyCode.Space,false,game);spaceHeld=true;task.wait(0.025)
                end
                if not valid() then return end
                if remote then remote:FireServer(which);sent=true
                else
                    -- A fourth pressed during third-swing recovery can be ignored. Observe acceptance
                    -- before retrying; any accepted basic fourth ends retries, even if it was not Down.
                    local deadline=tick()+0.36
                    for attempt=1,3 do
                        if not valid() or fourthSeen then break end
                        if which=="Down" and h.FloorMaterial~=Enum.Material.Air then break end
                        _G.VX_FINISHER_CLICK=token
                        _G.VX_SYNTH_CLICK=tick()+0.25;_G.VX_COMBAT_SEQUENCE=tick()+0.25
                        VIM:SendMouseButtonEvent(x,y,0,false,game,0);task.wait(0.016)
                        if not valid() then return end
                        clickAt=tick();mouseHeld=true
                        VIM:SendMouseButtonEvent(x,y,0,true,game,0);sent=true
                        task.wait(0.04)
                        VIM:SendMouseButtonEvent(x,y,0,false,game,0);mouseHeld=false
                        if _G.VX_FINISHER_CLICK==token then _G.VX_FINISHER_CLICK=nil end
                        local observeUntil=math.min(deadline,tick()+0.10)
                        while valid() and not fourthSeen and tick()<observeUntil do task.wait() end
                        if tick()>=deadline then break end
                    end
                end
                _G.VX_FINISHER_T=tick()
                if which=="Up" then _G.VX_UPPER_T=tick() else
                    local deadline=tick()+0.35
                    while valid() and not downSeen and tick()<deadline do task.wait() end
                    _G.VX_FINISHER_STATUS=downSeen and "native downslam animation observed; server hit unconfirmed" or (sent and "native fourth input sent; downslam animation unconfirmed" or "no airborne fourth input sent")
                end
            end)
            if connection then connection:Disconnect() end
            if mouseHeld then pcall(function() VIM:SendMouseButtonEvent(x,y,0,false,game,0) end) end
            if spaceHeld then pcall(function() VIM:SendKeyEvent(false,Enum.KeyCode.Space,false,game) end) end
            if which=="Down" and h.Parent then h.Jump=false end
            if _G.VX_FINISHER_CLICK==token then _G.VX_FINISHER_CLICK=nil end
            if _G.VX_FINISHER_INPUT==token then _G.VX_FINISHER_INPUT=nil end
            if not ok then warn("[DreamHub Finisher] "..tostring(err)) end
            return ok and sent
        end

        local function onSwing(observedTrack)
            -- ═══ r16: THE AUTO-DOWN-SLAM TRIGGER WAS DEAD CODE ═══ "auto down slam still don't work."
            -- FinisherAssistApi is ALWAYS loaded, so this delegation owned every swing and RETURNED - this
            -- module's own counter (State.m1Count) NEVER advanced, and the Auto Down Slam / Auto Uppercut
            -- toggles below could never fire no matter what they were set to. The delegation now only owns
            -- the swing when the FINISHER ASSIST's own auto toggles are the live ones (isAutoUp/isAutoDown
            -- read-backs); otherwise the swing falls through to OUR counter and the slam arms on swing 3.
            if FinisherAssistApi and (slamOn() or upperOn()) then
                local assistAuto=(FinisherAssistApi.isAutoDown and FinisherAssistApi.isAutoDown())
                    or (FinisherAssistApi.isAutoUp and FinisherAssistApi.isAutoUp())
                if assistAuto then
                    if realM1Now() and tick()>=(tonumber(_G.VX_SYNTH_CLICK) or 0) then
                        FinisherAssistApi.fromSwing(observedTrack)
                    elseif observedTrack and tick()>=(tonumber(_G.VX_SYNTH_CLICK) or 0) then
                        local observedAt=tick();local body=myModel()
                        task.delay(0.05,function()
                            local clicked=tonumber(_G.VX_LAST_HUMAN_CLICK) or -math.huge
                            if myModel()==body and observedTrack.IsPlaying and clicked>=observedAt-0.02
                                and clicked<=observedAt+0.08 and tick()>=(tonumber(_G.VX_SYNTH_CLICK) or 0)
                                and FinisherAssistApi and (FinisherAssistApi.isAutoDown() or FinisherAssistApi.isAutoUp()) then
                                FinisherAssistApi.fromSwing(observedTrack)
                            end
                        end)
                    end
                    return
                end
            end
            if not (slamOn() or upperOn()) or not realM1Now() then return end
            if tick() < (tonumber(_G.VX_COMBAT_SEQUENCE) or 0) or tick() < (tonumber(_G.VX_BF_CHAINDRIVE) or 0) then return end
            local now = tick()
            if now - State.lastM1 < 0.12 then return end
            -- ═══ r14: WIDER COMBO WINDOW ═══ "clicking slow or pausing and it stops working." Our counter
            -- used to reset at 1.2s of silence - a slow clicker never reached swing 3, so the slam never armed.
            -- 1.6s keeps the count alive through slow clicks and short pauses (the game's own combo window
            -- is longer than we assumed on most rigs).
            if now - State.lastM1 > 1.6 then State.m1Count = 0 end
            State.lastM1 = now
            State.m1Count = State.m1Count + 1
            local reach = targetWithin(9)
            if slamOn() and State.m1Count==3 and reach then
                -- ═══ r18: FIXED 0.07s BEAT INTO THE FORCE-JUMP ═══ "auto downslam timing is very bad." The
                -- r17 0.07s delay then VX_NATIVE_FINISHER's wait-for-airborne LOOP (up to 0.5s on laggy rigs)
                -- was the slow path. The VX_NATIVE_FINISHER function itself is rewritten in r18 to a FIXED
                -- +0.08s force-jump beat (no loop). Total chain: 0.07 + 0.08 + remote = ~0.15s.
                if now-(State.lastSlamArm or 0)<0.9 then return end
                State.lastSlamArm=now
                local bodyAtStart=myModel()
                task.delay(0.07,function()
                    if not slamOn() or myModel()~=bodyAtStart then return end
                    if tick()<(tonumber(_G.VX_SYNTH_CLICK) or 0) then return end
                    if not targetWithin(8) then return end
                    _G.VX_NATIVE_FINISHER("Down",function() return slamOn() and myModel()==bodyAtStart and targetWithin(9)~=nil end)
                end)
            elseif upperOn() then
                if State.m1Count==3 and reach then
                    keyDown(Enum.KeyCode.Space)
                    State.upperArmedAt=now
                elseif State.m1Count>=4 then
                    _G.VX_FINISHER_T=now; _G.VX_UPPER_T=now
                    task.delay(0.08,function() keyUp(Enum.KeyCode.Space) end)
                end
            end
            if State.m1Count >= 4 then
                State.m1Count = 0
            end
        end

        -- Hook the animator and count real swings. Re-hooks whenever the Animator instance changes (respawn /
        -- character swap), because a track bound to a dead Animator never fires again.
        -- Hook EVERY rig that can play your combat animations. JJS uses workspace.Characters[name] and
        -- LP.Character at different moments; hooking only one meant swings on the other never counted, so the
        -- 3rd/4th hit never arrived. Weak-keyed so dead animators drop out on their own.
        local comboHooked = setmetatable({}, { __mode = "k" })
        local comboLastId, comboLastAt = nil, 0
        local comboAnimLive = false   -- true once at least one animator is hooked (the click fallback stands down)
        local function hookComboAnims()
                local rigs = {}
                local chs = workspace:FindFirstChild("Characters")
                local resolved = chs and chs:FindFirstChild(LP.Name)
                if resolved then rigs[#rigs + 1] = resolved end
                if LP.Character and LP.Character ~= resolved then rigs[#rigs + 1] = LP.Character end
                for _, char in ipairs(rigs) do
                        local h = char:FindFirstChildOfClass("Humanoid")
                        local a = h and h:FindFirstChildOfClass("Animator")
                        if a and not comboHooked[a] then
                                comboHooked[a] = true
                                comboAnimLive = true
                                a.AnimationPlayed:Connect(function(track)
                                        if not (slamOn() or upperOn()) and not (_G.VXBF2 and _G.VXBF2.chainEnabled()) then return end
                                        local ok, id = pcall(function() return tostring(track.Animation.AnimationId):match("%d+") end)
                                        if not ok or not id then return end
                                        if id == comboLastId and tick()-comboLastAt < 0.12 then return end
                                        comboLastId, comboLastAt = id, tick()
                                        -- CHARACTER-AGNOSTIC SWING DETECTION. Relying on an id database means any character whose
                                        -- M1 ids were never captured simply never counts a swing - which is exactly "it does not
                                        -- work at all" on that character. A listed id still counts instantly; otherwise ANY
                                        -- Action-priority animation that starts right after a real click is a swing. That is the
                                        -- same universal test the working Black Flash engine uses, and it needs no database.
                                        local isKnown = COMBO_IDS[id] or (_G.VX_M1_IDS and _G.VX_M1_IDS[id])
                                        local isSwing = isKnown
                                        -- ═══ THE CHAIN COUNTS SWINGS ON EVERY CHARACTER ═══ the M1 chain used this
                                        -- counter too, and this counter only accepted CAPTURED ids - Todo (and every
                                        -- character added after the capture) counted zero swings, so "BF After (M1s)"
                                        -- never reached its number and the chain never ran. A listed id still counts
                                        -- for the finisher assists; the CHAIN additionally accepts the same universal
                                        -- test the working Black Flash engine uses: an Action-priority track that has
                                        -- only just started, right behind a real human click. Needs no database.
                                        local chainSwing=isSwing
                                        if not chainSwing then
                                            local packet=_G.VX_OBSERVED_BASIC_RE
                                            local priority=tostring(track.Priority)
                                            if packet and packet.body==myModel() and tick()-(tonumber(packet.at) or -math.huge)<=0.12
                                                and not track.Looped and priority:find("Action",1,true)
                                                and not AIR_ATTACK_IDS[id] and (tonumber(track.TimePosition) or 0)<0.12
                                                and tick()-(tonumber(_G.VX_LAST_HUMAN_CLICK) or 0)<=0.25 then
                                                chainSwing=true
                                                if _G.VX_M1_IDS then _G.VX_M1_IDS[id]=true end
                                            end
                                        end

                                        -- Unknown ability animations are not counted as M1s.
                                        if not isSwing and not chainSwing and not AIR_ATTACK_IDS[id]
                                            and not track.Looped and tostring(track.Priority):find("Action",1,true) then
                                            local eventAt=tick();local body=myModel()
                                            task.delay(0.09,function()
                                                local packet=_G.VX_OBSERVED_BASIC_RE
                                                local human=tonumber(_G.VX_LAST_HUMAN_CLICK) or -math.huge
                                                if body~=myModel() or not track.IsPlaying or _G.VX_COMBAT_OWNER
                                                    or tick()<(tonumber(_G.VX_SYNTH_CLICK) or 0) then return end
                                                if packet and packet.body==body and math.abs((tonumber(packet.at) or 0)-eventAt)<=0.15
                                                    and human>=eventAt-0.25 and human<=eventAt+0.08 then
                                                    if _G.VX_M1_IDS then _G.VX_M1_IDS[id]=true end
                                                    onSwing(track)
                                                    if _G.VX_CHAIN_COUNT then pcall(_G.VX_CHAIN_COUNT,track) end
                                                end
                                            end)
                                        end

                                        -- An AIRBORNE attack animation is a down slam by definition - announce it directly rather than
                                        -- routing it through the ground-combo counter, which has no concept of an air swing.
                                        if AIR_ATTACK_IDS[id] and slamOn() then
                                                -- The existing fourth attack is rewritten by the shared hook.
                                                return
                                        end
                                        if isSwing or chainSwing then
                                                onSwing(track)
                                        end
                                        -- Feed the Black Flash chain the same REAL swing. It used to count raw clicks, which a
                                        -- held combo does not produce - four swings arrive from one click.
                                        if chainSwing and _G.VX_CHAIN_COUNT then pcall(_G.VX_CHAIN_COUNT,track) end
                                end)
                        end
                end
        end
        _G.VX_REFRESH_COMBO_HOOK=hookComboAnims
        pcall(hookComboAnims)
        task.spawn(function() while true do pcall(hookComboAnims); task.wait(0.5) end end)

        -- Kept for compatibility: the click paths no longer count. If the animation DB somehow misses this
        -- character entirely, this is the safety net that still advances the combo.
        local function onM1()
                if not (slamOn() or upperOn()) then return end
                if comboAnimLive and tick() - State.lastM1 < 1.5 then return end   -- the animation path is counting; do not double-count this click
                onSwing()
        end
        -- REAL M1s come from the shared poll detector, NOT InputBegan: the game sinks the attack click, so the old
        -- InputBegan hook only ever fired on GUI/empty clicks = Auto Uppercut / Down Slam never ran at all.
        -- BOTH triggers, de-duplicated. It used to work off InputBegan, so that path stays; the poll is added
        -- because InputBegan does not see a sunk attack click on every build. Whichever fires first wins and the
        -- other is ignored for 0.05s, so a single M1 can never run onM1 twice.
        local __m1Guard = 0
        local function __m1Once()
                if UIS:GetFocusedTextBox() then return end
                if tick() < (tonumber(_G.VX_SYNTH_CLICK) or 0) then return end   -- ignore clicks WE injected
                if tick() - __m1Guard < 0.05 then return end
                __m1Guard = tick()
                -- The armed down slam runs off the RAW click, ahead of (and independently of) the swing counter: onM1
                -- refuses to count while the animation path is live, and an airborne M1 often plays no counted track at
                -- all, so routing the slam through the counter is what made it miss. doSlam's own cooldown stops this
                -- and the animation path from ever announcing the same slam twice.
                -- Raw click events do not count accepted swings.
        end
        UIS.InputBegan:Connect(function(input, _)
                if input.UserInputType == Enum.UserInputType.MouseButton1 then __m1Once() end
        end)
        if _G.VX_M1_SUB then _G.VX_M1_SUB("m1combo", function() __m1Once() end) end
        LP.CharacterAdded:Connect(function()
                task.wait(0.4)
                spaceUp(); downUp()   -- never carry a held direction key across a respawn
                State.spaceToken = nil
                State.m1Count = 0
                State.char = nil
                State.remote = nil
                refreshDetection()
        end)
        task.spawn(function()
                while true do
                        if mode ~= "Off" then refreshDetection() end
                        task.wait(1)
                end
        end)
        -- STUCK-KEY WATCHDOG. A held Space or S that never gets released is far worse than a missed uppercut: you
        -- would jump or walk backwards forever. Both are only ever held for 0.22s, so anything still down after 1s
        -- means a task.delay was lost (respawn, error, mode change mid-flight) and we release it unconditionally.
        task.spawn(function()
                while true do
                        task.wait(0.25)
                        -- keyUp releases whichever key the Uppercut Key dropdown is holding; spaceUp covers the legacy
                        -- Space/W pair. Both are no-ops when nothing is held, so running both is free and neither option
                        -- can leave a key stuck down.
                        if State.spaceHeld and tick() - (State.lastUp or 0) > 1 then pcall(keyUp); pcall(spaceUp) end
                        if State.downHeld and tick() - (State.lastDown or 0) > 1 then pcall(downUp) end
                end
        end)

        -- Move transport: decide without sending, then forward exactly once outside pcall.
        -- Resolve the character remote on a worker, never inside a game's FireServer call.
        do
            local cachedRemote, cachedBody
            local cachedNames={}
            local cancelToken={}; _G.VX_CANCEL_TOKEN=cancelToken
            local function norm(value) return tostring(value or ""):lower():gsub("[^%w]",""):gsub("service$","") end
            local function selectedCharacter()
                local chosen=norm(_G.VX_CANCEL_CHAR or "Any")
                return chosen=="any" or cachedNames[chosen]==true
            end
            _G.VX_KEY_BLOCKED=function(key)
                if not _G.VX_CANCEL_ON or not selectedCharacter() then return false end
                local slots={ [Enum.KeyCode.One]=1,[Enum.KeyCode.Two]=2,[Enum.KeyCode.Three]=3,[Enum.KeyCode.Four]=4 }
                local slot=slots[key]
                return slot and _G.VX_CANCEL_SLOTS and _G.VX_CANCEL_SLOTS[slot]==true or false
            end
            pcall(function()
                game:GetService("ContextActionService"):BindActionAtPriority("VX_SelectedMoveBlock",function(_,state,input)
                    if game:GetService("UserInputService"):GetFocusedTextBox() then return Enum.ContextActionResult.Pass end
                    if state~=Enum.UserInputState.Begin then return Enum.ContextActionResult.Pass end
                    local slots={ [Enum.KeyCode.One]=1,[Enum.KeyCode.Two]=2,[Enum.KeyCode.Three]=3,[Enum.KeyCode.Four]=4 }
                    local slot=slots[input.KeyCode]
                    if slot then _G.VX_LASTNUM_KEY={n=slot,t=tick()} end
                    if _G.VX_KEY_BLOCKED(input.KeyCode) then return Enum.ContextActionResult.Sink end
                    return Enum.ContextActionResult.Pass
                end,false,4500,Enum.KeyCode.One,Enum.KeyCode.Two,Enum.KeyCode.Three,Enum.KeyCode.Four)
            end)
            task.spawn(function()
                while true do
                    local ok, remote, body = pcall(function()
                        local c = myModel()
                        local name = vxMyCharSvc()
                        local names={}
                        if name then names[norm(name)]=true end
                        local detected=detectCharName(c)
                        if detected then names[norm(detected)]=true end
                        cachedNames=names
                        local services = vxServicesFolder()
                        local service = name and services and services:FindFirstChild(name)
                        local folder = service and service:FindFirstChild("RE")
                        return folder and folder:FindFirstChild("Activated"),c
                    end)
                    cachedRemote, cachedBody = ok and remote or nil, ok and body or nil
                    if not ok then cachedNames={} end
                    task.wait(0.25)
                end
            end)
            local function decide(remote,args)
                local intent=_G.VX_SIDE_DASH_INTENT
                if intent and intent.body==myModel() and tick()<intent.expires and remote.Name=="Dash"
                    and remote.Parent and remote.Parent.Name=="RE" and remote.Parent.Parent and remote.Parent.Parent.Name=="MovementService" then
                    if intent.stage~="input" or intent.sent then return cancelToken end
                    if type(args[1])=="string" then
                        local packet=table.clone(args);packet[1]=intent.direction
                        intent.sent=true;intent.sentAt=tick();_G.VX_NATIVE_DASH_PACKET=intent.direction
                        return packet
                    end
                end
                local move=args[1]
                if typeof(move)=="Instance" and move.Parent and move.Parent.Name=="Moveset" and move.Parent.Parent==myModel()
                    and move.Name:lower():gsub("[^%a]","")=="divergentfist"
                    and (tonumber(_G.VX_BF_TRIG3) or 0)>(tonumber(_G.VX_BF_PRESS_T) or 0)
                    and tick()-(tonumber(_G.VX_BF_TRIG3) or 0)<2 then
                    _G.VX_BF_LASTMSG="consumed trigger cast blocked; waiting for the chain cast"
                    return cancelToken
                end
                -- Preserve every normal move; the manual controller changes only an armed fourth M1.
                if _G.VX_FINISHER_PACKET then return _G.VX_FINISHER_PACKET(remote,args) end
                return args
            end
            _G.VX_MOVE_DECIDE=decide
            local function observe(remote,args)
                -- Observation is optional and cannot consume a cast.
                if remote.Name=="RightActivated" and remote.Parent and remote.Parent.Parent
                    and remote.Parent.Parent.Name=="LocustService" then _G.VX_LOCUST_R_SENT=tick() end
                local move=args[1]
                -- Count only routed local casts; a sent request is not proof of a server hit.
                if remote.Name=="Activated" and typeof(move)=="Instance" and move.Parent
                    and move.Parent.Name=="Moveset" and move.Parent.Parent==myModel()
                    and move.Name:lower():gsub("[^%a]","")=="divergentfist" then
                    _G.VX_BF_CAST_SEQ=(tonumber(_G.VX_BF_CAST_SEQ) or 0)+1
                end
                if _G.VX_LOCUST_CAST and typeof(move)=="Instance" and move.Parent and move.Parent.Name=="Moveset" and move.Parent.Parent==myModel() then _G.VX_LOCUST_CAST(move) end
                if move==false and remote.Name=="Activated" and remote.Parent and remote.Parent.Name=="RE"
                    and not _G.VX_COMBAT_OWNER and tick()>=(tonumber(_G.VX_SYNTH_CLICK) or 0) then
                    local at=tick();local body=myModel()
                    if at-(tonumber(_G.VX_LAST_HUMAN_CLICK) or 0)<0.25 then
                        _G.VX_OBSERVED_BASIC_RE={body=body,remote=remote,at=at}
                    else
                        task.delay(0.05,function()
                            local click=tonumber(_G.VX_LAST_HUMAN_CLICK) or -math.huge
                            if body==myModel() and remote.Parent and click>=at-0.02 and click<=at+0.08
                                and tick()>=(tonumber(_G.VX_SYNTH_CLICK) or 0) then
                                _G.VX_OBSERVED_BASIC_RE={body=body,remote=remote,at=at}
                            end
                        end)
                    end
                end
                if typeof(move)=="Instance" and move.Parent and move.Parent.Name=="Moveset" then
                    _G.VX_MOVE_RE=_G.VX_MOVE_RE or {}; _G.VX_MOVE_RE[move.Name]=remote
                    if _G.VX_FINISHER_ABILITY and move.Parent.Parent==myModel() then
                        if _G.VX_AUTO_DOWN_CANCEL then _G.VX_AUTO_DOWN_CANCEL() end
                        _G.VX_FINISHER_ABILITY()
                    end
                    local key=_G.VX_LASTNUM_KEY
                    if key and tick()-(key.t or 0)<0.5 then
                        _G.VX_SLOT_MOVE=_G.VX_SLOT_MOVE or {}; _G.VX_SLOT_MOVE[key.n]=move.Name
                    end
                end
                -- ═══ TODO DRAW DETECTION ═══ your OWN finisher direction packets: Activated("Up") =
                -- uppercut, Activated("Down") = down slam. Manual, hub-auto or assist - every one of them
                -- leaves through this hook, and it is stamped the moment it leaves for the server. (M1s fire
                -- Activated(false), so they can never false-stamp these.)
                if typeof(move)=="string" and (move=="Up" or move=="Down")
                    and remote==cachedRemote and cachedBody==myModel() then
                    if move=="Up" then _G.VX_UPPER_T=tick() else _G.VX_DOWN_T=tick() end
                end
            end
            _G.VX_MOVE_OBSERVE=observe
            local ok,err=pcall(function()
                local installed=_G.VX_SAFE_MOVE_HOOK
                if installed and installed.version==3 then return end
                if installed then
                    local meta=getrawmetatable(game)
                    if meta.__namecall~=installed.hook then error("move hook ownership changed; rejoin before loading") end
                    if setreadonly then setreadonly(meta,false) end
                    meta.__namecall=installed.original
                    if setreadonly then setreadonly(meta,true) end
                    _G.VX_SAFE_MOVE_HOOK=nil; _G.VX_M1HOOK_ON=false
                end
                if _G.VX_M1HOOK_ON then
                    warn("[DreamHub] Old move hook is still installed. Rejoin before loading this build.")
                    return
                end
                local mt=getrawmetatable(game)
                local original=mt.__namecall
                local hook=(newcclosure or function(fn) return fn end)(function(self,...)
                    local method=getnamecallmethod and getnamecallmethod()
                    if method~="FireServer" then return original(self,...) end
                    local args=table.pack(...)
                    local routed,packet=pcall(_G.VX_MOVE_DECIDE,self,args)
                    if routed and packet==_G.VX_CANCEL_TOKEN then return end
                    if not routed or type(packet)~="table" or packet.n~=args.n then packet=args end
                    if _G.VX_MOVE_OBSERVE then pcall(_G.VX_MOVE_OBSERVE,self,packet) end
                    if setnamecallmethod then
                        setnamecallmethod(method)
                        return original(self,table.unpack(packet,1,packet.n))
                    end
                    -- Named dispatch does not depend on the mutable namecall slot.
                    return self.FireServer(self,table.unpack(packet,1,packet.n))
                end)
                if setreadonly then setreadonly(mt,false) end
                local assigned,assignmentError=pcall(function() mt.__namecall=hook end)
                if setreadonly then setreadonly(mt,true) end
                if not assigned then error(assignmentError) end
                _G.VX_SAFE_MOVE_HOOK={original=original,hook=hook,version=3}
                _G.VX_M1HOOK_ON=true
            end)
            if not ok then warn("[DreamHub] Finisher hook unavailable; normal moves remain unchanged: "..tostring(err)) end
        end


        M1ComboApi = {
                setMode = function(m)
                        if type(m) == "table" then m = m[1] end
                        mode = m or "Off"; _G.VX_UPPER_FLAG = upperOn(); _G.VX_SLAM_FLAG = slamOn(); _G.VX_HOOK_COUNT = 0; count = 0; busy = false; State.m1Count = 0; State.spaceToken = nil; spaceUp(); downUp()
                        if mode ~= "Off" then refreshDetection() end
                        -- Observable on purpose: with _G.VX_M1_DEBUG = true this proves the dropdown actually reached the
                        -- module and what string it set, which separates "mode never set" from "swings never counted".
                        if _G.VX_M1_DEBUG or _G.VX_BF_DEBUG then print("[M1COMBO] mode set to: " .. tostring(mode)) end
                end,   -- unwrap Fluriore's {"Down Slam"} table (else the mode check never matched = "doesn't work")
                -- Read-backs so the finisher assists can borrow the toggle for a beat and put it back.
                isSlam   = function() return slamFlag end,
                isUpper  = function() return upperFlag end,
                -- The two independent toggles. Each one refreshes detection on the way in, so arming either from a
                -- cold start hooks the animators immediately instead of on the next sweep.
                setSlam  = function(v) slamFlag  = v == true; pcall(keyUp); pcall(spaceUp); _G.VX_SLAM_FLAG = slamOn(); _G.VX_HOOK_COUNT = 0; State.m1Count = 0; if slamFlag then refreshDetection();pcall(hookComboAnims) end
                        if _G.VX_M1_DEBUG then print("[M1COMBO] Auto Down Slam = " .. tostring(slamFlag)) end end,
                setUpper = function(v) upperFlag = v == true; pcall(keyUp); pcall(spaceUp); _G.VX_UPPER_FLAG = upperOn(); _G.VX_HOOK_COUNT = 0; State.m1Count = 0; if upperFlag then refreshDetection();pcall(hookComboAnims) end
                        if _G.VX_M1_DEBUG then print("[M1COMBO] Auto Uppercut = " .. tostring(upperFlag)) end end,
                setDelay = function() end,
                setCount = function() end,
                -- ═══ DIAGNOSTIC: RUN THE ACTION WITH NO DETECTION IN THE WAY ═══ Uppercut / Down Slam have two halves,
                -- the TRIGGER (did we notice your swing) and the ACTION (hold the direction + fire the remote). When it
                -- "doesn't work" we cannot tell which half failed. These run the ACTION alone, on demand, so one press
                -- of the button separates them: works here but not in a fight = the trigger; does nothing here either =
                -- the action, and the printout says exactly which service it resolved.
                testUp = function()
                        print("[M1COMBO TEST] Uppercut: svc=" .. tostring(vxMyCharSvc()) .. "  v5remote=" .. tostring(State.remote and State.remote:GetFullName() or "nil"))
                        spaceDown(); fireDir("Up"); task.delay(0.40, function() spaceUp() end)
                end,
                -- ═══ THE REAL SLAM, REUSABLE ═══ Auto Down Slam works; anything else that wants a slam should use
                -- THIS rather than re-deriving the service and firing "Down" on its own, which is what the Twofold
                -- sequence was doing. Hops you first (the slam is the airborne variant) and fires from the air.
                slamNow = function()
                    local character=myModel()
                    task.spawn(function() _G.VX_NATIVE_FINISHER("Down",function() return myModel()==character end) end)
                end,
                testDown = function()
                        print("[M1COMBO TEST] Down Slam: svc=" .. tostring(vxMyCharSvc()) .. "  v5remote=" .. tostring(State.remote and State.remote:GetFullName() or "nil"))
                        downDown(); fireDir("Down"); task.delay(0.40, function() downUp() end)
                end,
                -- Reports whether the swing detector is alive and when it last saw a real click/swing.
                testStatus = function()
                        print("[M1COMBO TEST] mode=" .. tostring(mode)
                                .. "  animHookLive=" .. tostring(comboAnimLive)
                                .. "  swingsCounted=" .. tostring(State.m1Count)
                                .. "  lastRealClick=" .. string.format("%.2fs ago", tick() - (tonumber(_G.VX_LAST_CLICK) or 0))
                                .. "  lastSwing=" .. string.format("%.2fs ago", tick() - (State.lastM1 or 0)))
                end,
                setChar = function(c) Config.Manual = (c and c ~= "" and c ~= "Auto") and c or nil; State.char = nil; State.remote = nil; refreshDetection() end,
        }
end

-- MODULE: DASH  (no-cooldown directional dash via MovementService; forward = Itadori Chase)
do
        local Players = game:GetService("Players")
        local UIS = game:GetService("UserInputService")
        local LP = Players.LocalPlayer
        local noCd = false
        local DASH_ANIM = { Right = "rbxassetid://75203303352791", Left = "rbxassetid://117223862448096", Front = "rbxassetid://110978068388232", Back = "rbxassetid://110978068388232" }  -- user-captured dash anim ids
        local function myChar() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
        local function playDash(dir)  -- play the real dash animation so the no-CD dash LOOKS like a dash
                local m = myChar(); local h = m and m:FindFirstChildOfClass("Humanoid"); local a = h and h:FindFirstChildOfClass("Animator"); if not a then return end
                local anim = Instance.new("Animation"); anim.AnimationId = DASH_ANIM[dir] or DASH_ANIM.Front
                local ok, t = pcall(function() return a:LoadAnimation(anim) end)
                if ok and t then pcall(function() t.Priority = Enum.AnimationPriority.Action2; t:Play(0.05) end); task.delay(0.55, function() pcall(function() t:Stop() end) end) end
        end
        local function moveDir()
                if UIS:IsKeyDown(Enum.KeyCode.S) then return "Back" end
                if UIS:IsKeyDown(Enum.KeyCode.A) then return "Left" end
                if UIS:IsKeyDown(Enum.KeyCode.D) then return "Right" end
                return "Front"
        end
        -- ═══ DASH EFFECT - MAKE IT LOOK REAL ═══ "add the dash effect to make it more real so people believe
        -- it actually works instead of me just playing the animation and just dashing around and spam dash."
        -- The real dash carries the game's own speed-lines; the no-CD dash was animation + movement with
        -- nothing else, which reads as a slide. This bolts the missing look on: a short white air TRAIL off
        -- the root and a dust burst at the feet on every dash, cleaned up automatically.
        local lastFX = 0
        local function dashFX()
                if tick() - lastFX < 0.08 then return end
                lastFX = tick()
                local m = myChar(); local root = m and m:FindFirstChild("HumanoidRootPart"); if not root then return end
                pcall(function()
                        local t0 = root:FindFirstChild("VX_DashTrail") or Instance.new("Trail")
                        t0.Name = "VX_DashTrail"
                        t0.Attachment0 = root:FindFirstChild("VX_TrailA0") or Instance.new("Attachment")
                        t0.Attachment0.Name = "VX_TrailA0"; t0.Attachment0.Position = Vector3.new(0, 1, 0); t0.Attachment0.Parent = root
                        t0.Attachment1 = root:FindFirstChild("VX_TrailA1") or Instance.new("Attachment")
                        t0.Attachment1.Name = "VX_TrailA1"; t0.Attachment1.Position = Vector3.new(0, -1, 0); t0.Attachment1.Parent = root
                        t0.Color = ColorSequence.new(Color3.fromRGB(255, 255, 255))
                        t0.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.35), NumberSequenceKeypoint.new(1, 1) })
                        t0.Lifetime = 0.22; t0.MinLength = 0.05; t0.FaceCamera = true; t0.WidthScale = NumberSequence.new(1, 0.2)
                        t0.LightEmission = 0.6; t0.Parent = root
                        local d = root:FindFirstChild("VX_DashDust") or Instance.new("ParticleEmitter")
                        d.Name = "VX_DashDust"
                        d.Texture = "rbxassetid://241876428"; d.Rate = 0; d.Speed = NumberRange.new(3, 7)
                        d.Lifetime = NumberRange.new(0.25, 0.45); d.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1.4), NumberSequenceKeypoint.new(1, 2.6) })
                        d.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.45), NumberSequenceKeypoint.new(1, 1) })
                        d.Color = ColorSequence.new(Color3.fromRGB(205, 205, 210)); d.Parent = root
                        d:Emit(10)
                        task.delay(0.3, function() pcall(function() if t0 and t0.Parent then t0.Enabled = false end end) end)
                        t0.Enabled = true
                end)
        end
        UIS.InputBegan:Connect(function(input, gpe)
                if not noCd or gpe then return end
                -- ONLY YOUR OWN Q. The Black Flash dash modes tap the real dash key on their way to the target; without
                -- this guard that tap landed here as well and fired a SECOND dash - a 105 stud/s shove in whatever
                -- direction moveDir() guessed (Front, with no key held) plus a forward dash clip - on top of the arc
                -- already moving you. The two fought frame by frame, which is the stutter and the wrong-looking clip.
                do local injK = _G.VX_INJ_KEYS; if injK and injK[input.KeyCode] and tick() < injK[input.KeyCode] then return end end
                if input.KeyCode == Enum.KeyCode.Q then
                        local d = moveDir()
                        fireKnit("MovementService", "Dash", d, true); vxClientDash(d, 105, 0.15); playDash(d); dashFX()  -- remote + velocity + the real dash ANIMATION + the effect
                end
        end)
        DashApi = {
                setNoCd = function(v) noCd = v == true end,
                forward = function() fireKnit("ItadoriService", "Chase", false) end,
                dash = function(dir) fireKnit("MovementService", "Dash", dir or "Front") end,
        }
end

-- MODULE: TRAIN  (spawn / auto-spawn the station train; 3 minute cooldown)
do
        local on, lastFire = false, 0
        local function trainRE()
                local map = workspace:FindFirstChild("Map"); local d = map and map:FindFirstChild("Destructible")
                local m = d and d:FindFirstChild("Model"); local sc = m and m:FindFirstChild("StationControl")
                local h = sc and sc:FindFirstChild("Handle"); return h and h:FindFirstChild("Train")
        end
        local function fire()
                local re = trainRE(); if re then pcall(function() re:FireServer() end); lastFire = tick(); return true end
                return false
        end
        task.spawn(function()
                while true do
                        if on and (tick() - lastFire >= 180) then fire() end
                        task.wait(1)
                end
        end)
        TrainApi = {
                spawn = function() if tick() - lastFire >= 180 then return fire() end return false end,
                setAuto = function(v) on = v == true end,
                cooldownLeft = function() local l = 180 - (tick() - lastFire); return (l > 0 and l <= 180) and l or 0 end,
        }
end

-- MODULE: GET DRINK WHEN LOW  (buy soda to heal once HP drops below the threshold)
do
        local Players = game:GetService("Players")
        local LP = Players.LocalPlayer
        local on, threshold, last = false, 35, 0
        task.spawn(function()
                while true do
                        if on then
                                local c = LP.Character; local h = c and c:FindFirstChildOfClass("Humanoid")
                                if h and h.MaxHealth > 0 and (h.Health / h.MaxHealth * 100) <= threshold and (tick() - last > 3) then
                                        last = tick(); fireKnit("ShopService", "PurchaseSoda")
                                end
                        end
                        task.wait(0.5)
                end
        end)
        DrinkApi = { set = function(v) on = v == true end, setThreshold = function(v) if type(v) == "number" then threshold = v end end }
end

-- MODULE: AUTO COUNTER  (blocks with F the instant a nearby enemy swings - F is JJS block)
do
        local Players = game:GetService("Players")
        local VIM = game:GetService("VirtualInputManager")
        local LP = Players.LocalPlayer
        local on, lockedOnly, last = false, false, 0
        local ACTION = { [Enum.AnimationPriority.Action] = true, [Enum.AnimationPriority.Action2] = true, [Enum.AnimationPriority.Action3] = true, [Enum.AnimationPriority.Action4] = true }
        local KW = { "punch", "hit", "swing", "strike", "slam", "kick", "combo", "m1", "slash", "rush", "stab" }
        -- per-character COUNTER keybind (vessel/Itadori/Sukuna = 4, Mahito = 4, restless gambler/Hakari = 3, blood manip/Choso = 3). No F fallback: unknown character = do nothing.
        local CKEY = { Itadori = Enum.KeyCode.Four, Sukuna = Enum.KeyCode.Four, Mahito = Enum.KeyCode.Four, Hakari = Enum.KeyCode.Three, Choso = Enum.KeyCode.Three }  -- vessel(Itadori/Sukuna)=4, Hakari=3, Mahito=4, Choso=3
        local function counterKey()
                local chs = workspace:FindFirstChild("Characters"); local m = (chs and chs:FindFirstChild(LP.Name)) or LP.Character
                local n = detectCharName(m)
                return n and CKEY[n] or nil   -- nil = no counter key for this character (F fallback removed)
        end
        local function lockedTarget() local g = _G.VX_LOCK; return (g and g.get) and g.get() or nil end
        local function myHRP() local chs = workspace:FindFirstChild("Characters"); local c = (chs and chs:FindFirstChild(LP.Name)) or LP.Character; return c and c:FindFirstChild("HumanoidRootPart") end
        local M1_ID = "75337033003776"  -- the JJS M1 anim id
        local function pressCounter()  -- TAP the per-character COUNTER key (short hold so it can re-counter fast M1s)
                -- ═══ THE LAST ZERO-INPUT PHANTOM ═══ Hakari's and Choso's counter key IS Three, which is also the Black
                -- Flash key. This press carried no injected-key marker at all, so VXBF2's BF-key handler read it as you
                -- tapping 3 and launched a whole dash chain - which injects an M1 you never threw and flashes it. Auto
                -- Counter triggers on any nearby enemy attack animation within ~16 studs, so it needed no input from
                -- you whatsoever: walk near someone, they swing at anything, and you dash and black flash. Mark it.
                local ck = counterKey(); if ck then last = tick(); _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[ck] = tick() + 0.5; pcall(function() VIM:SendKeyEvent(true, ck, false, game); task.wait(0.08); VIM:SendKeyEvent(false, ck, false, game) end) end
        end
        local function isAttackId(id)   -- EVERY known attack id: M1 + the full captured list + the block dict + the counter ids
                if not id then return false end
                if id == M1_ID then return true end
                local a = _G.VX_ADAPT_IDS; if a and a[id] then return true end
                local d = _G.VX_ANIMDICT; if d and d[id] then return true end
                local c = _G.VX_COUNTER_IDS; if c and c[id] then return true end
                return false
        end
        local function isAttacking(h)
                local anim = h:FindFirstChildOfClass("Animator"); if not anim then return false end
                local ok, tracks = pcall(function() return anim:GetPlayingAnimationTracks() end); if not ok then return false end
                local dict = _G.VX_ANIMDICT       -- the block engine's attack-animation-id map (hundreds of ids)
                local cdict = _G.VX_COUNTER_IDS   -- the user's captured counter ids
                local adict = _G.VX_ADAPT_IDS     -- the FULL user-captured attack/skill/domain id list
                for _, t in ipairs(tracks) do
                        if t.IsPlaying and t.Animation then
                                local id = tostring(t.Animation.AnimationId):match("%d+")
                                if id and dict and dict[id] then return true end   -- KNOWN JJS attack animation (most reliable)
                                if id and cdict and cdict[id] then return true end -- a captured counter id
                                if id and adict and adict[id] then return true end -- any of the full captured id list
                                if ACTION[t.Priority] then return true end          -- fallback: any Action-priority swing
                                local nm = string.lower(tostring(t.Name)); for _, kw in ipairs(KW) do if string.find(nm, kw, 1, true) then return true end end
                        end
                end
                return false
        end
        task.spawn(function()
                while true do
                        if on and tick() - last > 0.2 then   -- just a key press now, so it can react fast to each attack
                                local hrp = myHRP(); local chars = workspace:FindFirstChild("Characters")
                                local lockT = lockedOnly and lockedTarget() or nil   -- Locked Only: react to just this one target (nil target = counter nobody)
                                if hrp and chars and not (lockedOnly and not lockT) then
                                        for _, m in ipairs(chars:GetChildren()) do
                                                if m.Name ~= LP.Name and m ~= LP.Character and (not lockedOnly or m == lockT) then
                                                        local r = m:FindFirstChild("HumanoidRootPart"); local h = m:FindFirstChildOfClass("Humanoid")
                                                        if r and h and h.Health > 0 and (r.Position - hrp.Position).Magnitude <= 16 then
                                                                local toMe = hrp.Position - r.Position
                                                                if toMe.Magnitude > 0 and r.CFrame.LookVector:Dot(toMe.Unit) > 0.2 and isAttacking(h) then
                                                                        pressCounter(m)
                                                                        break
                                                                end
                                                        end
                                                end
                                        end
                                end
                                task.wait(0.05)
                        else task.wait(0.1) end
                end
        end)
        -- EVENT-DRIVEN reaction: the ANIM THREAT SYSTEM hooks every enemy Animator and calls this the INSTANT any anim starts, so we counter BEFORE the hit lands - on every M1 and every captured attack id, not a 0.05s poll.
        _G.VX_AUTOCOUNTER = function(enemyChar, id)
                if not on or tick() - last <= 0.2 then return end   -- just a key press now, react fast
                if not isAttackId(id) then return end
                local hrp = myHRP(); if not hrp then return end
                local r = enemyChar and enemyChar:FindFirstChild("HumanoidRootPart"); if not r then return end
                if (r.Position - hrp.Position).Magnitude > 18 then return end
                local toMe = hrp.Position - r.Position
                if toMe.Magnitude > 0 and r.CFrame.LookVector:Dot(toMe.Unit) < 0.1 then return end   -- enemy must roughly FACE you (skip attacks aimed at a third party / facing away, so it doesn't waste your counter)
                if lockedOnly then local lt = lockedTarget(); if not lt or enemyChar ~= lt then return end end   -- Locked Only: only the locked target
                pressCounter(enemyChar)
        end
        CounterApi = { set = function(v) on = v == true; _G.VX_AUTOCOUNTER_ON = on end, setLockedOnly = function(v) lockedOnly = v == true; if _G.VX_LOCK then _G.VX_LOCK.want("counter", lockedOnly) end end }
end

-- ============================================================
-- MODULE: LOCK TARGET SYSTEM  (shared) - click a user to lock onto them (red outline); click the same user again to release.
-- Feeds Crow lock-on + Auto Counter "Locked Only". Highlight is client-side (gethui/CoreGui), outline only, shows through walls.
-- ============================================================
do
        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local LP = Players.LocalPlayer
        local mouse = LP:GetMouse()
        -- executors re-run the whole hub: tear down the PREVIOUS run's lock (disconnect its handlers, kill its leftover outline) so nothing stacks or lingers
        if _G.VX_LOCK and _G.VX_LOCK._cleanup then pcall(_G.VX_LOCK._cleanup) end
        pcall(function()
                local host = (gethui and gethui()) or game:GetService("CoreGui")
                for _, o in ipairs(host:GetChildren()) do if o.Name == "VX_LockHighlight" then o:Destroy() end end
        end)
        local locked, hl = nil, nil
        local curColor = Color3.fromRGB(255, 40, 52)   -- live lock-outline colour (Lock Color dropdown)
        local manualOn = false                        -- true only while the user's Lock Target toggle is on
        local conns = {}  -- our RBXScriptConnections, so a later re-run can disconnect them
        local want = {}   -- feature key -> wants click-to-lock active (any true = active)
        local function clickActive() for _, v in pairs(want) do if v then return true end end return false end
        local function myModel() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
        local function clearHL() if hl then pcall(function() hl:Destroy() end); hl = nil end end
        local function makeHL(m)
                clearHL(); if not m then return end
                local h = Instance.new("Highlight")
                h.Name = "VX_LockHighlight"
                h.FillTransparency = 1                          -- outline only, no fill
                h.OutlineTransparency = 0
                h.OutlineColor = curColor
                h.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                h.Adornee = m
                pcall(function() h.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
                if not h.Parent then pcall(function() h.Parent = m end) end
                hl = h
        end
        local function release() locked = nil; clearHL() end
        local function enemyUnderMouse()  -- walk up from the clicked part to the character Model (has HRP/Humanoid), never your own body
                local t = mouse.Target; if not t then return nil end
                local node, mine = t, myModel()
                while node and node ~= workspace do
                        if node:IsA("Model") and (node:FindFirstChild("HumanoidRootPart") or node:FindFirstChildOfClass("Humanoid")) then
                                if node ~= mine and node.Name ~= LP.Name and node ~= LP.Character then return node end
                        end
                        node = node.Parent
                end
                return nil
        end
        pcall(function() conns[#conns + 1] = mouse.Button1Down:Connect(function()
                if not clickActive() then return end
                local m = enemyUnderMouse()
                -- ═══ CLICKING A TARGET MUST RETARGET ═══ This used to bail whenever anything was already locked, so
                -- once you had a target you could never pick a different one - clicking the enemy you actually wanted
                -- silently did nothing ("the lock is not working, when I click the target it needs to go to the
                -- target"). Now: clicking a DIFFERENT enemy moves the lock to them. Clicking anything that is not an
                -- enemy (ground, sky, your own body) still leaves the current lock alone, so ordinary combat clicking
                -- can never drop it - that stickiness was the part worth keeping.
                if not m then return end
                if locked == m and locked.Parent then return end     -- already on this one; nothing to do
                locked = m; makeHL(m)
                if _G.VX_LOCK_NOTIFY then pcall(function() _G.VX_LOCK_NOTIFY(m.Name) end) end
        end) end)
        conns[#conns + 1] = RunService.Heartbeat:Connect(function()
                if locked then
                        local _lh = locked:FindFirstChildOfClass("Humanoid")
                        if not locked.Parent or (_lh and _lh.Health <= 0) then release() end   -- despawned OR dead (a lingering corpse used to lock you out)
                end
                if locked and hl and hl.Adornee ~= locked then pcall(function() hl.Adornee = locked end) end
        end)
        _G.VX_LOCK = {
                get = function() return (locked and locked.Parent) and locked or nil end,   -- the currently locked Model, or nil
                set = function(m) if m and m.Parent then locked = m; makeHL(m) else locked = nil; clearHL() end end,     -- programmatic lock + red outline (set(nil) clears it) - used by Auto Rika Sword
                want = function(key, v) want[key] = v == true; if not clickActive() then release() end end,  -- register a feature that needs click-to-lock; auto-clears the lock when nothing needs it
                setColor = function(c) if typeof(c) == "Color3" then curColor = c; if hl then pcall(function() hl.OutlineColor = c end) end end end,   -- Lock Color dropdown
                manual = function(v) manualOn = (v == true); want["manual"] = manualOn; if not manualOn then release() end end,   -- turning the toggle off ALWAYS clears, even if another feature still wants click-lock   -- the user's own Lock Target toggle
                manualActive = function() return manualOn == true end,   -- ONLY a user click-lock retargets combat (a programmatic Rika lock must not)
                _cleanup = function() for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end; clearHL() end,  -- called by a later re-run to remove this run's handlers + outline
        }
end

-- ============================================================
-- MODULE: AUTO ULT CROW -- selected target, obstacle routing, one aimed hit.
do
-- Crow routing: steer around nearby collidable geometry before attempting a hit.
local function crowRoute(origin,goal,params)
    local delta=goal-origin
    if delta.Magnitude<0.1 then return goal,true end
    local function clear(a,b)
        local d=b-a
        if d.Magnitude<0.1 then return true end
        local side=d.Unit:Cross(Vector3.new(0,1,0))
        if side.Magnitude<0.1 then side=Vector3.new(1,0,0) else side=side.Unit end
        for _,offset in ipairs({Vector3.zero,side*1.4,-side*1.4,Vector3.new(0,1.4,0)}) do
            if workspace:Raycast(a+offset,d,params) then return false end
        end
        return true
    end
    if clear(origin,goal) then return goal,true end
    local ahead=origin+delta.Unit*math.min(delta.Magnitude,10)
    if clear(origin,ahead) then return ahead,false end
    local side=delta.Unit:Cross(Vector3.new(0,1,0))
    if side.Magnitude<0.1 then side=Vector3.new(1,0,0) else side=side.Unit end
    local best,score=nil,math.huge
    for _,offset in ipairs({Vector3.new(0,10,0),side*10,-side*10,
        Vector3.new(0,8,0)+side*8,Vector3.new(0,8,0)-side*8,-delta.Unit*6+Vector3.new(0,6,0)}) do
        local point=origin+offset
        if clear(origin,point) then
            local cost=(goal-point).Magnitude+(clear(point,goal) and 0 or 12)
            if cost<score then best,score=point,cost end
        end
    end
    return best or origin,false
end

    local VIM=game:GetService("VirtualInputManager")
    local UIS=game:GetService("UserInputService")
    local LP=game:GetService("Players").LocalPlayer
    local on,lockOn=false,false
    local generation=0
    local lastSend,aimUntil=0,0
    local savedCamera,savedRotation,hitRemote
    local function restore()
        if savedCamera and savedRotation then savedCamera.CFrame=CFrame.new(savedCamera.CFrame.Position)*savedRotation end
        savedCamera,savedRotation=nil,nil
    end
    local function selected()
        local lock=_G.VX_LOCK
        local t=lock and lock.get and lock.get()
        local h=t and t.Parent and t:FindFirstChildOfClass("Humanoid")
        return h and h.Health>0 and t or nil
    end
    local function aim(point)
        local camera=workspace.CurrentCamera
        if camera then
            if not savedCamera then savedCamera,savedRotation=camera,camera.CFrame.Rotation end
            camera.CFrame=CFrame.lookAt(camera.CFrame.Position,point)
        end
    end
    local function crowBody(body)
        local camera=workspace.CurrentCamera
        local candidates={}
        local function consider(c)
            if c==body or not (c:IsA("Model") or c:IsA("BasePart")) then return end
            local owner=c:GetAttribute("Owner") or c:GetAttribute("UserId")
            if owner and tostring(owner)~=LP.Name and tostring(owner)~=tostring(LP.UserId) then return end
            candidates[#candidates+1]=c
        end
        local folder=workspace:FindFirstChild("Crows")
        if folder then for _,c in ipairs(folder:GetChildren()) do consider(c) end end
        local effects=workspace:FindFirstChild("Effects")
        local crow=effects and effects:FindFirstChild("Crow")
        if crow then consider(crow) end
        for _,c in ipairs(workspace:GetChildren()) do
            if c.Name:lower():find("crow",1,true) and c~=folder then consider(c) end
            if c~=folder and (c:IsA("Folder") or c:IsA("Model")) then
                for _,child in ipairs(c:GetChildren()) do
                    if child.Name:lower():find("crow",1,true) then consider(child) end
                end
            end
        end
        local seen,unique={},{}
        for _,c in ipairs(candidates) do
            if not seen[c] then
                seen[c]=true; unique[#unique+1]=c
                local subject=camera and camera.CameraSubject
                if subject and (subject==c or subject:IsDescendantOf(c)) then return c end
                if tostring(c:GetAttribute("Owner"))==LP.Name or c:GetAttribute("UserId")==LP.UserId then return c end
            end
        end
        if #unique==1 then return unique[1] end
        -- Multiple unowned crows: do not click based on another player's projectile.
    end
    local function sync()
        if _G.VX_LOCK and _G.VX_LOCK.want then _G.VX_LOCK.want("crow",on or lockOn) end
        if not on and not lockOn then _G.VX_CROW_FLYING=0; restore(); hitRemote=nil end
    end
    game:GetService("RunService").Heartbeat:Connect(function()
        if not on and not lockOn then return end
        local body=vxMyChar()
        local info=body and body:FindFirstChild("Info")
        local remote=info and info:FindFirstChild("ControlRemote")
        if not remote or not (remote:IsA("RemoteEvent") or remote:IsA("UnreliableRemoteEvent")) then
            _G.VX_CROW_FLYING=0; hitRemote=nil
            local t=selected(); local root=t and t:FindFirstChild("HumanoidRootPart")
            if root and tick()<aimUntil then aim(root.Position) else restore() end
            return
        end
        local t=selected(); local root=t and t:FindFirstChild("HumanoidRootPart")
        if not root then _G.VX_CROW_FLYING=0; restore(); return end
        _G.VX_CROW_FLYING=tick()+0.2
        if tick()-lastSend<0.05 then return end
        lastSend=tick()
        local goal=root.Position+Vector3.new(0,1.5,0)
        -- ═══ ARRIVE ON THE TARGET, DON'T FLY PAST IT ═══ the crow's server-side flight chases the LAST sent
        -- point, so near the target it blew straight through and smacked the building behind them ("when it
        -- gets to the target, it just goes farther away... hitting the building that's close to the target").
        -- Once the crow is close, the point we send is pulled back toward the crow, so the flight converges
        -- ON the target instead of overshooting it.
        local route,clear,crow,origin=goal,false,nil,nil
        local ok,routeError=pcall(function()
            crow=crowBody(body)
            if crow then
                origin=crow:GetPivot().Position
                local d0=(origin-goal).Magnitude
                local sendGoal=goal
                if d0<14 and d0>0.5 then sendGoal=goal+(origin-goal).Unit*math.min(3.5,d0*0.35) end
                local params=RaycastParams.new()
                params.FilterType=Enum.RaycastFilterType.Exclude
                params.FilterDescendantsInstances={body,t,crow}
                params.RespectCanCollide=true
                route,clear=crowRoute(origin,sendGoal,params)
                if clear then route=sendGoal end
            end
        end)
        if not ok then _G.VX_CROW_STATUS="route unavailable: "..tostring(routeError); return end
        pcall(function() remote:FireServer(route) end)
        aim(clear and goal or route)
        -- ═══ THE CLICK RETRIES WHILE THE CROW IS ON THEM ═══ the old one-shot stamped hitRemote and never
        -- clicked again - one miss (a drift, a frame behind) and the crow just kept flying into the scenery
        -- for the rest of the ult. Now: click, wait a beat, and while the target lives and the crow is still
        -- within 12 studs, click again (3 tries).
        if not origin or not clear or (origin-goal).Magnitude>9 or hitRemote==remote or UIS:GetFocusedTextBox() then return end
        local camera=workspace.CurrentCamera
        if not camera then return end
        hitRemote=remote
        local gen=generation
        _G.VX_SYNTH_CLICK=tick()+0.3
        task.spawn(function()
            local okClick,err=pcall(function()
                for _=1,3 do
                    if gen~=generation or not (on or lockOn) or selected()~=t or vxMyChar()~=body
                        or info:FindFirstChild("ControlRemote")~=remote then return end
                    local root2=t:FindFirstChild("HumanoidRootPart"); if not root2 then return end
                    local cr=crowBody(body)
                    local cd=cr and (cr:GetPivot().Position-goal).Magnitude or 99
                    if cd>12 then return end   -- the crow drifted off the target: stop clicking
                    aim(goal)
                    local screen,visible=camera:WorldToScreenPoint(root2.Position)
                    if visible and screen.Z>0 then
                        VIM:SendMouseMoveEvent(screen.X,screen.Y,game)
                        VIM:SendMouseButtonEvent(screen.X,screen.Y,0,true,game,0)
                        task.wait(0.03)
                        VIM:SendMouseButtonEvent(screen.X,screen.Y,0,false,game,0)
                    end
                    task.wait(0.35)
                end
            end)
            if not okClick then hitRemote=nil; warn("[DreamHub Crow] "..tostring(err)) end
        end)
    end)
    CrowUltApi={set=function(v) on=v==true; generation+=1; sync() end}
    CrowHitApi={set=function(v) lockOn=v==true; generation+=1; sync() end}
    pcall(function()
        game:GetService("ContextActionService"):BindActionAtPriority("VX_CrowAim",function(_,state)
            if state==Enum.UserInputState.Begin and (on or lockOn) and not UIS:GetFocusedTextBox() then
                aimUntil=tick()+0.6
                local t=selected(); local root=t and t:FindFirstChild("HumanoidRootPart")
                if root then aim(root.Position) end
            end
            return Enum.ContextActionResult.Pass
        end,false,4300,Enum.KeyCode.G)
    end)
end

-- ============================================================

-- MODULE: LOCK ON  (Camera / Character lock + JJS-style targeting reticle on the locked target)
do
        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local LP = Players.LocalPlayer
        local mode, smooth, showReticle, locked = "Off", 0.4, true, nil  -- mode: Off / Camera / Character / Both
        local function myHRP() local c = LP.Character; return c and c:FindFirstChild("HumanoidRootPart") end

        local screen = Instance.new("ScreenGui")
        screen.Name = "VX_LockOn"; screen.ResetOnSpawn = false; screen.IgnoreGuiInset = true; screen.DisplayOrder = 9001
        pcall(function() screen.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
        if not screen.Parent then pcall(function() screen.Parent = LP:WaitForChild("PlayerGui") end) end
        -- LOCK-ON ICON: clean WHITE corner brackets + a small center dot (no more purple circle). Classic "target
        -- locked" look, matches the black/white theme.
        local ret = Instance.new("Frame"); ret.BackgroundTransparency = 1; ret.AnchorPoint = Vector2.new(0.5, 0.5); ret.Visible = false; ret.Parent = screen
        local WHT = Color3.fromRGB(255, 255, 255)
        -- four L-shaped corner brackets built from thin frames
        local function bracket(hx, hy)   -- hx/hy = -1 (left/top) or 1 (right/bottom)
                local armLen = 0.32
                local ax = (hx < 0) and 0 or (1 - armLen)
                local ay = (hy < 0) and 0 or (1 - armLen)
                -- horizontal arm
                local h = Instance.new("Frame"); h.BorderSizePixel = 0; h.BackgroundColor3 = WHT; h.Size = UDim2.new(armLen, 0, 0, 2)
                h.Position = UDim2.new(ax, 0, (hy < 0) and 0 or 1, (hy < 0) and 0 or -2); h.Parent = ret
                -- vertical arm
                local v = Instance.new("Frame"); v.BorderSizePixel = 0; v.BackgroundColor3 = WHT; v.Size = UDim2.new(0, 2, armLen, 0)
                v.Position = UDim2.new((hx < 0) and 0 or 1, (hx < 0) and 0 or -2, ay, 0); v.Parent = ret
        end
        bracket(-1, -1); bracket(1, -1); bracket(-1, 1); bracket(1, 1)
        local dot = Instance.new("Frame"); dot.Size = UDim2.fromOffset(4, 4); dot.AnchorPoint = Vector2.new(0.5, 0.5); dot.Position = UDim2.fromScale(0.5, 0.5); dot.BackgroundColor3 = WHT; dot.BorderSizePixel = 0; dot.Parent = ret
        Instance.new("UICorner", dot).CornerRadius = UDim.new(1, 0)
        local function layoutReticle(size)
                ret.Size = UDim2.fromOffset(size, size)
        end
        local function acquire()
                local hrp = myHRP(); local cam = workspace.CurrentCamera; if not (hrp and cam) then return nil end
                local vp = cam.ViewportSize; local center = Vector2.new(vp.X / 2, vp.Y / 2)
                local best, bestScore
                local function chk(m)
                        if not m or m == LP.Character then return end
                        local h = m:FindFirstChildOfClass("Humanoid"); local r = m:FindFirstChild("HumanoidRootPart")
                        if not (h and r and h.Health > 0) then return end
                        local d = (r.Position - hrp.Position).Magnitude; if d > 300 then return end
                        local sp = cam:WorldToViewportPoint(r.Position); if sp.Z <= 0 then return end  -- in-front check only; off-screen targets are still lockable
                        local sc = (Vector2.new(sp.X, sp.Y) - center).Magnitude + d * 0.5
                        if not bestScore or sc < bestScore then best, bestScore = m, sc end
                end
                for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP then chk(plr.Character) end end
                local chars = workspace:FindFirstChild("Characters"); if chars then for _, m in ipairs(chars:GetChildren()) do chk(m) end end
                return best
        end
        local function valid(m)
                if not m or not m.Parent then return false end
                local h = m:FindFirstChildOfClass("Humanoid"); local r = m:FindFirstChild("HumanoidRootPart")
                return h ~= nil and r ~= nil and h.Health > 0
        end
        local function setAR(v) local h = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid"); if h and h.AutoRotate ~= v then pcall(function() h.AutoRotate = v end) end end
        RunService.RenderStepped:Connect(function()
                if _G.VX_COMBAT_OWNER then ret.Visible=false; return end
                if mode == "Off" then setAR(true); ret.Visible = false; locked = nil; return end
                if not valid(locked) then locked = acquire() end
                if not valid(locked) then setAR(true); ret.Visible = false; return end
                local cam = workspace.CurrentCamera; local hrp = myHRP(); local tr = locked:FindFirstChild("HumanoidRootPart")
                if not (cam and hrp and tr) then setAR(true); ret.Visible = false; return end
                if mode == "Camera" or mode == "Both" then
                        cam.CFrame = cam.CFrame:Lerp(CFrame.new(cam.CFrame.Position, tr.Position), smooth)
                end
                if mode == "Character" or mode == "Both" then
                        setAR(false)  -- stop the Humanoid's auto-rotate from fighting our facing while we walk
                        pcall(function() hrp.CFrame = hrp.CFrame:Lerp(CFrame.lookAt(hrp.Position, Vector3.new(tr.Position.X, hrp.Position.Y, tr.Position.Z)), 0.5) end)
                else
                        setAR(true)
                end
                if showReticle then
                        local head = locked:FindFirstChild("Head") or tr
                        local sp, vis = cam:WorldToViewportPoint(head.Position)
                        if vis and sp.Z > 0 then
                                local dist = (tr.Position - hrp.Position).Magnitude
                                layoutReticle(math.clamp(2600 / math.max(dist, 6), 26, 120))
                                ret.Position = UDim2.fromOffset(sp.X, sp.Y); ret.Visible = true
                        else ret.Visible = false end
                else ret.Visible = false end
        end)
        LockOnApi = {
                setMode = function(m) mode = m or "Off"; if mode == "Off" then locked = nil end end,
                setReticle = function(v) showReticle = v == true end,
                setSmooth = function(s) if type(s) == "number" then smooth = s end end,
                set = function(v) mode = (v == true) and "Camera" or "Off" end,
        }
end

-- MODULE: AUTO ULT -- bounded input and shared combat exclusion.
do
    local VIM = game:GetService("VirtualInputManager")
    local UIS = game:GetService("UserInputService")
    local on = false
    task.spawn(function()
        while true do
            local c = vxMyChar(); local h = c and c:FindFirstChildOfClass("Humanoid")
            if on and h and h.Health > 0 and not UIS:GetFocusedTextBox()
                and tick() >= (tonumber(_G.VX_BF_CHAINDRIVE) or 0)
                and tick() >= (tonumber(_G.VX_COMBAT_SEQUENCE) or 0)
                and tick() >= (tonumber(_G.VX_CROW_FLYING) or 0) then
                _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.G] = tick()+0.3
                pcall(function() VIM:SendKeyEvent(true,Enum.KeyCode.G,false,game); task.wait(0.05) end)
                pcall(function() VIM:SendKeyEvent(false,Enum.KeyCode.G,false,game) end)
            end
            task.wait(on and 1.2 or 0.2)
        end
    end)
    AutoUltApi = {set = function(v) on = v == true end}
end

-- MODULE: ANTI-AFK
do
        local Players = game:GetService("Players")
        local VirtualUser = game:GetService("VirtualUser")
        local LP = Players.LocalPlayer
        local on = true
        LP.Idled:Connect(function() if on then pcall(function() VirtualUser:CaptureController(); VirtualUser:ClickButton2(Vector2.new()) end) end end)
        AntiAfkApi = { set = function(v) on = v == true end }
end

-- MODULE: NOCLIP  (removed per request)

-- MODULE: AUTO FARM PLAYER  (approach a chosen target - or nearest - and M1 it)
do
        local Players = game:GetService("Players")
        local LP = Players.LocalPlayer
        local on, targetName = false, nil
        local function myChar() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
        local function myHRP() local c = myChar(); return c and c:FindFirstChild("HumanoidRootPart") end
        local function act(arg)  -- real M1 on ONLY your detected character (firing all 21 services can get rejected/kicked)
                local svc = vxMyCharSvc()
                if svc then fireKnit(svc, "Activated", arg) else for _, c in ipairs(CHAR_NAMES) do fireKnit(c .. "Service", "Activated", arg) end end
        end
        local function acPass() fireKnit("AntiCheatService", "Teleport", workspace:GetServerTimeNow()) end
        local function nearest()
                local hrp = myHRP(); if not hrp then return nil end
                local best, bd
                local function chk(m) if m and m.Name ~= LP.Name and m ~= LP.Character then local h = m:FindFirstChildOfClass("Humanoid"); local r = m:FindFirstChild("HumanoidRootPart"); if h and h.Health > 0 and r then local d = (r.Position - hrp.Position).Magnitude; if not bd or d < bd then best, bd = m, d end end end end
                for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP then chk(plr.Character) end end
                local chars = workspace:FindFirstChild("Characters"); if chars then for _, m in ipairs(chars:GetChildren()) do chk(m) end end
                return best
        end
        local function pickTarget()
                -- ═══ CLICK THE PLAYER = ATTACK THE PLAYER ═══ "All you gotta do, just click the player and then
                -- it will just go and attack for you without you doing nothing." A Lock Target (click an enemy)
                -- now drives this directly; the named dropdown target still wins when one is set.
                if not targetName then
                        local g = _G.VX_LOCK; local lt = (g and g.get) and g.get() or nil
                        local lh = lt and lt.Parent and lt:FindFirstChildOfClass("Humanoid")
                        if lt and lt.Parent and lh and lh.Health > 0 and lt ~= myChar() then return lt end
                end
                if targetName then
                        local p = Players:FindFirstChild(targetName)
                        if p and p.Character then local h = p.Character:FindFirstChildOfClass("Humanoid"); if h and h.Health > 0 then return p.Character end end
                        local chars = workspace:FindFirstChild("Characters"); if chars then local m = chars:FindFirstChild(targetName); if m then local h = m:FindFirstChildOfClass("Humanoid"); if h and h.Health > 0 then return m end end end
                        return nil
                end
                return nearest()
        end
        -- ═══ THE APPROACH IS A GLIDE, NOT A BLINK ═══ the old loop wrote your CFrame to a fixed 5-stud spot
        -- every 0.2s; between writes the M1 lunge carried you THROUGH the target, then the next write yanked
        -- you back - "he tries to go to a target, but then it moves farther away into another place". Now the
        -- approach is one continuous per-frame glide: the goal is recomputed EVERY FRAME from the target's
        -- LIVE position, the speed shrinks as the gap closes (fast far, gentle near, zero inside the stop
        -- ring), and the lunge carry is damped the moment you arrive. No teleport anywhere in the loop.
        local function glideTo(tgt, stopDist)
            local deadline=tick()+1.4
            while tick()<deadline do
                local r=myHRP(); local tr=tgt.Parent and tgt:FindFirstChild("HumanoidRootPart")
                if not (r and tr) then return false end
                local flat=Vector3.new(tr.Position.X-r.Position.X,0,tr.Position.Z-r.Position.Z)
                local dist=flat.Magnitude
                if dist<=stopDist then break end
                local dir=(dist>0.1) and flat.Unit or Vector3.zero
                local spd=math.clamp((dist-stopDist)*6,14,62)
                acPass()
                pcall(function()
                    r.CFrame=CFrame.lookAt(r.Position,Vector3.new(tr.Position.X,r.Position.Y,tr.Position.Z))
                    r.AssemblyLinearVelocity=Vector3.new(dir.X*spd,r.AssemblyLinearVelocity.Y,dir.Z*spd)
                end)
                task.wait()
            end
            local r=myHRP()
            if r then pcall(function() local v=r.AssemblyLinearVelocity; r.AssemblyLinearVelocity=Vector3.new(v.X*0.08,v.Y,v.Z*0.08) end) end
            return true
        end
        task.spawn(function()
                while true do
                        if on then
                                local hrp = myHRP(); local tgt = pickTarget()
                                if hrp and tgt and tgt.Parent then
                                        local tr = tgt:FindFirstChild("HumanoidRootPart")
                                        if tr then
                                                local flat = Vector3.new(tr.Position.X-hrp.Position.X,0,tr.Position.Z-hrp.Position.Z)
                                                if flat.Magnitude > 5.5 then
                                                        glideTo(tgt, 4.5)
                                                end
                                                local r2 = myHRP(); local tr2 = tgt.Parent and tgt:FindFirstChild("HumanoidRootPart")
                                                if r2 and tr2 then pcall(function() r2.CFrame = CFrame.lookAt(r2.Position, Vector3.new(tr2.Position.X, r2.Position.Y, tr2.Position.Z)) end) end
                                                act(false)  -- real M1 on the faced target
                                        end
                                end
                                task.wait(0.2)
                        else task.wait(0.2) end
                end
        end)
        FarmApi = { set = function(v) on = v == true end, setTarget = function(name) targetName = (name and name ~= "Nearest" and name ~= "(none)") and name or nil end }
end

-- ============================================================
-- MODULE: SPEED HACK  (drive WASD by velocity at a set speed)
-- ============================================================
do
        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local UIS = game:GetService("UserInputService")
        local LP = Players.LocalPlayer
        local on, speed = false, 70
        local function hrp() local c = LP.Character; return c and c:FindFirstChild("HumanoidRootPart") end
        RunService.Heartbeat:Connect(function()
                if not on then return end
                local r = hrp(); local cam = workspace.CurrentCamera
                if not (r and cam) then return end
                local dir = Vector3.zero; local cf = cam.CFrame
                if UIS:IsKeyDown(Enum.KeyCode.W) then dir = dir + cf.LookVector end
                if UIS:IsKeyDown(Enum.KeyCode.S) then dir = dir - cf.LookVector end
                if UIS:IsKeyDown(Enum.KeyCode.A) then dir = dir - cf.RightVector end
                if UIS:IsKeyDown(Enum.KeyCode.D) then dir = dir + cf.RightVector end
                local flat = Vector3.new(dir.X, 0, dir.Z)
                if flat.Magnitude > 0 then
                        flat = flat.Unit * speed
                        pcall(function() r.AssemblyLinearVelocity = Vector3.new(flat.X, r.AssemblyLinearVelocity.Y, flat.Z) end)
                end
        end)
        SpeedApi = { set = function(v) on = v == true end, setSpeed = function(s) if type(s) == "number" then speed = s end end }
end

-- ============================================================
-- MODULE: FLY  (camera-steered: WASD + Space up / Ctrl down)
-- ============================================================
do
        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local UIS = game:GetService("UserInputService")
        local LP = Players.LocalPlayer
        local on, speed = false, 80
        local bv, bg, conn, clipConn
        local savedClip={}
        local function char() return vxMyChar() end
        local function hrp() local c = char(); return c and c:FindFirstChild("HumanoidRootPart") end
        local function stop()
                if conn then conn:Disconnect(); conn = nil end
                if clipConn then clipConn:Disconnect();clipConn=nil end
                for part,original in pairs(savedClip) do if part.Parent then pcall(function() part.CanCollide=original end) end end
                table.clear(savedClip)
                if bv then pcall(function() bv:Destroy() end); bv = nil end
                if bg then pcall(function() bg:Destroy() end); bg = nil end
                local c = char(); local h = c and c:FindFirstChildOfClass("Humanoid")
                if h then pcall(function() h.PlatformStand = false;if not on then h:ChangeState(Enum.HumanoidStateType.Freefall) end end) end
                local r=hrp();if r and not on then pcall(function() local v=r.AssemblyLinearVelocity;r.AssemblyLinearVelocity=Vector3.new(v.X,math.min(v.Y,0),v.Z) end) end
        end
        local function start()
                local r = hrp(); local c = char(); local h = c and c:FindFirstChildOfClass("Humanoid")
                if not (r and h) then return end
                stop()
                bv = Instance.new("BodyVelocity"); bv.MaxForce = Vector3.new(9e9, 9e9, 9e9); bv.P = 90000; bv.Velocity = Vector3.zero; bv.Parent = r
                bg = Instance.new("BodyGyro"); bg.MaxTorque = Vector3.new(9e9, 9e9, 9e9); bg.P = 30000; bg.CFrame = r.CFrame; bg.Parent = r
                pcall(function() h.PlatformStand = true end)
                clipConn=RunService.Stepped:Connect(function()
                    local current=char();if not on or not current then return end
                    for _,part in ipairs(current:GetDescendants()) do if part:IsA("BasePart") then
                        if savedClip[part]==nil then savedClip[part]=part.CanCollide end
                        part.CanCollide=false
                    end end
                end)
                conn = RunService.RenderStepped:Connect(function()
                        if not on then return end
                        local rr = hrp(); local cam = workspace.CurrentCamera
                        if not (rr and cam and bv and bg) then return end
                        local dir = Vector3.zero; local cf = cam.CFrame
                        if UIS:IsKeyDown(Enum.KeyCode.W) then dir = dir + cf.LookVector end
                        if UIS:IsKeyDown(Enum.KeyCode.S) then dir = dir - cf.LookVector end
                        if UIS:IsKeyDown(Enum.KeyCode.A) then dir = dir - cf.RightVector end
                        if UIS:IsKeyDown(Enum.KeyCode.D) then dir = dir + cf.RightVector end
                        if UIS:IsKeyDown(Enum.KeyCode.Space) then dir = dir + Vector3.new(0, 1, 0) end
                        if UIS:IsKeyDown(Enum.KeyCode.LeftControl) then dir = dir - Vector3.new(0, 1, 0) end
                        bv.Velocity = (dir.Magnitude > 0 and dir.Unit * speed) or Vector3.zero
                        bg.CFrame = cf
                end)
        end
        FlyApi = { set = function(v) on = v == true; if on then start() else stop() end end, setSpeed = function(s) if type(s) == "number" then speed = s end end }
        LP.CharacterAdded:Connect(function() if on then task.wait(0.6); start() end end)
end

-- ============================================================
-- MODULE: PLAYER ESP  (chams + name + character + health + distance + move + cooldowns + tracers)
-- ============================================================
do
        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local LP = Players.LocalPlayer
        local ACCENT = Color3.fromRGB(255, 46, 58)
        local cfg = { master = false, chams = true, name = true, character = false, health = true, distance = true, move = false, cooldowns = false, tracers = false, box = false, tracerThick = 2, accent = Color3.fromRGB(255, 46, 58) }

        local screen = Instance.new("ScreenGui")
        screen.Name = "VX_ESP"; screen.ResetOnSpawn = false; screen.IgnoreGuiInset = true; screen.DisplayOrder = 9000
        pcall(function() screen.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
        if not screen.Parent then pcall(function() screen.Parent = LP:WaitForChild("PlayerGui") end) end

        local pool = {}
        local function build(model, adornee)
                local hl = Instance.new("Highlight")
                hl.FillColor = ACCENT; hl.OutlineColor = Color3.fromRGB(255, 255, 255); hl.FillTransparency = 0.65; hl.OutlineTransparency = 0
                hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop; hl.Adornee = model; hl.Enabled = false; hl.Parent = model
                local bb = Instance.new("BillboardGui")
                bb.Name = "VXTag"; bb.Size = UDim2.fromOffset(244, 86); bb.StudsOffset = Vector3.new(0, 3.6, 0); bb.AlwaysOnTop = true; bb.Adornee = adornee; bb.Parent = adornee
                local nameL = Instance.new("TextLabel")
                nameL.BackgroundTransparency = 1; nameL.Size = UDim2.new(1, 0, 0, 16); nameL.Font = Enum.Font.GothamBlack; nameL.TextSize = 14
                nameL.TextColor3 = Color3.fromRGB(255, 255, 255); nameL.TextStrokeTransparency = 0.2; nameL.TextStrokeColor3 = Color3.new(0, 0, 0); nameL.Parent = bb
                local hpBg = Instance.new("Frame")
                hpBg.BackgroundColor3 = Color3.fromRGB(8, 8, 10); hpBg.BackgroundTransparency = 0.15; hpBg.BorderSizePixel = 0
                hpBg.Size = UDim2.new(0.72, 0, 0, 5); hpBg.Position = UDim2.new(0.14, 0, 0, 18); hpBg.Parent = bb
                local hpC = Instance.new("UICorner"); hpC.CornerRadius = UDim.new(1, 0); hpC.Parent = hpBg
                local hpS = Instance.new("UIStroke"); hpS.Color = Color3.fromRGB(0, 0, 0); hpS.Thickness = 1; hpS.Transparency = 0.4; hpS.Parent = hpBg
                local hpFill = Instance.new("Frame"); hpFill.BackgroundColor3 = Color3.fromRGB(70, 220, 90); hpFill.BorderSizePixel = 0; hpFill.Size = UDim2.fromScale(1, 1); hpFill.Parent = hpBg
                local hpFC = Instance.new("UICorner"); hpFC.CornerRadius = UDim.new(1, 0); hpFC.Parent = hpFill
                local infoL = Instance.new("TextLabel")
                infoL.BackgroundTransparency = 1; infoL.Position = UDim2.new(0, 0, 0, 26); infoL.Size = UDim2.new(1, 0, 0, 13); infoL.Font = Enum.Font.GothamMedium; infoL.TextSize = 11.5
                infoL.TextColor3 = Color3.fromRGB(230, 230, 232); infoL.TextStrokeTransparency = 0.35; infoL.Parent = bb
                local cdRow = Instance.new("Frame")
                cdRow.BackgroundTransparency = 1; cdRow.Position = UDim2.new(0, 0, 0, 54); cdRow.Size = UDim2.new(1, 0, 0, 28); cdRow.Visible = false; cdRow.Parent = bb
                local cdLayout = Instance.new("UIListLayout"); cdLayout.FillDirection = Enum.FillDirection.Horizontal; cdLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center; cdLayout.VerticalAlignment = Enum.VerticalAlignment.Center; cdLayout.Padding = UDim.new(0, 3); cdLayout.Parent = cdRow
                local tracer = Instance.new("Frame"); tracer.BackgroundColor3 = ACCENT; tracer.BorderSizePixel = 0; tracer.AnchorPoint = Vector2.new(0.5, 0.5); tracer.Visible = false; tracer.ZIndex = 2; tracer.Parent = screen
                local box = Instance.new("Frame"); box.BackgroundTransparency = 1; box.BorderSizePixel = 0; box.Visible = false; box.ZIndex = 3; box.Parent = screen
                local boxS = Instance.new("UIStroke"); boxS.Color = ACCENT; boxS.Thickness = 1.6; boxS.Parent = box
                local boxC = Instance.new("UICorner"); boxC.CornerRadius = UDim.new(0, 3); boxC.Parent = box
                local o = { hl = hl, bb = bb, nameL = nameL, hpBg = hpBg, hpFill = hpFill, infoL = infoL, cdRow = cdRow, cdBoxes = {}, charName = nil, charT = 0, tracer = tracer, box = box, boxS = boxS }
                pool[model] = o
                return o
        end
        local function destroy(model)
                local o = pool[model]; if not o then return end
                pcall(function() o.hl:Destroy() end); pcall(function() o.bb:Destroy() end); pcall(function() o.tracer:Destroy() end); pcall(function() o.box:Destroy() end)
                pool[model] = nil
        end
        local function clearAll() for m in pairs(pool) do destroy(m) end end

        local function makeCdBox(parent)  -- one small box per move: shows short name + a live cooldown timer
                local f = Instance.new("Frame")
                f.Size = UDim2.fromOffset(34, 26); f.BackgroundColor3 = Color3.fromRGB(20, 20, 24); f.BackgroundTransparency = 0.1; f.BorderSizePixel = 0; f.Parent = parent
                local cc = Instance.new("UICorner"); cc.CornerRadius = UDim.new(0, 4); cc.Parent = f
                local ss = Instance.new("UIStroke"); ss.Thickness = 1; ss.Color = Color3.fromRGB(0, 0, 0); ss.Transparency = 0.3; ss.Parent = f
                local lbl = Instance.new("TextLabel")
                lbl.BackgroundTransparency = 1; lbl.Size = UDim2.fromScale(1, 1); lbl.Font = Enum.Font.GothamBold; lbl.TextSize = 9
                lbl.TextColor3 = Color3.fromRGB(255, 255, 255); lbl.TextStrokeTransparency = 0.45; lbl.Parent = f
                return { f = f, lbl = lbl }
        end
        local function readMove(model)
                local hum = model:FindFirstChildOfClass("Humanoid")
                local anim = hum and hum:FindFirstChildOfClass("Animator")
                if not anim then return nil end
                local best, pr
                for _, t in ipairs(anim:GetPlayingAnimationTracks()) do
                        if t.IsPlaying and t.Animation then
                                local nm = t.Animation.Name; local low = nm and nm:lower() or ""
                                if nm and nm ~= "" and low ~= "idle" and low ~= "walk" and low ~= "run" and low ~= "fall" then
                                        local p = (t.Priority and t.Priority.Value) or 0
                                        if not pr or p >= pr then best, pr = nm, p end
                                end
                        end
                end
                return best
        end
        local function readCooldowns(model)
                local src = model:FindFirstChild("Moveset") or model:FindFirstChild("Cooldowns")  -- Moveset holds a NumberValue per move = its cooldown
                if not src then return nil end
                local act = {}
                for _, v in ipairs(src:GetChildren()) do
                        if (v:IsA("NumberValue") or v:IsA("IntValue")) and v.Value and v.Value > 0.05 then
                                act[#act + 1] = v.Name .. " " .. string.format("%.1f", v.Value) .. "s"
                        end
                end
                if #act == 0 then return nil end
                return "CD: " .. table.concat(act, ", ")
        end
        local function enemyList()
                local out, seen = {}, {}
                for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP and plr.Character then out[#out + 1] = plr.Character; seen[plr.Character] = true end end
                local chars = workspace:FindFirstChild("Characters")
                if chars then for _, m in ipairs(chars:GetChildren()) do if m:IsA("Model") and m.Name ~= LP.Name and not seen[m] then out[#out + 1] = m end end end
                return out
        end

        -- ═══ LAG ═══ ESP was the second-heaviest thing in the hub: for EVERY enemy, EVERY frame, it did a
        -- GetBoundingBox plus eight WorldToViewportPoint calls for the box corners, and rebuilt cooldown labels with
        -- fresh string.format allocations. At 60fps in a busy lobby that is thousands of projection calls a second.
        -- ESP does not need to update at render rate to look smooth - 30Hz is indistinguishable and halves the cost.
        -- _G.VX_ESP_HZ lets you raise it back if you want it perfectly glued.
        local espLast = 0
        RunService.RenderStepped:Connect(function()
                if not cfg.master then return end
                local espInterval = 1 / math.clamp(tonumber(_G.VX_ESP_HZ) or 30, 10, 60)
                if tick() - espLast < espInterval then return end
                espLast = tick()
                local cam = workspace.CurrentCamera; if not cam then return end
                local myHRP = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                local vp = cam.ViewportSize
                local present = {}
                for _, model in ipairs(enemyList()) do
                        local hrp = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
                        local head = model:FindFirstChild("Head") or hrp
                        local hum = model:FindFirstChildOfClass("Humanoid")
                        if hrp and head then
                                present[model] = true
                                local o = pool[model] or build(model, head)
                                o.hl.Enabled = cfg.chams
                                if cfg.name or cfg.character then
                                        local txt = cfg.name and model.Name or ""
                                        if cfg.character then
                                                if o.charName == nil or (tick() - o.charT > 3) then
                                                        local nm = detectCharName(model)
                                                        if not nm then local ms = model:FindFirstChild("Moveset"); if ms then local mv = {}; for _, v in ipairs(ms:GetChildren()) do mv[#mv + 1] = v.Name end; if #mv > 0 then nm = table.concat(mv, "/") end end end
                                                        o.charName = nm or false; o.charT = tick()  -- name if found, else the moveset (the moves identify the character)
                                                end
                                                if o.charName then txt = txt .. (txt ~= "" and "  " or "") .. "[" .. o.charName .. "]" end
                                        end
                                        o.nameL.Visible = true; o.nameL.Text = txt
                                else o.nameL.Visible = false end
                                if cfg.health and hum and hum.MaxHealth > 0 then
                                        local frac = math.clamp(hum.Health / hum.MaxHealth, 0, 1)
                                        o.hpBg.Visible = true; o.hpFill.Size = UDim2.fromScale(frac, 1)
                                        o.hpFill.BackgroundColor3 = Color3.fromRGB(math.floor(235 * (1 - frac)) + 20, math.floor(200 * frac) + 30, 55)
                                else o.hpBg.Visible = false end
                                local parts = {}
                                if cfg.distance and myHRP then parts[#parts + 1] = string.format("%dm", math.floor((hrp.Position - myHRP.Position).Magnitude)) end
                                if cfg.move then local mv = readMove(model); if mv then parts[#parts + 1] = mv end end
                                if #parts > 0 then o.infoL.Visible = true; o.infoL.Text = table.concat(parts, "  -  ") else o.infoL.Visible = false end
                                if cfg.cooldowns then
                                        local ms = model:FindFirstChild("Moveset")
                                        if ms then
                                                o.cdRow.Visible = true
                                                local seen2 = {}
                                                for _, v in ipairs(ms:GetChildren()) do
                                                        if v:IsA("NumberValue") or v:IsA("IntValue") then
                                                                seen2[v.Name] = true
                                                                local box = o.cdBoxes[v.Name]; if not box then box = makeCdBox(o.cdRow); o.cdBoxes[v.Name] = box end
                                                                local val = v.Value or 0
                                                                local short = (#v.Name > 5) and v.Name:sub(1, 5) or v.Name
                                                                if val > 0.05 then
                                                                        box.f.BackgroundColor3 = Color3.fromRGB(70, 18, 20); box.lbl.TextColor3 = Color3.fromRGB(255, 120, 120)
                                                                        box.lbl.Text = short .. "\n" .. string.format("%.1f", val)
                                                                else
                                                                        box.f.BackgroundColor3 = Color3.fromRGB(18, 40, 22); box.lbl.TextColor3 = Color3.fromRGB(120, 235, 140)
                                                                        box.lbl.Text = short .. "\nOK"
                                                                end
                                                        end
                                                end
                                                for nm, box in pairs(o.cdBoxes) do if not seen2[nm] then pcall(function() box.f:Destroy() end); o.cdBoxes[nm] = nil end end
                                        else o.cdRow.Visible = false end
                                else o.cdRow.Visible = false end
                                if cfg.box then
                                                local okb, bcf, bsize = pcall(function() local a, b = model:GetBoundingBox() return a, b end)  -- fitted 2D box: project the oriented bounding box, screen min/max = a rect that hugs them
                                                if okb and bcf and bsize then
                                                        local hx, hy, hz = bsize.X / 2, bsize.Y / 2, bsize.Z / 2
                                                        local minX, minY, maxX, maxY, onScreen = math.huge, math.huge, -math.huge, -math.huge, false
                                                        for _, cx in ipairs({ -hx, hx }) do for _, cy in ipairs({ -hy, hy }) do for _, cz in ipairs({ -hz, hz }) do
                                                                local sp2 = cam:WorldToViewportPoint((bcf * CFrame.new(cx, cy, cz)).Position)
                                                                if sp2.Z > 0 then
                                                                        onScreen = true
                                                                        if sp2.X < minX then minX = sp2.X end; if sp2.Y < minY then minY = sp2.Y end
                                                                        if sp2.X > maxX then maxX = sp2.X end; if sp2.Y > maxY then maxY = sp2.Y end
                                                                end
                                                        end end end
                                                        if onScreen then
                                                                o.box.Visible = true; o.boxS.Color = cfg.accent
                                                                o.box.Position = UDim2.fromOffset(minX, minY); o.box.Size = UDim2.fromOffset(maxX - minX, maxY - minY)
                                                        else o.box.Visible = false end
                                                else o.box.Visible = false end
                                        else o.box.Visible = false end
                                        if cfg.tracers then
                                        local sp, vis = cam:WorldToViewportPoint(hrp.Position)
                                        if vis and sp.Z > 0 then
                                                local ax, ay = vp.X / 2, vp.Y
                                                local dx, dy = sp.X - ax, sp.Y - ay
                                                local len = math.sqrt(dx * dx + dy * dy)
                                                o.tracer.Visible = true; o.tracer.Size = UDim2.fromOffset(len, cfg.tracerThick); o.tracer.BackgroundColor3 = cfg.accent
                                                o.tracer.Position = UDim2.fromOffset((ax + sp.X) / 2, (ay + sp.Y) / 2)
                                                o.tracer.Rotation = math.deg(math.atan2(dy, dx))
                                        else o.tracer.Visible = false end
                                else o.tracer.Visible = false end
                        end
                end
                for m in pairs(pool) do if not present[m] then destroy(m) end end
        end)

        PlayerEspApi = {
                setMaster = function(v) cfg.master = v == true; if not cfg.master then clearAll() end end,
                setOpt = function(k, v) if type(cfg[k]) == "boolean" then cfg[k] = v == true end end,  -- boolean opts only (chams/name/box/tracers/...)
                setThick = function(v) if type(v) == "number" then cfg.tracerThick = v end end,
                setColor = function(c) if typeof(c) == "Color3" then cfg.accent = c end end,
                set = function(v) cfg.master = v == true; if not cfg.master then clearAll() end end,
        }
end

-- ============================================================
-- MODULE: ANTI STUN  (zero your Info.Stun - throttled 0.1s loop, NOT every frame, so it won't lag your body)
-- ============================================================
do
        local Players = game:GetService("Players")
        local LP = Players.LocalPlayer
        local RunService = game:GetService("RunService")
        local on = false
        local function myModel() local chars = workspace:FindFirstChild("Characters"); return (chars and chars:FindFirstChild(LP.Name)) or LP.Character end
        local NAMES = { "Stun", "Stunned", "HitStun", "Hitstun", "eStun", "Knockback", "Knockbacked", "Blockstun", "BlockStun", "Guardbreak", "GuardBreak", "Stagger" }
        local baseWS, baseJP = 16, 50
        RunService.Heartbeat:Connect(function()  -- every frame so a stun is cleared the instant it lands (value writes = cheap). Covers every common stun/knockback flag JJS uses.
                if not on then return end
                local m = myModel(); if not m then return end
                local hum = m:FindFirstChildOfClass("Humanoid")
                local info = m:FindFirstChild("Info")
                if info then
                        for _, nm in ipairs(NAMES) do
                                local v = info:FindFirstChild(nm)
                                if v and (v:IsA("NumberValue") or v:IsA("IntValue") or v:IsA("BoolValue")) then
                                        pcall(function() if typeof(v.Value) == "boolean" then v.Value = false else v.Value = 0 end end)
                                end
                        end
                end
                if hum then
                        pcall(function()
                                if hum.WalkSpeed > 8 then baseWS = hum.WalkSpeed end        -- remember your real speed while un-stunned
                                if hum.JumpPower > 8 then baseJP = hum.JumpPower end
                                if hum.WalkSpeed < 1 then hum.WalkSpeed = baseWS end        -- a stun froze you (WS=0) -> restore movement
                                if hum.JumpPower < 1 then hum.JumpPower = baseJP end
                                local st = hum:GetState()
                                if st == Enum.HumanoidStateType.Physics or st == Enum.HumanoidStateType.FallingDown then hum:ChangeState(Enum.HumanoidStateType.GettingUp) end
                        end)
                        for _, nm in ipairs(NAMES) do if hum:GetAttribute(nm) ~= nil then pcall(function() hum:SetAttribute(nm, false) end) end end
                end
        end)
        AntiStunApi = { set = function(v) on = v == true end }
end

-- ============================================================
-- MODULE: ANTI RAGDOLL  (clear ragdoll ONLY while actually ragdolled - throttled, no per-frame GetDescendants = no lag)
-- ============================================================
do
        local Players = game:GetService("Players")
        local LP = Players.LocalPlayer
        local on = false
        local function myModel() local chars = workspace:FindFirstChild("Characters"); return (chars and chars:FindFirstChild(LP.Name)) or LP.Character end
        local hookedHum = nil
        local function protectStates(hum)  -- disable the ragdoll/falling states + snap OUT if the game forces one
                if not hum then return end
                pcall(function()
                        hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)
                        hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
                end)
                if hookedHum ~= hum then
                        hookedHum = hum
                        hum.StateChanged:Connect(function(_, new)
                                if not on then return end
                                if new == Enum.HumanoidStateType.Ragdoll or new == Enum.HumanoidStateType.FallingDown then
                                        pcall(function() hum:ChangeState(Enum.HumanoidStateType.GettingUp) end)
                                end
                        end)
                end
        end
        task.spawn(function()
                while true do
                        if on then
                                local m = myModel()
                                if m then
                                        local hum = m:FindFirstChildOfClass("Humanoid")
                                        protectStates(hum)
                                        if hum and hum.PlatformStand then pcall(function() hum.PlatformStand = false end) end
                                        local info = m:FindFirstChild("Info")
                                        local rag = info and (info:FindFirstChild("Ragdoll") or info:FindFirstChild("Ragdolled"))
                                        if rag then pcall(function() if typeof(rag.Value) == "boolean" then rag.Value = false else rag.Value = 0 end end) end
                                        local rc = m:FindFirstChild("RagdollConstraints")
                                        if rc then for _, c in ipairs(rc:GetDescendants()) do if c:IsA("Constraint") and c.Enabled then pcall(function() c.Enabled = false end) end end end
                                        for _, d in ipairs(m:GetDescendants()) do   -- kill custom ragdoll joints, re-enable the normal ones
                                                pcall(function()
                                                        if d:IsA("BallSocketConstraint") then d.Enabled = false
                                                        elseif d:IsA("Motor6D") and not d.Enabled then d.Enabled = true end
                                                end)
                                        end
                                end
                        end
                        task.wait(0.15)
                end
        end)
        AntiRagdollApi = { set = function(v) on = v == true end }
end

-- ============================================================
-- MODULE: ANIM THREAT SYSTEM  (real JJS animation IDs: domain casts, counters, and the block script's AnimDict)
-- Powers Anti-Domain (react to the cast anim, earlier than workspace.Domains), Anti-Counter (dodge a counter), Auto-Adapt (block every known attack).
-- ============================================================
do
        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local VIM = game:GetService("VirtualInputManager")
        local LP = Players.LocalPlayer

        -- user-captured domain CAST animation ids -> name
        local DOMAINS = {
                ["132725601768618"] = "Gojo", ["121984128639453"] = "Vessel", ["118861398234801"] = "Gambler",
                ["127843796051633"] = "Mahoraga", ["75736902190737"] = "Mahito", ["125335594549446"] = "Rika", ["101617544363219"] = "Higuruma",
        }
        -- ONLY the 3 REAL counter moves -> Anti Counter jumps on head. (The other ~19 ids were common attacks and made it false-fire on every hit; they live in ADAPT_IDS below.)
        local COUNTERS = { ["82987093810211"] = 1, ["92529934565092"] = 1, ["86073608599582"] = 1 }
        _G.VX_COUNTER_IDS = COUNTERS  -- shared with Auto Counter (per-character counter key)
        -- EVERY attack/skill/domain id the user captured -> Auto Adapt (press 4), Auto Counter (per-character counter key), Anti Counter all fire on ANY of these
        local ADAPT_IDS = {}
        for _, aid in ipairs({
                "137865634124104","137654778575373","95421145178968","104749346956269","101162958113766","124937162378188","132748613906344","77200218033775",
                "124901309160375","100962226150441","131506102901134","137611726964398","107554693613496","82541714192027","72063002791216","72467492674240",
                "108123475959041","95901746347992","132281807148575","120480195428173","132653290201368","111077341852080","116432619539029","81112033595734",
                "131219281339199","75390215999547","115683433001643","138852224035589","85024950165903","84870056161157","103493656287292","89092734635186",
                "72475960800126","108319980293313","125455197945793","123690534435200","128779949980528","127727754867974","76313364850487","105068005007692",
                "89888040037257","127171275866632","84039122607068","117045209683198","100446064103831","114321791577837","95097480425566","117371289990421",
                "107067953428369","94720627091769","136536827155962","111720035828971","100081544058065","121343824534765","89652378115594","76519264603956",
                "133869529005453","135411487367370","132704398648016","106649604455931","132754851925571","124243904748268","125904281673524","89582140026963",
                "95077220586856","108418554887656","93796567192197","88005970155216","131031842057158","123778544771528","71783955283661","120136894011461",
                "87472283043607","93901924492394","114277419400774","136523051723440","89009042593684","137638103122538","118652212972529","105121164520635",
                "118607369830566","86045680364061","119211164876773","94616006376147","70890372338556","115589615022077","82149987460883","115561023870463",
                "81210313723714","130957217409359","100811576955331","113359849246757","78578012001859","134622628645994","89891294371787","122015481201264",
                "113722638806911","92595499555055","96466374346823","81953935260783","73243807139765","114822879878184","138826705245289","70394890117813",
                "113479860283691","129678103897608","129132347098646","134777193523837","121550561336691","94590184881876","115097960689033","94347210073500",
                "104793932628579","77833820443705","103013818601982","79860101129549","72933571933445","72932825817330","123476590646783","120914276661831",
                "102053631728986","76957377224584","126362899488198","90781290293652","81007905598407","99180695169591","130209038947701","83430571986421",
                "78636717376287","85938446097801","116119661056362",
                -- day-11 additions: Brothers ult, Rika yellow-beam/love-ladder, Head of Hei domain hit (all -> Auto Adapt presses 4)
                "121572833341748","84448423136678","89677028738408","72828071138653",  -- Brothers ult
                "73482562876920",  -- Rika yellow beam / love ladder
                "125442768208685",  -- Head of Hei domain HIT
        }) do ADAPT_IDS[aid] = true end
        _G.VX_ADAPT_IDS = ADAPT_IDS

        local domainOn, domainMode, counterOn, adaptOn, blackholeOn, domainAdaptOn = false, "Safe Teleport", false, false, false, false
        local domainCd, counterCd, adaptCd, selfDomainCast = 0, 0, 0, 0
        local function idOf(s) return tostring(s):match("%d+") end
        local function myModel() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
        local function myHRP() local m = myModel(); return m and m:FindFirstChild("HumanoidRootPart") end
        local function tapF() pcall(function() VIM:SendKeyEvent(true, Enum.KeyCode.F, false, game); task.wait(0.16); VIM:SendKeyEvent(false, Enum.KeyCode.F, false, game) end) end
        local ADAPT_LEAD = 0.09  -- seconds to wait after the enemy STARTS the attack before pressing 4, so the adapt lands as the hit connects (raise if it fires too early, lower toward 0 if too late)
        local function pressFour()  -- Auto Adapt presses the 4 KEY (the Adapt skill) - it never plays an animation itself
                -- Marked, like every other injected key: 4 is one of the keys the Total page's Perfect Swap watches, and
                -- an unmarked press would be read there as you casting Elbow Drop.
                -- 0.15, not 0.5: the press lasts 0.05s and the rising-edge poll catches it within a frame. The wide
                -- stamp meant Auto Adapt's own 4 could eat YOUR real 4 for half a second - and Twofold listens on 4.
                _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Four] = tick() + 0.15
                pcall(function() VIM:SendKeyEvent(true, Enum.KeyCode.Four, false, game); task.wait(0.05); VIM:SendKeyEvent(false, Enum.KeyCode.Four, false, game) end)
        end
        local function clickM1()  -- an M1 click at screen-center (used by the moves that need a CLICK to adapt, not just 4)
                pcall(function()
                        local cam = workspace.CurrentCamera; local vp = (cam and cam.ViewportSize) or Vector2.new(1280, 720)
                        VIM:SendMouseButtonEvent(vp.X / 2, vp.Y / 2, 0, true, game, 0); task.wait(0.04); VIM:SendMouseButtonEvent(vp.X / 2, vp.Y / 2, 0, false, game, 0)
                end)
        end
        -- These moves ADAPT BY CLICKING (M1) as soon as they come, NOT by pressing 4: Hollow Purple + the fire move.
        local CLICK_ADAPT_IDS = { ["132748613906344"] = true, ["137611726964398"] = true }
        local function playAdapt(id)
                if id and CLICK_ADAPT_IDS[id] then                         -- Hollow Purple / fire: adapt by CLICKING, not 4
                        -- lands in the parry window (starts the instant it's detected).
                        task.spawn(function() for _ = 1, 4 do clickM1(); task.wait(0.12) end end)
                        return
                end
                task.delay(ADAPT_LEAD, pressFour)                          -- everything else: press 4 on the short lead
        end
        local function dist(er) local mr = myHRP(); return (mr and er) and (er.Position - mr.Position).Magnitude or 9999 end
        local function randomEnemyHRP()
                local list = {}
                for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP and plr.Character then local r = plr.Character:FindFirstChild("HumanoidRootPart"); if r then list[#list + 1] = r end end end
                local chs = workspace:FindFirstChild("Characters"); if chs then for _, m in ipairs(chs:GetChildren()) do if m.Name ~= LP.Name then local r = m:FindFirstChild("HumanoidRootPart"); local h = m:FindFirstChildOfClass("Humanoid"); if r and h and h.Health > 0 then list[#list + 1] = r end end end end
                if #list == 0 then return nil end
                return list[math.random(1, #list)]
        end
        local function trainPos()
                local map = workspace:FindFirstChild("Map"); local d = map and map:FindFirstChild("Destructible"); local m = d and d:FindFirstChild("Model")
                local sc = m and m:FindFirstChild("StationControl"); local h = sc and sc:FindFirstChild("Handle")
                if h and h:IsA("BasePart") then return h.Position end
                local sp = workspace:FindFirstChildOfClass("SpawnLocation"); if sp then return sp.Position end
                return nil
        end
        local function domainCenter()  -- where the active domain is, so we can flee directly AWAY from it
                local domains = workspace:FindFirstChild("Domains")
                if domains then for _, ch in ipairs(domains:GetChildren()) do local ok, cf = pcall(function() return ch:GetPivot() end); if ok and cf then return cf.Position end end end
                return nil
        end
        local function enemyOutsideDomain(c)  -- a user/DUMMY that is OUTSIDE the domain (so teleporting to them actually ESCAPES, never loops you back inside)
                local me = myHRP()
                local function far(r)
                        if not r then return false end
                        if c then return (r.Position - c).Magnitude > 150 end
                        return me and (r.Position - me.Position).Magnitude > 80 or false   -- no center found: at least far from YOU (never TP into the dome around you)
                end
                for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP and plr.Character then local r = plr.Character:FindFirstChild("HumanoidRootPart"); if far(r) then return r end end end
                local chs = workspace:FindFirstChild("Characters"); if chs then for _, m in ipairs(chs:GetChildren()) do if m.Name ~= LP.Name then local r = m:FindFirstChild("HumanoidRootPart"); local h = m:FindFirstChildOfClass("Humanoid"); if r and h and h.Health > 0 and far(r) then return r end end end end
                return nil
        end
        local function safeTeleport()  -- ESCAPE the domain: to a user/DUMMY OUTSIDE it, else bolt AWAY from the center + up, else train / straight up. Never lands you back inside.
                local hrp = myHRP(); if not hrp then return end
                local c = domainCenter()
                local out = enemyOutsideDomain(c)
                if out then vxTeleportHard(out.Position - out.CFrame.LookVector * 4 + Vector3.new(0, 3, 0), 1.25); return end   -- go to a user who is OUTSIDE the domain
                if c then local away = hrp.Position - c; local dir = away.Magnitude > 1 and away.Unit or hrp.CFrame.LookVector; vxTeleportHard(c + dir * 320 + Vector3.new(0, 140, 0), 1.25); return end  -- none outside: bolt far away from the center + high UP (out of the dome)
                local tp = trainPos(); if tp then vxTeleportHard(tp + Vector3.new(0, 6, 0), 1.25); return end               -- no center found: train station
                vxTeleportHard(hrp.Position + Vector3.new(0, 400, 0), 1.25)                                                  -- last resort: straight UP, high enough to clear the dome
        end
        local function domainCaster()  -- the enemy who CAST the domain = the living enemy nearest the domain center
                local c = domainCenter(); if not c then return randomEnemyHRP() end
                local best, bd
                local function chk(r) if r then local d = (r.Position - c).Magnitude; if not bd or d < bd then best, bd = r, d end end end
                for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP and plr.Character then local h = plr.Character:FindFirstChildOfClass("Humanoid"); if h and h.Health > 0 then chk(plr.Character:FindFirstChild("HumanoidRootPart")) end end end
                local chs = workspace:FindFirstChild("Characters"); if chs then for _, m in ipairs(chs:GetChildren()) do if m.Name ~= LP.Name then local h = m:FindFirstChildOfClass("Humanoid"); if h and h.Health > 0 then chk(m:FindFirstChild("HumanoidRootPart")) end end end end
                return best
        end
        local function domainReact(name, caster)
                local hrp = myHRP(); if not hrp then return end
                if domainMode == "To User + Hit" then
                        -- go to the CASTER (the one whose cast anim triggered this) and HIT them to interrupt the domain
                        local r = (caster and caster:FindFirstChild("HumanoidRootPart")) or domainCaster()
                        local cchar = caster or (r and r.Parent)
                        if r then
                                vxTeleportHard(r.Position - r.CFrame.LookVector * 3 + Vector3.new(0, 2, 0), 1.5)
                                task.delay(0.12, function()
                                        if _G.VX_RUNCHAIN and cchar and cchar.Parent then pcall(function() _G.VX_RUNCHAIN(cchar) end)   -- black flash the caster
                                        else pcall(function()                                                                            -- fallback: raw M1s
                                                local VIM = game:GetService("VirtualInputManager")
                                                for _ = 1, 4 do VIM:SendMouseButtonEvent(0, 0, 0, true, game, 0); task.wait(0.05); VIM:SendMouseButtonEvent(0, 0, 0, false, game, 0); task.wait(0.14) end
                                        end) end
                                end)
                        end
                else
                        safeTeleport()   -- Safe Teleport (default): OUT of the domain
                end
        end
        local counterMode, counterEmote = "Jump On Head", 1   -- what to do when an enemy counters: jump on their head OR play a saved emote
        local function emoteRE(name)
                local RSs = game:GetService("ReplicatedStorage")
                local k = RSs:FindFirstChild("Knit"); k = k and k:FindFirstChild("Knit"); k = k and k:FindFirstChild("Services")
                local s = k and k:FindFirstChild("EmoteService"); local re = s and s:FindFirstChild("RE"); return re and re:FindFirstChild(name)
        end
        local function counterReact(enemyChar)  -- enemy countered -> Jump On Head OR taunt them with your saved emote
                if counterMode == "Emote" then
                        local re = emoteRE("Emote")
                        if re then pcall(function() re:FireServer(counterEmote) end) end   -- play emote slot #counterEmote
                        task.delay(2.6, function()                                          -- end it once their counter is done
                                local re2 = emoteRE("EmoteEnd"); if re2 then pcall(function() re2:FireServer() end) end
                        end)
                else
                        if JumpHeadApi then JumpHeadApi.jump(enemyChar or "Nearest") end
                end
        end
        local function blackholeReact(hole)
            local hrp=myHRP()
            if not blackholeOn or not hrp or not hole or not hole.Parent then return end
            local delta=hrp.Position-hole.Position
            local flat=Vector3.new(delta.X,0,delta.Z)
            if flat.Magnitude<0.1 then flat=Vector3.new(1,0,0) end
            local destination=hrp.Position+flat.Unit*160
            local params=RaycastParams.new(); params.FilterType=Enum.RaycastFilterType.Exclude
            params.FilterDescendantsInstances={vxMyChar(),hole}
            local ground=workspace:Raycast(destination+Vector3.new(0,100,0),Vector3.new(0,-300,0),params)
            if not ground then return end
            local arrived=vxGlide(ground.Position+Vector3.new(0,4,0))
            if not arrived then warn("[DreamHub Black Hole] escape movement was not accepted") end
        end

        local function blackHoleObject()  -- detect the ACTUAL black-hole effect part (the anim id was Megumi's dive - it false-fired)
                local hrp = myHRP(); if not hrp then return nil end
                for _, d in ipairs(workspace:GetDescendants()) do
                        if d:IsA("BasePart") then local n = d.Name:lower()
                                if (n:find("black") and n:find("hole")) or n:find("voidsphere") or n:find("blackhole") then
                                        if (d.Position - hrp.Position).Magnitude <= 140 then return d end
                                end
                        end
                end
                return nil
        end
        local function onAnim(enemyChar, animId, track)
                local id = idOf(animId); if not id then return end
                local er = enemyChar:FindFirstChild("HumanoidRootPart")
                if domainOn and DOMAINS[id] and tick() - domainCd > 3 then domainCd = tick(); domainReact(DOMAINS[id], enemyChar) end   -- caster passed -> 'To User + Hit' hits the RIGHT person
                if counterOn and COUNTERS[id] and er and dist(er) <= 26 and tick() - counterCd > 0.8 then counterCd = tick(); counterReact(enemyChar) end
                -- AUTO ADAPT: on the AnimationPlayed event (so it is TIMED to the attack, not polled), if an enemy starts ANY
                -- of the full captured attack-id list OR a block-dict attack -> press 4 (after ADAPT_LEAD). 0.35s de-dupe.
                -- Range is 60 (was 20 = melee only) so Gojo's ULT / ranged casts (Purple, Red, Unlimited Void) trigger it too.
                if adaptOn and er and dist(er) <= 60 and tick() - adaptCd > 0.35 then local dict = _G.VX_ANIMDICT; if ADAPT_IDS[id] or (dict and dict[id]) then adaptCd = tick(); playAdapt(id) end end
                -- AUTO EVASIVE rides the SAME proven event: nearby enemy starts any attack -> the i-frame dash fires
                if _G.VX_EVADE and er and dist(er) <= 30 then local dict = _G.VX_ANIMDICT; if ADAPT_IDS[id] or (dict and dict[id]) or COUNTERS[id] then _G.VX_EVADE(enemyChar,track) end end
                if _G.VX_AUTOCOUNTER_ON and _G.VX_AUTOCOUNTER then _G.VX_AUTOCOUNTER(enemyChar, id) end  -- AUTO COUNTER reacts on the SAME event = counters before the hit lands, on every attack id
        end
        local hooked = setmetatable({}, { __mode = "k" })  -- animator -> connection (weak so dead chars GC)
        local function hookChar(char)
                if not char or char.Name == LP.Name or char == LP.Character then return end
                local hum = char:FindFirstChildOfClass("Humanoid") or char:FindFirstChildOfClass("AnimationController")
                local anim = hum and hum:FindFirstChildOfClass("Animator")
                if anim and not hooked[anim] then hooked[anim] = anim.AnimationPlayed:Connect(function(track) if track.Animation then onAnim(char, track.Animation.AnimationId,track) end end) end
        end
        pcall(function()  -- hook brand-new enemies THE MOMENT they spawn, so their first swing is already caught (no up-to-a-second blind window)
                local chs = workspace:FindFirstChild("Characters")
                if chs then chs.ChildAdded:Connect(function(m) task.wait(0.2); if domainOn or counterOn or adaptOn or blackholeOn or _G.VX_AUTOCOUNTER_ON or _G.VX_EVASIVE_ON then hookChar(m) end end) end
        end)
        task.spawn(function()
                while true do
                        if domainOn or counterOn or adaptOn or blackholeOn or _G.VX_AUTOCOUNTER_ON or _G.VX_EVASIVE_ON then
                                local chs = workspace:FindFirstChild("Characters"); if chs then for _, m in ipairs(chs:GetChildren()) do hookChar(m) end end
                                for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP and plr.Character then hookChar(plr.Character) end end
                        end
                        task.wait(0.6)  -- re-scan often so a newly-appeared enemy is hooked in time to adapt to their attacks
                end
        end)
        -- AUTO DOMAIN ADAPT: while you are trapped inside an enemy domain, keep pressing 4 to adapt to it (blood rain, Gojo, Head of Hei, etc.). Per-type time cap; Rika domain is skipped (no ult there).
        local DOMAIN_CAP = { vessel = 8 }  -- seconds to keep spamming 4 for this domain type; any type NOT listed = spam the whole time the domain is up
        local function activeDomain()
                local domains = workspace:FindFirstChild("Domains"); if not domains then return nil end
                for _, ch in ipairs(domains:GetChildren()) do if ch:IsA("Model") or ch:IsA("Folder") then return ch end end
                return nil
        end
        local function domainTypeOf(dom)  -- classify ONCE (on domain appear) by a name keyword anywhere inside it (e.g. DomainCollider.YutaDomain)
                if not dom then return "other" end
                local function kw(n) n = n:lower()
                        if n:find("yuta") or n:find("vessel") or n:find("authentic") then return "vessel" end   -- check BEFORE rika (Yuta's domain contains Rika parts but should be "vessel" = 8s cap)
                        if n:find("rika") then return "rika" end
                        if n:find("gojo") or n:find("void") or n:find("infinite") then return "gojo" end
                        if n:find("choso") or n:find("blood") then return "blood" end
                        if n:find("hei") then return "hei" end
                        if n:find("mahito") then return "mahito" end
                        return nil
                end
                local t = kw(dom.Name); if t then return t end
                for _, d in ipairs(dom:GetDescendants()) do local k = kw(d.Name); if k then return k end end
                return "other"
        end
        local function domainCenterPos(dom)
                local ok, cf = pcall(function() return dom:GetPivot() end); if ok and cf then return cf.Position end
                local p = dom:FindFirstChildWhichIsA("BasePart", true); return p and p.Position
        end
        local function insideDomain(dom)  -- are you caught in it? within ~160 studs of its center - or ASSUME yes if we can't resolve a center (domain exists = you're likely in it)
                local hrp = myHRP(); if not hrp then return false end
                local c = dom and domainCenterPos(dom)
                if not c then return true end
                return (hrp.Position - c).Magnitude <= 160
        end
        local function domainMine(dom)  -- is this YOUR OWN domain? (don't adapt against it) - check an Owner ObjectValue if the game exposes one anywhere inside
                local o = dom:FindFirstChild("Owner", true)
                if o and o:IsA("ObjectValue") and o.Value then return o.Value == myModel() or o.Value == LP.Character or o.Value.Name == LP.Name end
                return false
        end
        local SUKUNA_DOMAIN_IDS = { ["125442768208685"] = true, ["134795274895344"] = true, ["121752268008113"] = true }  -- Sukuna domain HIT anims -> spam 4 for 10s
        local GOJO_DOMAIN_IDS = { ["138196552148011"] = true }  -- Gojo domain HIT anim -> press 4 ONCE
        local sukunaSpamUntil, gojoAdaptCd, frozenCd = 0, 0, 0
        local selfHooked = setmetatable({}, { __mode = "k" })  -- hook YOUR animator so we know when YOU cast a domain / are caught in Sukuna's or Gojo's
        local function hookSelfDomain()
                local m = myModel(); local h = m and m:FindFirstChildOfClass("Humanoid"); local a = h and h:FindFirstChildOfClass("Animator")
                if not a or selfHooked[a] then return end
                selfHooked[a] = a.AnimationPlayed:Connect(function(track)
                        local id = track.Animation and idOf(track.Animation.AnimationId); if not id then return end
                        if DOMAINS[id] then selfDomainCast = tick() end                          -- you cast a domain -> the active one is YOURS
                        if SUKUNA_DOMAIN_IDS[id] and domainAdaptOn then                          -- caught in SUKUNA'S domain -> ADAPT: hammer 4 for 10s straight
                                local wasActive = tick() < sukunaSpamUntil
                                sukunaSpamUntil = tick() + 10
                                if not wasActive then task.spawn(function() while tick() < sukunaSpamUntil do pressFour(); task.wait(0.25) end end) end
                        end
                        if GOJO_DOMAIN_IDS[id] and domainAdaptOn and tick() - gojoAdaptCd > 2 then gojoAdaptCd = tick(); pressFour() end   -- caught in GOJO'S domain -> ADAPT: press 4 ONCE
                end)
        end
        -- GOJO / frozen detection: if you are TRYING to move (input a direction) but your body isn't actually
        -- moving (frozen by Gojo's Infinite Void), press 4 ONCE to adapt.
        task.spawn(function()
                local UIS = game:GetService("UserInputService")
                while true do
                        task.wait(0.15)
                        if domainAdaptOn and tick() - frozenCd > 2 then
                                local m = myModel(); local hum = m and m:FindFirstChildOfClass("Humanoid"); local hrp = m and m:FindFirstChild("HumanoidRootPart")
                                if hum and hrp then
                                        local wantsMove = hum.MoveDirection.Magnitude > 0.1 or UIS:IsKeyDown(Enum.KeyCode.W) or UIS:IsKeyDown(Enum.KeyCode.A) or UIS:IsKeyDown(Enum.KeyCode.S) or UIS:IsKeyDown(Enum.KeyCode.D)
                                        local vel = Vector3.new(hrp.AssemblyLinearVelocity.X, 0, hrp.AssemblyLinearVelocity.Z).Magnitude
                                        if wantsMove and vel < 1.5 then frozenCd = tick(); pressFour() end   -- you're inputting movement but not moving = frozen -> adapt once
                                end
                        end
                end
        end)
        task.spawn(function()  -- workspace.Domains scan: Anti-Domain escape (ANY domain, incl. vessel - not just anim-id) + Auto-Domain-Adapt spam + black-hole EFFECT scan
                local lastDom, lastReactedDom, domType, domStart, bhCd, dbgCd = nil, nil, "other", 0, 0, 0
                local lastHole
                local function dbg(msg) if VX_DEBUG and VX_NOTIFY and tick() - dbgCd > 2 then dbgCd = tick(); pcall(function() VX_NOTIFY(msg, nil) end) end end  -- ONLY with Debug on; never leaks internals during normal play
                while true do
                        local dom = (domainOn or domainAdaptOn) and activeDomain() or nil
                        if domainOn or domainAdaptOn then hookSelfDomain() end  -- track when YOU cast a domain
                        if not dom then lastDom = nil; if domainAdaptOn then dbg("Domain Adapt: none active") end
                        else
                                if dom ~= lastDom then lastDom = dom; domType = domainTypeOf(dom); domStart = tick() end  -- classify the new domain ONCE (avoid re-scanning its many parts each tick)
                                local mine = domainMine(dom) or (tick() - selfDomainCast <= 13)                          -- is this YOUR OWN domain? (Owner value or you just cast one)
                                if domainOn and not mine and (dom ~= lastReactedDom or insideDomain(dom)) and tick() - domainCd > 3 then
                                        domainCd = tick(); lastReactedDom = dom; domainReact("Domain")                        -- ESCAPE: fire once on any new domain, then RETRY every 3s while still trapped (so a set-back can't leave you stuck)
                                end
                                if domainAdaptOn and not mine then                                                        -- ADAPT: press 4 whenever an ENEMY domain is up (the inside-check was a false-negative that made it do nothing). Per-type time cap.
                                        local cap = DOMAIN_CAP[domType]
                                        if not cap or tick() - domStart <= cap then pressFour(); dbg("Domain Adapt: 4 (" .. domType .. ")") else dbg("Domain Adapt: cap (" .. domType .. ")") end
                                elseif domainAdaptOn and mine then dbg("Domain Adapt: own domain (skip)")
                                end
                        end
                        if blackholeOn then
                            local hole=blackHoleObject()
                            if hole and hole~=lastHole and tick()-bhCd>4 then lastHole=hole; bhCd=tick(); blackholeReact(hole)
                            elseif not hole then lastHole=nil end
                        else lastHole=nil end
                        task.wait(0.25)
                end
        end)
        AntiDomainApi = { set = function(v) domainOn = v == true end, setMode = function(m) domainMode = m or "Safe Teleport" end }
        AntiCounterApi = {
                set = function(v) counterOn = v == true end,
                setMode = function(m) counterMode = (m == "Emote") and "Emote" or "Jump On Head" end,   -- what to do on their counter
                setEmote = function(n) counterEmote = tonumber(n) or 1 end,                              -- which saved emote slot to play
        }
        AutoAdaptApi = { set = function(v) adaptOn = v == true end }
        AutoDomainAdaptApi = { set = function(v) domainAdaptOn = v == true end }
        AntiBlackHoleApi = { set = function(v) blackholeOn = v == true end }
end

-- ============================================================
-- MODULE: MAHORAGA SAFE TP + AUTO EARTHQUAKE + AUTO KILL-EMOTE
-- ============================================================
do
        local Players = game:GetService("Players")
        local RS = game:GetService("ReplicatedStorage")
        local LP = Players.LocalPlayer
        local function myModel() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
        local function myHRP() local m = myModel(); return m and m:FindFirstChild("HumanoidRootPart") end
        local function emoteRE(name)
                local k = RS:FindFirstChild("Knit"); k = k and k:FindFirstChild("Knit"); k = k and k:FindFirstChild("Services")
                local s = k and k:FindFirstChild("EmoteService"); local re = s and s:FindFirstChild("RE"); return re and re:FindFirstChild(name)
        end

        -- ---------- MAHORAGA SAFE TP ----------
        -- When ANY enemy summons Mahoraga (they play the summon anim rbxassetid://127843796051633, or the model
        -- appears), teleport ME to a fixed SAFE spot far off the map, hold there while the summon danger passes,
        -- then teleport ME back to the main map. Fixed coords the user gave.
        local mahoOn, mahoCd = false, 0
        local MAHO_SAFE   = Vector3.new(-66.9, 50.8, 424.0)   -- safe spot to sit out the Mahoraga summon
        local MAHO_RETURN = Vector3.new(-16.2, 24.4, 14.1)    -- main map spawn to return to when it's done
        local MAHO_ANIM = { ["127843796051633"] = true }      -- Mahoraga summon/cast id
        local function mahoNameHit(n) n = n:lower(); return n:find("mahoraga") or n:find("mahoro") or (n:find("divine") and n:find("general")) end
        local function scanMahoraga()  -- a Mahoraga model present in the world near you
                local hrp = myHRP(); if not hrp then return false end
                local function chkList(parent)
                        if not parent then return false end
                        for _, m in ipairs(parent:GetChildren()) do
                                if m:IsA("Model") and mahoNameHit(m.Name) then
                                        local r = m:FindFirstChild("HumanoidRootPart") or m:FindFirstChildWhichIsA("BasePart")
                                        if r and (r.Position - hrp.Position).Magnitude <= 260 then return true end
                                end
                        end
                        return false
                end
                return chkList(workspace) or chkList(workspace:FindFirstChild("Characters")) or chkList(workspace:FindFirstChild("Summons")) or chkList(workspace:FindFirstChild("Shadows"))
        end
        local mahoBusy = false
        local function mahoEscape()
                if mahoBusy then return end
                mahoBusy = true
                if VX_NOTIFY then VX_NOTIFY("Mahoraga sensed - safe teleport", false) end
                vxTeleportHard(MAHO_SAFE + Vector3.new(0, 4, 0), 5)          -- the WORKING glide teleport (same engine as the Teleports tab) to the safe spot + hold 5s
                task.delay(7, function()
                        vxTeleportHard(MAHO_RETURN + Vector3.new(0, 4, 0), 1.25)     -- summon done -> back to the main map
                        if VX_NOTIFY then VX_NOTIFY("Back to main map", true) end
                        task.delay(1.5, function() mahoBusy = false end)
                end)
        end
        -- CATCH THE SPAWN ANYWHERE: the Mahoraga model can stream in under any folder - a workspace-wide
        -- DescendantAdded listener catches it wherever it lands (the 4-folder poll kept missing it).
        pcall(function()
                workspace.DescendantAdded:Connect(function(d)
                        if not mahoOn then return end
                        if not (d:IsA("Model") and mahoNameHit(d.Name)) then return end
                        if tick() - mahoCd > 5 then mahoCd = tick(); mahoEscape() end
                end)
        end)
        -- CHANT path (most reliable): the Mahoraga summon makes the summoner SAY the ritual chant
        -- ("With this treasure I summon..."). The moment ANY enemy chats it, safe TP - fires even if
        -- the anim/model never streams in on your client.
        local CHANT = "with this treasure"
        local function chantHook(plr)
                pcall(function() plr.Chatted:Connect(function(msg)
                        if mahoOn and tostring(msg):lower():find(CHANT, 1, true) and tick() - mahoCd > 5 then mahoCd = tick(); mahoEscape() end
                end) end)
        end
        for _, p in ipairs(Players:GetPlayers()) do if p ~= LP then chantHook(p) end end
        Players.PlayerAdded:Connect(function(p) if p ~= LP then chantHook(p) end end)
        pcall(function()
                game:GetService("TextChatService").MessageReceived:Connect(function(m)
                        if not (mahoOn and m and m.Text) then return end
                        local src = m.TextSource
                        if src and src.UserId == LP.UserId then return end   -- your OWN summon must not teleport you away
                        if m.Text:lower():find(CHANT, 1, true) and tick() - mahoCd > 5 then mahoCd = tick(); mahoEscape() end
                end)
        end)
        -- anim path: catch the summon the instant an enemy plays it (earlier than the model streaming in)
        local mahoHooked = setmetatable({}, { __mode = "k" })
        local function hookMahoAnim(char)
                if not char or char.Name == LP.Name or char == LP.Character then return end
                local h = char:FindFirstChildOfClass("Humanoid") or char:FindFirstChildOfClass("AnimationController")
                local a = h and h:FindFirstChildOfClass("Animator")
                if a and not mahoHooked[a] then mahoHooked[a] = a.AnimationPlayed:Connect(function(track)
                        if not mahoOn then return end
                        local id = track.Animation and tostring(track.Animation.AnimationId):match("%d+")
                        if id and MAHO_ANIM[id] and tick() - mahoCd > 5 then mahoCd = tick(); mahoEscape() end
                end) end
        end
        task.spawn(function()
                while true do
                        if mahoOn then
                                local chs = workspace:FindFirstChild("Characters"); if chs then for _, m in ipairs(chs:GetChildren()) do hookMahoAnim(m) end end
                                for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP and plr.Character then hookMahoAnim(plr.Character) end end
                                if tick() - mahoCd > 5 and scanMahoraga() then mahoCd = tick(); mahoEscape() end   -- model-appearance fallback
                        end
                        task.wait(0.4)
                end
        end)

        -- ---------- AUTO EARTHQUAKE ----------
        -- Fire the Earthquake move ONCE, then WAIT for its real cooldown before firing again (the old 1.4s loop
        -- machine-gunned the remote = 'just spams the moves'). The move only lands when you're GROUNDED and it's
        -- off cooldown, so we gate on both.
        local quakeOn = false
        local function quakeRE()
                local k = RS:FindFirstChild("Knit"); k = k and k:FindFirstChild("Knit"); k = k and k:FindFirstChild("Services")
                local s = k and k:FindFirstChild("EarthquakeService"); local re = s and s:FindFirstChild("RE"); return re and re:FindFirstChild("Activated")
        end
        local function fireQuake()
                local m = myModel(); local ms = m and m:FindFirstChild("Moveset"); local eq = ms and ms:FindFirstChild("Earthquake")
                local hum = m and m:FindFirstChildOfClass("Humanoid")
                if not eq then return false end                                    -- your character has no Earthquake move -> no-op
                if hum and hum.FloorMaterial == Enum.Material.Air then return false end   -- must be grounded for the quake to land
                local re = quakeRE()
                if re then pcall(function() re:FireServer(eq) end); return true end
                return false
        end
        -- fireQuake is the fallback used by the key trigger below when the key hold didn't actually start the move.

        -- ---------- AUTO KILL-EMOTE ----------
        -- When a nearby enemy DIES, play your emote (taunt on the kill) via the EmoteService remote. No teleport
        -- onto the body - it just fires the emote where you stand. Death is detected by watching each enemy's
        -- health drop from >0 to <=0 (reliable for JJS enemies that ragdoll instead of firing Humanoid.Died).
        local killEmoteOn, killEmoteSlot, keCd = false, 1, 0
        local hpSeen = setmetatable({}, { __mode = "k" })   -- humanoid -> last seen health
        local function doKillEmote()
                if tick() - keCd < 1.5 then return end
                keCd = tick()
                local re = emoteRE("Emote"); if re then pcall(function() re:FireServer(killEmoteSlot) end) end
                task.delay(2.8, function()
                        local re2 = emoteRE("EmoteEnd"); if re2 then pcall(function() re2:FireServer() end) end
                end)
        end
        task.spawn(function()
                while true do
                        if killEmoteOn then
                                local mh = myHRP()
                                local function chk(char)
                                        if not char or char.Name == LP.Name or char == LP.Character then return end
                                        local hum = char:FindFirstChildOfClass("Humanoid"); local r = char:FindFirstChild("HumanoidRootPart")
                                        if not hum or not r then return end
                                        local prev = hpSeen[hum]
                                        if prev ~= nil and prev > 0 and hum.Health <= 0 then   -- just died
                                                if mh and (r.Position - mh.Position).Magnitude <= 130 then doKillEmote() end   -- only taunt a kill near you (yours)
                                        end
                                        hpSeen[hum] = hum.Health
                                end
                                for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP then chk(plr.Character) end end
                                local chs = workspace:FindFirstChild("Characters"); if chs then for _, m in ipairs(chs:GetChildren()) do chk(m) end end
                        end
                        task.wait(0.25)
                end
        end)

        MahoTpApi   = { set = function(v) mahoOn = v == true end }
        AutoQuakeApi = { set = function(v) quakeOn = v == true end }
        -- Earthquake: you tap 3, the script does the charged hold for you (Quake Hold slider = the length).
        -- TWO paths so it ALWAYS lands: (1) the key hold; (2) if your body never actually played the quake
        -- windup anim, the move clearly didn't start — fire it directly through its own service as a fallback.
        do
                local VIMq = game:GetService("VirtualInputManager")
                local UISq = game:GetService("UserInputService")
                local QUAKE_ANIM = "rbxassetid://85024950165903"
                local holding = false
                local quakeAnimSeen = 0
                task.spawn(function()   -- watch your live rig for the quake windup anim (proof the move started)
                        local hooked = setmetatable({}, { __mode = "k" })
                        while true do
                                task.wait(0.6)
                                pcall(function()
                                        local chs = workspace:FindFirstChild("Characters")
                                        local body = (chs and chs:FindFirstChild(LP.Name)) or LP.Character
                                        local hum = body and body:FindFirstChildOfClass("Humanoid")
                                        local a = hum and hum:FindFirstChildOfClass("Animator")
                                        if a and not hooked[a] then
                                                hooked[a] = a.AnimationPlayed:Connect(function(tr)
                                                        local ok, id = pcall(function() return tr.Animation.AnimationId end)
                                                        if ok and tostring(id):find("85024950165903") then quakeAnimSeen = tick() end
                                                end)
                                        end
                                end)
                        end
                end)
                -- nearest player OR dummy within range (the trigger for the auto quake)
                local function enemyNear(range)
                        local mh = myHRP(); if not mh then return false end
                        local function chk(m)
                                if not m or m == myModel() or m.Name == LP.Name then return false end
                                local r = m:FindFirstChild("HumanoidRootPart"); local h = m:FindFirstChildOfClass("Humanoid")
                                if not r then return false end
                                if h and h.Health <= 0 then return false end
                                return (r.Position - mh.Position).Magnitude <= range
                        end
                        for _, pl in ipairs(Players:GetPlayers()) do if pl ~= LP and chk(pl.Character) then return true end end
                        local chs = workspace:FindFirstChild("Characters")
                        if chs then for _, m in ipairs(chs:GetChildren()) do if chk(m) then return true end end end
                        local dummies = workspace:FindFirstChild("Dummies") or workspace:FindFirstChild("Training")
                        if dummies then for _, m in ipairs(dummies:GetChildren()) do if chk(m) then return true end end end
                        return false
                end
                -- One charged quake. You tap 3; from that instant the key is kept down for the full charge time and
                -- re-asserted every 80ms, so even if your finger lifts early the charge never drops. One clean release
                -- fires the shockwave, and the move's own service is fired in parallel as a backup.
                local function doQuake()
                        if holding then return end
                        holding = true
                        task.spawn(function()
                                local hold = tonumber(_G.VX_QUAKE_HOLD) or 2
                                local began = tick()
                                _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Three] = tick() + hold + 0.4
                                pcall(function()
                                        local t0 = tick()
                                        VIMq:SendKeyEvent(true, Enum.KeyCode.Three, false, game)     -- 3 down
                                        while tick() - t0 < hold do
                                                _G.VX_INJ_KEYS[Enum.KeyCode.Three] = tick() + 0.4
                                                VIMq:SendKeyEvent(true, Enum.KeyCode.Three, false, game)  -- keep it held for you
                                                task.wait(0.04)
                                        end
                                        VIMq:SendKeyEvent(false, Enum.KeyCode.Three, false, game)     -- let go -> shockwave
                                end)
                                task.wait(0.25)
                                local sawAnim = quakeAnimSeen >= began
                                if not sawAnim then pcall(fireQuake) end
                                _G.VX_QUAKE_LAST = tick(); _G.VX_QUAKE_LASTMSG = string.format("held 3 for %.1fs | windup seen=%s", hold, tostring(sawAnim))
                                if _G.VX_QUAKE_DEBUG then pcall(function() print(string.format("[QUAKE] held 3 for %.1fs | windup anim seen=%s | service backup fired=%s", hold, tostring(sawAnim), tostring(not sawAnim))) end) end
                                holding = false
                        end)
                end
                -- Free build: no auto-pressing. The move only starts when YOU tap 3 — then it is held 2s for you.
                -- Non-free (future Plus): keep the near-enemy auto loop.
                if not _G.JJS_FREE then
                        task.spawn(function()
                                while true do
                                        task.wait(0.3)
                                        if quakeOn and not holding and enemyNear(tonumber(_G.VX_QUAKE_RANGE) or 60) then
                                                doQuake()
                                                task.wait((tonumber(_G.VX_QUAKE_HOLD) or 2) + 2.5)
                                        end
                                end
                        end)
                end
                -- The trigger: your own tap on 3. On the press we take over and hold it for the charge length.
                -- (No gameProcessedEvent check — the game sinks the ability key, which would otherwise swallow the trigger.)
                UISq.InputBegan:Connect(function(input)
                        if input.KeyCode ~= Enum.KeyCode.Three then return end
                        if not quakeOn then return end
                        -- A 3 the BF chain consumed is the chain's trigger, not a quake request. Starting the 2s VIM
                        -- key-3 hold here is what swallowed the chain's flash press (a down onto an already-down key is
                        -- no press at all) and re-pressed 3 at quake timing on release. The chain wins for that beat.
                        if tick() - (tonumber(_G.VX_BF_TRIG3) or 0) < 0.9 then return end
                        if UISq:GetFocusedTextBox() then return end
                        local injK = _G.VX_INJ_KEYS
                        if injK and injK[Enum.KeyCode.Three] and tick() < injK[Enum.KeyCode.Three] then return end   -- our own injected press
                        doQuake()
                end)
                -- If you TAP (finger lifts right after), that physical key-up would end the charge early on a
                -- hold-to-charge move. While we hold it for you, re-press the instant your release is seen.
                UISq.InputEnded:Connect(function(input)
                        if input.KeyCode ~= Enum.KeyCode.Three then return end
                        if not (quakeOn and holding) then return end
                        _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Three] = tick() + 0.5   -- 3 is the Black Flash key: an unmarked press launches a BF chain
                        pcall(function() VIMq:SendKeyEvent(true, Enum.KeyCode.Three, false, game) end)
                end)
        end
        KillEmoteApi = { set = function(v) killEmoteOn = v == true end, setSlot = function(n) killEmoteSlot = tonumber(n) or 1 end }
end

-- ============================================================
-- MODULE: YUTA BLACK FLASH  (manual assist on your Yuta M1 + fully-auto teleport-kill flash)
-- ============================================================
do
        local Players = game:GetService("Players")
        local LP = Players.LocalPlayer
        local manualOn, autoOn, last = false, false, 0
        -- every Yuta / Yuta-Ult M1 anim id (from the M1 database) -> detect YOUR Yuta M1 landing
        local YUTA_M1 = {
                ["133240987753043"] = true, ["130806585141471"] = true, ["131967150738931"] = true, ["84442064935420"] = true,
                ["109432265703187"] = true, ["137919635923292"] = true, ["135256592475167"] = true, ["121403322067812"] = true,
        }
        local function myModel() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
        local function getHRP(m) return m and (m:FindFirstChild("HumanoidRootPart") or m:FindFirstChild("UpperTorso")) end
        local function nearestEnemy(maxD)
                local mh = getHRP(myModel()); if not mh then return nil end
                local best, bd = nil, maxD
                local function chk(m)
                        if not m or m == myModel() or m.Name == LP.Name then return end
                        local r = getHRP(m); local h = m:FindFirstChildOfClass("Humanoid")
                        if not r or (h and h.Health <= 0) then return end
                        local d = (r.Position - mh.Position).Magnitude; if d < bd then bd = d; best = m end
                end
                for _, pl in ipairs(Players:GetPlayers()) do if pl ~= LP then chk(pl.Character) end end
                local chs = workspace:FindFirstChild("Characters"); if chs then for _, m in ipairs(chs:GetChildren()) do if m:IsA("Model") then chk(m) end end end
                return best
        end
        local LOW_HP = 0.35   -- Yuta kill only fires when the target is LOW: at or below 35% health (the finisher)
        local function isLow(tgt)
                local h = tgt and tgt:FindFirstChildOfClass("Humanoid")
                if not h or h.MaxHealth <= 0 then return false end
                return (h.Health / h.MaxHealth) <= LOW_HP and h.Health > 0
        end
        -- YUTA BLACK FLASH mechanic (user): press move "2" TWICE and it black-flashes. Anim rbxassetid://89582140026963
        -- is the black-flash itself. So we double-tap the 2 key (its own move), not a custom teleport chain.
        local VIMy = game:GetService("VirtualInputManager")
        local function flash(tgt, requireLow)
                if tick() - last < 1.6 then return end
                if not (tgt and tgt.Parent) then return end
                if requireLow and not isLow(tgt) then return end   -- low-HP gate is ONLY for the auto kill mode (it blocked the manual toggle on full-HP targets = 'don't work')
                last = tick()
                _G.VX_INJECT_UNTIL = tick() + 1.2   -- our 2-taps must not trigger other features
                _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Two] = tick() + 1.2
                task.spawn(function()               -- Resolute Slash: press 2, wait for the slash, press 2 AGAIN = the black flash
                        pcall(function() VIMy:SendKeyEvent(true, Enum.KeyCode.Two, false, game); task.wait(0.06); VIMy:SendKeyEvent(false, Enum.KeyCode.Two, false, game) end)
                        task.wait(0.45)                  -- 'USE AGAIN' window: the first slash has to come out before the re-press converts
                        pcall(function() VIMy:SendKeyEvent(true, Enum.KeyCode.Two, false, game); task.wait(0.06); VIMy:SendKeyEvent(false, Enum.KeyCode.Two, false, game) end)
                end)
        end
        -- MANUAL "Yuta Black Flash" (user spec): when YOUR animator plays rbxassetid://89582140026963 (the
        -- black-flash-ready anim), the script presses 2 TWICE for you = the flash. No HP gate.
        local YUTA_BF_ANIM = "89582140026963"
        local function doubleTapTwo()
                if tick() - last < 1.4 then return end
                last = tick()
                _G.VX_INJECT_UNTIL = tick() + 1.2
                _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Two] = tick() + 1.2
                task.spawn(function()
                        pcall(function() VIMy:SendKeyEvent(true, Enum.KeyCode.Two, false, game); task.wait(0.06); VIMy:SendKeyEvent(false, Enum.KeyCode.Two, false, game) end)
                        task.wait(0.4)
                        pcall(function() VIMy:SendKeyEvent(true, Enum.KeyCode.Two, false, game); task.wait(0.06); VIMy:SendKeyEvent(false, Enum.KeyCode.Two, false, game) end)
                end)
                if VX_NOTIFY then pcall(function() VX_NOTIFY("Yuta BF: 2 + 2", nil) end) end
        end
        local hookedY = setmetatable({}, { __mode = "k" })
        local function hookSelfY()
                local m = myModel(); local h = m and m:FindFirstChildOfClass("Humanoid"); local a = h and h:FindFirstChildOfClass("Animator")
                if not a or hookedY[a] then return end
                hookedY[a] = a.AnimationPlayed:Connect(function(track)
                        if not manualOn then return end
                        local id = track.Animation and tostring(track.Animation.AnimationId):match("%d+")
                        if id == YUTA_BF_ANIM then doubleTapTwo() end
                end)
        end
        task.spawn(function() while true do if manualOn then pcall(hookSelfY) end task.wait(0.6) end end)
        -- SECOND trigger (in case the anim never reaches your animator): YOU press 2 as Yuta -> the script
        -- adds the second 2 = the 'use again' black flash. Shared debounce with the anim path.
        local function charIsYuta()
                local c = myModel(); if not c then return false end
                local h = c:FindFirstChildOfClass("Humanoid")
                local hay = string.lower((c.Name or "") .. " " .. (h and h.DisplayName or ""))
                local mv = c:FindFirstChild("Moveset"); if mv then for _, m in ipairs(mv:GetChildren()) do hay = hay .. " " .. string.lower(m.Name) end end
                return (hay:find("yuta", 1, true) or hay:find("resolute", 1, true) or hay:find("severing", 1, true) or hay:find("true love", 1, true)) ~= nil
        end
        local UISy = game:GetService("UserInputService")
        UISy.InputBegan:Connect(function(input)
                if not manualOn or UISy:GetFocusedTextBox() then return end
                if input.KeyCode ~= Enum.KeyCode.Two then return end
                local injK = _G.VX_INJ_KEYS
                if injK and injK[Enum.KeyCode.Two] and tick() < injK[Enum.KeyCode.Two] then return end   -- our own re-press: don't loop
                if not charIsYuta() then return end
                if tick() - last < 1.4 then return end
                last = tick()
                task.delay(0.45, function()   -- your 2 fired the slash -> the script presses 2 AGAIN = the flash
                        _G.VX_INJECT_UNTIL = tick() + 0.5
                        _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Two] = tick() + 0.5
                        pcall(function() VIMy:SendKeyEvent(true, Enum.KeyCode.Two, false, game); task.wait(0.06); VIMy:SendKeyEvent(false, Enum.KeyCode.Two, false, game) end)
                        if VX_NOTIFY then pcall(function() VX_NOTIFY("Yuta BF: second 2", nil) end) end
                end)
        end)
        -- AUTO "Yuta Teleport Kill Black Flash": fully automatic - hunt the nearest LOW-HP enemy and finish them.
        local function nearestLowEnemy(maxD)
                local mh = getHRP(myModel()); if not mh then return nil end
                local best, bd = nil, maxD
                local function chk(m)
                        if not m or m == myModel() or m.Name == LP.Name then return end
                        local r = getHRP(m); if not r or not isLow(m) then return end
                        local d = (r.Position - mh.Position).Magnitude; if d < bd then bd = d; best = m end
                end
                for _, pl in ipairs(Players:GetPlayers()) do if pl ~= LP then chk(pl.Character) end end
                local chs = workspace:FindFirstChild("Characters"); if chs then for _, m in ipairs(chs:GetChildren()) do if m:IsA("Model") then chk(m) end end end
                return best
        end
        task.spawn(function()
                while true do
                        if autoOn then local t = nearestLowEnemy(45); if t then flash(t, true) end task.wait(0.25) else task.wait(0.3) end
                end
        end)
        YutaBFApi = {
                setManual = function(v) manualOn = v == true end,
                setAuto   = function(v) autoOn = v == true end,
        }
end

-- ============================================================
-- MODULE: MISC EXTRAS  (Walk Into Domains, Spam Dash Noises, Unlock Extra Emote Slot, Instant Respawn)
-- ============================================================
do
        local Players = game:GetService("Players")
        local RS = game:GetService("ReplicatedStorage")
        local LP = Players.LocalPlayer
        local function myModel() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end

        -- ---------- WALK INTO DOMAINS ----------
        -- Normally a domain's barrier/collider traps you (sure-hit dome). This drops CanCollide/CanTouch on the
        -- domain's barrier parts so you can walk straight in/out of any domain.
        local walkDomOn = false
        local function isBarrier(n) n = n:lower(); return n:find("collider") or n:find("barrier") or n:find("wall") or n:find("dome") or n:find("border") or n:find("shell") or n:find("sphere") end
        -- ═══ WHY THIS DID NOTHING ═══ It only ever looked inside workspace.Domains and only matched parts BY NAME.
        -- JJS does not reliably park a cast domain there - it can sit directly in workspace, under the caster's
        -- model, or in a per-domain folder - and the barrier part is often generically named ("Part", "Union").
        -- Now: find domain CONTAINERS by keyword anywhere in workspace, and inside one treat any part that is
        -- barrier-named OR simply huge (a sure-hit dome is enormous; nothing else in a domain is) as the barrier.
        local DOM_WORDS = { "domain", "expansion", "malevolent", "shrine", "unlimited", "void", "chimera", "selfembodiment", "coffin", "horizon" }
        local function looksLikeDomain(name)
                local n = string.lower(tostring(name)):gsub("[%s_%-]", "")
                for _, w in ipairs(DOM_WORDS) do if string.find(n, w, 1, true) then return true end end
                return false
        end
        local function openPart(d)
                if not d:IsA("BasePart") then return end
                local sz = d.Size
                local huge = (sz.X > 55 or sz.Y > 55 or sz.Z > 55)     -- a sure-hit dome; regular props are not this big
                if huge or isBarrier(d.Name) or isBarrier((d.Parent and d.Parent.Name) or "") then
                        pcall(function() d.CanCollide = false; d.CanTouch = false; d.CanQuery = false end)
                end
        end
        local function sweepDomains()
                local roots = {}
                local folder = workspace:FindFirstChild("Domains")
                if folder then roots[#roots + 1] = folder end
                for _, v in ipairs(workspace:GetChildren()) do
                        if v ~= folder and looksLikeDomain(v.Name) then roots[#roots + 1] = v end
                end
                for _, root in ipairs(roots) do
                        for _, d in ipairs(root:GetDescendants()) do openPart(d) end
                end
        end
        task.spawn(function()
                while true do
                        if walkDomOn then pcall(sweepDomains) end
                        task.wait(0.35)
                end
        end)
        -- LIVE: a domain cast AFTER you switched this on has to be opened on the frame it appears, not up to
        -- 0.35s later - by then the sure-hit has already closed around you. This catches it as it spawns.
        workspace.DescendantAdded:Connect(function(d)
                if not walkDomOn then return end
                if not d:IsA("BasePart") then return end
                task.defer(function()
                        if not walkDomOn or not d.Parent then return end
                        local a = d
                        for _ = 1, 6 do                              -- walk up a few levels looking for a domain container
                                if not a or a == workspace then return end
                                if looksLikeDomain(a.Name) then openPart(d); return end
                                a = a.Parent
                        end
                end)
        end)

        -- ---------- SPAM DASH NOISES ----------
        -- Rapidly fire the game's own dash remote alternating opposite directions (net movement ~0) = the dash
        -- swoosh spams without launching you across the map.
        local dashNoiseOn = false
        task.spawn(function()
                local flip = true
                while true do
                        if dashNoiseOn then
                                flip = not flip
                                pcall(function() fireKnit("MovementService", "Dash", flip and "Left" or "Right", false) end)
                                task.wait(0.14)
                        else task.wait(0.3) end
                end
        end)

        -- ---------- UNLOCK EXTRA EMOTE SLOT ----------
        -- Best-effort: ping the EmoteService for the extra slot (some builds gate a bonus slot behind a remote).
        local function emoteRE(name)
                local k = RS:FindFirstChild("Knit"); k = k and k:FindFirstChild("Knit"); k = k and k:FindFirstChild("Services")
                local s = k and k:FindFirstChild("EmoteService"); local re = s and s:FindFirstChild("RE"); return re and re:FindFirstChild(name)
        end
        local function unlockEmoteSlot()
                for _, nm in ipairs({ "Unlock", "UnlockSlot", "ExtraSlot", "Purchase" }) do
                        local re = emoteRE(nm); if re then pcall(function() re:FireServer() end) end
                end
                if VX_NOTIFY then VX_NOTIFY("Emote slot unlock sent", true) end
        end

        -- ---------- INSTANT RESPAWN ----------
        -- On death, immediately request a fresh character (skip the death screen wait) via the reset binding.
        local instaOn = false
        local function requestRespawn()
                -- LoadCharacter is server-controlled and normally cannot be called by a client.
                -- Request a normal character reset instead; the server controls when it respawns.
                local c=myModel() or LP.Character
                local h=c and c:FindFirstChildOfClass("Humanoid")
                if not c or not h then
                        _G.VX_RESPAWN_STATUS="no character to reset"
                        return false
                end
                local ok=pcall(function() h.Health=0 end)
                _G.VX_RESPAWN_STATUS=ok and "reset requested; server respawn unconfirmed" or "reset request failed"
                return ok
        end
        task.spawn(function()
                while true do
                        if instaOn then
                                local m = LP.Character or myModel()
                                local h = m and m:FindFirstChildOfClass("Humanoid")
                                if h and h.Health <= 0 then requestRespawn(); task.wait(1.2) end
                        end
                        task.wait(0.3)
                end
        end)

        WalkDomainApi = { set = function(v) walkDomOn = v == true end }
        DashNoiseApi  = { set = function(v) dashNoiseOn = v == true end }
        EmoteSlotApi  = { unlock = unlockEmoteSlot }
        InstaRespawnApi = { set = function(v) instaOn = v == true end, now = requestRespawn }   -- now() = respawn RIGHT NOW (the button)
end

-- ============================================================
-- MODULE: ARCADE FLIGHT GAME  (the AI actually WATCHES the screen and flaps for you)
-- "it must be the AI seeing it and playing for you" - so this reads the game's own GUI instead of flapping
-- on a blind timer. The minigame draws real GuiObjects (a bird, pipe bars); every frame we classify them by
-- how they MOVE, because names can be anything:
--     an object whose X stays put while its Y changes  ->  the BIRD (it only ever falls and hops)
--     a tall object whose X is sliding left            ->  a PIPE
-- Then it is Flappy logic: find the nearest pipe column ahead of the bird, aim for the centre of its gap
-- (no pipes visible -> hold mid-screen), and fire the captured flap remote whenever the bird sits below the
-- aim point. One remote, rate-limited, only while the screen exists:
--     PlayerGui.DeviceUI.UnreliableRemoteEvent:FireServer()
-- ============================================================
do
        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local LP = Players.LocalPlayer
        local on, fired = false, 0
        local minGap = 0.12          -- s between flaps: faster is spam the server ignores, slower falls too far
        local lastFlap = 0
        local track = {}             -- GuiObject -> {x=, y=, t=} from the previous sample (motion classification)
        local dumped = false

        -- ═══ FIND THE REAL SCREEN, WHEREVER IT IS ═══ DeviceUI holds the REMOTE, but the drawing can live
        -- elsewhere - the green screen in your screenshot is on the CABINET, which usually means a SurfaceGui
        -- (in PlayerGui with an Adornee, or on the part itself). Scan: DeviceUI first, then any PlayerGui gui
        -- with a crowd of small frames, then SurfaceGuis on parts near you. Cached; re-found each enable.
        local screenCache
        local function busyGui(root)
                local n = 0
                for _, g in ipairs(root:GetDescendants()) do
                        if g:IsA("GuiObject") and g.Visible then n = n + 1; if n >= 4 then return true end end
                end
                return false
        end
        local function deviceGui()
                if screenCache and screenCache.Parent then return screenCache end
                local pg = LP:FindFirstChild("PlayerGui"); if not pg then return nil end
                local d = pg:FindFirstChild("DeviceUI")
                if d and busyGui(d) then screenCache = d; return d end
                for _, g in ipairs(pg:GetChildren()) do
                        if (g:IsA("ScreenGui") or g:IsA("SurfaceGui")) and g ~= d and busyGui(g) then screenCache = g; return g end
                end
                -- SurfaceGui on the cabinet itself, near you
                local chs = workspace:FindFirstChild("Characters")
                local me = (chs and chs:FindFirstChild(LP.Name)) or LP.Character
                local hrp = me and me:FindFirstChild("HumanoidRootPart")
                if hrp then
                        for _, sg in ipairs(workspace:GetDescendants()) do
                                if sg:IsA("SurfaceGui") and sg.Enabled then
                                        local part = sg.Adornee or sg.Parent
                                        if part and part:IsA("BasePart") and (part.Position - hrp.Position).Magnitude < 40 and busyGui(sg) then
                                                screenCache = sg; return sg
                                        end
                                end
                        end
                end
                return d   -- fall back to DeviceUI even if quiet, so the warn path still reports something sane
        end
        -- ═══ FIND THE REMOTE WHEREVER IT ACTUALLY LIVES ═══ This used to look only at the DIRECT CHILDREN of the
        -- screen gui, so if the game parents the event one level deeper - or under a different gui, or in
        -- ReplicatedStorage - we reported "open the machine first" while the machine was open in front of you.
        -- That is "auto play flight dont work" with no flap ever sent. Now: the screen's whole subtree first
        -- (nearest to the game we are reading), then the rest of PlayerGui, then ReplicatedStorage.
        local remoteCache
        local function deviceRemote()
                if remoteCache and remoteCache.Parent then return remoteCache end
                local function pick(root)
                        if not root then return nil end
                        local fallback
                        for _, o in ipairs(root:GetDescendants()) do
                                if o:IsA("UnreliableRemoteEvent") then return o end
                                if o:IsA("RemoteEvent") and not fallback then fallback = o end
                        end
                        return fallback
                end
                local r = pick(deviceGui())
                if not r then
                        local pg = LP:FindFirstChild("PlayerGui")
                        if pg then
                                for _, g in ipairs(pg:GetChildren()) do
                                        local nm = string.lower(g.Name)
                                        if string.find(nm, "device", 1, true) or string.find(nm, "arcade", 1, true) or string.find(nm, "game", 1, true) then
                                                r = pick(g); if r then break end
                                        end
                                end
                                if not r then r = pick(pg) end
                        end
                end
                if not r then
                        local rs = game:GetService("ReplicatedStorage")
                        for _, o in ipairs(rs:GetChildren()) do
                                if o:IsA("UnreliableRemoteEvent") then r = o break end
                        end
                end
                remoteCache = r
                return r
        end
        local function flap()
                if tick() - lastFlap < minGap then return end
                local re = deviceRemote(); if not re then return end
                lastFlap = tick()
                fired = fired + 1
                -- BOTH captured forms. Your spy shows the game firing this remote with 0 AND with no argument at
                -- all - so the flap is probably one of them and the other is a different signal (start / score).
                -- Sending both costs nothing and guarantees whichever one is the flap actually goes out.
                pcall(function() re:FireServer(0) end)
                pcall(function() re:FireServer() end)
        end

        -- One frame of WATCHING: sample every visible GuiObject in DeviceUI, compare against the last sample,
        -- and sort movers into the bird and the pipes. Returns birdY, aimY and the container height.
        local function readScreen()
                local d = deviceGui(); if not d then return nil end
                local bird, birdY, birdX
                local pipes = {}          -- { x=, topFree=, bottomFree= } per column is overkill; store objects
                local H, W
                for _, g in ipairs(d:GetDescendants()) do
                        if g:IsA("GuiObject") and g.Visible and g.AbsoluteSize.X > 1 and g.AbsoluteSize.Y > 1 then
                                local pos = g.AbsolutePosition
                                local prev = track[g]
                                track[g] = { x = pos.X, y = pos.Y, t = tick() }
                                -- the play AREA is the biggest thing on the device
                                if not H or (g.AbsoluteSize.X * g.AbsoluteSize.Y) > (H * W) then
                                        -- (only used for proportions; exact parent does not matter)
                                        W, H = g.AbsoluteSize.X, g.AbsoluteSize.Y
                                end
                                if prev and tick() - prev.t < 0.4 then
                                        local dx, dy = pos.X - prev.x, pos.Y - prev.y
                                        if math.abs(dx) < 2 and math.abs(dy) >= 1 and g.AbsoluteSize.Y < 80 and g.AbsoluteSize.X < 80 then
                                                -- X pinned, Y moving, small: the bird
                                                if not bird or g.AbsoluteSize.X * g.AbsoluteSize.Y < bird.AbsoluteSize.X * bird.AbsoluteSize.Y then
                                                        bird = g; birdY = pos.Y + g.AbsoluteSize.Y / 2; birdX = pos.X
                                                end
                                        elseif dx < -1 and g.AbsoluteSize.Y > 30 then
                                                -- sliding left and tall: a pipe bar
                                                pipes[#pipes + 1] = g
                                        end
                                end
                        end
                end
                if not bird then return nil end
                -- Aim: the gap of the nearest pipe column that is still AHEAD of the bird. A column is one or two
                -- bars sharing an X; the gap is the vertical space they leave open.
                local aimY
                local bestX
                local colTop, colBot   -- free-space bounds of the chosen column
                for _, pgui in ipairs(pipes) do
                        local px = pgui.AbsolutePosition.X
                        if px + pgui.AbsoluteSize.X >= birdX then                    -- not already behind us
                                if not bestX or px < bestX - 6 then
                                        bestX = px
                                        colTop, colBot = nil, nil
                                end
                                if math.abs(px - (bestX or px)) <= 6 then
                                        local topEdge = pgui.AbsolutePosition.Y
                                        local botEdge = topEdge + pgui.AbsoluteSize.Y
                                        -- a bar hanging from the top ends where the gap starts; a bar rising from the bottom
                                        -- starts where the gap ends
                                        if topEdge <= (bird.Parent and bird.Parent.AbsolutePosition.Y or topEdge) + 4 then
                                                colTop = math.max(colTop or 0, botEdge)          -- gap begins under this bar
                                        else
                                                colBot = math.min(colBot or math.huge, topEdge)  -- gap ends above this bar
                                        end
                                end
                        end
                end
                if bestX then
                        local ph = H or 300
                        local top = colTop or ((bird.Parent and bird.Parent.AbsolutePosition.Y) or 0)
                        local bot = colBot or (top + ph)
                        aimY = (top + bot) / 2
                end
                if not aimY then
                        -- no pipes readable yet: hold just above the middle, where the gaps always are
                        local base = (bird.Parent and bird.Parent.AbsolutePosition.Y) or 0
                        aimY = base + (H or 300) * 0.45
                end
                if _G.VX_FLIGHT_DEBUG and not dumped then
                        dumped = true
                        print("[DreamHub Flight] bird=" .. bird:GetFullName() .. "  pipes seen=" .. #pipes)
                end
                return birdY, aimY
        end

        task.spawn(function()
                while true do
                        if on then
                                local re = deviceRemote()
                                if not re then
                                        if tick() - (_G.VX_FLIGHT_WARN or 0) > 6 then
                                                _G.VX_FLIGHT_WARN = tick()
                                                print("[DreamHub Flight] DeviceUI.UnreliableRemoteEvent not found - open the game first (press E at the cabinet)")
                                                if VX_NOTIFY then VX_NOTIFY("Flight game: open the machine first (press E)", false) end
                                        end
                                        task.wait(0.5)
                                else
                                        local birdY, aimY = readScreen()
                                        if birdY and aimY then
                                                -- BELOW the aim point (screen Y grows downward) -> flap. A little hysteresis so it
                                                -- does not machine-gun at the boundary; gravity handles being too high on its own.
                                                if birdY > aimY + 4 then flap() end
                                                if fired == 1 and VX_NOTIFY then VX_NOTIFY("Flight game: I can see it - playing", true) end
                                        else
                                                -- Screen exists but nothing readable is MOVING yet. Two cases, and they need
                                                -- different answers: the run has not STARTED (one nudge starts it), or it is running
                                                -- and our reader cannot see it. One flap a second loses the second case immediately,
                                                -- so fall back to a steady flappy cadence instead - blind, but alive.
                                                if fired < 2 then
                                                        if tick() - lastFlap > 0.8 then flap() end
                                                else
                                                        flap()          -- flap() enforces minGap itself
                                                end
                                        end
                                        task.wait(0.03)     -- ~33 samples/s: enough to track the bird between frames
                                end
                        else
                                table.clear(track)
                                screenCache = nil          -- re-find the screen next enable; a new cabinet is a new gui
                                remoteCache = nil
                                task.wait(0.5)
                        end
                end
        end)
        FlightGameApi = {
                set     = function(v) on = v == true
                        if on then
                                -- Report what the eyes actually found, immediately - "auto play dont work" with nothing on
                                -- screen has cost three rounds already.
                                task.spawn(function()
                                        task.wait(0.5)
                                        local scr = deviceGui()
                                        local re = deviceRemote()
                                        local msg = "Flight: screen=" .. (scr and scr.Name or "NOT FOUND") .. " remote=" .. (re and "ok" or "MISSING")
                                        print("[DreamHub Flight] " .. msg .. (scr and ("  (" .. scr:GetFullName() .. ")") or ""))
                                        if VX_NOTIFY then VX_NOTIFY(msg, re ~= nil) end
                                end)
                        end end,
                setRate = function(v) minGap = math.clamp(tonumber(v) or minGap, 0.05, 1.2) end,   -- now the MINIMUM gap between flaps
                flap    = flap,
                count   = function() return fired end,
        }
end

-- ============================================================
-- MODULE: AUTO THROWABLE  (walk up to a trash can / grave / arcade prop and it picks it up)
-- Remote is the capture verbatim:
--   MovementService.RE.Throwable:FireServer(workspace.Map.Destructible.Throwable.Trash)
-- The argument is the PROP INSTANCE, so this works on every throwable the map has, not just Trash -
-- we hand it whichever one you are standing next to.
-- ============================================================
do
        local Players = game:GetService("Players")
        local RS = game:GetService("ReplicatedStorage")
        local LP = Players.LocalPlayer
        local on, range, lastGrab = false, 14, 0
        local function myModel() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
        local function myHRP() local m = myModel(); return m and m:FindFirstChild("HumanoidRootPart") end
        local function throwRemote()
                local k = RS:FindFirstChild("Knit"); k = k and k:FindFirstChild("Knit"); k = k and k:FindFirstChild("Services")
                local s = k and k:FindFirstChild("MovementService"); local r = s and s:FindFirstChild("RE")
                return r and r:FindFirstChild("Throwable")
        end
        -- The folder from the capture, plus a fallback sweep for maps that lay it out differently.
        local function throwFolder()
                local m = workspace:FindFirstChild("Map")
                local d = m and m:FindFirstChild("Destructible")
                return d and d:FindFirstChild("Throwable")
        end
        local function partOf(o)
                if o:IsA("BasePart") then return o end
                if o:IsA("Model") then return o.PrimaryPart or o:FindFirstChildWhichIsA("BasePart") end
                return nil
        end
        -- Nearest throwable within range. Everything in the Throwable folder counts - trash cans, graves,
        -- arcade props - because the remote takes the instance and does not care what it is.
        local function nearestThrowable()
                local hrp = myHRP(); if not hrp then return nil end
                local f = throwFolder(); if not f then return nil end
                local best, bd
                for _, o in ipairs(f:GetChildren()) do
                        local pt = partOf(o)
                        if pt then
                                local d = (pt.Position - hrp.Position).Magnitude
                                if d <= range and (not bd or d < bd) then best, bd = o, d end
                        end
                end
                return best
        end
        local function grab(o)
                local re = throwRemote()
                if not re then
                        if tick() - (_G.VX_THROW_WARN or 0) > 8 then
                                _G.VX_THROW_WARN = tick()
                                print("[DreamHub Throwable] MovementService.RE.Throwable not found (send me this)")
                                if VX_NOTIFY then VX_NOTIFY("Auto Throwable: remote not found", false) end
                        end
                        return false
                end
                local ok = pcall(function() re:FireServer(o) end)
                if ok and _G.VX_THROW_DEBUG then print("[DreamHub Throwable] picked up " .. o.Name) end
                return ok
        end
        task.spawn(function()
                while true do
                        if on then
                                if tick() - lastGrab > 1.0 then
                                        local o = nearestThrowable()
                                        if o then lastGrab = tick(); pcall(grab, o) end
                                end
                                task.wait(0.2)
                        else
                                task.wait(0.5)
                        end
                end
        end)
        ThrowableApi = {
                set      = function(v) on = v == true end,
                setRange = function(v) range = math.clamp(tonumber(v) or range, 4, 60) end,
                grabNow  = function() local o = nearestThrowable(); if o then return grab(o) end
                        if VX_NOTIFY then VX_NOTIFY("Nothing throwable within " .. range .. " studs", false) end return false end,
        }
end

-- ============================================================
-- MODULE: SOUL COMBO ASSIST -- preserve 1, aim up after launch, bounded 3 follow-up.
do
    local LP=game:GetService("Players").LocalPlayer
    local UIS=game:GetService("UserInputService")
    local VIM=game:GetService("VirtualInputManager")
    local RS=game:GetService("RunService")
    local on,generation,running=false,0,false
    local followDelay=0
    local last=-math.huge
    local function start(manual)
        if running or not on and not manual or UIS:GetFocusedTextBox() then return end
        local character=vxMyChar(); local camera=workspace.CurrentCamera
        local hum=character and character:FindFirstChildOfClass("Humanoid")
        if not camera or not hum or hum.Health<=0 then return end
        local gen=generation; running=true
        local target=_G.VX_LOCK and _G.VX_LOCK.get and _G.VX_LOCK.get()
        local ownRoot=character:FindFirstChild("HumanoidRootPart")
        if not target and ownRoot then
            local gap=30
            for _,candidate in ipairs(_G.VX_LIVING_MODELS()) do
                local r=candidate:FindFirstChild("HumanoidRootPart")
                if candidate~=character and r and (r.Position-ownRoot.Position).Magnitude<gap then target=candidate; gap=(r.Position-ownRoot.Position).Magnitude end
            end
        end
        local targetHum=target and target:FindFirstChildOfClass("Humanoid")
        local targetRoot=target and target:FindFirstChild("HumanoidRootPart")
        local baseY=targetRoot and targetRoot.Position.Y
        local function live() return gen==generation and vxMyChar()==character and hum.Health>0 and not UIS:GetFocusedTextBox() end
        task.spawn(function()
            local owner,rotation,bound
            local ok,err=pcall(function()
                local deadline=tick()+0.8
                while _G.VX_COMBAT_OWNER and live() and tick()<deadline do task.wait() end
                if not live() or _G.VX_COMBAT_OWNER then _G.VX_SOUL_STATUS="another sequence still owns input"; return end
                owner={}; _G.VX_COMBAT_OWNER=owner; rotation=camera.CFrame.Rotation
                local look=camera.CFrame.LookVector
                local flat=Vector3.new(look.X,0,look.Z)
                if flat.Magnitude<0.01 then flat=Vector3.new(0,0,-1) end
                local direction=flat.Unit*0.5+Vector3.new(0,0.8660254,0)
                local function aim()
                    if live() and workspace.CurrentCamera==camera then camera.CFrame=CFrame.lookAt(camera.CFrame.Position,camera.CFrame.Position+direction) end
                end
                local function tap(key)
                    if not live() or _G.VX_KEY_BLOCKED and _G.VX_KEY_BLOCKED(key) then return false end
                    _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[key]=tick()+0.3
                    VIM:SendKeyEvent(false,key,false,game); RS.RenderStepped:Wait()
                    if not live() then return false end
                    VIM:SendKeyEvent(true,key,false,game); task.wait(0.10)
                    VIM:SendKeyEvent(false,key,false,game); return true
                end
                if manual and not tap(Enum.KeyCode.One) then return end
                local deadline=tick()+1.8; local airborne=false
                repeat
                    if not live() or not targetHum or not targetRoot or not targetRoot.Parent or targetHum.Health<=0 then return end
                    airborne=targetHum.FloorMaterial==Enum.Material.Air or targetRoot.Position.Y-baseY>1.5
                    if airborne then break end
                    task.wait()
                until tick()>=deadline
                if not airborne then _G.VX_SOUL_STATUS="target launch not observed"; return end
                RS:BindToRenderStep("VX_SoulAim",Enum.RenderPriority.Camera.Value+60,aim); bound=true
                aim()
                RS.RenderStepped:Wait()
                local sendAt=tick()+followDelay
                while live() and tick()<sendAt do task.wait() end
                if not live() then return end
                local name=_G.VX_SLOT_MOVE and _G.VX_SLOT_MOVE[3]
                local moves=character:FindFirstChild("Moveset"); local move=moves and name and moves:FindFirstChild(name)
                local remote=name and _G.VX_MOVE_RE and _G.VX_MOVE_RE[name]
                for _=1,6 do
                    if not live() or not target.Parent or targetHum.Health<=0
                        or _G.VX_KEY_BLOCKED and _G.VX_KEY_BLOCKED(Enum.KeyCode.Three) then return end
                    aim()
                    if move and remote and remote.Parent then
                        remote:FireServer(move); task.wait(0.12)
                        _G.VX_SOUL_STATUS="captured slot 3 burst after launch"
                    elseif tap(Enum.KeyCode.Three) then
                        _G.VX_SOUL_STATUS="3 burst after launch and upward aim"
                        task.wait(0.02)
                    else return end
                end
                task.wait(0.08)
            end)
            if bound then pcall(function() RS:UnbindFromRenderStep("VX_SoulAim") end) end
            pcall(function() VIM:SendKeyEvent(false,Enum.KeyCode.Three,false,game) end)
            if manual then pcall(function() VIM:SendKeyEvent(false,Enum.KeyCode.One,false,game) end) end
            if rotation and workspace.CurrentCamera==camera then camera.CFrame=CFrame.new(camera.CFrame.Position)*rotation end
            if owner and _G.VX_COMBAT_OWNER==owner then _G.VX_COMBAT_OWNER=nil end
            running=false
            if not ok then warn("[DreamHub Soul] "..tostring(err)) end
        end)
    end
    local function key(k)
        if k~=Enum.KeyCode.One or not on or UIS:GetFocusedTextBox() then return end
        if _G.VX_KEY_BLOCKED and _G.VX_KEY_BLOCKED(k) then return end
        if tick()<((_G.VX_INJ_KEYS or {})[k] or 0) or tick()-last<0.15 then return end
        last=tick(); start(false)
    end
    pcall(function() game:GetService("ContextActionService"):BindActionAtPriority("VX_SoulCombo",function(_,state,input)
        if state==Enum.UserInputState.Begin then key(input.KeyCode) end
        return Enum.ContextActionResult.Pass
    end,false,4300,Enum.KeyCode.One) end)
    UIS.InputBegan:Connect(function(input) key(input.KeyCode) end)
    if _G.VX_ON_KEY then _G.VX_ON_KEY("soulcombo",key) end
    LP.CharacterAdded:Connect(function() generation+=1 end)
    SoulComboApi={set=function(v) on=v==true; generation+=1 end,now=function() start(true) end,
        setDelay=function(v) followDelay=math.clamp(tonumber(v) or 0,0,0.6) end}
end

-- MODULE: DOMAIN SAVIOR  (auto-save a chosen player from a domain)
-- "select a username; when it detects the target is about to go in a domain, use the grab move."
-- The savers and their grabs, straight from the three movesets in the screenshots:
--     Megumi ("Insanity")             ->  move 3, Toad          (TARGET tag: it grabs and pulls)
--     Gojo   ("Six Eyes")             ->  move 1, Lapse Blue    (pull)
--     Mahito ("Essence of the Soul")  ->  move 2, Body Disfigure
-- (The "must have the R special" note is the awakened form those movesets belong to - if the move is not
-- in your Moveset, the cast resolver simply refuses and reports, so the wrong form cannot misfire.)
-- Detection: a domain CONTAINER appearing in the world (same keyword net Walk Into Domains uses, on the
-- instant DescendantAdded event) with your chosen player inside its reach. The moment both are true, the
-- grab is cast AT their character - the same Activated(move, targetChar) shape as the Shutter Doors capture.
-- ============================================================
do
        local Players = game:GetService("Players")
        local LP = Players.LocalPlayer
        local on, savedName = false, ""
        local lastSave = 0
        local GRABS = { { "Toad" }, { "Lapse Blue" }, { "Body Disfigure" } }   -- tried in order; first one you own fires
        local function myModel() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
        local function norm(x) return (string.gsub(string.lower(tostring(x or "")), "[^%a%d]", "")) end
        local function myGrab()
                for _, c in ipairs({ myModel(), LP.Character }) do
                        local mv = c and c:FindFirstChild("Moveset")
                        if mv then
                                for _, g in ipairs(GRABS) do
                                        for _, m in ipairs(mv:GetChildren()) do
                                                if norm(m.Name) == norm(g[1]) then return g[1] end
                                        end
                                end
                        end
                end
                return nil
        end
        local function targetChar()
                -- ═══ THE LOCKED TARGET IS THE SAVE TARGET ═══ "make sure it grabs the target out of the domain."
                -- If you locked someone (click lock / the Lock Target toggle), the savior saves THEM - no name
                -- typing needed. The dropdown name still wins when you set one.
                do
                        local g = _G.VX_LOCK; local lt = (g and g.get) and g.get() or nil
                        local lh = lt and lt.Parent and lt:FindFirstChildOfClass("Humanoid")
                        if lt and lt.Parent and lh and lh.Health > 0 and lt ~= myModel() then return lt end
                end
                if savedName == "" then return nil end
                local want = norm(savedName)
                local chs = workspace:FindFirstChild("Characters")
                if chs then for _, m in ipairs(chs:GetChildren()) do
                        if norm(m.Name):find(want, 1, true) then return m end
                end end
                for _, plr in ipairs(Players:GetPlayers()) do
                        if norm(plr.Name):find(want, 1, true) or norm(plr.DisplayName):find(want, 1, true) then
                                local c = plr.Character
                                local w = chs and c and chs:FindFirstChild(c.Name)
                                return w or c
                        end
                end
                return nil
        end
        local DOM_WORDS = { "domain", "expansion", "malevolent", "shrine", "unlimited", "void", "chimera", "selfembodiment", "coffin", "horizon" }
        local function looksDomain(n)
                n = norm(n)
                for _, w in ipairs(DOM_WORDS) do if n:find(w, 1, true) then return true end end
                return false
        end
        local function trySave(domPart)
                if not on or tick() - lastSave < 4 then return end
                local t = targetChar()
                        -- no name set and no lock: save whoever the domain is about to swallow (nearest to me)
                        or (function()
                                local me = myModel(); local mr = me and me:FindFirstChild("HumanoidRootPart")
                                local center = domPart:IsA("BasePart") and domPart.Position
                                        or (domPart:IsA("Model") and domPart:GetPivot().Position) or nil
                                if not (mr and center) then return nil end
                                local best, bd
                                local function chk(m)
                                        if m and m ~= me and m.Name ~= LP.Name and m:IsA("Model") then
                                                local r = m:FindFirstChild("HumanoidRootPart"); local h = m:FindFirstChildOfClass("Humanoid")
                                                if r and h and h.Health > 0 then
                                                        local dc = (r.Position - center).Magnitude
                                                        if dc <= 80 then local dm = (r.Position - mr.Position).Magnitude; if not bd or dm < bd then best, bd = m, dm end end
                                                end
                                        end
                                end
                                local chs = workspace:FindFirstChild("Characters")
                                if chs then for _, m in ipairs(chs:GetChildren()) do chk(m) end end
                                for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP then chk(plr.Character) end end
                                return best
                        end)()
                if not t then return end
                local r = t:FindFirstChild("HumanoidRootPart"); if not r then return end
                if t == myModel() then return end                 -- saving yourself is Anti-Domain's job, not a grab
                local center = domPart:IsA("BasePart") and domPart.Position
                        or (domPart:IsA("Model") and domPart:GetPivot().Position) or nil
                if not center then return end
                -- inside or about to be swallowed: domes in this game reach ~60 studs; act on anyone that close
                if (r.Position - center).Magnitude > 80 then return end
                local grab = myGrab()
                if not grab then
                        if tick() - (_G.VX_DS_WARN or 0) > 8 then
                                _G.VX_DS_WARN = tick()
                                if VX_NOTIFY then VX_NOTIFY("Domain Savior: you have no grab move (need Toad / Lapse Blue / Body Disfigure)", false) end
                        end
                        return
                end
                lastSave = tick()
                -- ═══ IT CLICKS THE MOVE FOR YOU ═══ Not a bare remote-and-hope: TARGET moves go through the game's
                -- own aim-and-press flow, so the savior performs exactly what a player would do - turn your body AND
                -- camera onto them, then PRESS the move's real key (read from whichever slot your Moveset actually
                -- has the grab in, not hardcoded). The remote with the target attached still goes out right behind
                -- the press as the backup, so whichever mechanism this game honours, the grab happens.
                task.spawn(function()
                        -- 1) aim: the game's targeted moves grab whoever you are looking at
                        pcall(function()
                                local me = myModel(); local hrp = me and me:FindFirstChild("HumanoidRootPart")
                                if hrp then hrp.CFrame = CFrame.lookAt(hrp.Position, Vector3.new(r.Position.X, hrp.Position.Y, r.Position.Z)) end
                                local cam = workspace.CurrentCamera
                                if cam then cam.CFrame = CFrame.lookAt(cam.CFrame.Position, r.Position) end
                        end)
                        -- 2) the KEY, from the slot the grab actually sits in
                        local slotKey
                        for _, c in ipairs({ myModel(), LP.Character }) do
                                local mv = c and c:FindFirstChild("Moveset")
                                if mv then
                                        local KEYS = { Enum.KeyCode.One, Enum.KeyCode.Two, Enum.KeyCode.Three, Enum.KeyCode.Four }
                                        for idx, m in ipairs(mv:GetChildren()) do
                                                if norm(m.Name) == norm(grab) and KEYS[idx] then slotKey = KEYS[idx] break end
                                        end
                                end
                                if slotKey then break end
                        end
                        if slotKey then
                                _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[slotKey] = tick() + 0.5
                                _G.VX_INJECT_UNTIL = tick() + 0.5
                                pcall(function()
                                        local VIM = game:GetService("VirtualInputManager")
                                        VIM:SendKeyEvent(true, slotKey, false, game); task.wait(0.06); VIM:SendKeyEvent(false, slotKey, false, game)
                                end)
                        end
                        -- 3) the remote with the target attached, right behind the press
                        task.wait(0.05)
                        local ok = _G.VX_CAST_MOVE and _G.VX_CAST_MOVE(grab, t) or false
                        print("[DreamHub Savior] domain '" .. domPart.Name .. "' near " .. t.Name .. " -> pressed "
                                .. tostring(slotKey and slotKey.Name or "?") .. " + " .. grab .. " remote " .. (ok and "sent" or "MISSING (send me this)"))
                        if VX_NOTIFY then VX_NOTIFY("Saving " .. t.Name .. " with " .. grab, true) end
                        -- ═══ VERIFY, THEN RE-GRAB ONCE ═══ "make it more better and accurate and make sure grab
                        -- the target out of the domain." One aim-and-press can be eaten by a cooldown or a
                        -- turned camera - if they are STILL inside the dome half a second later, aim, press and
                        -- fire the remote one more time (once; the 4s lastSave gate keeps it from spamming).
                        task.delay(0.55, function()
                                if not on then return end
                                local tr2 = t.Parent and t:FindFirstChild("HumanoidRootPart")
                                local center2 = domPart.Parent and (domPart:IsA("BasePart") and domPart.Position
                                        or (domPart:IsA("Model") and domPart:GetPivot().Position)) or nil
                                if tr2 and center2 and (tr2.Position - center2).Magnitude <= 70 then
                                        pcall(function()
                                                local me2 = myModel(); local hrp2 = me2 and me2:FindFirstChild("HumanoidRootPart")
                                                if hrp2 then hrp2.CFrame = CFrame.lookAt(hrp2.Position, Vector3.new(tr2.Position.X, hrp2.Position.Y, tr2.Position.Z)) end
                                                local cam2 = workspace.CurrentCamera
                                                if cam2 then cam2.CFrame = CFrame.lookAt(cam2.CFrame.Position, tr2.Position) end
                                        end)
                                        if slotKey then _G.VX_INJ_KEYS[slotKey] = tick() + 0.5 end
                                        pcall(function()
                                                local VIM = game:GetService("VirtualInputManager")
                                                if slotKey then VIM:SendKeyEvent(true, slotKey, false, game); task.wait(0.06); VIM:SendKeyEvent(false, slotKey, false, game) end
                                        end)
                                        task.wait(0.05)
                                        pcall(function() if _G.VX_CAST_MOVE then _G.VX_CAST_MOVE(grab, t) end end)
                                        print("[DreamHub Savior] re-grab on " .. t.Name .. " (still inside the domain)")
                                end
                        end)
                end)
        end
        workspace.DescendantAdded:Connect(function(d)
                if not on then return end
                if not (d:IsA("BasePart") or d:IsA("Model")) then return end
                task.defer(function()
                        if not d.Parent then return end
                        local a = d
                        for _ = 1, 5 do
                                if not a or a == workspace then break end
                                if looksDomain(a.Name) then trySave(d) return end
                                a = a.Parent
                        end
                        if looksDomain(d.Name) then trySave(d) end
                end)
        end)
        -- ═══ "MAKE SURE IT GRABS THEM BEFORE THEY USE THE DOMAIN - IT NEEDS TO BE QUICKER" ═══
        -- DescendantAdded was already instant, but it fires when the domain SHELL spawns, and by then the domain
        -- is up. There is an earlier signal: the caster has to play the domain animation first. Hooking each
        -- nearby enemy's Animator and reacting to a track that NAMES a domain moves the save to the start of the
        -- cast instead of the end of it, which is the whole difference between saving them and being late.
        local domHooked = setmetatable({}, { __mode = "k" })
        local function hookCaster(m)
                local h = m and m:FindFirstChildOfClass("Humanoid"); if not h then return end
                local a = h:FindFirstChildOfClass("Animator"); if not a or domHooked[a] then return end
                domHooked[a] = true
                pcall(function()
                        a.AnimationPlayed:Connect(function(tr)
                                if not on then return end
                                local okn, nm = pcall(function() return tostring(tr.Animation.Name) end)
                                if okn and nm and looksDomain(nm) then trySave(m) end
                        end)
                end)
        end
        -- backstop: a domain that already exists when you toggle on, or one the event missed
        task.spawn(function()
                while true do
                        if on then
                                for _, v in ipairs(workspace:GetChildren()) do
                                        if looksDomain(v.Name) then trySave(v) end
                                end
                                local chs = workspace:FindFirstChild("Characters")
                                if chs then for _, m in ipairs(chs:GetChildren()) do pcall(function() hookCaster(m) end) end end
                                for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP and plr.Character then pcall(function() hookCaster(plr.Character) end) end end
                                task.wait(0.1)   -- 0.4 -> 0.1: this is pure notice latency on everything the events miss
                        else
                                task.wait(0.8)
                        end
                end
        end)
        DomainSaviorApi = {
                set     = function(v) on = v == true end,
                setName = function(v) savedName = tostring(v or "") end,
        }
end

-- ============================================================
-- MODULE: FINISHER ASSIST -- three observed swings, approach, one fourth hit.
do
    local Players = game:GetService("Players")
    local LP = Players.LocalPlayer
    local VIM = game:GetService("VirtualInputManager")
    local upOn, downOn, running = false, false, false
    local generation, nearDist, farDist = 0, 8, 40
    local assistSpeed=1
    local autoUp,autoDown,abilityPending=false,false,false
    local nextUpper = true
    local done = setmetatable({}, {__mode="k"})
    local attempted=setmetatable({}, {__mode="k"})
    local function rig()
        local folder = workspace:FindFirstChild("Characters")
        return (folder and folder:FindFirstChild(LP.Name)) or LP.Character
    end
    local function down(t)
        local h = t and t:FindFirstChildOfClass("Humanoid")
        if not h or h.Health <= 0 then return false end
        local state = h:GetState()
        local ragdolled = h.PlatformStand or state == Enum.HumanoidStateType.FallingDown or state == Enum.HumanoidStateType.Physics or state == Enum.HumanoidStateType.Ragdoll
            or h:GetAttribute("Ragdoll") == true or h:GetAttribute("Ragdolled") == true
        if ragdolled then return true end
        for _,object in ipairs({t,h,t:FindFirstChild("Info")}) do
            for _,name in ipairs({"Ragdoll","Ragdolled","Downed","Stunned","Stun"}) do
                local value=object:FindFirstChild(name)
                local attr=object:GetAttribute(name)
                if attr==true or type(attr)=="number" and attr>0 or value and (not value:IsA("BoolValue") or value.Value==true) then return true end
            end
        end
        local constraints=t:FindFirstChild("RagdollConstraints")
        if constraints then
            for _,joint in ipairs(constraints:GetDescendants()) do
                if joint:IsA("BallSocketConstraint") and joint.Enabled then return true end
            end
        end
        return false
    end
    local function distance(t)
        local c = rig(); local r = c and c:FindFirstChild("HumanoidRootPart")
        local e = t and t.Parent and t:FindFirstChild("HumanoidRootPart")
        return r and e and (r.Position-e.Position).Magnitude or math.huge
    end
    local function face(t)
        local c = rig(); local r = c and c:FindFirstChild("HumanoidRootPart")
        local e = t and t:FindFirstChild("HumanoidRootPart")
        if r and e then r.CFrame = CFrame.lookAt(r.Position,Vector3.new(e.Position.X,r.Position.Y,e.Position.Z)) end
    end
    -- ═══ r14: MOVEMENT-AWARE M1 CADENCE ═══ "make the assist's M1s faster; when I'm backing away even
    -- faster; walking towards them, slower; and moving at all should never slow it down." The old cadence
    -- waited a FIXED 0.38s after each OBSERVED swing - and the observation itself arrives late while you
    -- move (the walk anim blends the swing in), so any movement stretched the real cadence out to ~0.55s.
    -- The gap is now measured from the PREVIOUS PRESS (observation latency can no longer stack onto it)
    -- and scaled by how you are moving relative to the target: backing away = 0.6x (they are escaping,
    -- chain the combo fast), walking in = 1.5x (your own lunge is closing the gap), strafing or standing
    -- = the base beat - which is itself faster than the old fixed one. Movement NEVER adds delay anymore.
    local function swingGap(tgt)
        -- ═══ r15: A DOWNED TARGET GETS THE FASTEST BEAT ═══ "focus on their speed once the target is down."
        -- The downed window is short - they get up and the punish window closes - so while they are on the
        -- floor the cadence drops to the fastest safe rate regardless of your movement, and the pre-finisher
        -- waits shrink to near-nothing (see run()). A standing target keeps the movement-aware beats.
        if tgt and down(tgt) then return math.max(0.10,0.16/(assistSpeed or 1)) end
        local base=math.max(0.13,0.30/(assistSpeed or 1))
        local c=rig(); local r=c and c:FindFirstChild("HumanoidRootPart")
        local e=tgt and tgt.Parent and tgt:FindFirstChild("HumanoidRootPart")
        if not (r and e) then return base end
        local ok,v=pcall(function() return r.AssemblyLinearVelocity end)
        if not ok or not v then return base end
        local vel=Vector3.new(v.X,0,v.Z)
        if vel.Magnitude<3 then return base end                 -- standing still: the base beat
        local to=Vector3.new(e.Position.X-r.Position.X,0,e.Position.Z-r.Position.Z)
        if to.Magnitude<0.1 then return base end
        local approach=vel:Dot(to.Unit)
        if approach<-1 then return math.max(0.10,base*0.6) end  -- BACKING AWAY: even faster
        if approach>1 then return base*1.5 end                  -- WALKING IN: ease off, the lunge closes
        return base                                              -- any other movement: base, never slower
    end
    -- A time budget alone cannot prove that the game accepted three attacks.
    local function swings(n,live,onLast,which,tgt)
        if n<1 then return true end
        local c=rig(); local h=c and c:FindFirstChildOfClass("Humanoid")
        local a=h and h:FindFirstChildOfClass("Animator")
        if not a then return false end
        local remote=_G.VX_BASIC_RE and _G.VX_BASIC_RE()
        local vp=workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize
        local x,y=vp and vp.X/2 or 400,vp and vp.Y/2 or 300
        local count,inputAt,last=0,nil,-math.huge
        local awaiting=false
        local seen=setmetatable({}, {__mode="k"})
        local function release() pcall(function() VIM:SendMouseButtonEvent(x,y,0,false,game,0) end) end
        local connection=a.AnimationPlayed:Connect(function(track)
            if not awaiting or not live() or count>=n or seen[track] and tick()-seen[track]<0.15 then return end
            local id=tostring(track.Animation and track.Animation.AnimationId or ""):match("%d+")
            local known=id and _G.VX_M1_IDS and _G.VX_M1_IDS[id]
            local ability=id and ((_G.VX_ADAPT_IDS and _G.VX_ADAPT_IDS[id]) or (_G.VX_ANIMDICT and _G.VX_ANIMDICT[id]))
            local correlated=not ability and not track.Looped and tostring(track.Priority):find("Action",1,true)
                and inputAt and tick()-inputAt<0.5
            if (known or correlated) and tick()-last>0.15 then
                count+=1; seen[track]=tick(); last=tick(); awaiting=false
                if count==n then if onLast then onLast() end; release() end
            end
        end)
        local prior={_G.VX_SYNTH_CLICK,_G.VX_COMBAT_SEQUENCE,_G.VX_COMBAT_SUPPRESS_BF}
        local deadline=tick()+math.max(3,n*1.0)
        local ok,err=pcall(function()
            _G.VX_SYNTH_CLICK=deadline; _G.VX_COMBAT_SEQUENCE=deadline; _G.VX_COMBAT_SUPPRESS_BF=deadline
            release()
            local lastPress=nil
            for step=1,n do
                if not live() then return end
                -- r14: cadence measured from the previous PRESS, velocity-aware (see swingGap) - a moving
                -- player's late swing observation used to stack a hidden 0.15s+ onto every beat.
                if lastPress then while tick()-lastPress<swingGap(tgt) and live() do task.wait() end end
                if not live() then return end
                lastPress=tick()
                for attempt=1,2 do
                    inputAt=tick(); awaiting=true
                    if remote then remote:FireServer(which or false)
                    else VIM:SendMouseButtonEvent(x,y,0,true,game,0) end
                    local timeout=tick()+0.55
                    while live() and awaiting and tick()<timeout do task.wait() end
                    if not remote then release() end
                    if not awaiting or not live() then break end
                    task.wait(0.08)
                end
                if count~=step then _G.VX_FINISHER_STATUS="swing "..step.." not observed"; return end
            end
        end)
        release(); connection:Disconnect()
        if _G.VX_SYNTH_CLICK==deadline then _G.VX_SYNTH_CLICK=prior[1] end
        if _G.VX_COMBAT_SEQUENCE==deadline then _G.VX_COMBAT_SEQUENCE=prior[2] end
        if _G.VX_COMBAT_SUPPRESS_BF==deadline then _G.VX_COMBAT_SUPPRESS_BF=prior[3] end
        if not ok then warn("[DreamHub Combo] "..tostring(err)) end
        return ok and count==n and live()
    end

    _G.VX_COMBAT_M1S = swings
    local function sideDashTo(t,live)
        return _G.VXBF2 and _G.VXBF2.approach and _G.VXBF2.approach(t,false,live,false,false,{range=farDist,reach=math.min(nearDist,8),smooth=true,speed=assistSpeed})==true
    end

    -- ═══ r14: THE FAR-RUNNER CHASE - FULL-SPEED VELOCITY GLIDE ═══ "when the target's far and running
    -- away: do the three M1s, then a full glide or dash to them - NOT a teleport, a full slide after them,
    -- very fast, pro-like - then the downslam." The Q-dash orbit is a curved path around a point and it
    -- dead-reckons a runner; this is a straight pursuit: every heartbeat your body is turned to their LIVE
    -- position and the velocity is written toward it (full sprint far, eased in near - never a CFrame
    -- position write, so it is a slide, not a blink), the anti-cheat Teleport ack fires alongside exactly
    -- like every other glide in this file, and your collisions drop for the run so nothing body-blocks the
    -- chase. Reads as a player sprinting after a runner; lands just inside finisher reach.
    local function glideChase(t,live)
        local c=rig(); local r=c and c:FindFirstChild("HumanoidRootPart")
        local e=t and t.Parent and t:FindFirstChild("HumanoidRootPart")
        if not (r and e) then return false end
        local stopAt=math.max(math.min(nearDist,8)-1.2,3.5)
        local savedCollide={}
        for _,p in ipairs(c:GetDescendants()) do
            if p:IsA("BasePart") and p.CanCollide then savedCollide[p]=true; pcall(function() p.CanCollide=false end) end
        end
        local deadline=tick()+1.6
        local arrived=false
        while tick()<deadline and live() do
            r=c and c:FindFirstChild("HumanoidRootPart")
            e=t.Parent and t:FindFirstChild("HumanoidRootPart")
            if not (r and e) then break end
            local flat=Vector3.new(e.Position.X-r.Position.X,0,e.Position.Z-r.Position.Z)
            local dist=flat.Magnitude
            if dist<=stopAt then arrived=true; break end
            local dir=dist>0.1 and flat.Unit or Vector3.zero
            local spd=math.clamp(40+(dist-stopAt)*4.5,60,105)   -- full sprint far, eased in near
            if _G.VX_ACPASS then _G.VX_ACPASS() end
            pcall(function()
                r.CFrame=CFrame.lookAt(r.Position,Vector3.new(e.Position.X,r.Position.Y,e.Position.Z))
                r.AssemblyLinearVelocity=Vector3.new(dir.X*spd,r.AssemblyLinearVelocity.Y,dir.Z*spd)
            end)
            task.wait()
        end
        -- clean hand-off: kill the slide, restore collisions, hand the finisher a settled body
        local rEnd=c and c:FindFirstChild("HumanoidRootPart")
        if rEnd then pcall(function() local v=rEnd.AssemblyLinearVelocity; rEnd.AssemblyLinearVelocity=Vector3.new(v.X*0.1,v.Y,v.Z*0.1) end) end
        for p in pairs(savedCollide) do if p.Parent then pcall(function() p.CanCollide=true end) end end
        return arrived and live()
    end

    local function run(t,initialCount,manual)
        initialCount=initialCount or 0
        if running or _G.VX_COMBAT_OWNER or not t or not manual and (done[t] or not down(t) or tick()-(attempted[t] or -math.huge)<1) or distance(t)>farDist then return end
        local up,slam=upOn,downOn
        local which = up and (not slam or nextUpper) and "Up" or "Down"
        if which=="Up" and not up or which=="Down" and not slam then return end
        -- Acquire immediately. Waiting 0.45s consumed most of a short downed window.

        running=true; attempted[t]=tick()
        local owner = {}; _G.VX_COMBAT_OWNER = owner
        if upOn and downOn then nextUpper = not nextUpper end
        local gen, character = generation, rig()
        task.spawn(function()
            local function live()
                local h = character and character:FindFirstChildOfClass("Humanoid")
                local eh = t.Parent and t:FindFirstChildOfClass("Humanoid")
                return generation == gen and rig() == character and h and h.Health>0 and eh and eh.Health>0
                    and distance(t)<=farDist and (which == "Up" and upOn or which == "Down" and downOn)
            end
            local ok, err = pcall(function()
                if not live() then return end
                if not live() then return end
                face(t)
                -- Every finisher is the fourth attack. Close targets need no dash.
                if initialCount>0 then task.wait(down(t) and 0.06 or math.max(0.20,0.40/assistSpeed)) end
                local function prepareThird()
                    if which=="Up" and distance(t)<=nearDist then
                        _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Space]=tick()+1
                        VIM:SendKeyEvent(true,Enum.KeyCode.Space,false,game)
                    end
                end
                _G.VX_FINISHER_STATUS="building three swings for "..which
                if not swings(3-initialCount,live,prepareThird,nil,t) then warn("[DreamHub Finisher] three swings not observed; stopped"); return end
                task.wait(down(t) and 0.08 or math.max(0.20,0.40/assistSpeed))
                if not live() then return end
                if distance(t)>math.min(nearDist,8) then
                    -- ═══ r14: FAR AND/OR FLEEING = THE GLIDE CHASE ═══ mid-range stationary targets keep
                    -- the proven Q-dash orbit; anything far or actively running away gets the straight-line
                    -- full-speed pursuit glide (see glideChase) - "a full slide after them, then a downslam".
                    local fleeing=false
                    do
                        local c=rig(); local r=c and c:FindFirstChild("HumanoidRootPart")
                        local e=t.Parent and t:FindFirstChild("HumanoidRootPart")
                        if r and e then
                            local okv,tv=pcall(function() return e.AssemblyLinearVelocity end)
                            if okv and tv then
                                local away=Vector3.new(e.Position.X-r.Position.X,0,e.Position.Z-r.Position.Z)
                                if away.Magnitude>0.1 and Vector3.new(tv.X,0,tv.Z):Dot(away.Unit)>6 then fleeing=true end
                            end
                        end
                    end
                    if fleeing or distance(t)>13 then
                        _G.VX_FINISHER_STATUS="glide chase into finisher range"
                        if not glideChase(t,live) then _G.VX_FINISHER_STATUS="chase did not reach target"; return end
                    else
                        _G.VX_FINISHER_STATUS="side dash into finisher range"
                        if not sideDashTo(t,live) then _G.VX_FINISHER_STATUS="side dash did not reach target"; return end
                    end
                end
                if not live() or distance(t)>8 then return end
                face(t)

                if _G.VX_NATIVE_FINISHER(which,function() if live() then face(t) end; return live() and distance(t)<=8 end) then done[t]=true; _G.VX_FINISHER_STATUS=which.." fourth sent; hit unconfirmed"
                else _G.VX_FINISHER_STATUS=which.." fourth not sent; jump/range unavailable" end
            end)
            pcall(function() VIM:SendKeyEvent(false,Enum.KeyCode.Space,false,game) end)
            if not ok then warn("[DreamHub Finisher] "..tostring(err)) end
            if _G.VX_COMBAT_OWNER == owner then _G.VX_COMBAT_OWNER = nil end
            running = false
        end)
    end
    local function cancel() generation += 1; abilityPending=false; table.clear(done); table.clear(attempted); if _G.VX_FINISHER_RESET then _G.VX_FINISHER_RESET() end end
    LP.CharacterAdded:Connect(function() cancel(); table.clear(done) end)
    local function nearestFinisherTarget()
        local chosen=_G.VX_LOCK and _G.VX_LOCK.get and _G.VX_LOCK.get()
        local function valid(t)
            local h=t and t.Parent and t:FindFirstChildOfClass("Humanoid")
            return t~=rig() and h and h.Health>0 and distance(t)<=farDist
        end
        if valid(chosen) then return chosen end
        local best,range=nil,farDist
        for _,t in ipairs(_G.VX_LIVING_MODELS()) do
            if valid(t) and distance(t)<range then best,range=t,distance(t) end
        end
        return best
    end
    local abilityTicket=0
    _G.VX_FINISHER_ABILITY=function(observedTrack)
        if not (upOn or downOn) or running or abilityPending or _G.VX_COMBAT_OWNER then return end
        local target=nearestFinisherTarget(); if not target then return end
        local character=rig(); local h=character and character:FindFirstChildOfClass("Humanoid")
        local a=h and h:FindFirstChildOfClass("Animator")
        local th=target:FindFirstChildOfClass("Humanoid")
        if not a or not th then return end
        local health,wasDown,gen=th.Health,down(target),generation
        abilityTicket+=1; local ticket=abilityTicket; abilityPending=true
        local activeTrack=observedTrack; local began=tick()
        local function capture(track)
            local id=tostring(track.Animation and track.Animation.AnimationId or ""):match("%d+")
            if _G.VX_M1_IDS and _G.VX_M1_IDS[id] then return end
            local known=id and ((_G.VX_ADAPT_IDS and _G.VX_ADAPT_IDS[id]) or (_G.VX_ANIMDICT and _G.VX_ANIMDICT[id]))
            if known or tick()-began<0.45 and not track.Looped and tostring(track.Priority):find("Action",1,true) then activeTrack=track end
        end
        local connection=a.AnimationPlayed:Connect(capture)
        for _,track in ipairs(a:GetPlayingAnimationTracks()) do if track.TimePosition<0.12 then capture(track) end end
        task.spawn(function()
            local ok,err=pcall(function()
                local deadline=tick()+4
                repeat
                    if ticket~=abilityTicket or gen~=generation or rig()~=character or not target.Parent or h.Health<=0 then return end
                    local hit=th.Health<health or not wasDown and down(target)
                    if activeTrack and not activeTrack.IsPlaying and hit then
                        abilityPending=false; done[target]=nil; run(target,0,true); return
                    end
                    task.wait()
                until tick()>=deadline
                _G.VX_FINISHER_STATUS="no completed move with target hit observed"
            end)
            connection:Disconnect()
            if ticket==abilityTicket then abilityPending=false end
            if not ok then warn("[DreamHub Finisher] "..tostring(err)) end
        end)
    end

    local abilityAnimators=setmetatable({}, {__mode="k"})
    task.spawn(function()
        while true do
            local c=rig(); local h=c and c:FindFirstChildOfClass("Humanoid")
            local a=h and h:FindFirstChildOfClass("Animator")
            if a and not abilityAnimators[a] then
                abilityAnimators[a]=a.AnimationPlayed:Connect(function(track)
                    if c~=rig() or not (upOn or downOn) then return end
                    local id=tostring(track.Animation and track.Animation.AnimationId or ""):match("%d+")
                    if id and not (_G.VX_M1_IDS and _G.VX_M1_IDS[id])
                        and ((_G.VX_ADAPT_IDS and _G.VX_ADAPT_IDS[id]) or (_G.VX_ANIMDICT and _G.VX_ANIMDICT[id])) then
                        _G.VX_FINISHER_ABILITY(track)
                    end
                end)
            end
            task.wait(0.5)
        end
    end)
    local upperHoldToken=0; local upperHeld=false
    local function releaseManualUpper()
        upperHoldToken+=1
        if upperHeld then upperHeld=false; pcall(function() VIM:SendKeyEvent(false,Enum.KeyCode.Space,false,game) end) end
    end
    local function armManualUpper()
        if upperHeld then return end
        upperHoldToken+=1; local token=upperHoldToken; upperHeld=true
        _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Space]=tick()+0.65
        VIM:SendKeyEvent(true,Enum.KeyCode.Space,false,game)
        task.delay(0.65,function() if upperHoldToken==token then releaseManualUpper() end end)
    end

    local downPulse=0
    local function prepareDownPacket()
        releaseManualUpper()
        local c=rig(); local h=c and c:FindFirstChildOfClass("Humanoid")
        if h then h.Jump=false end
        _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Space]=tick()+0.2
        VIM:SendKeyEvent(false,Enum.KeyCode.Space,false,game)
    end
    -- Keep the active auto-finisher path consistent with the older M1 combo
    -- counter's 1.6-second window, so moderately slow real swings are not discarded.
    local manualWindow=1.6
    local manualCount,manualLast,manualIgnore=0,-math.huge,0
    local autoPacketCount,autoPacketLast=0,-math.huge
    local downWorker,thirdTrack
    local startDown,startUp
    local function stopDown()
        local token=downWorker;downWorker=nil
        if token and _G.VX_COMBAT_OWNER==token then _G.VX_COMBAT_OWNER=nil end
        if token and _G.VX_AUTO_DOWN_TOKEN==token then _G.VX_AUTO_DOWN_TOKEN=nil end
    end
    _G.VX_AUTO_DOWN_CANCEL=stopDown
    _G.VX_AUTO_FINISHER_OWNER=function() return downWorker end
    _G.VX_FINISHER_RESET=function()
        stopDown();manualCount=0;manualLast=-math.huge;manualIgnore=0;thirdTrack=nil;releaseManualUpper()
        autoPacketCount=0;autoPacketLast=-math.huge
    end
    pcall(function()
        game:GetService("ContextActionService"):BindActionAtPriority("VX_DownFourth",function(_,state)
            if state==Enum.UserInputState.Begin and autoDown and not downWorker and manualCount==3
                and tick()-manualLast<=manualWindow and not game:GetService("UserInputService"):GetFocusedTextBox() then
                local t=nearestFinisherTarget()
                if t and distance(t)<=nearDist then startDown(t,thirdTrack) end
            end
            if state==Enum.UserInputState.Begin and downWorker and not _G.VX_FINISHER_CLICK
                and not game:GetService("UserInputService"):GetFocusedTextBox() then return Enum.ContextActionResult.Sink end
            return Enum.ContextActionResult.Pass
        end,false,3200,Enum.UserInputType.MouseButton1)
    end)
    startDown=function(t,track)
        if downWorker or _G.VX_COMBAT_OWNER or not _G.VX_NATIVE_FINISHER then return end
        local character=rig();local h=character and character:FindFirstChildOfClass("Humanoid")
        if not h then return end
        local token={gen=generation};downWorker=token;_G.VX_AUTO_DOWN_TOKEN=token;_G.VX_COMBAT_OWNER=token
        manualCount=0;manualIgnore=tick()+1.2
        local function live()
            return downWorker==token and token.gen==generation and autoDown and not autoUp
                and rig()==character and h.Health>0 and t.Parent and distance(t)<=nearDist
                and not game:GetService("UserInputService"):GetFocusedTextBox()
        end
        task.spawn(function()
            local ok,err=pcall(function()
                -- Release the native held-M1 loop immediately, before a fourth can be selected as Up.
                local camera=workspace.CurrentCamera;local vp=camera and camera.ViewportSize
                _G.VX_SYNTH_CLICK=tick()+1.1
                VIM:SendMouseButtonEvent(vp and vp.X/2 or 400,vp and vp.Y/2 or 300,0,false,game,0)
                local recovery=0.08
                if track and (tonumber(track.Length) or 0)>0 then
                    recovery=math.clamp((track.Length*0.55-(tonumber(track.TimePosition) or 0))/math.max(tonumber(track.Speed) or 1,0.05),0.05,0.16)
                end
                local deadline=tick()+recovery
                while live() and tick()<deadline do task.wait() end
                if live() then face(t);_G.VX_NATIVE_FINISHER("Down",live) end
            end)
            if downWorker==token then stopDown() end
            manualIgnore=tick()+0.15
            if not ok then warn("[DreamHub Auto Downslam] "..tostring(err)) end
        end)
    end
    startUp=function(t,track)
        if downWorker or _G.VX_COMBAT_OWNER or not _G.VX_NATIVE_FINISHER then return end
        local character=rig();local h=character and character:FindFirstChildOfClass("Humanoid")
        if not h then return end
        local token={gen=generation,kind="Up"};downWorker=token;_G.VX_COMBAT_OWNER=token
        manualCount=0;manualIgnore=tick()+1.2
        local function live()
            return downWorker==token and token.gen==generation and autoUp and not autoDown
                and rig()==character and h.Health>0 and t.Parent and distance(t)<=nearDist
                and not game:GetService("UserInputService"):GetFocusedTextBox()
        end
        task.spawn(function()
            local ok,err=pcall(function()
                local camera=workspace.CurrentCamera;local vp=camera and camera.ViewportSize
                _G.VX_SYNTH_CLICK=tick()+0.8
                VIM:SendMouseButtonEvent(vp and vp.X/2 or 400,vp and vp.Y/2 or 300,0,false,game,0)
                local recovery=0.08
                if track and (tonumber(track.Length) or 0)>0 then
                    recovery=math.clamp((track.Length*0.55-(tonumber(track.TimePosition) or 0))/math.max(tonumber(track.Speed) or 1,0.05),0.05,0.16)
                end
                local deadline=tick()+recovery
                while live() and tick()<deadline do task.wait() end
                if live() then face(t);_G.VX_NATIVE_FINISHER("Up",live) end
            end)
            if downWorker==token then stopDown() end
            manualIgnore=tick()+0.15
            if not ok then warn("[DreamHub Auto Uppercut] "..tostring(err)) end
        end)
    end
    _G.VX_FINISHER_PACKET=function(remote,args)
        local basic=args[1]==false or args[1]=="Up" or args[1]=="Down"
        if not basic or not downWorker and not autoUp and not autoDown then return args end
        local own=_G.VX_BASIC_RE and _G.VX_BASIC_RE()
        if remote~=own or not basic then return args end
        if downWorker then
            if downWorker.kind=="Up" and args[1]=="Up" then return args end
            if not _G.VX_FINISHER_CLICK then return _G.VX_CANCEL_TOKEN end
            local body=rig();local hum=body and body:FindFirstChildOfClass("Humanoid")
            if hum and hum.FloorMaterial==Enum.Material.Air then
                local packet=table.clone(args);packet[1]="Down";return packet
            end
            return _G.VX_CANCEL_TOKEN
        end
        if not (autoUp or autoDown) or _G.VX_COMBAT_OWNER
            or tick()<(tonumber(_G.VX_SYNTH_CLICK) or 0) then return args end
        local now=tick()
        if now-autoPacketLast>manualWindow then autoPacketCount=0 end
        autoPacketLast=now
        if args[1]==false then autoPacketCount+=1 else autoPacketCount=4 end
        _G.VX_FINISHER_STATUS="basic attack packet "..autoPacketCount.." of 4"
        if autoPacketCount<4 then return args end
        autoPacketCount=0;manualCount=0;manualIgnore=now+0.3
        local packet=table.clone(args);packet[1]=autoDown and "Down" or "Up"
        _G.VX_FINISHER_STATUS=packet[1].." fourth sent; server hit unconfirmed"
        if autoDown then _G.VX_DOWN_T=now else _G.VX_UPPER_T=now end
        return packet
    end

    FinisherAssistApi = {
        setAutoUpper=function(v) autoUp=v==true; if autoUp then autoDown=false end; cancel() end,
        setAutoSlam=function(v) autoDown=v==true; if autoDown then autoUp=false end; cancel() end,
        -- r16: read-backs so the M1COMBO module can tell whose auto owns the swing (its own Auto Down Slam
        -- counter only runs when the assist's autos are OFF - see onSwing).
        isAutoUp=function() return autoUp==true end,
        isAutoDown=function() return autoDown==true end,
        fromSwing=function(track)
            if not (autoUp or autoDown) or _G.VX_COMBAT_OWNER or tick()<manualIgnore then return end
            local now=tick()
            if now-manualLast<0.15 then return end
            if now-manualLast>manualWindow then manualCount=0 end
            manualLast=now;manualCount=manualCount+1
            _G.VX_FINISHER_STATUS="observed swing "..manualCount.." of 3"
            if manualCount>=4 then manualCount=0;thirdTrack=nil;return end
            if manualCount~=3 then return end
            thirdTrack=track
            -- When the packet hook is active the user's own fourth basic
            -- attack is rewritten; do not race it with an injected fourth.
            if _G.VX_M1HOOK_ON and _G.VX_BASIC_RE and _G.VX_BASIC_RE() then return end
            local target=nearestFinisherTarget()
            if not target or distance(target)>nearDist then return end
            if autoUp then startUp(target,track) else startDown(target,track) end
        end,

        setUpper = function(v) upOn = v == true; if upOn then downOn=false end; cancel() end,
        setSlam = function(v) downOn = v == true; if downOn then upOn=false end; cancel() end,
        setNear = function(v) nearDist = math.clamp(tonumber(v) or 8,4,8) end,
        setFar = function(v) farDist = math.clamp(tonumber(v) or 40,8,50) end,
        setSpeed = function(v) assistSpeed=math.clamp(tonumber(v) or 1,0.5,2) end,
    }
end


-- ============================================================

-- MODULE: AUTO CANCEL  ("if I don't mean to click 3, block 3 from firing")
--
-- Pick a character and pick which slots to cancel. While it is on, pressing one of those keys does nothing:
-- the game still handles the keypress, but the Activated remote that spends the move is stopped dead in the
-- __namecall hook and never reaches the server. Nothing is used, nothing goes on cooldown.
--
-- There is no state here on purpose - the hook has to read this decision on the hot path, from inside a
-- newcclosure that survives a re-execution of the hub, and upvalues from a previous run are dead by then.
-- Globals are the only thing both halves can see, so this module is just the setters for them. The blocking
-- itself lives in the hook, next to the code it has to run before.
-- ============================================================
do
        _G.VX_CANCEL_ON    = false
        _G.VX_CANCEL_SLOTS = {}
        _G.VX_CANCEL_CHAR  = "Any"
        AutoCancelApi = {
                set     = function(v) _G.VX_CANCEL_ON = v == true end,
                setChar = function(v) v = (type(v) == "table") and v[1] or v; if type(v) == "string" then _G.VX_CANCEL_CHAR = v end end,
                setSlot = function(n, v) n = tonumber(n); if n then _G.VX_CANCEL_SLOTS[n] = (v == true) or nil; _G.VX_CANCEL_ON = next(_G.VX_CANCEL_SLOTS) ~= nil end end,
                isOn    = function() return _G.VX_CANCEL_ON == true end,
        }
end

-- ============================================================
-- MODULE: CURSED STRIKE ASSIST  ("when I do uppercut, the moment the target is in the air, cast move 1")
--
-- WHAT IT DOES, IN YOUR WORDS
-- "after the target... if they uppercut them, as soon as they ragdoll, it will do cursed strike - ONLY after
--  an uppercut. Time it very good."  and  "the moment the target is in the air, it needs to do curse strike,
--  or the first move. Timing is important."
--
-- SO THE TIMING IS THE WHOLE FEATURE, and it is built out of two facts rather than a guess at a delay:
--   1) ONLY AN UPPERCUT ARMS IT. An uppercut is Activated("Up") no matter who sends it, so the __namecall
--      hook stamps _G.VX_UPPER_T on every one - the hub's Auto Uppercut, the assist's, and a manual one you
--      do yourself. A down slam never writes that stamp, so a slam can never trigger this.
--   2) THE CAST GOES OUT ON THE FRAME THEY LEAVE THE GROUND. Not on a timer - a fixed delay is wrong the
--      moment ping or the launch height changes. This watches the target at 60Hz and fires the frame their
--      feet are off the floor, which is the earliest instant the airborne move can connect.
--
-- The remote is your capture verbatim:
--     CursedStrikesService.RE.Activated:FireServer(Moveset["Cursed Strikes"], true)
-- resolved through _G.VX_CAST_MOVE, which derives the service from the move's own name - so this is not a
-- Yuji-only feature. It casts whatever sits in SLOT 1 for the character you are on, with the airborne flag.
-- ============================================================
do
        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local LP = Players.LocalPlayer
        local on = false
        local seenStamp, lastCast = 0, 0

        local function myModel() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
        local function myHRP() local m = myModel(); return m and m:FindFirstChild("HumanoidRootPart") end
        -- Slot 1, whatever it is called. On vessel Yuji that IS Cursed Strikes; on anyone else it is their own
        -- first move, which is what "curse strike or the first move" asks for.
        local function slot1Name()
                -- The learned map first: it comes from pairing YOUR key presses with the game's own casts, so it is
                -- the real slot order. GetChildren() is creation order, which is only usually the same thing.
                local sm = _G.VX_SLOT_MOVE
                if sm and sm[1] then return sm[1] end
                for _, c in ipairs({ myModel(), LP.Character }) do
                        local mv = c and c:FindFirstChild("Moveset")
                        if mv then local kids = mv:GetChildren(); if kids[1] then return kids[1].Name end end
                end
                return nil
        end
        -- Who did you just uppercut? The locked target if you have one, else the nearest body in front of you -
        -- an uppercut is a melee move, so "nearest" is the right answer at the moment it lands.
        local function victim()
                local g = _G.VX_LOCK; local lt = (g and g.get) and g.get() or nil
                if lt and lt.Parent then return lt end
                local hrp = myHRP(); if not hrp then return nil end
                local best, bd
                local function chk(m)
                        if not m or m == myModel() or m.Name == LP.Name then return end
                        local r = m:FindFirstChild("HumanoidRootPart"); if not r then return end
                        local h = m:FindFirstChildOfClass("Humanoid"); if h and h.Health <= 0 then return end
                        local d = (r.Position - hrp.Position).Magnitude
                        if d <= 45 and (not bd or d < bd) then best, bd = m, d end
                end
                local chs = workspace:FindFirstChild("Characters")
                if chs then for _, m in ipairs(chs:GetChildren()) do chk(m) end end
                for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP then chk(plr.Character) end end
                return best
        end
        -- Airborne, judged three ways so a launch is never missed: the humanoid says it has no floor, OR it is
        -- rising fast, OR it has simply gained height since the uppercut connected. Any one is enough.
        local function airborne(t, baseY)
                local r = t.Parent and t:FindFirstChild("HumanoidRootPart"); if not r then return false end
                local h = t:FindFirstChildOfClass("Humanoid")
                if h and h.FloorMaterial == Enum.Material.Air then return true end
                if r.AssemblyLinearVelocity.Y > 12 then return true end
                if baseY and (r.Position.Y - baseY) > 3.5 then return true end
                return false
        end
        local function fire()
                -- ═══ "IT NEEDS TO CLICK 1, NOT 3" ═══ The press is now literal and explicit: KEY ONE, sent first,
                -- marked as ours. The remote follows as the backup. Nothing here can ever touch key 3 - the only
                -- keycode in this function is One.
                pcall(function()
                        local VIM = game:GetService("VirtualInputManager")
                        _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.One] = tick() + 0.4
                        _G.VX_INJECT_UNTIL = tick() + 0.4
                        VIM:SendKeyEvent(true, Enum.KeyCode.One, false, game); task.wait(0.03); VIM:SendKeyEvent(false, Enum.KeyCode.One, false, game)
                end)
                local nm = slot1Name()
                if not (nm and _G.VX_CAST_MOVE) then return false end
                -- The airborne flag is the second argument, and it is only correct while YOU are actually up there.
                -- An uppercut takes you up with them, so this is normally true; sending true from the ground would
                -- ask the server for a variant your state cannot support.
                local c = myModel(); local h = c and c:FindFirstChildOfClass("Humanoid")
                local up = (h and h.FloorMaterial == Enum.Material.Air) or false
                local ok
                if up then ok = _G.VX_CAST_MOVE(nm, true) else ok = _G.VX_CAST_MOVE(nm) end
                if _G.VX_MOVE_DEBUG then print("[DreamHub CursedStrike] " .. tostring(nm) .. " air=" .. tostring(up) .. " -> " .. tostring(ok)) end
                return ok
        end

        -- One watcher, armed by the stamp. Nothing polls the world while you are not uppercutting.
        task.spawn(function()
                while true do
                        if on then
                                local st = tonumber(_G.VX_UPPER_T) or 0
                                if st > seenStamp and tick() - st < 0.5 and tick() - lastCast > 1.0 then
                                        seenStamp = st
                                        local t = victim()
                                        if t then
                                                lastCast = tick()
                                                task.spawn(function()
                                                        local r = t:FindFirstChild("HumanoidRootPart")
                                                        local baseY = r and r.Position.Y
                                                        -- 1.5s: the uppercut is four remotes 0.22s apart, so the launch can be most of a
                                                        -- second after the first one. Past that it did not land and there is nothing to hit.
                                                        local deadline = tick() + 1.5
                                                        while tick() < deadline do
                                                                if not t.Parent then return end
                                                                if airborne(t, baseY) then
                                                                        -- face them so the cast goes where they are, then send it THIS frame.
                                                                        pcall(function()
                                                                                local hrp = myHRP(); local rr = t:FindFirstChild("HumanoidRootPart")
                                                                                if hrp and rr then hrp.CFrame = CFrame.lookAt(hrp.Position, Vector3.new(rr.Position.X, hrp.Position.Y, rr.Position.Z)) end
                                                                        end)
                                                                        fire()
                                                                        return
                                                                end
                                                                RunService.Heartbeat:Wait()
                                                        end
                                                        if _G.VX_MOVE_DEBUG then print("[DreamHub CursedStrike] target never left the ground - no cast") end
                                                end)
                                        end
                                end
                                task.wait(0.02)
                        else
                                task.wait(0.4)
                        end
                end
        end)

        CursedStrikeApi = {
                set = function(v)
                        on = v == true
                        -- Take the current stamp on the way in, so arming the toggle right after an uppercut does not
                        -- immediately fire off a stale one.
                        seenStamp = tonumber(_G.VX_UPPER_T) or 0
                end,
                now = fire,
        }
end

-- ============================================================
-- MODULE: TWOFOLD KICK ASSIST  (the friend's script VERBATIM - my "improvements" are gone)
-- Last build I ported this with tweaks: both-rig animator checks, a resolver with a fallback, trimmed
-- timings. It stopped working. The friend's original works. So this is now that script line for line -
-- hardcoded GojoService, single rig, 0.35s gaps, 0.2s jump wait - wrapped in nothing but the on/off
-- toggle and a watchdog on the latch. The ONLY speed knob is _G.VX_TF_GAP, default the friend's own 0.35;
-- lower it yourself if you want to experiment. I am done experimenting with a thing that works.
-- ============================================================
do
        local plrs = game:GetService("Players")
        local lp = plrs.LocalPlayer
        local on = false
        -- ═══ IT WAS WATCHING THE WRONG BODY ═══ This returned lp.Character. In JJS the rig that actually plays
        -- your animations lives at workspace.Characters[yourName]; lp.Character can be a stale or decoy rig - the
        -- file says so at vxMyChar and every other module resolves it that way. So check() searched an animator
        -- that never plays the kick, found rbxassetid://104749 never, and the Heartbeat gate never opened once.
        -- The finisher was fine. It was simply never called. That is "twofold kick assist dont work".
        local function char(plr)
                plr = plr or lp
                if plr == lp then
                        local chs = workspace:FindFirstChild("Characters")
                        local m = chs and chs:FindFirstChild(lp.Name)
                        if m and m:FindFirstChildOfClass("Humanoid") then return m end
                end
                return plr.Character or plr.CharacterAdded:Wait()
        end
        local function check()
                -- Both rigs, because which one is "yours" changes with the character swap and a miss here is the
                -- whole feature. His single-rig read is otherwise untouched.
                for _, rig in ipairs({ char(), lp.Character }) do
                        local ok, res = pcall(function()
                                local h = rig and rig:FindFirstChildOfClass("Humanoid")
                                local a = h and h:FindFirstChildOfClass("Animator")
                                if not a then return false end
                                for _, v in pairs(a:GetPlayingAnimationTracks()) do
                                        if v.Animation.AnimationId:find("rbxassetid://104749") then return true end
                                end
                                return false
                        end)
                        if ok and res then return true end
                end
                return false
        end
        local running = false
        -- ═══ HIS SCRIPT, CHARACTER FOR CHARACTER ═══ You pasted it a third time, so a third time I deleted
        -- everything of mine: the 0.22 gap experiment, the injected clicks, and last build's watch-the-target-
        -- into-the-air gate before the 4th Down. What follows is the friend's finisher VERBATIM - his 0.35s
        -- gaps, his jump, his flat 0.2s wait, his 4th Down - because the verbatim version is the only one that
        -- has ever been reported working, both times it regressed it was my "improvement", and I am done.
        local function finisher()
                for _ = 1, 3 do
                        pcall(function() game:GetService("ReplicatedStorage").Knit.Knit.Services.GojoService.RE.Activated:FireServer("Down") end)
                        task.wait(.35)
                end
                task.wait()
                pcall(function() local h = char():FindFirstChildOfClass("Humanoid"); if h then h:ChangeState(Enum.HumanoidStateType.Jumping) end end)
                task.wait(.2)
                pcall(function() game:GetService("ReplicatedStorage").Knit.Knit.Services.GojoService.RE.Activated:FireServer("Down") end)
        end
        game:GetService("RunService").Heartbeat:Connect(function()
                if not on then return end
                if not check() or running then return end
                running = true
                task.delay(5, function() running = false end)   -- watchdog: the latch can never stick
                task.spawn(function()
                        repeat task.wait() until not check()      -- his exact wait: until the kick animation is over
                        finisher()
                        running = false
                end)
        end)
        TwofoldApi = { set = function(v) on = v == true end, now = finisher }
end

-- ============================================================
-- MODULE: AUTO HAKARI  (Reserve Balls + Shutter Doors together - "it uses 1 and 2 at the same time")
-- Both remotes verbatim from the user's captures:
--   ReserveBallService.RE.Activated(Moveset["Reserve Balls"])
--   ShutterDoorService.RE.Activated(Moveset["Shutter Doors"], workspace.Characters.<target>)
-- Neither service name is guessed: _G.VX_CAST_MOVE derives it from the move's own name, which is the rule
-- every capture in this project follows.
-- ============================================================
do
        local Players = game:GetService("Players")
        local LP = Players.LocalPlayer
        local on, rate = false, 3.0
        local function myModel() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
        local function myHRP() local m = myModel(); return m and m:FindFirstChild("HumanoidRootPart") end
        local function hasMove(name)
                local n = string.lower(name):gsub("[^%a]", "")
                for _, c in ipairs({ myModel(), LP.Character }) do
                        local mv = c and c:FindFirstChild("Moveset")
                        if mv then for _, m in ipairs(mv:GetChildren()) do
                                if string.lower(m.Name):gsub("[^%a]", "") == n then return true end
                        end end
                end
                return false
        end
        -- Shutter Doors takes a TARGET as its second argument - the workspace.Characters model, exactly as the
        -- capture shows (it passed workspace.Characters.Dummy). Prefer the locked target, else the nearest body.
        local function target()
                local g = _G.VX_LOCK; local lt = (g and g.get) and g.get() or nil
                if lt and lt.Parent then return lt end
                local hrp = myHRP(); if not hrp then return nil end
                local best, bd
                local chs = workspace:FindFirstChild("Characters")
                if chs then
                        for _, m in ipairs(chs:GetChildren()) do
                                if m.Name ~= LP.Name and m ~= myModel() then
                                        local r = m:FindFirstChild("HumanoidRootPart")
                                        local h = m:FindFirstChildOfClass("Humanoid")
                                        if r and (not h or h.Health > 0) then
                                                local d = (r.Position - hrp.Position).Magnitude
                                                if not bd or d < bd then best, bd = m, d end
                                        end
                                end
                        end
                end
                return best
        end
        local function cast()
                if not _G.VX_CAST_MOVE then return end
                -- "it use 1 and 2 at the same time" - both go out on the same beat, not one after the other, so the
                -- doors close around them while the balls are already in the air.
                task.spawn(function() _G.VX_CAST_MOVE("Reserve Balls") end)
                task.spawn(function() _G.VX_CAST_MOVE("Shutter Doors", target()) end)
        end
        task.spawn(function()
                while true do
                        if on then
                                -- Only when you actually own them: firing another character's move remote is the 267 risk.
                                if hasMove("Reserve Balls") or hasMove("Shutter Doors") then
                                        pcall(cast)
                                        task.wait(rate)
                                else
                                        if VX_NOTIFY and tick() - (_G.VX_HAK_WARN or 0) > 8 then
                                                _G.VX_HAK_WARN = tick()
                                                VX_NOTIFY("Auto Hakari: you are not playing Hakari", false)
                                        end
                                        task.wait(2)
                                end
                        else
                                task.wait(0.4)
                        end
                end
        end)
        HakariApi = {
                set = function(v) on = v == true end,
                setRate = function(v) rate = math.clamp(tonumber(v) or rate, 0.5, 10) end,
                now = cast,
        }
end

-- ============================================================
-- MODULE: TOTAL  (Todo's swap + the character changer)
--   Auto Swap          - fire TodoService.RE.RightActivated at a target (Closest / Random / Lock Target)
--   Auto Perfect Swap  - you cast a Todo move (1/2/3/4), we swap the instant it commits
--   Auto Character     - pick a character; re-pick it automatically when you die
--   Switch Character   - force reset + JoinService.RE.Change("<Name>") on demand
-- Every remote here is one the user captured verbatim; nothing in this module guesses a remote name.
-- ============================================================
do
        local Players = game:GetService("Players")
        local RS = game:GetService("ReplicatedStorage")
        local VIM = game:GetService("VirtualInputManager")
        local LP = Players.LocalPlayer

        local function myModel() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
        local function myHRP() local m = myModel(); return m and m:FindFirstChild("HumanoidRootPart") end
        local function norm(s) return (string.gsub(string.lower(tostring(s or "")), "[^%a%d]", "")) end
        local function note(msg) if _G.VX_TOTAL_DEBUG then pcall(function() print("[DreamHub Todo] " .. tostring(msg)) end) end end

        local function svcFolder()
                local k = RS:FindFirstChild("Knit"); k = k and k:FindFirstChild("Knit"); return k and k:FindFirstChild("Services")
        end
        local function svcRE(svc, re)
                local f = svcFolder(); local s = f and f:FindFirstChild(svc); local r = s and s:FindFirstChild("RE")
                return r and r:FindFirstChild(re)
        end
        -- A missing remote is reported OUT LOUD (throttled), the same lesson Auto Air taught us: a silently
        -- absent service is indistinguishable from "the feature does nothing" and costs a whole test round.
        local function fireSvc(svc, re, ...)
                local r = svcRE(svc, re)
                if not r then
                        if tick() - (_G.VX_TOTAL_MISS_T or 0) > 2 then
                                _G.VX_TOTAL_MISS_T = tick()
                                pcall(function() print("[DreamHub Todo] remote MISSING: " .. svc .. ".RE." .. re .. "  (send me this line)") end)
                        end
                        return false
                end
                local a = table.pack(...)
                local ok = pcall(function() r:FireServer(table.unpack(a, 1, a.n)) end)
                note((ok and "fired " or "FAILED ") .. svc .. "." .. re)
                return ok
        end

        -- ═══════════════════════ WHO AM I ═══════════════════════
        -- The swap remote belongs to Todo. Firing another character's remote is exactly what earned a 267 kick
        -- before, so this gate is STRICT: no proof you are Todo, no fire. Proof comes from your own Moveset (the
        -- four moves are unique to Todo) or from the character-service resolver the combo module already uses.
        local TODO_MOVES = { ["swiftkick"] = true, ["bruteforce"] = true, ["pebblethrow"] = true, ["elbowdrop"] = true }
        -- The move capture reads Players.LocalPlayer.Character.Moveset, but everything else in this game lives on
        -- workspace.Characters[name] - and in JJS those are two DIFFERENT rigs. Checking only one is how a
        -- detection like this ends up answering "you are not Todo" while you are standing there as Todo. Check both.
        local function myRigs()
                local out = {}
                local chs = workspace:FindFirstChild("Characters")
                local w = chs and chs:FindFirstChild(LP.Name)
                if w then out[#out + 1] = w end
                if LP.Character and LP.Character ~= w then out[#out + 1] = LP.Character end
                return out
        end
        local function moveNamed(name)   -- the Moveset entry the move remotes want, from whichever rig has it
                local want = norm(name)
                for _, c in ipairs(myRigs()) do
                        local mv = c:FindFirstChild("Moveset")
                        if mv then
                                local direct = mv:FindFirstChild(name); if direct then return direct end
                                for _, m in ipairs(mv:GetChildren()) do if norm(m.Name) == want then return m end end
                        end
                end
                return nil
        end
        local function isTodo()
                for _, c in ipairs(myRigs()) do
                        local mv = c:FindFirstChild("Moveset")
                        if mv then for _, m in ipairs(mv:GetChildren()) do if TODO_MOVES[norm(m.Name)] then return true end end end
                        local h = c:FindFirstChildOfClass("Humanoid")
                        if h and string.find(norm(h.DisplayName), "todo", 1, true) then return true end
                end
                local ok, svc = pcall(vxMyCharSvc)
                return ok and svc == "TodoService"
        end
        local function todoWarn()
                if tick() - (_G.VX_TOTAL_WARN_T or 0) < 8 then return end
                _G.VX_TOTAL_WARN_T = tick()
                if VX_NOTIFY then VX_NOTIFY("Todo: you are not playing Todo - swap is off", false) end
                note("not Todo; refusing to fire TodoService (firing another character's remote is a 267 risk)")
        end

        -- ═══════════════════════ TARGETING ═══════════════════════
        -- ═══ WHICH MODEL THE REMOTE WANTS ═══ The capture is explicit:
        --     args = { workspace:WaitForChild("Characters"):WaitForChild("Dummy") }
        --     TodoService.RE.RightActivated:FireServer(unpack(args))
        -- It is the workspace.Characters child, NOT Players[name].Character. Those are two DIFFERENT instances in
        -- JJS - the game keeps live bodies under workspace.Characters and LP.Character is a separate rig - so
        -- handing over the wrong one is a silently-rejected call, i.e. "auto swap does nothing". (The Gojo
        -- RightActivated capture went the other way and wants the player's Character; same remote NAME, different
        -- service, different argument. They do not generalise, so each one follows its own capture.)
        local function asWorkspaceChar(mdl)
                if not mdl then return nil end
                local chs = workspace:FindFirstChild("Characters")
                local w = chs and chs:FindFirstChild(mdl.Name)
                return w or mdl
        end
        -- Deduped BY NAME, not by instance: a real player shows up twice (plr.Character and the
        -- workspace.Characters model are different Instances with the same name) and would otherwise be counted
        -- as two separate enemies, which skews "Random" and double-counts "Closest".
        local function eachEnemy(fn)
                local seen = {}
                local function chk(m)
                        if not m then return end
                        m = asWorkspaceChar(m)                      -- always hand the callback the model the remote wants
                        if seen[m.Name] then return end
                        if m.Name == LP.Name or m == LP.Character or m == myModel() then return end
                        local r = m:FindFirstChild("HumanoidRootPart"); if not r then return end
                        local h = m:FindFirstChildOfClass("Humanoid")
                        if h and h.Health <= 0 then return end          -- a corpse is not a swap target
                        seen[m.Name] = true
                        fn(m, r)
                end
                local chs = workspace:FindFirstChild("Characters"); if chs then for _, m in ipairs(chs:GetChildren()) do chk(m) end end
                for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP then chk(plr.Character) end end
                for _, folderName in ipairs({ "Dummies", "Training", "NPCs", "Dummy" }) do
                        local f = workspace:FindFirstChild(folderName)
                        if f then for _, m in ipairs(f:GetChildren()) do chk(m) end end
                end
        end

        local swapOn, swapMode, swapRange, swapCD = false, "Closest", 60, 2.5
        local perfectOn, perfectDelay = false, 0.12
        -- ═══════════════════════ SWAP TRIGGERS ═══════════════════════
        -- "make it work when they dash, m1, or when the target is on the floor."
        -- All three OFF = the original behaviour, a swap whenever the cooldown is up and you are not busy. Turn any
        -- of them ON and the swap becomes REACTIVE: it waits for that moment on the target and takes it. They stack,
        -- so you can arm dash + down and ignore M1s.
        local trigDash, trigM1, trigDown = false, false, false
        -- WHOSE dash / WHOSE M1. "Them" = react to the target (swap in when they commit). "Me" = react to
        -- YOURSELF (you dash or M1, and it swaps you onto them on that beat). Down is always THEIRS - swapping
        -- because you are the one on the floor is not a thing anyone wants - so it ignores this setting.
        local trigWho = "Me"

        local function anyTrigger() return trigWho ~= "Off" and (trigDash or trigM1 or trigDown) end
        local DASH_SPEED = 55        -- studs/s, horizontal. Sprinting sits well under this; the game's dash impulse is ~105.
        -- Per-target memory so an event fires ONCE per occurrence instead of every frame it is still true.
        local seenState = setmetatable({}, { __mode = "k" })
        local function trackOf(t)    -- what the target is playing right now, by id
                local h = t and t:FindFirstChildOfClass("Humanoid")
                local a = h and h:FindFirstChildOfClass("Animator")
                if not a then return nil end
                local ok, tracks = pcall(function() return a:GetPlayingAnimationTracks() end)
                if not ok or not tracks then return nil end
                return tracks
        end
        -- ON THE FLOOR = knocked down. JJS expresses this several different ways depending on what put them there,
        -- so accept any of them rather than betting on one: the ragdoll humanoid states, PlatformStand, and the
        -- Ragdoll/Ragdolled value the anti-ragdoll module already looks for on the character's Info folder.
        local function isDown(t)
                local h = t and t:FindFirstChildOfClass("Humanoid")
                if not h then return false end
                if h.PlatformStand then return true end
                local ok, st = pcall(function() return h:GetState() end)
                if ok and (st == Enum.HumanoidStateType.Physics or st == Enum.HumanoidStateType.Ragdoll
                        or st == Enum.HumanoidStateType.FallingDown or st == Enum.HumanoidStateType.GettingUp) then return true end
                if h:GetAttribute("Ragdoll") == true or h:GetAttribute("Ragdolled") == true or h:GetAttribute("Downed") == true then return true end
                local info = t:FindFirstChild("Info")
                local rag = info and (info:FindFirstChild("Ragdoll") or info:FindFirstChild("Ragdolled"))
                if rag and rag:IsA("ValueBase") and rag.Value == true then return true end
                return false
        end
        local function isDashing(t)
                local r = t and t:FindFirstChild("HumanoidRootPart"); if not r then return false end
                local v = r.AssemblyLinearVelocity
                -- HORIZONTAL only: falling is not dashing, and a knockback launch would otherwise read as one.
                return Vector3.new(v.X, 0, v.Z).Magnitude >= DASH_SPEED
        end
        -- ═══ "FIX SWAP M1 DONT WORK" ═══ This only accepted ids in _G.VX_M1_IDS. That table was CAPTURED, so it
        -- covers the characters that existed when it was made and nobody since - Jawbreaker is not in it, and
        -- neither are Todo or Hakari. On any of them this returned false forever and the M1 trigger was dead.
        -- A known id is still the strong signal, but an Action-priority swing that has only just started is the
        -- same universal test the flash engine falls back to, and it needs no per-character data at all.
        local function isM1ing(t)
                local tracks = trackOf(t); if not tracks then return false end
                for _, tr in ipairs(tracks) do
                        local ok, id = pcall(function() return string.match(tostring(tr.Animation.AnimationId), "%d+") end)
                        if ok and id and tr.TimePosition < 0.45 then
                                if _G.VX_M1_IDS and _G.VX_M1_IDS[id] then return true end
                                local okp, pr = pcall(function() return tostring(tr.Priority) end)
                                if okp and string.find(pr, "Action", 1, true) then return true end
                        end
                end
                return false
        end
        -- Returns the trigger name if one just BECAME true for this target, else nil. Edge-detected: holding a
        -- dash or lying on the floor is one event, not sixty.
        local function triggerFired(t)
                if not t then return nil end
                local was = seenState[t]; if not was then was = {}; seenState[t] = was end
                local fired = nil
                local function edge(key, now, label)
                        if now and not was[key] then fired = fired or label end
                        was[key] = now
                end
                -- Own Q/M1 inputs go through onMySwapInput; only opponent actions are polled.
                if trigWho=="Them" then
                        edge("dash", trigDash and isDashing(t) or false, "they dashed")
                        edge("m1", trigM1 and isM1ing(t) or false, "they M1'd")
                end

                edge("down", trigDown and isDown(t) or false, "they're down")   -- always theirs
                return fired
        end

        local function lockedTarget()
                local g = _G.VX_LOCK
                local t = (g and g.get) and g.get() or nil
                return (t and t.Parent) and t or nil
        end
        local function pickTarget()
                if swapMode == "Off" then return nil end                      -- the dropdown's own off switch
                if swapMode == "Lock Target" then return lockedTarget() end   -- no fallback: "Lock Target" means THAT one or none
                local hrp = myHRP(); if not hrp then return nil end
                if swapMode == "Random" then
                        local pool = {}
                        eachEnemy(function(m, r) if (r.Position - hrp.Position).Magnitude <= swapRange then pool[#pool + 1] = m end end)
                        if #pool == 0 then return nil end
                        return pool[math.random(1, #pool)]
                end
                local best, bd
                eachEnemy(function(m, r)
                        local d = (r.Position - hrp.Position).Magnitude
                        if d <= swapRange and (not bd or d < bd) then best, bd = m, d end
                end)
                return best
        end

        -- ═══════════════════════ THE BUSY GATE ═══════════════════════
        -- "not random when they doing an upper cut or down slam or in a combo." A swap teleports you onto the
        -- target and cancels whatever you were mid-way through, so Auto Swap only fires in a GAP.
        --   VX_FINISHER_T  - stamped by the combo module the moment a slam/uppercut goes out
        --   VX_LAST_CLICK  - stamped EVERY FRAME the M1 button is held, so a held combo reads busy for its whole
        --                    length (that is the same stamp the Black Flash engine relies on)
        --   VX_BF_LAST_FIRE- a flash just landed; the follow-through is still playing
        -- reactive = a Swap When trigger asked for this specific moment. A finisher is still untouchable (that was
        -- the original ask: never interrupt an uppercut or a down slam), but the "you clicked recently" and "you
        -- just cast a move" blocks are dropped - in a real fight you are almost always inside those windows, so
        -- keeping them would mean the triggers essentially never fire, which is not what asking for them means.
        local function busy(reactive)
                local now = tick()
                -- ═══ "WHEN I GOT TO THIS TARGET IT DIDN'T SWAP" ═══ every window here was tuned for a fight
                -- that never pauses, so the swap sat blocked all session. Shortened across the board: a reactive
                -- trigger (Swap On Dash/M1/Down) is only held back by a finisher actually in flight, and the
                -- passive auto-swap waits 0.25s after your last click instead of 0.4s.
                if now - (tonumber(_G.VX_FINISHER_T) or 0) < (reactive and 0.6 or 0.4) then return true end
                if now - (tonumber(_G.VX_BF_LAST_FIRE) or 0) < (reactive and 0 or 0.5) then return true end
                if reactive then return false end
                if now - (tonumber(_G.VX_LAST_CLICK) or 0) < 0.25 then return true end
                if now - (tonumber(_G.VX_TOTAL_MOVE_T) or 0) < 0.2 then return true end
                return false
        end

        local lastSwap = 0
        local function doSwap(why, minGap, forced)
                if _G.VX_TODO_BF_ACTIVE then return false end
                local t = forced or pickTarget()
                if not t then note("no target (" .. tostring(why) .. ")") return false end
                if tick() - lastSwap < (minGap or swapCD) then
                        note("swap held by cooldown (" .. tostring(why) .. ") - " ..
                                string.format("%.2fs left", (minGap or swapCD) - (tick() - lastSwap)))
                        return false
                end
                if not isTodo() then todoWarn() return false end
                lastSwap = tick()
                _G.VX_TOTAL_SWAP_T = tick()
                local ok = fireSvc("TodoService", "RightActivated", asWorkspaceChar(t))
                if not ok then
                        -- The remote is the real swap; the key is only here so a renamed service still does SOMETHING.
                        _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.R] = tick() + 0.3
                        pcall(function()
                                VIM:SendKeyEvent(true, Enum.KeyCode.R, false, game)
                                task.wait(0.03)
                                VIM:SendKeyEvent(false, Enum.KeyCode.R, false, game)
                        end)
                end
                note("swap -> " .. tostring(t.Name) .. "  (" .. tostring(why) .. ")")
                return true
        end

        -- One user input may arrive through UIS and the shared poll. Handle it once.
        local lastMyInput={Dash=-math.huge,M1=-math.huge}
        local function onMySwapInput(kind)
            local UIS=game:GetService("UserInputService")
            local function allowed()
                -- "Me" inputs fire unless you picked "Them": Off only silences the THEM-side watcher,
                -- it must not silently disable Swap On Dash / Swap On M1 when you press the keys yourself.
                return swapOn and trigWho~="Them" and not UIS:GetFocusedTextBox()
                    and not _G.VX_TODO_BF_ACTIVE and not busy(true)
                    and (kind=="Dash" and trigDash or kind=="M1" and trigM1)
            end
            if not allowed() then return end
            if kind=="Dash" and _G.VX_INJ_KEYS and tick()<(_G.VX_INJ_KEYS[Enum.KeyCode.Q] or 0) then return end
            if kind=="M1" and tick()<(tonumber(_G.VX_SYNTH_CLICK) or 0) then return end
            if tick()-lastMyInput[kind]<0.12 then return end
            lastMyInput[kind]=tick()
            local character=vxMyChar()
            local function execute()
                if not allowed() or vxMyChar()~=character then return end
                local target=pickTarget()
                if target then pcall(doSwap,kind=="Dash" and "I pressed Q" or "I clicked",0.12,target) end
            end
            -- ═══ M1 FIRST, THEN THE SWAP ═══ "I want them to, like, M1 and then it swaps, not just when I
            -- click - it's every M1." The swap used to fire on the click BEFORE the swing landed, so the
            -- clap could cancel your own M1. Every M1 still swaps - a beat AFTER the swing connects.
            if kind=="M1" then task.delay(0.16,execute) else task.delay(0.03,execute) end
        end
        game:GetService("UserInputService").InputBegan:Connect(function(input)
            if input.KeyCode==Enum.KeyCode.Q then onMySwapInput("Dash")
            elseif input.UserInputType==Enum.UserInputType.MouseButton1 then onMySwapInput("M1") end
        end)

        task.spawn(function()
                while true do
                        if swapOn then
                                if anyTrigger() then
                                        -- REACTIVE. Poll fast: a dash is over in ~0.15s and an M1 windup in ~0.2s, so at the
                                        -- 0.2s idle rate we would miss most of them.
                                        -- Watch EVERYONE in range, not just pickTarget(): "swap when they dash" means whoever
                                        -- dashes. Resolving a single target each tick would also re-roll "Random" every 60ms and
                                        -- reset the edge detector before it ever saw an edge. Lock Target still means only them.
                                        local hit, hitWhy, hitD
                                        if swapMode == "Lock Target" then
                                                local lt = lockedTarget()
                                                local w = lt and triggerFired(lt) or nil
                                                if w then hit, hitWhy = lt, w end
                                        else
                                                local hrp = myHRP()
                                                if hrp then
                                                        eachEnemy(function(m, r)
                                                                local d = (r.Position - hrp.Position).Magnitude
                                                                if d > swapRange then return end
                                                                local w = triggerFired(m)                       -- called for EVERY enemy: the edge
                                                                if w and (not hitD or d < hitD) then            -- state has to stay live for all of them
                                                                        hit, hitWhy, hitD = m, w, d
                                                                end
                                                        end)
                                                end
                                        end
                                        if hit and not busy(true) then pcall(doSwap, hitWhy, math.min(swapCD,0.15), hit) end
                                        task.wait(0.03)
                                else
                                        if not busy() then pcall(doSwap, "auto", swapCD) end
                                        task.wait(0.2)
                                end
                        else
                                task.wait(0.4)
                        end
                end
        end)

        -- ═══════════════════════ AUTO PERFECT SWAP ═══════════════════════
        -- You press 1/2/3/4; we swap the instant the move actually commits.
        -- "use the animation ids for that character" - we do not need a hardcoded id table for that. A key press
        -- only counts as a CAST if an Action-priority animation starts right behind it; on cooldown nothing plays
        -- and we stay quiet. That is the whole difference between a perfect swap and R-spam.
        local MOVE_FOR_KEY = {
                [Enum.KeyCode.One]   = { svc = "SwiftKickService",   move = "Swift Kick" },
                [Enum.KeyCode.Two]   = { svc = "BruteForceService",  move = "Brute Force" },
                [Enum.KeyCode.Three] = { svc = "PebbleThrowService", move = "Pebble Throw" },
                [Enum.KeyCode.Four]  = { svc = "ElbowDropService",   move = "Elbow Drop" },
        }
        local lastAction, lastActionId = 0, nil
        local faceThreat
        local animHooked = setmetatable({}, { __mode = "k" })
        -- ═══ "USE THE ANIMATION IDS FOR THAT CHARACTER" ═══ We do not ship a hardcoded id table, because a table
        -- we never captured means the feature is dead on that character. Instead it LEARNS: press 1, and the move
        -- animation that plays right behind it is recorded as a candidate for Swift Kick. After the same id turns
        -- up twice it is trusted, and from then on the id alone triggers the swap - so a cast that did NOT come
        -- from a key press (mobile button, a rebind, a move fired elsewhere in the hub) still gets its swap.
        local LEARNED_ID = {}     -- animation id (string) -> move name  (committed, safe to fire on)
        local LEARN_SEEN = {}     -- move name -> { id -> how many separate presses produced it }
        local LEARN_RIG = nil     -- which rig the table was learned on; a character change wipes it
        -- ═══ A LEARNER THAT CANNOT BE POISONED ═══ Naively recording "the last Action track after the key press"
        -- is dangerous: JJS M1 swings, dashes and the flash itself are ALL Action priority, so one press landing
        -- while you were mid-combo would record an M1 id as "Pebble Throw" - and from then on every ordinary M1
        -- would fire a swap. That is a phantom, and phantoms are what we are trying to remove. So:
        --   * never learn an id that _G.VX_M1_IDS already knows is an M1 (it covers all 20 characters)
        --   * never learn while a real click is in flight - that track is a swing, not a move
        --   * require the SAME id from two separate presses of that key before trusting it
        --   * wipe everything when the rig changes (respawn, character swap): ids belong to a character
        local function learnId(id, moveName)
                if not id or not moveName then return end
                if _G.VX_M1_IDS and _G.VX_M1_IDS[id] then return end
                if tick() - (tonumber(_G.VX_LAST_HUMAN_CLICK) or 0) < 0.6 then return end
                local rig = myRigs()[1]
                if rig ~= LEARN_RIG then LEARNED_ID = {}; LEARN_SEEN = {}; LEARN_RIG = rig end
                local seen = LEARN_SEEN[moveName]; if not seen then seen = {}; LEARN_SEEN[moveName] = seen end
                seen[id] = (seen[id] or 0) + 1
                if seen[id] >= 2 then
                        LEARNED_ID[id] = moveName
                        note("learned " .. moveName .. " animation id " .. id)
                end
        end
        local function isActionPriority(track)
                local ok, p = pcall(function() return track.Priority end)
                if not ok then return false end
                -- Action2/3/4 only exist on newer engine builds; compare by name so an older client cannot error here.
                local n = tostring(p)
                return string.find(n, "Action", 1, true) ~= nil
        end
        local onLearnedCast   -- forward declaration: defined below, once doSwap's caller exists
        local function hookAnims()
                for _, char in ipairs(myRigs()) do
                        local h = char:FindFirstChildOfClass("Humanoid")
                        local a = h and h:FindFirstChildOfClass("Animator")
                        if a and not animHooked[a] then
                                animHooked[a] = true
                                a.AnimationPlayed:Connect(function(track)
                                        if not isActionPriority(track) then return end
                                        lastAction = tick()
                                        local ok, id = pcall(function() return string.match(tostring(track.Animation.AnimationId), "%d+") end)
                                        if ok and id then
                                                lastActionId = id
                                                local known = LEARNED_ID[id]
                                                if known and onLearnedCast then onLearnedCast(known, id) end
                                        end
                                end)
                        end
                end
        end
        task.spawn(function() while true do if perfectOn then pcall(hookAnims) end task.wait(1) end end)

        -- The swap that follows a cast. Short gap only: this is YOUR input, so it must not be throttled by the auto
        -- loop's cooldown. Kept in one place so the key path and the learned-animation path behave identically.
        local lastPerfect = 0
        local function perfectSwap(moveName)
                if not perfectOn then return end
                if tick() - lastPerfect < 0.30 then return end
                lastPerfect = tick()
                if perfectDelay > 0 then task.wait(perfectDelay) end
                pcall(doSwap, "perfect " .. tostring(moveName), 0.30)
        end
        onLearnedCast = function(moveName)   -- a move whose id we already learned just played, no key needed
                if not perfectOn or not isTodo() then return end
                _G.VX_TOTAL_MOVE_T = tick()
                task.spawn(function() perfectSwap(moveName) end)
        end

        local function onMoveKey(kc)
                if _G.VX_TODO_BF_ACTIVE then return end
                local e = MOVE_FOR_KEY[kc]; if not e then return end
                -- ═══ NOT EVERY 1/2/3/4 IS YOURS ═══ The shared key poll uses IsKeyDown, which sees VirtualInputManager
                -- presses, and every consumer in this file is expected to filter its own. The Black Flash engine injects
                -- key THREE on every single flash - so without this, every auto black flash was read as "the user cast
                -- Pebble Throw" and yanked you onto an enemy. The check goes BEFORE the stamp on purpose: stamping off
                -- our own key 3 would also make busy() true for a second after every flash and starve Auto Swap.
                do local injK = _G.VX_INJ_KEYS; if injK and injK[kc] and tick() < injK[kc] then return end end
                _G.VX_TOTAL_MOVE_T = tick()          -- a cast is in flight: Auto Swap holds off (see busy())
                if not perfectOn then return end
                if not isTodo() then return end
                -- You cannot cast a move you do not own. Checking the Moveset entry first means a stray 1/2/3/4 press
                -- on a character without that move never even starts the watcher.
                if not moveNamed(e.move) then note("perfect swap: no Moveset entry '" .. e.move .. "' - ignoring the key") return end
                local at = tick()
                task.spawn(function()
                        -- A key press only counts as a CAST if an Action-priority animation starts right behind it. On
                        -- cooldown nothing plays and we stay quiet - that is the whole difference between a perfect swap
                        -- and R-spam.
                        local deadline = tick() + 0.45
                        repeat task.wait(0.03) until lastAction >= at or tick() > deadline
                        if lastAction < at then note("perfect swap: " .. e.move .. " never played (cooldown?) - not swapping") return end
                        learnId(lastActionId, e.move)
                        perfectSwap(e.move)
                end)
        end
        -- Subscribe ONLY while something here needs the keys. The shared key poll skips itself entirely when no
        -- module is subscribed, and a permanent subscription from a switched-off feature would put that per-frame
        -- sweep back on the hot path for everyone - the exact cost the lag pass removed.
        local function syncKeySub()
                if _G.VX_ON_KEY then
                        _G.VX_ON_KEY("totalperfect", (swapOn or perfectOn) and function(kc)
                                if kc==Enum.KeyCode.Q then onMySwapInput("Dash") end
                                onMoveKey(kc)
                        end or nil)
                end
                if _G.VX_M1_SUB then
                        _G.VX_M1_SUB("totalswap", (swapOn and trigM1 and trigWho~="Them")
                                and function() onMySwapInput("M1") end or nil)
                end
        end


        -- ═══════════════════════ CHARACTER CHANGER ═══════════════════════
        -- JoinService.RE.Change:FireServer("Gojo")
        -- The name list comes from the SERVICE names, as asked. Every playable character owns a <Name>Service with
        -- RE.Activated - but so do a few MOVE services (SwiftKickService, BruteForceService...), and the system
        -- services obviously are not characters. So: start from the known roster, keep the ones whose service is
        -- really there, then add any other <Name>Service that has RE.Activated and is not an obvious non-character.
        -- ═══ THESE ARE YOUR CAPTURES, VERBATIM ═══ Every name below came from a real
        -- JoinService.RE.Change:FireServer("<name>") you recorded, so each one is exactly the string the server
        -- compares against - no guessing, no spelling drift, nothing invented. That is why this list, and not a
        -- sweep of the services folder, is now the source for the dropdown: the services folder is mostly MOVE
        -- services (CursedBash, DecisiveStrike, ElbowRush...), which is what filled it with junk.
        -- Hanami / Ryu / Sukuna / Toji are gone: they were mine, not yours, and never appeared in a capture.
        local KNOWN = {
                "Gojo", "Itadori", "Hakari", "Megumi", "Mahito", "Choso", "Todo", "Hiromi", "Yuta",
                "Mechamaru", "Naoya", "Nanami",
                -- early access, from the same captures
                "Kurourushi", "MeiMei", "Haruta", "Charles", "Yuki", "Locust",
        }
        local NOT_A_CHARACTER = {}
        -- Move services this file already resolves by name elsewhere - every one of them owns RE.Activated, so
        -- without listing them the sweep below happily offers "Block" and "Earthquake" as playable characters.
        for _, w in ipairs({ "block", "earthquake", "cursedstrikes", "roughenergy", "redscale", "rabbitescape",
                "reversalred", "reversalredmax", "lapseblue", "lapsebluemax", "crushingjaws", "nue", "twofoldkick",
                "divergentfist", "blackflash", "piercingblood", "bloodedge", "hollowpurple", "divinedog", "toad",
                -- Jawbreaker's four, read straight off the skill bar in your screenshot. The live-Moveset scan below
                -- catches these on its own whenever a Jawbreaker is in the server; listing them means the dropdown is
                -- clean even in an empty one.
                "ambush", "backstab", "trip", "cheapshot" }) do
                NOT_A_CHARACTER[w] = true
        end
        for _, w in ipairs({ "swiftkick", "bruteforce", "pebblethrow", "elbowdrop", "join", "anticheat", "movement",
                "emote", "data", "camera", "effect", "sound", "music", "round", "match", "lobby", "shop", "trade", "quest",
                "daily", "leaderboard", "chat", "notification", "ui", "replication", "ragdoll", "hitbox", "damage", "combat",
                "skill", "move", "animation", "particle", "vfx", "spectate", "report", "ban", "admin", "gamepass", "product",
                "purchase", "reward", "crate", "spin", "level", "stat", "title", "badge", "friend", "party", "server",
                "teleport", "region", "weather", "time", "player", "character", "input", "client", "network", "save",
                "setting", "settings", "tutorial", "codes", "code", "rank", "session", "analytics", "todoservice" }) do
                NOT_A_CHARACTER[w] = true
        end
        local function characterNames()
                local f = svcFolder()
                -- ═══ KNOWN FIRST, THEN THE REST ═══ The sweep can never be perfectly clean - any move that owns a
                -- service looks exactly like a character from here - so instead of relying on the blocklist being
                -- exhaustive, we fix the ORDER. Confirmed characters are sorted and listed first; anything the sweep
                -- turns up is sorted and appended after them. names[1] is then always a real character, which matters
                -- because it is the default for the death-character dropdown and the pre-selection for "Switch Now".
                -- (Previously the whole list was sorted together, so "Block" and "Earthquake" ranked ahead of
                -- "Charles" and the default pick was a move name the server just ignores - leaving you dead as the
                -- same character after a force reset.)
                local known, extra, seen = {}, {}, {}
                local function add(t, n) if n and n ~= "" and not seen[norm(n)] then seen[norm(n)] = true; t[#t + 1] = n end end
                local function join()
                        table.sort(known); table.sort(extra)
                        for _, n in ipairs(extra) do known[#known + 1] = n end
                        return known
                end
                -- The captured roster ALWAYS populates the list. It is ground truth - every name in it came from a
                -- real Change:FireServer you recorded - so it does not depend on the services folder being readable
                -- or on any heuristic being right.
                for _, n in ipairs(KNOWN) do add(known, n) end
                if not f then return join() end
                -- ═══ THE REAL SERVICE NAMES, FULL STOP ═══ A hardcoded roster can only ever list the characters that
                -- existed when it was written - it had no Jawbreaker, so Jawbreaker was unpickable, and no list I type
                -- out will survive the next update either. The services ARE the character list, and their names are
                -- the exact strings JoinService.Change compares against, so they cannot be misspelled by definition.
                --
                -- The one real problem with sweeping them is that MOVES own services too (SwiftKickService,
                -- AmbushService...), which is what padded the list with junk. Rather than guess from a fixed
                -- blocklist, we ASK THE GAME: every character standing in the server publishes its moves in
                -- <char>.Moveset, so anything named after a live move is a move service, not a character. That adapts
                -- on its own - a Jawbreaker in the server removes Ambush / Backstab / Trip / Cheap Shot from the list
                -- without anyone having to know they were moves.
                local liveMove = {}
                local function harvest(m)
                        local mv = m and m:FindFirstChild("Moveset")
                        if not mv then return end
                        for _, x in ipairs(mv:GetChildren()) do liveMove[norm(x.Name)] = true end
                end
                local chs = workspace:FindFirstChild("Characters")
                if chs then for _, m in ipairs(chs:GetChildren()) do harvest(m) end end
                for _, plr in ipairs(Players:GetPlayers()) do harvest(plr.Character) end
                -- Movesets we have already seen this session stay excluded even after that player leaves.
                _G.VX_TOTAL_SEENMOVES = _G.VX_TOTAL_SEENMOVES or {}
                for k in pairs(liveMove) do _G.VX_TOTAL_SEENMOVES[k] = true end
                for k in pairs(_G.VX_TOTAL_SEENMOVES) do liveMove[k] = true end

                -- ═══ THE DISCRIMINATOR, FROM YOUR OWN CAPTURES ═══ Your dropdown filled with CursedBash,
                -- DecisiveStrike, ElbowRush, DivinePummel... because this game has ONE SERVICE PER MOVE, hundreds of
                -- them, and they are indistinguishable from character services by name alone. But the captures show a
                -- difference in what they CONTAIN:
                --     TodoService.RE.RightActivated      <- character (the R ability)
                --     GojoService.RE.RightActivated      <- character
                --     SwiftKickService.RE.Activated      <- move: Activated and nothing else
                --     ReserveBallService.RE.Activated    <- move
                -- Every playable character has an R; a move service has no use for one. So a character service is one
                -- with BOTH Activated and RightActivated, and that single test removes every move in one go without
                -- needing to know a single move name. If the game ever breaks that pattern the roster fallback below
                -- still fills the list, so this cannot end up empty.
                -- The sweep is opt-in now. The roster above is captured ground truth and covers every character the
                -- game actually offers; the services folder is dominated by one service per MOVE, which is what put
                -- CursedBash and DecisiveStrike in your dropdown. Set _G.VX_TOTAL_ALLCHARS = true before loading if a
                -- game update adds someone the roster does not know yet.
                if _G.VX_TOTAL_ALLCHARS then
                        local strict = false
                        for _, s in ipairs(f:GetChildren()) do
                                local re = s:FindFirstChild("RE")
                                if re and re:FindFirstChild("RightActivated") and re:FindFirstChild("Activated") then strict = true break end
                        end
                        for _, s in ipairs(f:GetChildren()) do
                                local base = string.match(s.Name, "^(.-)Service$")
                                local re = s:FindFirstChild("RE")
                                local looksCharacter = re and re:FindFirstChild("Activated")
                                        and ((not strict) or re:FindFirstChild("RightActivated"))
                                if base and #base >= 3 and looksCharacter
                                        and not NOT_A_CHARACTER[norm(base)] and not liveMove[norm(base)] then
                                        -- Roster names go in the first group so the DEFAULT pick is always a character we are sure
                                        -- about; everything else the game offers is listed right after, in the game's own spelling.
                                        local isKnown = false
                                        for _, n in ipairs(KNOWN) do if norm(n) == norm(base) then isKnown = true break end end
                                        add(isKnown and known or extra, base)
                                end
                        end
                end
                if #known == 0 and #extra == 0 then for _, n in ipairs(KNOWN) do add(known, n) end end
                if _G.VX_TOTAL_DEBUG then
                        local all = {}
                        for _, s in ipairs(f:GetChildren()) do all[#all + 1] = s.Name end
                        table.sort(all)
                        pcall(function() print("[DreamHub Todo] every Knit service = { " .. table.concat(all, ", ") .. " }") end)
                end
                return join()
        end

        -- ═══ SAY WHY IT DID NOT WORK ═══ "switch character dont work" with nothing on screen is a dead end for
        -- both of us. If JoinService.RE.Change is not where we think it is, this now says so out loud once, and
        -- prints every remote the service DOES have so the right name can be read straight off your F9.
        local function changeRemote()
                local re = svcRE("JoinService", "Change")
                if re then return re end
                if tick() - (_G.VX_TOTAL_JOINWARN or 0) > 10 then
                        _G.VX_TOTAL_JOINWARN = tick()
                        local f = svcFolder()
                        local svc = f and f:FindFirstChild("JoinService")
                        pcall(function()
                                if not f then print("[DreamHub Todo] no Knit Services folder at all")
                                elseif not svc then
                                        local names = {}
                                        for _, s in ipairs(f:GetChildren()) do if string.find(string.lower(s.Name), "join", 1, true) or string.find(string.lower(s.Name), "select", 1, true) or string.find(string.lower(s.Name), "spawn", 1, true) then names[#names + 1] = s.Name end end
                                        print("[DreamHub Todo] there is NO JoinService. Closest matches = { " .. table.concat(names, ", ") .. " }  (send me this line)")
                                else
                                        local names = {}
                                        local r = svc:FindFirstChild("RE")
                                        if r then for _, x in ipairs(r:GetChildren()) do names[#names + 1] = x.Name end end
                                        print("[DreamHub Todo] JoinService exists but has no RE.Change. Its remotes = { " .. table.concat(names, ", ") .. " }  (send me this line)")
                                end
                        end)
                        if VX_NOTIFY then VX_NOTIFY("Character switch: remote not found - check F9", false) end
                end
                return nil
        end
        local lastChange = 0
        local function changeChar(name, why, bypassGap)
                if type(name) ~= "string" or name == "" or name == "Off" then return false end
                if not bypassGap and tick() - lastChange < 1.2 then return false end
                lastChange = tick()
                local re = changeRemote(); if not re then return false end
                local ok = pcall(function() re:FireServer(name) end)
                note("change character -> " .. name .. "  (" .. tostring(why) .. ")  ok=" .. tostring(ok))
                return ok
        end

        -- ═══ MID-BATTLE SWITCH ═══ The game only accepts a character pick while you are dead / at the select
        -- screen. Two attempts at fixed delays was a guess at when that screen appears, and if both landed
        -- outside the window the switch simply did not happen - which is "switch character dont work".
        -- Instead: kill, then keep sending the pick across the whole respawn window, and STOP as soon as it
        -- takes (your live character reports the name you asked for). Sending Change repeatedly at the select
        -- screen is what a player does when they click a portrait, so there is nothing unusual about it.
        local function amNow(name)
                local want = norm(name)
                for _, c in ipairs(myRigs()) do
                        local h = c:FindFirstChildOfClass("Humanoid")
                        if h and norm(h.DisplayName) == want then return true end
                end
                -- The reliable one: the same resolver the combo module uses to decide which <Char>Service is yours.
                -- It reads your Moveset, so it answers correctly even when the rig is named after the player.
                local ok, svc = pcall(vxMyCharSvc)
                return ok and svc == (name .. "Service")
        end
        local switchGen = 0
        local function switchNow(name)
                if type(name) ~= "string" or name == "" or name == "Off" then return end
                if not changeRemote() then return end            -- no remote: report once, do NOT kill the user for nothing
                if VX_NOTIFY then VX_NOTIFY("Switching to " .. name .. "...", true) end
                switchGen = switchGen + 1
                local myGen = switchGen
                if ResetApi and ResetApi.reset then pcall(ResetApi.reset) end
                task.spawn(function()
                        -- ═══ THE GAME TOLD US THE RULE ═══ "You're switching. Wait 2 seconds before retrying." Retrying
                        -- every 0.35s was not persistence, it was the reason nothing happened: each attempt landed inside
                        -- the previous one's cooldown and got refused, forever. RETRY_GAP is 2.5s - comfortably past the
                        -- game's own 2s - and we check for arrival continuously in between, so a switch that takes is
                        -- noticed immediately instead of waiting out the gap.
                        local RETRY_GAP = 2.5
                        local deadline = tick() + 14
                        local nextSend = 0
                        while tick() < deadline do
                                if switchGen ~= myGen then return end     -- a newer switch owns this now
                                if tick() >= nextSend then
                                        changeChar(name, "mid-battle", true)
                                        nextSend = tick() + RETRY_GAP
                                end
                                task.wait(0.2)
                                if amNow(name) then
                                        if VX_NOTIFY then VX_NOTIFY("Now playing " .. name, true) end
                                        return
                                end
                        end
                        note("switch to " .. name .. " never took - the name may not be what the server expects")
                        if VX_NOTIFY then VX_NOTIFY("Switch to " .. name .. " did not take", false) end
                end)
        end

        -- AUTO CHARACTER ON DEATH. JJS runs a custom health system and Humanoid.Died does not always fire, so we
        -- hook Died where we can AND poll the health as a backstop. One switch per death, via the edge flag.
        local deathOn, deathChar = false, nil
        local humHooked = setmetatable({}, { __mode = "k" })
        local deathGen = 0
        local function onDeath()
                if not (deathOn and deathChar) then return end
                if tick() - lastChange < 1.2 then return end
                -- Same treatment as the manual switch: two attempts at fixed delays was a guess at when the select
                -- screen appears. Keep sending across the respawn window and stop the moment it takes. No reset here -
                -- you are already dead, which is the whole point.
                deathGen = deathGen + 1
                local myGen, name = deathGen, deathChar
                task.spawn(function()
                        task.wait(0.5)
                        -- Same 2.5s spacing as the manual switch, for the same reason: the game answers a too-soon retry
                        -- with "Wait 2 seconds before retrying" and does nothing. Spamming it was why dying never put you
                        -- back on the character you picked.
                        local RETRY_GAP = 2.5
                        local deadline = tick() + 20     -- a death screen can sit for a while; keep offering the pick
                        local nextSend = 0
                        while tick() < deadline do
                                if deathGen ~= myGen or not deathOn then return end
                                if tick() >= nextSend then
                                        changeChar(name, "death", true)
                                        nextSend = tick() + RETRY_GAP
                                end
                                task.wait(0.2)
                                if amNow(name) then
                                        if VX_NOTIFY then VX_NOTIFY("Respawned as " .. name, true) end
                                        return
                                end
                        end
                        note("death switch to " .. name .. " never took")
                end)
        end
        task.spawn(function()
                local wasDead = false
                while true do
                        if deathOn and deathChar then
                                local m = myModel()
                                local h = m and m:FindFirstChildOfClass("Humanoid")
                                if h and not humHooked[h] then
                                        humHooked[h] = true
                                        pcall(function() h.Died:Connect(onDeath) end)
                                end
                                -- Only a live humanoid at 0 HP counts. Treating "no model" as death would fire every time the
                                -- rig is being rebuilt during a normal respawn.
                                local dead = (h ~= nil) and h.Health <= 0
                                if dead and not wasDead then onDeath() end
                                wasDead = dead
                                task.wait(0.25)
                        else
                                wasDead = false
                                task.wait(0.4)
                        end
                end
        end)

        TodoApi = {
                setSwap      = function(v) swapOn = v == true; syncKeySub(); if swapOn and not isTodo() then todoWarn() end end,
                setSwapMode  = function(v) v = (type(v) == "table") and v[1] or v; if type(v) == "string" then swapMode = v end end,   -- "Off" makes pickTarget return nothing, so nothing swaps
                setSwapRange = function(v) swapRange = tonumber(v) or swapRange end,
                setSwapCD    = function(v) swapCD = tonumber(v) or swapCD end,
                setTrigWho   = function(v) v = (type(v) == "table") and v[1] or v; if v == "Me" or v == "Them" or v == "Off" then trigWho = v; syncKeySub() end end,
                setTrigDash  = function(v) trigDash = v == true; syncKeySub() end,
                setTrigM1    = function(v) trigM1   = v == true; syncKeySub() end,
                setTrigDown  = function(v) trigDown = v == true end,
                setDashSpeed = function(v) DASH_SPEED = tonumber(v) or DASH_SPEED end,
                setPerfect   = function(v) perfectOn = v == true; syncKeySub(); if perfectOn then pcall(hookAnims) end end,   -- hook NOW, not up to a second from now, or the first cast after switching on is missed
                setPerfectDelay = function(v) perfectDelay = math.max(0, tonumber(v) or 0) end,
                swapNow      = function() return doSwap("manual", 0) end,
                isTodo       = isTodo,
        }
        CharSwapApi = {
                names       = characterNames,
                setDeath    = function(v) deathOn = v == true end,
                setDeathChar= function(v) v = (type(v) == "table") and v[1] or v; if type(v) == "string" then deathChar = v end end,
                getDeathChar= function() return deathChar end,
                switchNow   = switchNow,
                change      = function(n) return changeChar(n, "manual", true) end,
        }
end

-- ============================================================
-- Todo: arm animation observation before the user's input reaches the game.
do
    local UIS=game:GetService("UserInputService")
    local VIM=game:GetService("VirtualInputManager")
    local full,busy=false,false
    local generation,delay=0,0.30
    local lastInput={}
    -- The USER's own R / 2 stamps, so the full chain (3 -> R -> 2 -> 2) never doubles a press you made yourself.
    local userR,userTwo=0,0
    -- ═══ TODO DETECTION THAT CANNOT GO STALE ═══ "Auto total blacklist actually don't work." The chain asked
    -- TodoApi.isTodo() and silently returned when it said no - after a character swap (you swap constantly)
    -- the detection could disagree with the body actually holding Todo's moveset, and the whole chain died
    -- with no message. This falls back to reading YOUR OWN Moveset for Todo's four moves, and every refusal
    -- now says WHY on screen (throttled), so "doesn't work" can never again be silent.
    local lastWarn=0
    local function warnOnce(msg)
        if tick()-lastWarn<8 then return end
        lastWarn=tick()
        if VX_NOTIFY then pcall(function() VX_NOTIFY(msg,false) end) end
    end
    local function todo()
        if TodoApi and TodoApi.isTodo then
            local ok,r=pcall(TodoApi.isTodo); if ok and r then return true end
        end
        local me=vxMyChar(); local mv=me and me:FindFirstChild("Moveset")
        if mv then
            for _,m in ipairs(mv:GetChildren()) do
                local n=string.lower(tostring(m.Name or "")):gsub("[^%w]","")
                if n=="swiftkick" or n=="bruteforce" or n=="pebblethrow" or n=="elbowdrop" then return true end
            end
        end
        return false
    end
    local function start(all)
        if busy or _G.VX_COMBAT_OWNER or not todo() or UIS:GetFocusedTextBox() then return end
        local body=vxMyChar(); local root=body and body:FindFirstChild("HumanoidRootPart")
        local hum=body and body:FindFirstChildOfClass("Humanoid")
        local camera=workspace.CurrentCamera
        if not root or not hum or not camera then return end
        local victim,best=nil,30
        local lock=_G.VX_LOCK; local selected=lock and lock.get and lock.get()
        for _,model in ipairs(_G.VX_LIVING_MODELS()) do
            local r=model:FindFirstChild("HumanoidRootPart")
            if model~=body and model.Name~=game:GetService("Players").LocalPlayer.Name and r then
                local d=(root.Position-r.Position).Magnitude
                if d<=30 and (model==selected or not victim or victim~=selected and d<best) then victim,best=model,d end
            end
        end
        if not victim then _G.VX_TODO_BF_STATUS="no target within 30 studs"; return end
        local gen,origin,rotation=generation,root.Position,camera.CFrame.Rotation
        local owner={}; local recent,connections,candidates={},{},{}
        local startedAt=tick()
        local previousSuppress=tonumber(_G.VX_COMBAT_SUPPRESS_BF) or 0
        local suppress=tick()+4
        busy=true; _G.VX_TODO_BF_ACTIVE=true; _G.VX_COMBAT_OWNER=owner; _G.VX_COMBAT_SUPPRESS_BF=suppress
        local function live()
            local th=victim.Parent and victim:FindFirstChildOfClass("Humanoid")
            return gen==generation and full and body==vxMyChar() and hum.Health>0 and th and th.Health>0 and not UIS:GetFocusedTextBox()
        end
        local function aimAt(position)
            if workspace.CurrentCamera~=camera then return end
            camera.CFrame=CFrame.lookAt(camera.CFrame.Position,position)
            local point,visible=camera:WorldToScreenPoint(position)
            if visible then VIM:SendMouseMoveEvent(point.X,point.Y,game) end
        end
        local function tap(key)
            if not live() or _G.VX_KEY_BLOCKED and _G.VX_KEY_BLOCKED(key) then return false end
            _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[key]=tick()+0.25
            VIM:SendKeyEvent(false,key,false,game); task.wait(0.025)
            if not live() then return false end
            VIM:SendKeyEvent(true,key,false,game); task.wait(0.035)
            VIM:SendKeyEvent(false,key,false,game)
            return true
        end
        local function capture(track)
            local id=tostring(track.Animation and track.Animation.AnimationId or ""):match("%d+")
            if not track.Looped and tostring(track.Priority):find("Action",1,true) and not (_G.VX_M1_IDS and _G.VX_M1_IDS[id]) then
                table.insert(recent,{track=track,at=tick()})
            end
        end
        local animator=hum:FindFirstChildOfClass("Animator")
        if animator then table.insert(connections,animator.AnimationPlayed:Connect(capture)) end
        local function candidate(object)
            if not object:IsA("BasePart") or object:IsDescendantOf(body) then return end
            local n=(object.Name.." "..(object.Parent and object.Parent.Name or "")):lower()
            if not n:find("pebble",1,true) or (object.Position-origin).Magnitude>14 then return end
            -- Only a newly spawned projectile close to this cast can be selected.
            table.insert(candidates,object)
        end
        table.insert(connections,workspace.DescendantAdded:Connect(candidate))
        local function waitFor(check,budget,message)
            local deadline=tick()+budget
            repeat
                if not live() then return false end
                if check() then return true end
                task.wait()
            until tick()>=deadline
            _G.VX_TODO_BF_STATUS=message
            return false
        end
        task.defer(function()
            local ok,err=pcall(function()
                local pebble
                if not waitFor(function()
                    for _,part in ipairs(candidates) do
                        if part.Parent and part.AssemblyLinearVelocity.Magnitude>6 then pebble=part; return true end
                    end
                    return false
                end,1.4,"moving pebble not observed; no blind R sent") then return end
                local rAt=tick()
                -- Swap BEFORE the pebble hits: this is what starts Blazing Star.
                if userR<startedAt then
                    aimAt(pebble.Position)
                    if not tap(Enum.KeyCode.R) then return end
                else rAt=userR end
                if not waitFor(function()
                    local v=root.AssemblyLinearVelocity
                    local moving=Vector3.new(v.X,0,v.Z).Magnitude>=35
                    if not moving then return false end
                    for _,entry in ipairs(recent) do if entry.at>=rAt and entry.track.IsPlaying then return true end end
                    return false
                end,0.9,"Blazing Star not observed after R") then return end
                local targetRoot=victim:FindFirstChild("HumanoidRootPart")
                if not targetRoot then return end
                aimAt(targetRoot.Position+Vector3.new(0,0.8,0))
                local castAt=tick(); local previousTracks=#recent
                if userTwo<rAt then
                    if not tap(Enum.KeyCode.Two) then return end
                else castAt=userTwo; previousTracks=0 end
                local kickAt
                if not waitFor(function()
                    for i=previousTracks+1,#recent do
                        if recent[i].at>=castAt and recent[i].track.IsPlaying then kickAt=recent[i].at; return true end
                    end
                    return false
                end,0.65,"Brutal Impact animation not observed") then return end
                local due=kickAt+delay
                while live() and tick()<due do
                    aimAt(targetRoot.Position+Vector3.new(0,0.8,0)); task.wait()
                end
                if not live() or tick()-due>0.12 then return end
                if userTwo>castAt+0.06 then _G.VX_TODO_BF_STATUS="manual kick follow-up preserved"; return end
                if tap(Enum.KeyCode.Two) then _G.VX_TODO_BF_STATUS="kick follow-up sent; Black Flash unconfirmed" end
            end)
            for _,connection in ipairs(connections) do connection:Disconnect() end
            for _,key in ipairs({Enum.KeyCode.R,Enum.KeyCode.Two}) do pcall(function() VIM:SendKeyEvent(false,key,false,game) end) end
            if workspace.CurrentCamera==camera then camera.CFrame=CFrame.new(camera.CFrame.Position)*rotation end
            if _G.VX_COMBAT_OWNER==owner then _G.VX_COMBAT_OWNER=nil end
            if _G.VX_COMBAT_SUPPRESS_BF==suppress then _G.VX_COMBAT_SUPPRESS_BF=previousSuppress end
            busy=false; _G.VX_TODO_BF_ACTIVE=false
            if not ok then warn("[DreamHub Todo BF] "..tostring(err)) end
        end)
    end

    -- ═══ THE AUTO TAP, THE REAL ONE ═══ "you just click three. And when that pebble - the third move,
    -- Pebble Throw - LANDS on the target, then you click R. That's all you do." NOT a 3+R spam loop. On
    -- your 3 this watches the target for the landing (a hit track starts on them / they jolt / they drop)
    -- and fires exactly ONE R on that beat. A distance-based flight time is the fallback so R still lands
    -- even if the hit signal is missed. (full Black Flash mode owns key 3 first - this yields to it.)
    local pebBusy=false
    local function startPebble()
        if pebBusy or full or not (TodoBFApi and TodoBFApi.tapLoopOn) then return end
        pebBusy=true
        task.spawn(function()
            local okP,errP=pcall(function()
                local LP2=game:GetService("Players").LocalPlayer
                local g2=_G.VX_LOCK; local tgt=(g2 and g2.get and g2.get()) or nil
                local chs=workspace:FindFirstChild("Characters")
                local me=(chs and chs:FindFirstChild(LP2.Name)) or LP2.Character
                local mr=me and me:FindFirstChild("HumanoidRootPart")
                if not (tgt and tgt.Parent) and mr then
                    local best,bd=nil,45
                    for _,m in ipairs((chs or workspace):GetChildren()) do
                        if m:IsA("Model") and m~=me and m.Name~=LP2.Name then
                            local r=m:FindFirstChild("HumanoidRootPart"); local h=m:FindFirstChildOfClass("Humanoid")
                            if r and h and h.Health>0 then local d=(r.Position-mr.Position).Magnitude if d<bd then best,bd=m,d end end
                        end
                    end
                    tgt=best
                end
                local tr=tgt and tgt:FindFirstChild("HumanoidRootPart")
                if not (tgt and tr and mr) then return end
                local th=tgt:FindFirstChildOfClass("Humanoid")
                local ta=th and th:FindFirstChildOfClass("Animator")
                local flight=0.5+((tr.Position-mr.Position).Magnitude)/110   -- pebble flight estimate
                local t0=tick(); local landed=false
                while tick()-t0<1.8 and (TodoBFApi and TodoBFApi.tapLoopOn) and not full do
                    if not (tgt.Parent and tr.Parent) then break end
                    if ta then
                        -- ═══ THEIR HIT-REACTION, NOT THEIR OWN MOVE ═══ ANY Action track on the target counted
                        -- as "pebble landed", so a target casting or dashing mid-flight fired a stray R while
                        -- you were running ("I move so I have to turn auto to black flash off"). The reaction
                        -- trigger now requires them to be roughly STATIONARY (a hit-stun), and the jolt trigger
                        -- is raised above any dash speed. The ragdoll/flight fallbacks are untouched.
                        local tv=tr.AssemblyLinearVelocity
                        local tvFlat=Vector3.new(tv.X,0,tv.Z).Magnitude
                        if tvFlat<28 then
                            local okT,tracks=pcall(function() return ta:GetPlayingAnimationTracks() end)
                            if okT and tracks then
                                for _,t2 in ipairs(tracks) do
                                    local okp,p2,tp2=pcall(function() return tostring(t2.Priority),t2.TimePosition end)
                                    if okp and string.find(p2,"Action",1,true) and tp2<0.15 then landed=true break end
                                end
                            end
                        end
                    end
                    if not landed then
                        local v=tr.AssemblyLinearVelocity
                        if v.Magnitude>60 then landed=true end
                        local okS,st=pcall(function() return th:GetState() end)
                        if okS and (st==Enum.HumanoidStateType.Ragdoll or st==Enum.HumanoidStateType.Physics or st==Enum.HumanoidStateType.FallingDown) then landed=true end
                    end
                    if not landed and tick()-t0>=flight then landed=true end   -- clock fallback
                    if landed and tick()-t0<0.12 then landed=false end   -- never R the instant the 3 leaves
                    if landed then break end
                    task.wait(0.03)
                end
                if landed and (TodoBFApi and TodoBFApi.tapLoopOn) and not full and not UIS:GetFocusedTextBox() then
                    _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.R]=tick()+0.25
                    VIM:SendKeyEvent(false,Enum.KeyCode.R,false,game); task.wait(0.025)
                    VIM:SendKeyEvent(true,Enum.KeyCode.R,false,game); task.wait(0.05)
                    VIM:SendKeyEvent(false,Enum.KeyCode.R,false,game)
                end
            end)
            pebBusy=false
            if not okP then warn("[DreamHub Todo] "..tostring(errP)) end
        end)
    end
    local function key(k)
        -- ═══ STAMP YOUR PRESSES FIRST ═══ even while a chain is busy, your own R / 2 count as the chain's step -
        -- without this the full chain fired its own R/2 ON TOP of yours ("just click one at a time").
        local injNow=_G.VX_INJ_KEYS and _G.VX_INJ_KEYS[k] and tick()<_G.VX_INJ_KEYS[k]
        if not injNow and not UIS:GetFocusedTextBox() and todo() then
            if k==Enum.KeyCode.R then userR=tick() elseif k==Enum.KeyCode.Two then userTwo=tick() end
        end
        if not (full or (TodoBFApi and TodoBFApi.tapLoopOn)) or busy or UIS:GetFocusedTextBox() or not todo() then return end
        if _G.VX_KEY_BLOCKED and _G.VX_KEY_BLOCKED(k) then return end
        if _G.VX_INJ_KEYS and tick()<(_G.VX_INJ_KEYS[k] or 0) then return end
        if tick()-(lastInput[k] or -math.huge)<0.12 then return end
        lastInput[k]=tick()
        if k==Enum.KeyCode.Three and full then start(true)
        elseif k==Enum.KeyCode.Three and not full then startPebble() end   -- Auto Tap: 3 -> pebble lands -> R
    end
    UIS.InputBegan:Connect(function(input) key(input.KeyCode) end)
    pcall(function()
        game:GetService("ContextActionService"):BindActionAtPriority("VX_TodoBFInput",function(_,state,input)
            if state==Enum.UserInputState.Begin then key(input.KeyCode) end
            return Enum.ContextActionResult.Pass
        end,false,4400,Enum.KeyCode.Three,Enum.KeyCode.R,Enum.KeyCode.Two)
    end)
    if _G.VX_ON_KEY then _G.VX_ON_KEY("todoBF",key) end
    TodoBFApi={
        set=function(v) full=v==true; _G.VX_TODO_BF_ON=full; generation+=1; table.clear(lastInput) end,
        setDelay=function(v) delay=math.clamp(tonumber(v) or 0.30,0.1,1.2) end,
        -- ═══ AUTO TAP (3 -> R when the pebble lands) ═══ the old "3+R loop" hammered both keys on a timer,
        -- which cast Pebble Throw repeatedly and swapped you backwards mid-swing. The loop is GONE: this flag
        -- only arms the watcher, and the watcher (above) taps R exactly ONCE on the pebble's landing beat.
        tapLoopOn=false,
        setTapLoop=function(v) TodoBFApi.tapLoopOn=v==true end,
    }
end

-- ============================================================
-- MODULE: TODO DROP  (was "Todo Draw" - renamed) "Rename Todo Draw with Todo Drop. And Todo Drop, I want
-- it to start AFTER. After is a keyword. After I do an uppercut and after I do a down slam - so not during
-- my fourth M1."
-- DETECTION: the shared __namecall observer stamps _G.VX_UPPER_T / _G.VX_DOWN_T the instant YOUR
-- <Char>Service.RE.Activated("Up"/"Down") leaves for the server - manual finishers, the hub's Auto
-- Upper/Slam and the finisher assists all produce them, so every path is covered.
-- TIMING IS **AFTER**, NOT DURING: the uppercut branch no longer fires the elbow drop 0.35s after the
-- launch request (that was DURING the 4th M1). It waits until the uppercut has actually finished its
-- work - the target is up in the air AND the swing is done - then drops. The down-slam branch already
-- waited (slider, default 2.5s) - unchanged.
-- ============================================================
do
    local VIM=game:GetService("VirtualInputManager")
    local UIS=game:GetService("UserInputService")
    local on,slamDelay,lastUp,lastDown,lastFired=false,2.5,0,0,0
    local function isTodoChar()
        if TodoApi and TodoApi.isTodo then
            local ok,r=pcall(TodoApi.isTodo); if ok and r then return true end
        end
        local me=vxMyChar(); local n=me and detectCharName and detectCharName(me)
        return type(n)=="string" and string.lower(n):find("todo",1,true)~=nil
    end
    local function launchTarget()  -- who the uppercut hit: the locked target, else the nearest living body
        local g=_G.VX_LOCK; local t=(g and g.get) and g.get() or nil
        local me=vxMyChar(); local mr=me and me:FindFirstChild("HumanoidRootPart")
        if not (t and t.Parent and t:FindFirstChild("HumanoidRootPart")) and mr then
            local best,bd=nil,14
            local chs=workspace:FindFirstChild("Characters")
            for _,m in ipairs((chs or workspace):GetChildren()) do
                if m:IsA("Model") and m~=me and m.Name~=game:GetService("Players").LocalPlayer.Name then
                    local r=m:FindFirstChild("HumanoidRootPart"); local h=m:FindFirstChildOfClass("Humanoid")
                    if r and h and h.Health>0 then local d=(r.Position-mr.Position).Magnitude if d<bd then best,bd=m,d end end
                end
            end
            t=best
        end
        return (t and t.Parent) and t or nil
    end
    local function aimDropTarget()
        local target=launchTarget(); local r=target and target:FindFirstChild("HumanoidRootPart")
        local camera=workspace.CurrentCamera
        if r and camera then camera.CFrame=CFrame.lookAt(camera.CFrame.Position,r.Position+Vector3.new(0,0.5,0)) end
    end
    local function pressFour()
        if UIS:GetFocusedTextBox() then return end
        if _G.VX_KEY_BLOCKED and _G.VX_KEY_BLOCKED(Enum.KeyCode.Four) then return end
        _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {}
        _G.VX_INJ_KEYS[Enum.KeyCode.Four]=tick()+0.4
        pcall(function()
            VIM:SendKeyEvent(false,Enum.KeyCode.Four,false,game); task.wait(0.025)
            VIM:SendKeyEvent(true,Enum.KeyCode.Four,false,game); task.wait(0.06)
            VIM:SendKeyEvent(false,Enum.KeyCode.Four,false,game)
        end)
    end
    task.spawn(function()
        while true do
            if on and isTodoChar() and not UIS:GetFocusedTextBox() then
                local now=tick()
                local up=tonumber(_G.VX_UPPER_T) or 0
                local down=tonumber(_G.VX_DOWN_T) or 0
                if up>lastUp then
                    lastUp=up
                    if now-lastFired>3.5 and now-up<1.0 then
                        lastFired=now
                        if VX_NOTIFY then pcall(function() VX_NOTIFY("Todo Drop: uppercut",true) end) end
                        task.spawn(function()
                            if on then
                                local camera=workspace.CurrentCamera; local rotation=camera and camera.CFrame.Rotation
                                aimDropTarget(); pressFour()
                                if camera and rotation and workspace.CurrentCamera==camera then camera.CFrame=CFrame.new(camera.CFrame.Position)*rotation end
                            end
                        end)
                    end
                elseif down>lastDown then
                    lastDown=down
                    if now-lastFired>3.5 and now-down<1.0 then
                        lastFired=now
                        if VX_NOTIFY then pcall(function() VX_NOTIFY(string.format("Todo Drop: down slam -> elbow drop in %.1fs",slamDelay),true) end) end
                        task.delay(slamDelay,function() if on then pressFour() end end)
                    end
                end
            else
                lastUp=tonumber(_G.VX_UPPER_T) or 0; lastDown=tonumber(_G.VX_DOWN_T) or 0
            end
            task.wait(0.05)
        end
    end)
    TodoDrawApi={
        set=function(v) on=v==true; lastUp=tonumber(_G.VX_UPPER_T) or 0; lastDown=tonumber(_G.VX_DOWN_T) or 0 end,
        setSlamDelay=function(v) slamDelay=math.clamp(tonumber(v) or 2.5,1,4) end,
    }
end

-- MODULE: JUMP ON HEAD -- real takeoff, then steer toward the target's head.
do
    local LP=game:GetService("Players").LocalPlayer
    local RS=game:GetService("RunService")
    local UIS=game:GetService("UserInputService")
    local VIM=game:GetService("VirtualInputManager")
    local busy=false
    local function resolve(name)
        local c=vxMyChar(); local root=c and c:FindFirstChild("HumanoidRootPart")
        if not root then return end
        local selected=_G.VX_LOCK and _G.VX_LOCK.get and _G.VX_LOCK.get()
        local best,range=nil,20
        for _,t in ipairs(_G.VX_LIVING_MODELS()) do
            local r=t:FindFirstChild("HumanoidRootPart"); local h=t:FindFirstChildOfClass("Humanoid")
            if t~=c and r and h and h.Health>0 then
                local d=(root.Position-r.Position).Magnitude
                if d<=20 and (t==name or t.Name==name or (name=="Nearest" or not name) and t==selected) then return t end
                if d<range then best,range=t,d end
            end
        end
        return best
    end
    JumpHeadApi={jump=function(name)
        if busy or _G.VX_COMBAT_OWNER or UIS:GetFocusedTextBox() then return false end
        local t=resolve(name); local c=vxMyChar()
        local head=t and (t:FindFirstChild("Head") or t:FindFirstChild("HumanoidRootPart"))
        local h=c and c:FindFirstChildOfClass("Humanoid"); local root=c and c:FindFirstChild("HumanoidRootPart")
        if not head or not h or not root or h.Health<=0 then return false end
        busy=true; local owner={}; _G.VX_COMBAT_OWNER=owner
        task.spawn(function()
            local camera=workspace.CurrentCamera; local rotation=camera and camera.CFrame.Rotation
            local ok,err=pcall(function()
                _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Space]=tick()+0.3
                VIM:SendKeyEvent(false,Enum.KeyCode.Space,false,game)
                VIM:SendKeyEvent(true,Enum.KeyCode.Space,false,game)
                h.Jump=true; h:ChangeState(Enum.HumanoidStateType.Jumping)
                task.wait(0.04); VIM:SendKeyEvent(false,Enum.KeyCode.Space,false,game)
                local deadline=tick()+0.9; local airborne=false
                while tick()<deadline and vxMyChar()==c and h.Health>0 and head.Parent and not UIS:GetFocusedTextBox() do
                    local delta=head.Position-root.Position; local flat=Vector3.new(delta.X,0,delta.Z)
                    h:Move(flat.Magnitude>0.45 and flat.Unit or Vector3.zero,false)
                    if camera and workspace.CurrentCamera==camera then camera.CFrame=CFrame.lookAt(camera.CFrame.Position,head.Position) end
                    if h.FloorMaterial==Enum.Material.Air then airborne=true end
                    if flat.Magnitude<0.6 and airborne and h.FloorMaterial~=Enum.Material.Air then break end
                    RS.Heartbeat:Wait()
                end
            end)
            pcall(function() h:Move(Vector3.zero,false); VIM:SendKeyEvent(false,Enum.KeyCode.Space,false,game) end)
            if camera and rotation and workspace.CurrentCamera==camera then camera.CFrame=CFrame.new(camera.CFrame.Position)*rotation end
            if _G.VX_COMBAT_OWNER==owner then _G.VX_COMBAT_OWNER=nil end
            busy=false
            if not ok then warn("[DreamHub Head Jump] "..tostring(err)) end
        end)
        return true
    end}
end

-- MODULE: SPECIAL ULTS  (Auto Ult Head of Hei: your M1 -> press G | Auto Rika Love Sword: inside a domain, slash 4 users then press 4)
-- ============================================================
do
        local Players = game:GetService("Players")
        local VIM = game:GetService("VirtualInputManager")
        local LP = Players.LocalPlayer
        local headOn, swordOn = false, false
        local SWORD_ANIM = "rbxassetid://72914783159396"         -- Rika love-ladder sword slash
        local function myModel() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
        local function myHRP() local m = myModel(); return m and m:FindFirstChild("HumanoidRootPart") end
        local function animatorOf() local m = myModel(); local h = m and m:FindFirstChildOfClass("Humanoid"); return h and h:FindFirstChildOfClass("Animator") end
        local function play(id) local a = animatorOf(); if not a then return end local anim = Instance.new("Animation"); anim.AnimationId = id; local ok, t = pcall(function() return a:LoadAnimation(anim) end); if ok and t then pcall(function() t:Play() end) end end
        local function pressKey(kc) pcall(function() VIM:SendKeyEvent(true, kc, false, game); task.wait(0.05); VIM:SendKeyEvent(false, kc, false, game) end) end

        -- AUTO ULT HEAD OF HEI: when YOUR character plays an M1 ANIMATION (any character's M1 id, shared via _G.VX_M1_IDS) -> press G to ult. Anim-based = fires on a real M1 (incl. hitting the dummy), not just a raw click.
        local UIS = game:GetService("UserInputService")
        local HEI_LEAD = 0.26    -- press G as the M1 CONNECTS; adjustable in the UI ('Hei Ult Timing' slider).
        local heiCd, heiGeneration = 0, 0
        local function heiFire()
                if tick() - heiCd < 1.2 then return end
                heiCd = tick()
                local gen, body = heiGeneration, myModel()
                task.delay(HEI_LEAD, function()
                    local h = body and body:FindFirstChildOfClass("Humanoid")
                    if gen ~= heiGeneration or not headOn or body ~= myModel() or not h or h.Health <= 0 then return end
                    if _G.VX_BF_CHAINDRIVE and tick() < _G.VX_BF_CHAINDRIVE then return end
                    pressKey(Enum.KeyCode.G)
                end)
        end
        local heiHooked = setmetatable({}, { __mode = "k" })
        local function hookHei()
                local a = animatorOf(); if not a or heiHooked[a] then return end
                heiHooked[a] = a.AnimationPlayed:Connect(function(track)
                        if not headOn then return end
                        if _G.VX_IS_M1 and _G.VX_IS_M1(track) then heiFire() end  -- strict: real M1 swings only
                end)
        end
        task.spawn(function() while true do if headOn then hookHei() end task.wait(0.7) end end)
        -- G is pressed ONLY off the detected M1 ANIMATION (any character's M1 id) + a 1.2s cooldown = one timed G per
        -- M1 swing, not a spam. (Removed the raw-click backup, which fired G on every click incl. GUI clicks.)
        HeadUltApi = { set = function(v) headOn = v == true; heiGeneration = heiGeneration + 1 end, setLead = function(v) HEI_LEAD = math.clamp(tonumber(v) or 0.26, 0.05, 0.6) end }

        local function findSwords()  -- ONLY the exact "Sword" objects at workspace.Domains.Domain.DomainCollider.Sword (NOT the "long" swords)
                local domains = workspace:FindFirstChild("Domains"); if not domains then return {} end
                local list = {}
                local dom = domains:FindFirstChild("Domain"); local coll = dom and dom:FindFirstChild("DomainCollider")
                if coll then for _, d in ipairs(coll:GetChildren()) do if d.Name == "Sword" then list[#list + 1] = d end end end   -- exact name = only these swords, not longs
                if #list == 0 then for _, d in ipairs(domains:GetDescendants()) do if d.Name == "Sword" then list[#list + 1] = d end end end  -- fallback if the domain nests differently
                return list
        end
        local function swordPos(s)
                if s:IsA("BasePart") then return s.Position end
                local ok, cf = pcall(function() return s:GetPivot() end); if ok and cf then return cf.Position end
                local p = s:FindFirstChildWhichIsA("BasePart", true); return p and p.Position
        end
        local function grabSword(sword)  -- EQUIP the sword: if it's a Tool -> EquipTool/reparent to your character; also fire any ProximityPrompt / ClickDetector / Touched so the pickup registers
                local hrp = myHRP(); if not hrp then return end
                local m = myModel(); local hum = m and m:FindFirstChildOfClass("Humanoid")
                local tool = (sword:IsA("Tool") and sword) or sword:FindFirstChildWhichIsA("Tool")
                if tool and m then pcall(function() if hum then hum:EquipTool(tool) else tool.Parent = m end end) end
                local parts = sword:IsA("BasePart") and { sword } or sword:GetDescendants()
                for _, d in ipairs(parts) do
                        pcall(function()
                                if d:IsA("ProximityPrompt") and fireproximityprompt then fireproximityprompt(d) end
                                if d:IsA("ClickDetector") and fireclickdetector then fireclickdetector(d) end
                                if d:IsA("BasePart") and firetouchinterest then firetouchinterest(hrp, d, 0); task.wait(); firetouchinterest(hrp, d, 1) end
                        end)
                end
        end
        local function nearbyEnemies()  -- living enemies near you (you are standing in the domain)
                local hrp = myHRP(); if not hrp then return {} end
                local list = {}
                local function chk(m) if m and m.Name ~= LP.Name and m ~= LP.Character then local r = m:FindFirstChild("HumanoidRootPart"); local h = m:FindFirstChildOfClass("Humanoid"); if r and (not h or h.Health > 0) and (r.Position - hrp.Position).Magnitude <= 220 then list[#list + 1] = m end end end
                for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP then chk(plr.Character) end end
                local chs = workspace:FindFirstChild("Characters"); if chs then for _, m in ipairs(chs:GetChildren()) do chk(m) end end
                return list
        end
        local function domainActive() local d = workspace:FindFirstChild("Domains"); if d then for _, ch in ipairs(d:GetChildren()) do if ch:IsA("Model") or ch:IsA("Folder") then return true end end end return false end
        local function note(msg) if VX_NOTIFY then pcall(function() VX_NOTIFY(msg, nil) end) end end  -- shows only when Debug is on
        local busy = false
        task.spawn(function()
                while true do
                        if swordOn and not busy and (domainActive() or #findSwords() > 0) then   -- run when you are inside a domain (swords present)
                                busy = true
                                task.spawn(function()
                                        local hits = 0
                                        local swords = findSwords()
                                        note("Rika: " .. tostring(#swords) .. " swords found")
                                        -- LOCK ON one target (nearest user) for the whole barrage - every slash goes to THEM
                                        local hrp0 = myHRP(); local users = nearbyEnemies()
                                        if #users == 0 or not hrp0 then note("Rika: no users near"); task.wait(0.5); busy = false; return end
                                        local target, td
                                        for _, u in ipairs(users) do local r = u:FindFirstChild("HumanoidRootPart"); if r then local dd = (r.Position - hrp0.Position).Magnitude; if not td or dd < td then target, td = u, dd end end end
                                        if _G.VX_LOCK and _G.VX_LOCK.set then pcall(function() _G.VX_LOCK.set(target) end) end; note("Rika: locked " .. (target and target.Name or "?"))
                                        -- GRAB every sword (up to 30) and slash the LOCKED target with each one
                                        local n = math.min(#swords, 30)
                                        for i = 1, n do
                                                if not swordOn or not (target and target.Parent) then break end
                                                local sw = swords[i]; local sp = sw and sw.Parent and swordPos(sw)
                                                if sp then vxGlide(sp + Vector3.new(0, 3, 0)); task.wait(0.14); grabSword(sw) end   -- grab this sword
                                                if not swordOn then break end
                                                local r = target:FindFirstChild("HumanoidRootPart")
                                                if r then
                                                        local ang = i * 1.4; local off = Vector3.new(math.cos(ang), 0, math.sin(ang)) * 4   -- CIRCLE around them so slashes land from every angle = breaks their block
                                                        vxGlide(CFrame.lookAt(r.Position + off + Vector3.new(0, 2, 0), r.Position)); task.wait(0.05); play(SWORD_ANIM); hits = hits + 1
                                                end
                                                task.wait(0.2)
                                        end
                                        if swordOn and hits > 0 then pressKey(Enum.KeyCode.Four) end                -- finish: press 4
                                        note("Rika: done, " .. hits .. " slashes")
                                        task.wait(1.2)
                                        busy = false
                                end)
                        end
                        task.wait(0.3)
                end
        end)
        RikaSwordApi = { set = function(v) swordOn = v == true; if not swordOn and _G.VX_LOCK and _G.VX_LOCK.set then pcall(function() _G.VX_LOCK.set(nil) end) end end }  -- clear the red outline when turned off
end

-- ============================================================
-- MODULE: AUTO RIKA DOWN SLAM  (toggle - near a target / the locked target: press R, then press 2)
-- ============================================================
do
        local Players = game:GetService("Players")
        local VIM = game:GetService("VirtualInputManager")
        local LP = Players.LocalPlayer
        local on, last = false, 0
        local function myHRP() local chs = workspace:FindFirstChild("Characters"); local c = (chs and chs:FindFirstChild(LP.Name)) or LP.Character; return c and c:FindFirstChild("HumanoidRootPart") end
        local function targetNear()  -- near an enemy/dummy OR the locked target, within ~16 studs
                local hrp = myHRP(); if not hrp then return false end
                local function isNear(m) if m and m.Name ~= LP.Name and m ~= LP.Character then local r = m:FindFirstChild("HumanoidRootPart"); local h = m:FindFirstChildOfClass("Humanoid"); return r ~= nil and (not h or h.Health > 0) and (r.Position - hrp.Position).Magnitude <= 16 end return false end
                local g = _G.VX_LOCK; local lt = (g and g.get) and g.get() or nil; if lt and isNear(lt) then return true end  -- the locked target
                for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP and isNear(plr.Character) then return true end end
                local chs = workspace:FindFirstChild("Characters"); if chs then for _, m in ipairs(chs:GetChildren()) do if isNear(m) then return true end end end
                return false
        end
        local function press(kc) pcall(function() VIM:SendKeyEvent(true, kc, false, game); task.wait(0.05); VIM:SendKeyEvent(false, kc, false, game) end) end
        task.spawn(function()
                while true do
                        if on and tick() - last > 1.2 and targetNear() then
                                last = tick()
                                press(Enum.KeyCode.R)     -- 1) press R
                                task.wait(0.12)
                                press(Enum.KeyCode.Two)   -- 2) then press 2 = the down slam
                        end
                        task.wait(0.1)
                end
        end)
        SlamApi = { set = function(v) on = v == true end }
end

-- ============================================================
-- MODULE: GOKU M1  (toggle - when YOU play an M1, instant-transmission BEHIND the nearest enemy/dummy with a Goku pose + sound)
-- ============================================================
do
        local Players = game:GetService("Players")
        local Debris = game:GetService("Debris")
        local LP = Players.LocalPlayer
        local on, last = false, 0
        -- ═══ REAL ANIMATIONS, TRIED IN ORDER ═══ "Can you add real animations for Goku and make it more
        -- nice? Just research some." Community animation ids are usually private and silently fail to
        -- load, so the pose is a CHAIN: the game's own captured flying-kick (reads exactly like an IT
        -- strike), then public Roblox-owned catalog emotes, then the old pose as the guaranteed fallback.
        -- The first id that LOADS wins, so this can never end up with no animation at all.
        local GOKU_ANIMS = {
                "rbxassetid://104749346956269",   -- in-game flying kick (captured, loads)
                "rbxassetid://507770677",         -- Roblox-owned catalog emote (public)
                "rbxassetid://507771019",         -- Roblox-owned dance (public)
                "rbxassetid://96489184596023",    -- the original pose (guaranteed fallback)
        }
        local GOKU_SOUND = ""  -- <<< put your Goku SFX asset id here, e.g. "rbxassetid://123..."; empty = no sound until you give me the id
        local function myModel() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
        local function myHRP() local m = myModel(); return m and m:FindFirstChild("HumanoidRootPart") end
        local function animatorOf()  -- your Animator (under Humanoid OR AnimationController)
                local m = myModel(); if not m then return nil end
                local h = m:FindFirstChildOfClass("Humanoid") or m:FindFirstChildOfClass("AnimationController")
                return h and h:FindFirstChildOfClass("Animator")
        end
        local function note(msg) if VX_NOTIFY then pcall(function() VX_NOTIFY(msg, nil) end) end end  -- shows only with Debug on
        local function playGoku()
                task.spawn(function()
                        local a; for _ = 1, 5 do a = animatorOf(); if a then break end task.wait(0.06) end  -- wait out the teleport for the animator to be ready
                        if not a then note("Goku: no animator"); return end
                        pcall(function() for _, tr in ipairs(a:GetPlayingAnimationTracks()) do local p = tr.Priority; if p == Enum.AnimationPriority.Action or p == Enum.AnimationPriority.Action4 then tr:Stop(0.05) end end end)  -- clear the M1 anim so the pose isn't buried
                        -- try the chain until one animation actually loads
                        local t
                        for _, id in ipairs(GOKU_ANIMS) do
                                local anim = Instance.new("Animation"); anim.AnimationId = id
                                local ok, tr = pcall(function() return a:LoadAnimation(anim) end)
                                if ok and tr then t = tr; note("Goku: pose " .. id); break end
                        end
                        if not t then note("Goku: every pose id failed to load"); return end
                        pcall(function() t.Priority = Enum.AnimationPriority.Action4; t:Play(0.1) end)
                        for _ = 1, 12 do if not t.IsPlaying then pcall(function() t:Play(0.05) end) end task.wait(0.1) end  -- keep re-asserting for ~1.2s so PlatformStand/the game can't kill it
                        pcall(function() t:Stop() end)
                end)
                if GOKU_SOUND ~= "" then pcall(function() local s = Instance.new("Sound"); s.SoundId = GOKU_SOUND; s.Volume = 3; s.Parent = myHRP() or workspace; s:Play(); Debris:AddItem(s, 3) end) end
        end
        local RS = game:GetService("ReplicatedStorage")
        local busy = false
        local function acPass() local k = RS:FindFirstChild("Knit"); k = k and k:FindFirstChild("Knit"); k = k and k:FindFirstChild("Services"); local svc = k and k:FindFirstChild("AntiCheatService"); local re = svc and svc:FindFirstChild("RE"); re = re and re:FindFirstChild("Teleport"); if re then pcall(function() re:FireServer(workspace:GetServerTimeNow()) end) end end
        local function behindPos(er)  -- a point behind their back, ON THE GROUND (raycast down - floating in the air broke the follow-up M1)
                local look = er.CFrame.LookVector; local flat = Vector3.new(look.X, 0, look.Z); local dir = flat.Magnitude > 0.01 and flat.Unit or Vector3.new(0, 0, -1)
                local p = er.Position - dir * 3
                local rp = RaycastParams.new(); rp.FilterType = Enum.RaycastFilterType.Exclude
                local ex = { myModel() }; if er.Parent then ex[#ex + 1] = er.Parent end
                rp.FilterDescendantsInstances = ex
                local hit = workspace:Raycast(p + Vector3.new(0, 4, 0), Vector3.new(0, -22, 0), rp)
                if hit then return Vector3.new(p.X, hit.Position.Y + 3, p.Z) end        -- feet on the floor behind them
                return Vector3.new(p.X, er.Position.Y, p.Z)                              -- no floor found: at least match THEIR height
        end
        local function goBehind(enemyChar)  -- TELEPORT-style Goku blink to behind them (grounded), then STAY behind ~1s
                local er = enemyChar and enemyChar:FindFirstChild("HumanoidRootPart"); if not er or busy then return end
                busy = true
                playGoku()
                -- ═══ THE IT FLASH ═══ a quarter-second white outline the instant you vanish - the classic
                -- instant-transmission read, purely client-side (no physics writes, nothing for AC to see).
                pcall(function()
                        local c = myModel(); if c then
                                local hl = Instance.new("Highlight"); hl.Name = "VX_GokuFlash"
                                hl.FillTransparency = 1; hl.OutlineColor = Color3.fromRGB(240, 240, 255); hl.OutlineTransparency = 0.1
                                hl.Adornee = c; hl.Parent = (gethui and gethui()) or game:GetService("CoreGui")
                                game:GetService("Debris"):AddItem(hl, 0.3)
                        end
                end)
                task.spawn(function()
                        local hum = myModel() and myModel():FindFirstChildOfClass("Humanoid")
                        if hum then pcall(function() hum.PlatformStand = true end) end
                        local t0 = tick()
                        while tick() - t0 < 1.1 do
                                local hrp = myHRP(); if not (hrp and er.Parent) then break end
                                acPass()
                                local dest = behindPos(er)
                                local to = dest - hrp.Position; local d = to.Magnitude
                                local step = math.min(d, 5)                                     -- ~5 studs/frame = a visible FLY, then tracks (stays behind) once there
                                local nextPos = d > 0.05 and (hrp.Position + to.Unit * step) or hrp.Position
                                pcall(function() hrp.CFrame = CFrame.lookAt(nextPos, er.Position); hrp.AssemblyLinearVelocity = Vector3.zero end)  -- face them the whole time
                                task.wait()
                        end
                        if hum then pcall(function() hum.PlatformStand = false end) end
                        busy = false
                end)
        end
        local function nearestEnemy()  -- closest enemy/DUMMY to you
                local hrp = myHRP(); if not hrp then return nil end
                local best, bd
                local function chk(m) if m and m.Name ~= LP.Name and m ~= LP.Character then local r = m:FindFirstChild("HumanoidRootPart"); local h = m:FindFirstChildOfClass("Humanoid"); if r and (not h or h.Health > 0) then local d = (r.Position - hrp.Position).Magnitude; if not bd or d < bd then best, bd = m, d end end end end
                for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP then chk(plr.Character) end end
                local chs = workspace:FindFirstChild("Characters"); if chs then for _, m in ipairs(chs:GetChildren()) do chk(m) end end
                return best
        end
        -- CLICK fallback: a LANDED left-click (enemy in front, melee range) triggers the Goku blink even when the
        -- anim-id detection misses (that miss = 'Goku M1 no work at all').
        do
                local UISg = game:GetService("UserInputService")
                UISg.InputBegan:Connect(function(input, gpe)
                        if gpe or not on then return end
                        if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
                        if tick() - last <= 0.6 then return end
                        local mh = myHRP(); if not mh then return end
                        local tgt = nearestEnemy(); local er = tgt and tgt:FindFirstChild("HumanoidRootPart")
                        if not er then return end
                        local to = er.Position - mh.Position
                        if to.Magnitude <= 9 and mh.CFrame.LookVector:Dot(to.Unit) > 0.35 then last = tick(); task.delay(0.15, function() goBehind(tgt) end) end
                end)
        end
        -- fire on YOUR M1 (so it works when you M1 the dummy): flash behind the nearest enemy + Goku pose
        local hooked = setmetatable({}, { __mode = "k" })
        local function hookSelf()
                local a = animatorOf(); if not a or hooked[a] then return end
                hooked[a] = a.AnimationPlayed:Connect(function(track)
                        if not on then return end
                        if _G.VX_IS_M1 and _G.VX_IS_M1(track) and tick() - last > 0.6 then  -- strict: real M1 swings only
                                local tgt = nearestEnemy(); local hrp = myHRP(); local er = tgt and tgt:FindFirstChild("HumanoidRootPart")
                                if er and hrp and (er.Position - hrp.Position).Magnitude <= 45 then last = tick(); goBehind(tgt) end
                        end
                end)
        end
        task.spawn(function() while true do if on then hookSelf() end task.wait(0.7) end end)
        -- ── GOKU DODGE ── "for Goku, dodge" - the old hook required a HUMAN click stamp within 0.4s, but
        -- that stamp only proves MY clicks: an enemy's M1 never follows my click, so the dodge was dead
        -- code that never fired once. An enemy swing now dodges off their ANIMATION alone: a listed M1 id
        -- on their animator, or (characters whose M1 ids were never captured) any fresh Action track while
        -- they are close AND facing me. The dodge itself is an instant transmission BEHIND the attacker -
        -- their swing whiffs and you are already at their back (lateral sidestep only if no floor there).
        local dodgeOn, lastDodge, dodgeSide = false, 0, 1
        local dHooked = setmetatable({}, { __mode = "k" })
        local function dodgeBlink(attacker)
                local hrp = myHRP(); local er = attacker and attacker:FindFirstChild("HumanoidRootPart")
                if not (hrp and er) then return end
                local look = er.CFrame.LookVector; local flat = Vector3.new(look.X, 0, look.Z)
                local dir = flat.Magnitude > 0.01 and flat.Unit or Vector3.new(0, 0, -1)
                local dest = er.Position - dir * 3
                local rp = RaycastParams.new(); rp.FilterType = Enum.RaycastFilterType.Exclude
                rp.FilterDescendantsInstances = { myModel(), attacker }
                local hit = workspace:Raycast(dest + Vector3.new(0, 4, 0), Vector3.new(0, -22, 0), rp)
                if hit then dest = Vector3.new(dest.X, hit.Position.Y + 3, dest.Z)
                else
                        -- no floor behind them: fall back to the lateral sidestep
                        dodgeSide = -dodgeSide
                        local right = hrp.CFrame.RightVector; local rflat = Vector3.new(right.X, 0, right.Z)
                        local rdir = rflat.Magnitude > 0.01 and rflat.Unit or Vector3.new(1, 0, 0)
                        dest = hrp.Position + rdir * (13 * dodgeSide)
                        local hit2 = workspace:Raycast(dest + Vector3.new(0, 6, 0), Vector3.new(0, -24, 0), rp)
                        if hit2 then dest = Vector3.new(dest.X, hit2.Position.Y + 3, dest.Z) end
                end
                acPass()
                pcall(function() hrp.CFrame = CFrame.lookAt(dest, Vector3.new(er.Position.X, dest.Y, er.Position.Z)); hrp.AssemblyLinearVelocity = Vector3.zero end)
        end
        local function hookEnemyAnimsForDodge()
                local hrp = myHRP(); if not hrp then return end
                local function consider(m)
                        if not m or not m:IsA("Model") or m.Name == LP.Name or m == LP.Character then return end
                        local er = m:FindFirstChild("HumanoidRootPart")
                        if er and (er.Position - hrp.Position).Magnitude <= 30 then
                                local h = m:FindFirstChildOfClass("Humanoid") or m:FindFirstChildOfClass("AnimationController")
                                local a = h and h:FindFirstChildOfClass("Animator")
                                if a and not dHooked[a] then
                                        dHooked[a] = a.AnimationPlayed:Connect(function(track)
                                                if not dodgeOn or tick() - lastDodge <= 0.5 then return end
                                                local okD, swing = pcall(function()
                                                        local mh = myHRP(); local eh = m:FindFirstChild("HumanoidRootPart")
                                                        if not (mh and eh) then return false end
                                                        local d = (eh.Position - mh.Position).Magnitude
                                                        if d > 22 then return false end
                                                        local id = tostring(track.Animation.AnimationId):match("%d+")
                                                        if id and _G.VX_M1_IDS and _G.VX_M1_IDS[id] then return true end
                                                        -- universal: their fresh Action track, close (<=16) and aimed at me
                                                        local okp, pr, tp2 = pcall(function() return tostring(track.Priority), tonumber(track.TimePosition) or 0 end)
                                                        if not (okp and pr and string.find(pr, "Action", 1, true) and tp2 < 0.15) then return false end
                                                        local faceMe = eh.CFrame.LookVector:Dot((mh.Position - eh.Position).Unit) > 0.25
                                                        return faceMe and d <= 16
                                                end)
                                                if okD and swing then
                                                        lastDodge = tick(); dodgeBlink(m)
                                                end
                                        end)
                                end
                        end
                end
                local chs = workspace:FindFirstChild("Characters"); if chs then for _, m in ipairs(chs:GetChildren()) do consider(m) end end
                for _, f in ipairs({ "Dummies", "Training", "NPCs", "Dummy" }) do
                        local fo = workspace:FindFirstChild(f)
                        if fo then for _, m in ipairs(fo:GetChildren()) do consider(m) end end
                end
                for _, pl in ipairs(Players:GetPlayers()) do if pl ~= LP and pl.Character then consider(pl.Character) end end
        end
        task.spawn(function() while true do if dodgeOn then pcall(hookEnemyAnimsForDodge) end task.wait(0.5) end end)
        GokuApi = { set = function(v) on = v == true end, setDodge = function(v) dodgeOn = v == true end }
end

-- ============================================================
-- MODULE: AUTO HOLLOW NUKE -- Blue, approach, Blue, aim Red at the observed Blue orb.
do
    local LP=game:GetService("Players").LocalPlayer
    local UIS=game:GetService("UserInputService")
    local VIM=game:GetService("VirtualInputManager")
    local RS=game:GetService("RunService")
    local armed,mode,threshold,generation=false,"Lock Target",30,0
    local running,lastRun,lastSelected=false,-math.huge,nil
    local function valid(t)
        local h=t and t.Parent and t:FindFirstChildOfClass("Humanoid")
        local r=t and t:FindFirstChild("HumanoidRootPart")
        return t~=vxMyChar() and h and h.Health>0 and r
    end
    local function hasMoves()
        local c=vxMyChar(); local moves=c and c:FindFirstChild("Moveset")
        local blue,red=false,false
        if moves then for _,move in ipairs(moves:GetChildren()) do
            local name=move.Name:lower():gsub("[^%a]","")
            if name:find("lapseblue",1,true) then blue=true end
            if name:find("reversalred",1,true) or name:find("reversered",1,true) then red=true end
        end end
        return blue and red
    end
    local function pick()
        local c=vxMyChar(); local root=c and c:FindFirstChild("HumanoidRootPart")
        if not root then return end
        if mode=="Lock Target" then
            local t=_G.VX_LOCK and _G.VX_LOCK.get and _G.VX_LOCK.get()
            if valid(t) and (root.Position-t.HumanoidRootPart.Position).Magnitude<=120 then return t end
            return
        end
        local best,score,gap=nil,math.huge,math.huge
        for _,t in ipairs(_G.VX_LIVING_MODELS()) do
            if valid(t) then
                local h=t:FindFirstChildOfClass("Humanoid"); local r=t:FindFirstChild("HumanoidRootPart")
                local distance=(r.Position-root.Position).Magnitude
                local value=distance
                if mode=="Lowest HP" then value=h.Health
                elseif mode=="Largest Target" then local size=t:GetExtentsSize(); value=-(size.X*size.Y*size.Z) end
                if distance<=120 and (value<score or value==score and distance<gap) then best,score,gap=t,value,distance end
            end
        end
        return best
    end
    local function execute(t)
        if running or _G.VX_COMBAT_OWNER or not valid(t) or not hasMoves() or UIS:GetFocusedTextBox() then return false end
        local c=vxMyChar(); local h=c and c:FindFirstChildOfClass("Humanoid")
        local root=c and c:FindFirstChild("HumanoidRootPart"); local tr=t:FindFirstChild("HumanoidRootPart")
        local camera=workspace.CurrentCamera
        if not h or not root or not camera or (root.Position-tr.Position).Magnitude>120 then return false end
        running=true; lastRun=tick(); local gen=generation
        local owner={}; _G.VX_COMBAT_OWNER=owner
        local rotation=camera.CFrame.Rotation; local committed=false
        local function live() return armed and generation==gen and vxMyChar()==c and h.Health>0 and (committed or valid(t)) and not UIS:GetFocusedTextBox() end
        local function aim(position)
            if not live() then return end
            local flat=Vector3.new(position.X,root.Position.Y,position.Z)
            if (flat-root.Position).Magnitude>0.1 then root.CFrame=CFrame.lookAt(root.Position,flat) end
            camera.CFrame=CFrame.lookAt(camera.CFrame.Position,position)
        end
        local orbs={}
        local function capture(object)
            local part=object:IsA("BasePart") and object or object:FindFirstAncestorWhichIsA("BasePart")
            if not part or part:IsDescendantOf(c) or part:IsDescendantOf(t) then return end
            local node=object; local blue=false
            local function isBlue(color) return color.B>0.65 and color.B>color.R*1.3 end
            if object:IsA("BasePart") then blue=isBlue(object.Color)
            elseif object:IsA("ParticleEmitter") or object:IsA("Beam") then
                for _,point in ipairs(object.Color.Keypoints) do if isBlue(point.Value) then blue=true; break end end
            elseif object:IsA("PointLight") then blue=isBlue(object.Color) end
            for _=1,5 do
                if not node or node==workspace then break end
                local name=node.Name:lower():gsub("[^%a]","")
                if name:find("blue",1,true) then blue=true end
                local own=node:GetAttribute("Owner") or node:GetAttribute("UserId") or node:GetAttribute("Caster")
                if own and own~=LP.UserId and own~=LP.Name and own~=c then return end
                node=node.Parent
            end
            if blue and (part.Position-tr.Position).Magnitude<=60 then table.insert(orbs,part) end
        end
        local connection=workspace.DescendantAdded:Connect(capture)
        task.spawn(function()
            local held
            local ok,err=pcall(function()
                local function key(k)
                    if not live() or _G.VX_KEY_BLOCKED and _G.VX_KEY_BLOCKED(k) then return false end
                    _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[k]=tick()+0.4
                    VIM:SendKeyEvent(false,k,false,game); RS.RenderStepped:Wait()
                    if not live() then return false end
                    held=k; VIM:SendKeyEvent(true,k,false,game); task.wait(0.08)
                    VIM:SendKeyEvent(false,k,false,game); held=nil; return true
                end
                aim(tr.Position)
                if not key(Enum.KeyCode.One) then return end
                committed=true
                if not live() then return end
                local deadline=tick()+2.5; local orb
                repeat
                    if not live() then return end
                    for i=#orbs,1,-1 do if orbs[i].Parent then orb=orbs[i]; break end end
                    if orb then break end
                    task.wait()
                until tick()>=deadline
                if not orb then _G.VX_HOLLOW_STATUS="new Blue orb not observed; Red not sent"; return end
                RS:BindToRenderStep("VX_HollowAim",Enum.RenderPriority.Camera.Value+60,function() if orb.Parent then aim(orb.Position) end end)
                aim(orb.Position); RS.RenderStepped:Wait()
                if not orb.Parent then return end
                if key(Enum.KeyCode.Two) then _G.VX_HOLLOW_STATUS="Red aimed at observed Blue orb; detonation unconfirmed" end
                task.wait(0.15)
            end)
            connection:Disconnect()
            pcall(function() RS:UnbindFromRenderStep("VX_HollowAim"); if held then VIM:SendKeyEvent(false,held,false,game) end end)
            if workspace.CurrentCamera==camera then camera.CFrame=CFrame.new(camera.CFrame.Position)*rotation end
            if _G.VX_COMBAT_OWNER==owner then _G.VX_COMBAT_OWNER=nil end
            running=false
            if not ok then warn("[DreamHub Hollow] "..tostring(err)) end
        end)
        return true
    end
    pcall(function()
        local mouse=LP:GetMouse()
        mouse.Button1Down:Connect(function()
            if not armed or mode~="Lock Target" or tick()-lastRun<=0.5 or tick()<(tonumber(_G.VX_SYNTH_CLICK) or 0) then return end
            local node=mouse.Target
            while node and node~=workspace do
                if node:IsA("Model") and valid(node) then
                    if execute(node) then lastSelected=node end
                    return
                end
                node=node.Parent
            end
        end)
    end)
    task.spawn(function()
        while true do
            if armed and not running and tick()-lastRun>0.5 then
                local t=pick()
                if mode=="Lock Target" then
                    if not t then lastSelected=nil
                    elseif execute(t) then lastSelected=t end
                elseif t then
                    local h=t:FindFirstChildOfClass("Humanoid")
                    if mode~="Lowest HP" or h.Health<=threshold then execute(t) end
                end
            end
            task.wait(0.1)
        end
    end)
    HollowApi={
        set=function(v)
            armed=v==true; generation+=1; lastSelected=nil
            if _G.VX_LOCK and _G.VX_LOCK.want then _G.VX_LOCK.want("hollow",armed) end
        end,
        setMode=function(v)
            if type(v)=="table" then v=v[1] end
            if v=="Lock Target" or v=="Lowest HP" or v=="Largest Target" or v=="Closest" then mode=v; generation+=1; lastSelected=nil end
        end,
        setThreshold=function(v) threshold=math.clamp(tonumber(v) or 30,5,100) end,
    }
end

-- MODULE: FORCE RESET  (force your character to reset / respawn)
-- ============================================================
do
        local Players = game:GetService("Players")
        local LP = Players.LocalPlayer
        ResetApi = { reset = function()
                -- Force Reset that ACTUALLY kills you in JJS (Health=0 alone gets ignored by the custom-health system).
                -- Try every real kill path: Humanoid.Health=0, the Health attribute/value, the game's own reset request,
                -- and finally BreakJoints (the guaranteed one) — whatever the game respects, one of these ends you.
                local chs = workspace:FindFirstChild("Characters")
                local bodies = {}
                if chs and chs:FindFirstChild(LP.Name) then bodies[#bodies+1] = chs:FindFirstChild(LP.Name) end
                if LP.Character then bodies[#bodies+1] = LP.Character end
                for _, c in ipairs(bodies) do
                        pcall(function()
                                local h = c:FindFirstChildOfClass("Humanoid")
                                if h then
                                        h:SetStateEnabled(Enum.HumanoidStateType.Dead, true)   -- JJS often DISABLES the Dead state so Health=0 is ignored; re-enable it first
                                        h.Health = 0; h.MaxHealth = 0
                                        h:TakeDamage(1e9)
                                        h:ChangeState(Enum.HumanoidStateType.Dead)             -- force the death state directly
                                end
                                c:SetAttribute("Health", 0)
                                local hv = c:FindFirstChild("Health")
                                if hv and hv:IsA("ValueBase") then hv.Value = 0 end
                        end)
                end
                -- try the game's OWN reset/respawn remote (Knit services) - the path the game itself uses
                pcall(function()
                        local RS = game:GetService("ReplicatedStorage")
                        local k = RS:FindFirstChild("Knit"); k = k and k:FindFirstChild("Knit"); k = k and k:FindFirstChild("Services")
                        if k then for _, svc in ipairs(k:GetChildren()) do
                                local re = svc:FindFirstChild("RE")
                                if re then for _, nm in ipairs({ "Reset", "Respawn", "Die", "Kill", "Suicide" }) do
                                        local r = re:FindFirstChild(nm); if r and r:IsA("RemoteEvent") then pcall(function() r:FireServer() end) end
                                end end
                        end end
                end)
                -- the built-in reset button, fired programmatically via a BindableEvent (works when the game keeps default reset)
                pcall(function()
                        local ev = Instance.new("BindableEvent")
                        game:GetService("StarterGui"):SetCore("ResetButtonCallback", ev)
                        ev:Fire()
                end)
                pcall(function() game:GetService("StarterGui"):SetCore("ResetButtonCallback", true) end)
                -- guaranteed fallback: break the rig so you die for sure
                for _, c in ipairs(bodies) do pcall(function() c:BreakJoints() end) end
        end }
end

-- ============================================================
-- MODULE: SIDE DASH ASSIST  (on M1, fire an L/R side dash - NO rotation snap, so it can't break your M1 combo state)
-- ============================================================
do
        local Players = game:GetService("Players")
        local UIS = game:GetService("UserInputService")
        local LP = Players.LocalPlayer
        local on, last = false, 0
        -- EVERY character's M1 anim id (user-captured) -> detect a REAL M1 by animation, not an unreliable mouse click
        local M1_IDS = {}
        for _, id in ipairs({
                "133240987753043","127851700400958","120133391090244","94588892125071","75337033003776","126277739156443","96185406489877",
                "96327114254575","133936641185614","98783064085844","101283990868172","9443519528","84359513001979","89537672683114",
                "105077924973072","85068785050521","131909724908049","125689391910002","133447840605824","114985590391235","86519781516542",
        }) do M1_IDS[id] = true end
        if _G.VX_M1_IDS then for id in pairs(_G.VX_M1_IDS) do M1_IDS[id] = true end end
        _G.VX_M1_IDS = M1_IDS  -- MERGED with the master per-character list (this module used to clobber it with its short list = detection missing for most characters)
        -- RIGHT dash anim = rbxassetid://75203303352791 (what plays when you dash right; kept for reference)
        local function myModel() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
        local function getHRP(m) return m and (m:FindFirstChild("HumanoidRootPart") or m:FindFirstChild("Torso") or m:FindFirstChild("UpperTorso")) end
        local function nearestEnemy(maxD)  -- closest living enemy/dummy
                local mh = getHRP(myModel()); if not mh then return nil end
                local best, bd = nil, maxD
                local function chk(m)
                        if not m or m == myModel() or m.Name == LP.Name then return end
                        local r = getHRP(m); if not r then return end
                        local h = m:FindFirstChildOfClass("Humanoid"); if h and h.Health <= 0 then return end
                        local d = (r.Position - mh.Position).Magnitude; if d < bd then bd = d; best = m end
                end
                for _, pl in ipairs(Players:GetPlayers()) do if pl ~= LP then chk(pl.Character) end end
                local chs = workspace:FindFirstChild("Characters"); if chs then for _, m in ipairs(chs:GetChildren()) do if m:IsA("Model") then chk(m) end end end
                return best
        end
        -- play a client animation (the flourish the user asked for) so the left dash LOOKS like the real curve-around
        local function playAnim(id)
                pcall(function()
                        local m = myModel(); local h = m and m:FindFirstChildOfClass("Humanoid"); local a = h and h:FindFirstChildOfClass("Animator")
                        if not a then return end
                        local anim = Instance.new("Animation"); anim.AnimationId = id
                        local t = a:LoadAnimation(anim); t.Priority = Enum.AnimationPriority.Action2; t:Play(0.05)
                        task.delay(0.5, function() pcall(function() t:Stop() end) end)
                end)
        end
        local sdaInjecting = 0
        -- SIDE DASH ASSIST (user spec v2): fires ONLY when YOU press Q — never off an M1 anim (that dashed you when you
        -- never clicked). Q -> short FAST LEFT dash (the game's Dash remote is validation-only per the user's own test,
        -- so we drive a client velocity LEFT) -> face the enemy -> throw one M1. Left = -RightVector. Short = no over-glide.
        local function trigger()
                if not on then return end
                if tick() - last < 0.4 then return end                     -- one dash per press
                if tick() < sdaInjecting then return end
                if tick() - (_G.VX_LAUNCHING or 0) < 0.3 then return end   -- not during an uppercut launch
                if tick() < (_G.VX_BUSY or 0) then return end              -- not during an Auto Air sequence
                local mh = getHRP(myModel()); if not mh then return end
                local tgt = nearestEnemy(18); local tr = tgt and getHRP(tgt)
                if not tr then return end   -- no enemy nearby -> don't dash for nothing (was firing with no target = felt broken)
                last = tick(); sdaInjecting = tick() + 0.3
                _G.VX_INJECT_UNTIL = tick() + 0.3
                if _G.VX_CLAIMOWN then pcall(_G.VX_CLAIMOWN) end   -- the velocity write below is cosmetic without network ownership
                playAnim("rbxassetid://95295463826732"); playAnim("rbxassetid://75203303352791")   -- the two anim ids the user gave
                fireKnit("MovementService", "Dash", "Left", true)   -- harmless if validation-only; the velocity below is the real mover
                task.spawn(function()
                        -- SHORT pure-LEFT push (0.1s @ 80 ≈ 8 studs) — enough to whip left, short enough it can't "glide too far"
                        local t0 = tick()
                        while tick() - t0 < 0.10 do
                                local mh2 = getHRP(myModel()); if not mh2 then break end
                                local v = -mh2.CFrame.RightVector * 80   -- PURE LEFT (no forward/right component)
                                pcall(function() mh2.AssemblyLinearVelocity = Vector3.new(v.X, math.min(mh2.AssemblyLinearVelocity.Y, 0), v.Z) end)
                                task.wait()
                        end
                        local mhS = getHRP(myModel()); if mhS then pcall(function() local vv = mhS.AssemblyLinearVelocity; mhS.AssemblyLinearVelocity = Vector3.new(0, vv.Y, 0) end) end   -- stop dead, no residual slide
                        local mh3 = getHRP(myModel()); local tr3 = tgt and tgt.Parent and getHRP(tgt)
                        if mh3 and tr3 then pcall(function() mh3.CFrame = CFrame.lookAt(mh3.Position, Vector3.new(tr3.Position.X, mh3.Position.Y, tr3.Position.Z)) end) end   -- face them
                        local VIM = game:GetService("VirtualInputManager")
                        local cam = workspace.CurrentCamera; local vp = (cam and cam.ViewportSize) or Vector2.new(800, 600)
                        pcall(function() VIM:SendMouseButtonEvent(vp.X / 2, vp.Y / 2, 0, true, game, 0); task.wait(0.04); VIM:SendMouseButtonEvent(vp.X / 2, vp.Y / 2, 0, false, game, 0) end)   -- M1 for you
                end)
                if _G.VX_BF_DEBUG then print("[DreamHub SideDash] Q -> Left dash + M1 at "..(tgt and tgt.Name or "no target")) end
        end
        UIS.InputBegan:Connect(function(input, gpe)
                if not on or gpe then return end
                if UIS:GetFocusedTextBox() then return end
                if input.KeyCode ~= Enum.KeyCode.Q then return end
                do local injK = _G.VX_INJ_KEYS; if injK and injK[Enum.KeyCode.Q] and tick() < injK[Enum.KeyCode.Q] then return end end
                trigger()
        end)
        -- BLOCK PUNISH (part of Side Dash Assist): the enemy you're hitting raises BLOCK -> instantly get BEHIND
        -- them and M1 (their block faces the wrong way = free hit). This is the 'escape their block and hit them'.
        local lastPunish = 0
        local function targetBlocking(tgt)
                if not tgt then return false end
                local info = tgt:FindFirstChild("Info")
                if info then for _, nm in ipairs({ "Block", "Blocking", "IsBlocking", "Guard" }) do
                        local v = info:FindFirstChild(nm); if v and v.Value and v.Value ~= false and v.Value ~= 0 then return true end
                end end
                local h = tgt:FindFirstChildOfClass("Humanoid")
                if h and (h:GetAttribute("Blocking") == true or h:GetAttribute("Block") == true) then return true end
                return false
        end
        task.spawn(function()
                local VIMs = game:GetService("VirtualInputManager")
                while true do
                        task.wait(0.12)
                        if on and tick() - lastPunish > 1.6 and tick() >= (_G.VX_BUSY or 0) then
                                local mh = getHRP(myModel())
                                local tgt = nearestEnemy(10); local tr = tgt and getHRP(tgt)
                                if mh and tr and targetBlocking(tgt) then
                                        lastPunish = tick()
                                        -- DASH around their guard (real dash remote + velocity), NO CFrame teleport
                                        local side = math.random(1, 2) == 1 and "Left" or "Right"
                                        fireKnit("MovementService", "Dash", side, true)
                                        local rv = side == "Left" and -mh.CFrame.RightVector or mh.CFrame.RightVector
                                        task.spawn(function()
                                                local t0 = tick()
                                                while tick() - t0 < 0.16 do
                                                        local h = getHRP(myModel()); if not h then break end
                                                        pcall(function() h.AssemblyLinearVelocity = Vector3.new(rv.X * 70, math.min(h.AssemblyLinearVelocity.Y, 0), rv.Z * 70); h.CFrame = CFrame.lookAt(h.Position, Vector3.new(tr.Position.X, h.Position.Y, tr.Position.Z)) end)
                                                        task.wait()
                                                end
                                        end)
                                        task.wait(0.16)
                                        pcall(function()   -- and HIT
                                                local cam = workspace.CurrentCamera; local v = (cam and cam.ViewportSize) or Vector2.new(800, 600)
                                                VIMs:SendMouseButtonEvent(v.X / 2, v.Y / 2, 0, true, game, 0); task.wait(0.04); VIMs:SendMouseButtonEvent(v.X / 2, v.Y / 2, 0, false, game, 0)
                                        end)
                                        vxLog("Block punish -> dash + M1")
                                end
                        end
                end
        end)
        -- SUPERSEDED: VXBF2's doSideDash is the live Side Dash Assist (bound to Q at ~3192). This older module is
        -- also bound to Q; leaving it settable risked two handlers firing on one press ("dashes weird"). Hard-off.
        SideDashApi = { set = function() on = false end }
end

-- ============================================================
-- MODULE: AUTO EVASIVE -- escape first, approach only after recovery.
do
    local Players=game:GetService("Players")
    local UIS=game:GetService("UserInputService")
    local RS=game:GetService("RunService")
    local LP=Players.LocalPlayer
    local on,busy,follow=false,false,"Behind Target"
    local direction,index,generation="Cycle",0,0
    local cycle={"Back","Left","Right"}
    local wasDown,attempted,last=false,false,-math.huge
    local recentAttacker,recentAt,recentTrack=nil,0,nil
    local function body() return vxMyChar() end
    local function isDown(c)
        local h=c and c:FindFirstChildOfClass("Humanoid")
        if not h or h.Health<=0 then return false end
        local state=h:GetState()
        if h.PlatformStand or state==Enum.HumanoidStateType.Ragdoll or state==Enum.HumanoidStateType.Physics or state==Enum.HumanoidStateType.FallingDown then return true end
        for _,object in pairs({c,h,c:FindFirstChild("Info")}) do
            for _,name in ipairs({"Ragdoll","Ragdolled","Downed"}) do
                local value=object:FindFirstChild(name)
                if object:GetAttribute(name)==true or value and value:IsA("BoolValue") and value.Value then return true end
            end
        end
        return false
    end
    local function target()
        if recentAttacker and recentAttacker.Parent and tick()-recentAt<3 then return recentAttacker end
        local me=body(); local r=me and me:FindFirstChild("HumanoidRootPart")
        if not r then return end
        local best,dist=nil,26
        for _,model in ipairs(_G.VX_LIVING_MODELS()) do
            local e=model:FindFirstChild("HumanoidRootPart")
            if model~=me and e and (e.Position-r.Position).Magnitude<dist then best,dist=model,(e.Position-r.Position).Magnitude end
        end
        return best
    end
    local function evade()
        local character=body(); local root=character and character:FindFirstChild("HumanoidRootPart")
        if not on or busy or attempted or not root or not isDown(character) or UIS:GetFocusedTextBox() then return end
        local services=vxServicesFolder(); local move=services and services:FindFirstChild("MovementService")
        local remote=move and move:FindFirstChild("RE"); remote=remote and remote:FindFirstChild("Dash")
        attempted=true; busy=true; last=tick()
        local gen=generation; local enemy=target()
        local chosen=direction
        if chosen=="Cycle" then index=index%#cycle+1; chosen=cycle[index] end
        local owner={}; local previousOwner=_G.VX_COMBAT_OWNER
        if not previousOwner then _G.VX_COMBAT_OWNER=owner end
        task.spawn(function()
            local function live() return on and generation==gen and body()==character and character.Parent and not UIS:GetFocusedTextBox() end
            local ok,err=pcall(function()
                local camera=workspace.CurrentCamera; local rotation=camera and camera.CFrame.Rotation
                -- ═══ r13: MASH, DON'T SINGLE-TAP ═══ "auto bounce does not work even when it is spamming." JJS
                -- only accepts the downed evasive AFTER the knockdown lockout - the old code fired the Dash
                -- remote ONCE at the instant you dropped (inside the lockout), got refused, and the `attempted`
                -- flag then refused to ever try again for the rest of the knockdown. A player mashes the
                -- evasive; the hub now does too: one try every ~0.45s for up to ~2.6s, and each try is BOTH
                -- channels - the Dash remote (dir, true) AND a real Q key tap (the game's own downed-evasive
                -- input) - so whichever one this build accepts, the bounce goes out.
                local tries=0
                local t0=tick()
                while live() and isDown(character) and tries<5 and tick()-t0<2.6 do
                    tries=tries+1
                    local er=enemy and enemy:FindFirstChild("HumanoidRootPart")
                    if er and root.Parent and (er.Position-root.Position).Magnitude>0.1 then
                        local point=Vector3.new(er.Position.X,root.Position.Y,er.Position.Z)
                        pcall(function() root.CFrame=CFrame.lookAt(root.Position,point) end)
                        if camera then pcall(function() camera.CFrame=CFrame.lookAt(camera.CFrame.Position,camera.CFrame.Position+(point-root.Position).Unit) end) end
                    end
                    if remote then pcall(function() remote:FireServer(chosen,true) end) end
                    _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Q]=tick()+0.30
                    pcall(function()
                        local VIMq=game:GetService("VirtualInputManager")
                        VIMq:SendKeyEvent(true,Enum.KeyCode.Q,false,game)
                        task.wait(0.04)
                        VIMq:SendKeyEvent(false,Enum.KeyCode.Q,false,game)
                    end)
                    local tryEnd=tick()+0.45
                    while live() and isDown(character) and tick()<tryEnd do task.wait() end
                end
                if camera and workspace.CurrentCamera==camera and rotation then camera.CFrame=CFrame.new(camera.CFrame.Position)*rotation end
                if not live() or isDown(character) then _G.VX_EVASIVE_STATUS="escape unavailable after "..tries.." tries"; return end
                _G.VX_EVASIVE_STATUS="escaped "..chosen.." (try "..tries..")"
                if follow~="Off" and enemy and enemy.Parent and not previousOwner then
                    -- Side/back dash has a shared two-second cooldown after an evasive.
                    while live() and tick()<last+2.05 do task.wait() end
                    if live() and not isDown(character) and not (recentTrack and recentTrack.IsPlaying)
                        and _G.VXBF2 and _G.VXBF2.approach then
                        if follow=="Toward Target" then _G.VXBF2.approach(enemy,false,live,true,true,{range=26,reach=6})
                        else _G.VXBF2.approach(enemy,false,live) end
                    end
                end
            end)
            if _G.VX_COMBAT_OWNER==owner then _G.VX_COMBAT_OWNER=nil end
            busy=false
            if not ok then warn("[DreamHub Evasive] "..tostring(err)) end
        end)
    end
    RS.Heartbeat:Connect(function()
        local down=isDown(body())
        if down and not wasDown then attempted=false end
        wasDown=down
        if on and down and not busy and tick()-last>0.2 then evade() end
    end)
    -- The animation pipeline supplies the likely attacker; it does not spend evasive while standing.
    _G.VX_EVADE=function(attacker,track)
        if attacker then recentAttacker,recentAt,recentTrack=attacker,tick(),track end
        evade()
    end
    LP.CharacterAdded:Connect(function() generation+=1; wasDown=false; attempted=false end)
    EvasiveApi={
        set=function(v) on=v==true; _G.VX_EVASIVE_ON=on; generation+=1; attempted=false end,
        setDir=function(v) if type(v)=="table" then v=v[1] end; if v=="Cycle" or v=="Back" or v=="Left" or v=="Right" then direction=v end end,
        setFollow=function(v) if type(v)=="table" then v=v[1] end; if v=="Off" or v=="Behind Target" or v=="Toward Target" then follow=v end end,
    }
end

-- MODULE: GOJO TP (R) + REVERSAL RED (3 -> R)
-- ============================================================
do
        local Players = game:GetService("Players")
        local UIS = game:GetService("UserInputService")
        local VIM = game:GetService("VirtualInputManager")
        local RS = game:GetService("ReplicatedStorage")
        local LP = Players.LocalPlayer
        local gojoOn, redOn, lastGojo = false, false, 0
        local function myHRP() local chs = workspace:FindFirstChild("Characters"); local c = (chs and chs:FindFirstChild(LP.Name)) or LP.Character; return c and c:FindFirstChild("HumanoidRootPart") end
        local function nearestEnemyChar(raw)   -- raw = ignore the lock (used by the 'is anyone near me' gate)
                local hrp = myHRP(); if not hrp then return nil end
                if not raw then
                        local _g=_G.VX_LOCK; local _lt=(_g and _g.manualActive and _g.manualActive() and _g.get) and _g.get() or nil   -- LOCK TARGET wins over any range scan
                        if _lt and _lt.Parent and _lt:FindFirstChild("HumanoidRootPart") then local _lh=_lt:FindFirstChildOfClass("Humanoid"); if not _lh or _lh.Health > 0 then return _lt end end
                end
                local best, bd
                -- Health check is now `not h or h.Health > 0`: training dummies often have NO Humanoid at all, and the
                -- old `h and h.Health > 0` rejected them outright.
                local function chk(m)
                        if m and m.Name ~= LP.Name and m ~= LP.Character then
                                local r = m:FindFirstChild("HumanoidRootPart"); local h = m:FindFirstChildOfClass("Humanoid")
                                if r and (not h or h.Health > 0) then
                                        local d = (r.Position - hrp.Position).Magnitude; if not bd or d < bd then best, bd = m, d end
                                end
                        end
                end
                for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP then chk(plr.Character) end end
                local chs = workspace:FindFirstChild("Characters"); if chs then for _, m in ipairs(chs:GetChildren()) do chk(m) end end
                -- DUMMY FOLDERS: Auto Air's 60-stud presence gate rides this. Training dummies usually live outside
                -- workspace.Characters, so testing on one left the gate permanently false = "Auto Air does nothing".
                for _, folderName in ipairs({ "Dummies", "Training", "NPCs", "Dummy" }) do
                        local f = workspace:FindFirstChild(folderName)
                        if f then for _, m in ipairs(f:GetChildren()) do chk(m) end end
                end
                return best
        end
        local function gojoRE()  -- GojoService.RE.RightActivated -> fires with a target Character = TP behind them
                local k = RS:FindFirstChild("Knit"); k = k and k:FindFirstChild("Knit"); k = k and k:FindFirstChild("Services")
                local s = k and k:FindFirstChild("GojoService"); local re = s and s:FindFirstChild("RE"); return re and re:FindFirstChild("RightActivated")
        end
        local function asPlayerCharacter(mdl)  -- the remote wants the PLAYER's .Character (the working capture used Players[name].Character), not the workspace.Characters model
                if not mdl then return nil end
                local plr = Players:GetPlayerFromCharacter(mdl) or Players:FindFirstChild(mdl.Name)
                return (plr and plr.Character) or mdl
        end
        local function faceTargetNow(tgtModel)  -- AIM at the user before/while the ability fires (Gojo R requires aiming at them)
                local hrp = myHRP(); local tr = tgtModel and (tgtModel:FindFirstChild("HumanoidRootPart") or tgtModel:FindFirstChildWhichIsA("BasePart"))
                if hrp and tr then
                        pcall(function() hrp.CFrame = CFrame.lookAt(hrp.Position, Vector3.new(tr.Position.X, hrp.Position.Y, tr.Position.Z)) end)
                        pcall(function() local cam = workspace.CurrentCamera; cam.CFrame = CFrame.lookAt(cam.CFrame.Position, tr.Position) end)
                end
        end
        local function currentTarget()
                local g = _G.VX_LOCK; local lt = (g and g.get) and g.get() or nil
                return (lt and lt.Parent) and lt or nearestEnemyChar()
        end
        -- helpers for the Auto Air / mid-M1 sequences
        local autoAirOn = false
        local lastVesselAir = 0
        -- Auto Air's OWN injected-key stamps. Kept separate from the shared _G.VX_INJ_KEYS on purpose: that global is
        -- written by several modules (Auto Earthquake re-stamps key 3 every 40ms while charging, Yuta stamps key 2),
        -- and checking it made Auto Air suppress ITSELF whenever another feature was running — the real reason Rough
        -- Energy / Crushing Jaws never fired. We must only ignore keys WE pressed, not keys another module claimed.
        local airSelfInj = {}
        local function dbgAir(msg) if _G.VX_BF_DEBUG then print("[DreamHub AutoAir] " .. tostring(msg)) end end
        -- The keys Auto Air actually reacts to. Used by the always-on refusal report so pressing W or a hotkey it
        -- has no opinion about never prints anything.
        local AIR_KEYS = {
                [Enum.KeyCode.One] = true, [Enum.KeyCode.Two] = true, [Enum.KeyCode.Three] = true,
                [Enum.KeyCode.Four] = true, [Enum.KeyCode.R] = true, [Enum.KeyCode.Space] = true,
        }
        -- PER-CHARACTER Auto Air switches ("make the user pick which auto air it wants on"). All default ON; the
        -- Combat page exposes one toggle each. A sequence only runs if BOTH the master Auto Air toggle and its own
        -- switch are on AND you actually own the move.
        local airOpt = {} -- Native recipes own all options except the two-kick animation follow-up.
        -- ═══ NO MASTER SWITCH ═══ "remove the word auto air, and just put the things as it is, when I use each
        -- one it does what it must do." Each sequence is its own toggle now, so switching one on arms the engine
        -- by itself; switching the last one off stands it down again. Nothing is hidden behind a second switch
        -- the user has to find first.
        AutoAirOptSet = function(k, v)
                if k == nil then return end
                airOpt[k] = v == true
                local any = false
                for _, on in pairs(airOpt) do if on then any = true break end end
                autoAirOn = any
        end
        local lastM1Tgt = nil                 -- the enemy your last LANDED M1 hit (all sequences target THEM, like the Dummy in your captures)
        local function knitRE(svcName, reName)
                local k = RS:FindFirstChild("Knit"); k = k and k:FindFirstChild("Knit"); k = k and k:FindFirstChild("Services")
                local s = k and k:FindFirstChild(svcName); local re = s and s:FindFirstChild("RE"); return re and re:FindFirstChild(reName)
        end
        local function myMoveset(name)
                local chs = workspace:FindFirstChild("Characters"); local c = (chs and chs:FindFirstChild(LP.Name)) or LP.Character
                local mv = c and c:FindFirstChild("Moveset"); return mv and mv:FindFirstChild(name)
        end
        local function airborneMe()
                local hrp = myHRP(); if not hrp then return false end
                local chs = workspace:FindFirstChild("Characters"); local c = (chs and chs:FindFirstChild(LP.Name)) or LP.Character
                local h = c and c:FindFirstChildOfClass("Humanoid")
                return (h and h.FloorMaterial == Enum.Material.Air) or false
        end
        local function landedM1Target()  -- an enemy in melee range IN FRONT = your M1 landed on them
                local mh = myHRP(); if not mh then return nil end
                local mdl = nearestEnemyChar(); if not mdl then return nil end
                local tr = mdl:FindFirstChild("HumanoidRootPart"); if not tr then return nil end
                local to = tr.Position - mh.Position
                if to.Magnitude <= 9 and mh.CFrame.LookVector:Dot(to.Unit) > 0.35 then return mdl end
                return nil
        end
        local lastThree = 0   -- you pressed 3 (Lapse Blue etc): R now means REVERSAL RED, so the mid-M1 auto-R must stand down
        local function __airHandler(input, gpe)
                -- DON'T bail on gpe: pressing 1/2/3/R to use a move sets gpe=true (the game bound the key), and those
                -- are EXACTLY the presses Auto Air chains off. Only skip while you're TYPING in a textbox.
                if UIS:GetFocusedTextBox() then return end
                if input.KeyCode == Enum.KeyCode.Three then lastThree = tick() end
                -- GOJO TP BACK: configurable. Mode "Q Dash" = TP behind the moment you press Q. Mode "After M1s" =
                -- TP behind after your chosen number of Gojo M1s land (counted by anim below). Both fire GojoService TP.
                local function pressR()
                        _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.R] = tick() + 0.3
                        pcall(function() VIM:SendKeyEvent(true, Enum.KeyCode.R, false, game); task.wait(0.05); VIM:SendKeyEvent(false, Enum.KeyCode.R, false, game) end)
                end
                local function doGojoTpBack()
                    if not gojoOn or _G.VX_GOJO_ASSIST_ACTIVE or tick()-lastGojo<0.9 then return end
                    local mdl=currentTarget(); if not mdl then return end
                    lastGojo=tick(); _G.VX_GOJO_ASSIST_ACTIVE=true
                    local character=vxMyChar(); local camera=workspace.CurrentCamera
                    local rotation=camera and camera.CFrame.Rotation
                    task.spawn(function()
                        local ok,err=pcall(function()
                            faceTargetNow(mdl)
                            if tostring(_G.VX_GOJO_MODE)=="After M1s" then
                                _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Q]=tick()+0.5
                                VIM:SendKeyEvent(false,Enum.KeyCode.Q,false,game); task.wait(0.025)
                                VIM:SendKeyEvent(true,Enum.KeyCode.Q,false,game); task.wait(0.06)
                                VIM:SendKeyEvent(false,Enum.KeyCode.Q,false,game)
                                task.wait(0.14)   -- After-M1s only: let the Q dash commit before the TP
                            end
                            -- ═══ TELEPORT ME BACK INSTANTLY ═══ the 0.16s wait used to run in BOTH modes, so
                            -- Q Dash felt like it thought about it before moving. R now goes out on the same
                            -- beat; the aim-keeper (R-anim hook below) holds the target through the blink.
                            if not gojoOn or character~=vxMyChar() or not mdl.Parent then return end
                            faceTargetNow(mdl)
                            VIM:SendKeyEvent(false,Enum.KeyCode.R,false,game); task.wait(0.025)
                            pressR() -- one native cast supplies the game's animation and movement
                        end)
                        pcall(function() VIM:SendKeyEvent(false,Enum.KeyCode.Q,false,game); VIM:SendKeyEvent(false,Enum.KeyCode.R,false,game) end)
                        if camera and rotation then camera.CFrame=CFrame.new(camera.CFrame.Position)*rotation end
                        _G.VX_GOJO_ASSIST_ACTIVE=false
                        if not ok then warn("[DreamHub Gojo] "..tostring(err)) end
                    end)
                end

                _G.VX_GOJO_TPBACK = doGojoTpBack   -- the anim counter (below) calls this when the M1 count is reached
                if input.UserInputType == Enum.UserInputType.MouseButton1 then local mdl = landedM1Target(); if mdl then lastM1Tgt = mdl end end
                -- Q DASH mode: press Q -> TP behind them right away
                if input.KeyCode == Enum.KeyCode.Q and gojoOn and (tostring(_G.VX_GOJO_MODE or "Q Dash") == "Q Dash") then
                        doGojoTpBack()
                end
                if input.UserInputType == Enum.UserInputType.MouseButton1 then local mdl = landedM1Target(); if mdl then lastM1Tgt = mdl end end   -- remember who you're hitting (Auto Air targets THEM)
                if input.KeyCode == Enum.KeyCode.Three and redOn and tick() >= (_G.VX_INJECT_UNTIL or 0) then
                        -- FIX CHAR-1: Don't fire Reversal Red when Black Flash is active - the R press cancels the flash.
                        -- Check if any BF mode is armed (M1 BF, Auto BF, or a chain borrow).
                        if not (_G.VX_BFAPI_ON or _G.VX_M1BF_ON or _G.VX_BF_BORROWED) then
                                task.delay(0.12, function() pcall(function() VIM:SendKeyEvent(true, Enum.KeyCode.R, false, game); task.wait(0.12); VIM:SendKeyEvent(false, Enum.KeyCode.R, false, game) end) end)
                        end
                end
                -- ══ AUTO AIR sequences ══
                -- KEYS, not remotes: the remotes were server-rejected out of context ('nothing works at all').
                -- Pressing the real key is identical to you pressing it, so the game itself aims/validates.
                local function myCharName()
                        local chs = workspace:FindFirstChild("Characters"); local c = (chs and chs:FindFirstChild(LP.Name)) or LP.Character
                        return c and detectCharName(c) or nil
                end
                local function tapKey(kc, hold)
                        _G.VX_INJECT_UNTIL = tick() + 0.35
                        _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[kc] = tick() + 0.5   -- tell OTHER modules this key was synthetic
                        airSelfInj[kc] = tick() + 0.5                                               -- and remember it was OURS
                        pcall(function() VIM:SendKeyEvent(true, kc, false, game); task.wait(hold or 0.09); VIM:SendKeyEvent(false, kc, false, game) end)
                end
                -- EVERY M1, which was eating your real 1/2/3/R presses = 'Auto Air doesn't work'). Now a key is only
                -- ═══ AUTO AIR ROOT CAUSE #2 ═══ These two guards used to `return` out of the WHOLE shared InputBegan
                -- handler. Two consequences, both of which read as "Auto Air doesn't work":
                --   (a) Auto Earthquake re-stamps VX_INJ_KEYS[Three] every 40ms while it is on, so the key-3 branches
                --       (Rough Energy / Crushing Jaws) could NEVER run. The Yuta module does the same to key 2 (Nue).
                --   (b) With no enemy in range the handler returned early, silently disabling unrelated features below.
                -- They are now BOOLEANS that gate only the Auto Air branches, never the rest of the handler.
                -- Only ignore a key WE just injected (self-retrigger guard). Reading the SHARED _G.VX_INJ_KEYS here was the
                -- bug: Auto Earthquake re-stamps key 3 every 40ms while charging and Yuta stamps key 2, so Auto Air was
                -- being suppressed by other features rather than by its own presses.
                local injBlocked = false
                do local k = input.KeyCode; local t = k and airSelfInj[k]; if t and tick() < t then injBlocked = true end end
                -- ENEMY-PRESENCE GATE (root cause of "Auto Air activates randomly"): every sequence below fires off a real
                -- key/click (jump, 1/2/3, M1). With no enemy engaged, jumping to move or pressing 1 in the open used to launch
                -- the whole air combo. Require an enemy within engagement range (40 studs) before ANY sequence runs. This is a
                -- correctness condition, not a timing tweak — it does not change WHEN a valid air combo fires, only that one is
                -- actually intended. (The lines ABOVE this guard — Gojo-TP / lastM1Tgt memory — are separate and unaffected.)
                -- airOK gates the Auto Air branches ONLY (see the note above) — it no longer returns out of the handler.
                local airOK = false
                local _airWhy = "off"
                -- The test button sets this so the enemy-presence gate cannot hide whether the branches themselves work.
                local _airForced = tick() < (tonumber(_G.VX_AIR_FORCE) or 0)
                if autoAirOn then
                        if injBlocked then _airWhy = "ignored (we pressed this key ourselves)"
                        elseif not _G.VX_AIR_NEEDENEMY then
                                -- Gate disabled (the default). Your key press is the intent; we do not second-guess it.
                                airOK = true; _airWhy = "ok (enemy gate off)"
                        else
                                local _am = myHRP(); local _ae = nearestEnemyChar(true); local _ar = _ae and _ae:FindFirstChild("HumanoidRootPart")   -- raw: a far-away LOCK must not disable Auto Air
                                if not _am then _airWhy = "no HumanoidRootPart on you"
                                elseif not _ar then _airWhy = "NO ENEMY FOUND (need a player/dummy in workspace.Characters)"
                                else
                                        -- ═══ THE GATE THAT KEPT AUTO AIR SILENT ═══ The test button forces this open and the
                                        -- sequences fire; the normal path did not, so the gate WAS the blocker. It exists to stop a
                                        -- stray key in the open launching an air combo, which is worth keeping - but 60 studs and a
                                        -- hard requirement that an enemy be resolvable was far too strict, and nearestEnemyChar can
                                        -- miss dummies that live outside the folders it knows. Range raised, and the whole gate is
                                        -- now optional (Combat page toggle, default OFF = no gate) so it can never be the reason
                                        -- nothing happens.
                                        local lim = tonumber(_G.VX_AIR_RANGE) or 150
                                        local d = (_ar.Position - _am.Position).Magnitude
                                        if d <= lim then airOK = true; _airWhy = "ok (enemy " .. math.floor(d) .. " studs)"
                                        else _airWhy = "enemy too far: " .. math.floor(d) .. " studs (limit " .. lim .. ")" end
                                end
                        end
                        if _airForced and not airOK then airOK = true; _airWhy = "FORCED by the test button (" .. _airWhy .. ")" end
                end
                -- DIAGNOSTIC: with _G.VX_BF_DEBUG = true every key press prints whether Auto Air was allowed to run and,
                -- if not, exactly why. This is the fastest way to find out why a sequence stays silent.
                if _G.VX_BF_DEBUG and autoAirOn and input.KeyCode and input.KeyCode ~= Enum.KeyCode.Unknown then
                        dbgAir("key=" .. tostring(input.KeyCode.Name) .. "  airOK=" .. tostring(airOK) .. "  (" .. _airWhy .. ")")
                end
                -- ═══ ALWAYS-ON BLOCK REPORT ═══ Auto Air has been "fixed" several times against a guessed gate and kept
                -- staying silent, so when it is ON and you press one of its keys and it DECLINES, it now says why in F9
                -- without any debug flag. Throttled to one line every 2s per reason, so it is a hint and not a spam.
                -- (It prints only on refusal - a working sequence stays quiet.)
                -- ═══ NAME THE SILENCE ═══ "the auto airs moves dont work" has never come with data. If a sequence
                -- toggle is on, the key is an air key, airOK passed, and NOTHING below claimed the press, say which
                -- character/key found no branch - that one toast is the whole diagnosis.
                if autoAirOn and airOK and input.KeyCode and AIR_KEYS[input.KeyCode] then
                        task.delay(0.1, function()
                                if tick() - (tonumber(_G.VX_AIR_RAN) or 0) < 0.3 then return end   -- a branch ran; quiet
                                if tick() - (_G.VX_AIRNOSEQ_T or 0) < 4 then return end
                                _G.VX_AIRNOSEQ_T = tick()
                                local msg = "Auto Air: no sequence matched key " .. tostring(input.KeyCode.Name) .. " on your character"
                                print("[DreamHub AutoAir] " .. msg .. " (send me this)")
                                if VX_NOTIFY then VX_NOTIFY(msg, false) end
                        end)
                end
                if autoAirOn and not airOK and input.KeyCode and AIR_KEYS[input.KeyCode] then
                        if tick() - (_G.VX_AIRWHY_T or 0) > 2 or _G.VX_AIRWHY_LAST ~= _airWhy then
                                _G.VX_AIRWHY_T = tick(); _G.VX_AIRWHY_LAST = _airWhy
                                print("[DreamHub AutoAir] " .. tostring(input.KeyCode.Name) .. " did nothing: " .. _airWhy)
                        end
                end
                -- ═══════════════ AUTO AIR FOR EVERY CHARACTER, NOT A LIST OF EIGHT ═══════════════
                -- "u made auto swap work for remotes. so why not auto air work" - because until now Auto Air was
                -- nothing BUT hardcoded sequences: Vessel, Gojo, Megumi, Hakari, Choso, Locust. You are playing
                -- Jawbreaker, so not one line of this module has ever run for you. No amount of fixing those branches
                -- was going to change that.
                -- Auto Swap works because it derives its remote instead of hardcoding it, and moves work the same way:
                -- a move's service is its own name without spaces plus "Service" (your Swift Kick / Reserve Balls /
                -- Shutter Doors captures all agree). So this branch does the generic thing for ANY character:
                --   you press 1/2/3/4  ->  we jump  ->  we cast the move that slot owns, in the air.
                -- Nothing is character-specific, so it works on Jawbreaker and on whoever the next update adds.
                local UNIVERSAL_SLOT = {
                        [Enum.KeyCode.One] = 1, [Enum.KeyCode.Two] = 2, [Enum.KeyCode.Three] = 3, [Enum.KeyCode.Four] = 4,
                }
                local function moveInSlot(n)
                        local chs = workspace:FindFirstChild("Characters")
                        for _, c in ipairs({ (chs and chs:FindFirstChild(LP.Name)) or nil, LP.Character }) do
                                local mv = c and c:FindFirstChild("Moveset")
                                if mv then
                                        -- A slot number on the entry wins if the game provides one; otherwise child order IS the
                                        -- bar order (Jawbreaker: Ambush, Backstab, Trip, Cheap Shot = 1,2,3,4).
                                        for _, m in ipairs(mv:GetChildren()) do
                                                local sl = m:GetAttribute("Slot") or m:GetAttribute("Key") or m:GetAttribute("Index")
                                                if tonumber(sl) == n then return m end
                                        end
                                        local kids = mv:GetChildren()
                                        if kids[n] then return kids[n] end
                                end
                        end
                        return nil
                end
                if autoAirOn and airOK and not injBlocked then
                        local slot = UNIVERSAL_SLOT[input.KeyCode]
                        -- ═══ 3 BELONGS TO THE BLACK FLASH WHEN A FLASH MODE IS ARMED ═══ Key 3 is the flash input, and it
                        -- is also ability slot 3. With both features on, one press would try to be a flash AND an air cast
                        -- of slot 3 at the same time - the jump alone would ruin the flash timing. So while any flash mode
                        -- is live, the universal air branch leaves 3 alone and still handles 1, 2 and 4.
                        if slot == 3 and (_G.VX_BFAPI_ON or _G.VX_M1BF_ON or _G.VX_BF_BORROWED) then
                                dbgAir("key 3 is the Black Flash input right now - not air-casting slot 3")
                                slot = nil
                        end
                        -- Explicit opt-in now that it has its own toggle ("Air Cast Any Character"), rather than riding
                        -- along with a character sequence somebody turned on for a different reason.
                        if slot and _G.VX_AIR_UNIVERSAL == true then
                                local mv = moveInSlot(slot)
                                if mv then
                                        task.spawn(function()
                                                -- Jump first so the cast happens off the ground - that is the whole point of "air".
                                                -- Written out rather than calling holdJump(), which is declared further down this
                                                -- function: referencing it from here would read a nil GLOBAL, not that local, and the
                                                -- whole branch would die on the first press.
                                                _G.VX_INJECT_UNTIL = tick() + 0.35
                                                _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Space] = tick() + 0.5
                                                airSelfInj[Enum.KeyCode.Space] = tick() + 0.5
                                                pcall(function()
                                                        VIM:SendKeyEvent(true, Enum.KeyCode.Space, false, game)
                                                        task.wait(0.08)
                                                        VIM:SendKeyEvent(false, Enum.KeyCode.Space, false, game)
                                                end)
                                                -- AIR CAST POWER %. A plain jump is not much height, and some moves want more before
                                                -- they read as airborne. Above 100% we top up the upward velocity on the way past -
                                                -- only the Y component, so it lifts you without throwing you across the map.
                                                local pw = _G.VX_AIR_POWER_ON and (tonumber(_G.VX_AIR_POWER) or 100) or 100
                                                if pw > 100 then
                                                        pcall(function()
                                                                local chs2 = workspace:FindFirstChild("Characters")
                                                                local c2 = (chs2 and chs2:FindFirstChild(LP.Name)) or LP.Character
                                                                local r2 = c2 and c2:FindFirstChild("HumanoidRootPart")
                                                                if r2 then
                                                                        local v2 = r2.AssemblyLinearVelocity
                                                                        r2.AssemblyLinearVelocity = Vector3.new(v2.X, math.max(v2.Y, 50 * (pw / 100)), v2.Z)
                                                                end
                                                        end)
                                                end
                                                game:GetService("RunService").Heartbeat:Wait()   -- land the cast while genuinely airborne
                                                -- The AIR flag. The Vessel branch's own working call is FireServer(move, true) - the
                                                -- second argument is what asks for the airborne variant. Without it we jumped and then
                                                -- politely requested the GROUND move, which is why "auto air moves dont work" even when
                                                -- the remote resolved fine.
                                                _G.VX_NO_KEYFALLBACK = true
                                                local ok = _G.VX_CAST_MOVE and _G.VX_CAST_MOVE(mv.Name, true)
                                                _G.VX_NO_KEYFALLBACK = nil
                                                dbgAir("universal air: slot " .. slot .. " = " .. mv.Name .. "  -> " .. (ok and "cast" or "no service"))
                                                if not ok and tick() - (_G.VX_AIRUNI_T or 0) > 3 then
                                                        _G.VX_AIRUNI_T = tick()
                                                        local guess = (mv.Name:gsub("%s+", "")) .. "Service"
                                                        print("[DreamHub AutoAir] no service for '" .. mv.Name .. "' (looked for " .. guess .. ") - send me this line")
                                                        -- On screen too. Every round of "auto air dont work" so far has come with no console
                                                        -- line attached, and this one sentence is the entire fix: it names the move and the
                                                        -- service that does not exist.
                                                        if VX_NOTIFY then VX_NOTIFY("Auto Air: no " .. guess .. " for " .. mv.Name, false) end
                                                elseif ok and not _G.VX_AIRUNI_OK then
                                                        _G.VX_AIRUNI_OK = true
                                                        if VX_NOTIFY then VX_NOTIFY("Auto Air: cast " .. mv.Name .. " in the air", true) end
                                                end
                                        end)
                                elseif tick() - (_G.VX_AIRUNI_T or 0) > 3 then
                                        _G.VX_AIRUNI_T = tick()
                                        dbgAir("universal air: nothing in slot " .. slot .. " of your Moveset")
                                end
                        end
                end

                -- BULLETPROOF character check: detected name, model name, DISPLAY name, or any Moveset entry containing the word.
                local function charIs(...)
                        local chs = workspace:FindFirstChild("Characters"); local c = (chs and chs:FindFirstChild(LP.Name)) or LP.Character
                        if not c then return false end
                        local n = c:FindFirstChildOfClass("Humanoid")
                        local hay = string.lower((c.Name or "") .. " " .. (n and n.DisplayName or "") .. " " .. (detectCharName(c) or ""))
                        local mv = c:FindFirstChild("Moveset"); if mv then for _, m in ipairs(mv:GetChildren()) do hay = hay .. " " .. string.lower(m.Name) end end
                        -- NORMALISED compare: the game writes names unspaced ("BlackFlash"), so a raw search for "black flash"
                        -- could never match. Strip spaces/underscores/hyphens from BOTH sides, same as normMove does for moves.
                        local nhay = (string.gsub(hay, "[%s_%-]", ""))
                        for _, w in ipairs({ ... }) do
                                local nw = (string.gsub(string.lower(tostring(w)), "[%s_%-]", ""))
                                if nw ~= "" and string.find(nhay, nw, 1, true) then return true end
                        end
                        return false
                end
                -- MOVE-BASED detection (user's exact captures): check YOUR Moveset for the move name, not the character name.
                -- ═══ THE AUTO AIR BUG ═══ The game stores move names UNSPACED ("RoughEnergy", "LapseBlue",
                -- "TwofoldKick", "CrushingJaws"), but every call below asks for the SPACED display name
                -- ("Rough Energy"). A plain substring search for "rough energy" inside "roughenergy" never matches, so
                -- ONLY the single-word "Nue" branches could ever fire — that is why Auto Air did nothing for the
                -- Vessel / Gambler / Locust. We now NORMALISE both sides (strip spaces, underscores, hyphens, case)
                -- before comparing, and we look in EVERY place a moveset is known to live:
                --   char.Moveset/*            (folder of move objects  - original)
                --   char.Info.Moveset         (StringValue             - newer layout)
                --   char.Info.Character/Moveset attributes
                local function normMove(s) return (string.gsub(string.lower(tostring(s or "")), "[%s_%-]", "")) end
                local function hasMove(name)
                        local chs = workspace:FindFirstChild("Characters"); local c = (chs and chs:FindFirstChild(LP.Name)) or LP.Character
                        if not c then return false end
                        local want = normMove(name); if want == "" then return false end
                        -- ONE-SHOT DEBUG DUMP: with _G.VX_BF_DEBUG = true, print your character's real Moveset child names to
                        -- F9 the first time this runs. That tells us definitively whether the game spells moves "RoughEnergy"
                        -- or "Rough Energy" — send me that line and any future move can be matched exactly.
                        if _G.VX_BF_DEBUG and not _G.VX_MOVEDUMPED then
                                _G.VX_MOVEDUMPED = true
                                pcall(function()
                                        local mv0 = c:FindFirstChild("Moveset")
                                        local names = {}
                                        if mv0 then for _, mm in ipairs(mv0:GetChildren()) do names[#names + 1] = mm.Name end end
                                        print("[DreamHub AutoAir] character=" .. tostring(c.Name) .. "  Moveset children = { " .. table.concat(names, ", ") .. " }")
                                end)
                        end
                        -- 1) the Moveset FOLDER (each child is a move)
                        local mv = c:FindFirstChild("Moveset")
                        if mv then for _, mm in ipairs(mv:GetChildren()) do if string.find(normMove(mm.Name), want, 1, true) then return true end end end
                        -- FALLBACKS BELOW ARE DELIBERATELY NARROW. They only run when the Moveset FOLDER did not answer, and
                        -- only for needles of 5+ chars. A short needle like "nue" is a substring of ordinary words such as
                        -- "Continue", so searching attributes / animation names with it would auto-press keys for a character
                        -- that has no Nue. Long needles ("roughenergy", "crushingjaws", "twofoldkick", "lapseblue") are safe.
                        if #want < 5 then return false end
                        -- 2) a Moveset StringValue (folder absent / renamed after a game update)
                        local hay = ""
                        pcall(function()
                                local info = c:FindFirstChild("Info")
                                if info then
                                        local msv = info:FindFirstChild("Moveset")
                                        if msv and msv:IsA("StringValue") then hay = hay .. " " .. msv.Value end
                                        local cv = info:FindFirstChild("Character")
                                        if cv and cv:IsA("StringValue") then hay = hay .. " " .. cv.Value end
                                end
                                if mv and mv:IsA("StringValue") then hay = hay .. " " .. mv.Value end
                                for _, an in ipairs({ "Moveset", "Character", "Class" }) do
                                        local av = c:GetAttribute(an); if type(av) == "string" then hay = hay .. " " .. av end
                                end
                        end)
                        if hay ~= "" and string.find(normMove(hay), want, 1, true) then return true end
                        -- 3) last resort: the equipped tool / animation names sometimes carry the move name
                        local okd, res = pcall(function()
                                local h = c:FindFirstChildOfClass("Humanoid"); local an = h and h:FindFirstChildOfClass("Animator")
                                if not an then return false end
                                for _, tr in ipairs(an:GetPlayingAnimationTracks()) do
                                        if tr.Animation and string.find(normMove(tr.Animation.Name), want, 1, true) then return true end
                                end
                                return false
                        end)
                        if okd and res then return true end
                        return false
                end
                local function holdJump() _G.VX_INJECT_UNTIL = tick() + 0.35; _G.VX_INJ_KEYS = _G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Space] = tick() + 0.5; airSelfInj[Enum.KeyCode.Space] = tick() + 0.5; pcall(function() VIM:SendKeyEvent(true, Enum.KeyCode.Space, false, game); task.wait(0.08); VIM:SendKeyEvent(false, Enum.KeyCode.Space, false, game) end) end
                local kc = input.KeyCode

                -- ═══════════════════ AUTO AIR — built from the user's exact remote captures ═══════════════════
                -- Every sequence below fires the REAL Knit service RemoteEvent the user captured, with the real Moveset
                -- object as the argument, exactly as the capture showed. Key presses are kept only where the capture
                -- itself was a key (jump / R / 1). Each character has its own toggle so you pick what runs.
                -- Cache resolved moves per (character, name). The descendant scan below is only reached when the folder
                -- lookups fail, and that is a PERSISTENT state - without a cache it would re-scan the whole rig on every
                -- single press of that key for the rest of the session.
                local function moveObj(nm)
                        local chs = workspace:FindFirstChild("Characters"); local c = (chs and chs:FindFirstChild(LP.Name)) or LP.Character
                        local mv = c and c:FindFirstChild("Moveset")
                        -- ONE-SHOT DEBUG DUMP (moved here from hasMove, which is no longer on the hot path): with
                        -- _G.VX_BF_DEBUG = true this prints your character's REAL Moveset child names to F9 the first time
                        -- Auto Air looks one up. If Auto Air ever goes quiet, that line tells us exactly why.
                        if _G.VX_BF_DEBUG and not _G.VX_MOVEDUMPED then
                                _G.VX_MOVEDUMPED = true
                                pcall(function()
                                        local names = {}
                                        if mv and mv:IsA("Folder") or (mv and mv:IsA("Model")) then
                                                for _, mm in ipairs(mv:GetChildren()) do names[#names + 1] = mm.Name end
                                        end
                                        print("[DreamHub AutoAir] char=" .. tostring(c and c.Name) ..
                                                "  Moveset=" .. tostring(mv and mv.ClassName or "MISSING") ..
                                                "  children = { " .. table.concat(names, ", ") .. " }")
                                end)
                        end
                        if not mv then dbgAir("no Moveset folder - falling back to a descendant scan") end
                        local want = normMove(nm)                                   -- spacing-proof ("RoughEnergy" == "Rough Energy")
                        _G.VX_MOVECACHE = _G.VX_MOVECACHE or {}
                        local ck = tostring(c) .. "|" .. want
                        local hit = _G.VX_MOVECACHE[ck]
                        if hit and hit.Parent then return hit end
                        if mv then
                                local direct = mv:FindFirstChild(nm); if direct then _G.VX_MOVECACHE[ck]=direct; return direct end
                                for _, mm in ipairs(mv:GetChildren()) do if normMove(mm.Name) == want then _G.VX_MOVECACHE[ck]=mm; return mm end end
                                -- SUBSTRING fallback: covers suffixed entries like "Lapse Blue MAX"
                                for _, mm in ipairs(mv:GetChildren()) do if string.find(normMove(mm.Name), want, 1, true) then _G.VX_MOVECACHE[ck]=mm; return mm end end
                        end
                        -- LAST RESORT: a game update can relocate/rename the Moveset container. Scan all descendants for an
                        -- Instance whose normalised name matches EXACTLY (strict equality, never substring - a loose match
                        -- here could hand FireServer an unrelated Sound/Animation and get the call rejected).
                        -- Only container-ish classes are plausible Moveset entries. Accepting an Animation/Sound here would
                        -- hand FireServer a junk instance (silently rejected) AND mask the key fallback below it.
                        for _, d in ipairs(c:GetDescendants()) do
                                if normMove(d.Name) == want then
                                        local cn = d.ClassName
                                        if cn == "Folder" or cn == "Model" or cn == "Configuration" or cn == "ModuleScript"
                                                or cn == "ObjectValue" or cn == "StringValue" or cn == "Tool" or cn == "Part" then
                                                _G.VX_MOVECACHE[ck]=d; return d
                                        end
                                end
                        end
                        return nil
                end
                local function svcRE(svc, re)
                        local k = RS:FindFirstChild("Knit"); k = k and k:FindFirstChild("Knit"); k = k and k:FindFirstChild("Services")
                        local s = k and k:FindFirstChild(svc); local r = s and s:FindFirstChild("RE")
                        return r and r:FindFirstChild(re)
                end
                local function fireSvc(svc, re, ...)
                        local r = svcRE(svc, re)
                        if not r then
                                -- ═══ SAY IT OUT LOUD ═══ A missing remote was only reported behind a debug flag, so every
                                -- wrong service name in this module failed completely silently - which is what "auto air does
                                -- nothing" looks like from the outside. Several of these names are guesses at MOVE-named
                                -- services (RoughEnergyService, CrushJawService...) while the capture only ever proved the
                                -- CHARACTER-named pattern (<Char>Service.RE.Activated). Report it unconditionally, throttled,
                                -- so one run in-game names the ones that are wrong instead of another round of guessing.
                                if tick() - (_G.VX_AIRMISS_T or 0) > 2 then
                                        _G.VX_AIRMISS_T = tick()
                                        print("[DreamHub AutoAir] remote MISSING: " .. svc .. ".RE." .. re .. "  (send me this line)")
                                        -- ═══ AND PUT IT ON SCREEN ═══ Printing to F9 only works if someone opens F9. "auto air dont
                                        -- work" has come back several times with no console line attached, so the reason now shows
                                        -- up in the game where it cannot be missed. It also names the service, which is the single
                                        -- piece of information needed to fix it.
                                        if VX_NOTIFY then VX_NOTIFY("Auto Air: no remote " .. svc .. "." .. re, false) end
                                        -- One-shot: dump what the service folder ACTUALLY has, so a wrong guess is identifiable
                                        -- from one run instead of one guess per round trip.
                                        if not _G.VX_AIRDUMPED then
                                                _G.VX_AIRDUMPED = true
                                                pcall(function()
                                                        local k = RS:FindFirstChild("Knit"); k = k and k:FindFirstChild("Knit"); k = k and k:FindFirstChild("Services")
                                                        if not k then print("[DreamHub AutoAir] no Knit.Knit.Services folder at all") return end
                                                        local names = {}
                                                        for _, s in ipairs(k:GetChildren()) do names[#names + 1] = s.Name end
                                                        table.sort(names)
                                                        print("[DreamHub AutoAir] every service that EXISTS = { " .. table.concat(names, ", ") .. " }")
                                                end)
                                        end
                                end
                                return false
                        end
                        local a = table.pack(...)
                        local ok = pcall(function() r:FireServer(table.unpack(a, 1, a.n)) end)
                        dbgAir((ok and "fired " or "FAILED ") .. svc .. "." .. re)
                        return ok
                end
                -- Fire the remote if it exists; otherwise press the key the game itself binds to that move. A wrong
                -- service name then degrades to "the key press still happens" instead of "nothing happens at all".
                local function fireOrKey(svc, re, key, ...)
                        if fireSvc(svc, re, ...) then return true end
                        if key then tapKey(key) end
                        return false
                end
                -- ═══ CHARACTER SERVICE FIRST ═══ The only remote path this game was ever OBSERVED to use is the
                -- character-named one: <Char>Service.RE.Activated(<move>, ...). Five of the seven services this module
                -- fired were MOVE-named guesses (RoughEnergyService, CrushJawService, RedScaleService,
                -- RabbitEscapeService, ReversalRedService) - and the only two that follow the observed pattern,
                -- MegumiService and GojoService, are the two that were reported working. A move-named service that
                -- does not exist means the call silently does nothing, which is exactly "auto air doesn't work".
                -- So: resolve YOUR character's service from your moveset and fire that; only fall back to the
                -- move-named guess if the character service has no such remote; only then press the key.
                -- ═══ AUTO AIR STOPS GUESSING SERVICE NAMES ═══ Every failure this module has ever had was the same
                -- one: a hardcoded guess at a service name (RoughEnergyService, CrushJawService, RedScaleService...)
                -- that does not exist, failing silently. The captures show the name is DERIVABLE - a move's service is
                -- its own name with the spaces removed and "Service" on the end - so the first thing we try now is
                -- the move you actually own, resolved by name at the moment we fire it. That works on every character
                -- including ones nobody has ever captured, which is the whole problem.
                -- The old paths stay as fallbacks, in that order, so nothing that used to work can stop working.
                local function fireMove(moveSvc, re, key, ...)
                        _G.VX_AIR_RAN = tick()   -- a sequence claimed this press; the no-sequence toast stands down
                        -- 1) THE DERIVED MOVE SERVICE. Only for Activated (the cast remote); a directional/right-click
                        --    remote still belongs to the character service below.
                        if re == "Activated" then
                                local a = table.pack(...)
                                local moveObj = a.n >= 1 and a[1] or nil
                                local nm = (typeof(moveObj) == "Instance") and moveObj.Name or (type(moveObj) == "string" and moveObj) or nil
                                if nm and _G.VX_CAST_MOVE then
                                        local extra = {}
                                        for i = 2, a.n do extra[#extra + 1] = a[i] end
                                        if _G.VX_CAST_MOVE(nm, table.unpack(extra, 1, math.max(0, a.n - 1))) then
                                                dbgAir("fired the derived move service for " .. nm)
                                                return true
                                        end
                                end
                        end
                        -- 2) the character service (proven for Down/Up and the RightActivated family)
                        local charSvc = vxMyCharSvc()
                        if charSvc and svcRE(charSvc, re) then
                                local a = table.pack(...)
                                local ok = pcall(function() svcRE(charSvc, re):FireServer(table.unpack(a, 1, a.n)) end)
                                dbgAir((ok and "fired " or "FAILED ") .. charSvc .. "." .. re .. "  (character service)")
                                if ok then return true end
                        end
                        -- 3) the hardcoded guess this module shipped with
                        if moveSvc and svcRE(moveSvc, re) then return fireSvc(moveSvc, re, ...) end
                        if tick() - (_G.VX_AIRMISS_T or 0) > 2 then
                                _G.VX_AIRMISS_T = tick()
                                print("[DreamHub AutoAir] no remote for " .. re .. ": tried the derived move service, "
                                        .. tostring(charSvc) .. " and " .. tostring(moveSvc) .. (key and " - pressing the key instead" or ""))
                                if VX_NOTIFY then VX_NOTIFY("Auto Air: no remote for that move - check F9", false) end
                        end
                        if key then tapKey(key) end
                        return false
                end
                local function airTarget()   -- the capture used workspace.Characters.Dummy; live play wants the real enemy
                        local e = nearestEnemyChar(); if e then return e end
                        local chs = workspace:FindFirstChild("Characters"); return chs and chs:FindFirstChild("Dummy")
                end

                -- PRINCIPLE: your own key press already casts the move. Each branch adds ONLY the follow-up the capture
                -- describes — it never re-sends the same ability the key just fired, and it never both presses the key
                -- AND fires the remote that key triggers (that double-cast burns a second cooldown or cancels the first).

                -- Every branch below stamps _G.VX_BUSY, so comparing it before/after tells us whether ANY sequence
                -- matched. That is how the report at the bottom can say "the range gate passed but no branch owns your
                -- character + that key" without threading a flag through twenty branches.
                local _airBusyBefore = _G.VX_BUSY or 0

                -- ── VESSEL (Itadori) — key 1 -> Cursed Strikes (air variant: the captured `true` flag) ──
                if airOK and airOpt.Vessel and kc == Enum.KeyCode.One and (hasMove("Cursed Strikes") or charIs("vessel","itadori","sukuna","divergent")) then
                        _G.VX_BUSY = tick() + 1.2; dbgAir("Vessel 1 -> Cursed Strikes")
                        task.delay(0.05, function()
                                local mv = moveObj("Cursed Strikes"); if autoAirOn and mv then fireMove("CursedStrikesService", "Activated", nil, mv, true) end   -- no key fallback: it would just re-press the key you already hit
                        end)
                end

                -- ── HAKARI (Restless Gambler) — key 3 -> jump + Rough Energy (air variant) ──
                if airOK and airOpt.Hakari and kc == Enum.KeyCode.Three and (hasMove("Rough Energy") or charIs("hakari","gambler")) then
                        _G.VX_BUSY = tick() + 1.4; dbgAir("Hakari 3 -> jump + Rough Energy")
                        task.spawn(function() holdJump() end)
                        task.delay(0.10, function()
                                local mv = moveObj("Rough Energy"); if autoAirOn then if mv then fireMove("RoughEnergyService", "Activated", Enum.KeyCode.Three, mv, true) else tapKey(Enum.KeyCode.Three) end end
                        end)

                end

                -- ── MEGUMI — key 2 (Nue) -> add the R effect. We fire RightActivated directly INSTEAD of tapping R:
                --    tapping R would make the game fire the same remote, double-casting it. ──
                if airOK and airOpt.Megumi and kc == Enum.KeyCode.Two and (hasMove("Nue") or charIs("megumi","shadows","fushiguro")) then
                        _G.VX_BUSY = tick() + 1.4; dbgAir("Megumi 2 -> R")
                        task.delay(0.03, function()
                                if not autoAirOn then return end
                                if svcRE("MegumiService", "RightActivated") then fireSvc("MegumiService", "RightActivated")
                                else tapKey(Enum.KeyCode.R) end          -- remote missing -> just press the key
                        end)

                -- ── CHOSO (Blood Manip) — key 2 -> Flowing Red Scale, must JUMP ──
                elseif airOK and airOpt.Choso and kc == Enum.KeyCode.Two and (hasMove("Flowing Red Scale") or charIs("choso","blood")) then
                        _G.VX_BUSY = tick() + 1.4; dbgAir("Choso 2 -> jump + Flowing Red Scale")
                        task.spawn(function() holdJump() end)
                        task.delay(0.08, function()
                                local mv = moveObj("Flowing Red Scale"); if autoAirOn then if mv then fireMove("RedScaleService", "Activated", Enum.KeyCode.Two, mv, true) else tapKey(Enum.KeyCode.Two) end end
                        end)
                end

                -- ── MEGUMI — key R -> Rabbit Escape. Firing the remote IS the "press 1" the capture shows, so we do not
                --    also tap 1 (that would cast Rabbit Escape twice). ──
                if airOK and airOpt.Megumi and kc == Enum.KeyCode.R and (hasMove("Rabbit Escape") or charIs("megumi","shadows","fushiguro")) then
                        _G.VX_BUSY = tick() + 1.4; dbgAir("Megumi R -> Rabbit Escape / 1")
                        task.delay(0.03, function()
                                if not autoAirOn then return end
                                local mv = moveObj("Rabbit Escape")
                                if mv and svcRE("RabbitEscapeService", "Activated") then fireMove("RabbitEscapeService", "Activated", Enum.KeyCode.One, mv, airTarget())
                                else tapKey(Enum.KeyCode.One) end        -- no Moveset/remote -> just press 1
                        end)
                end

                -- ── GOJO — key 1 (Lapse Blue) -> SPAM R during it ──
                -- ═══ ONE TIMED R KEPT MISSING ═══ "as soon as I click one, you need to automatically spam R to
                -- make it work." The single 0.22s-delayed R landed only if the cast committed at exactly the
                -- guessed beat. Now R starts 0.12s after your 1 and repeats across the whole cast window -
                -- every press is stamped as ours (tapKey), so nothing downstream chains off them.
                if airOK and airOpt.LapseBlue and kc == Enum.KeyCode.One and (hasMove("Lapse Blue") or charIs("gojo","limitless")) then
                        _G.VX_BUSY = tick() + 1.6; dbgAir("Gojo 1 -> Lapse Blue -> R spam")
                        task.spawn(function()
                                task.wait(0.12)
                                for _ = 1, 8 do
                                        if not autoAirOn then break end
                                        tapKey(Enum.KeyCode.R)
                                        task.wait(0.13)
                                end
                        end)   -- anim 99920923658527
                end

                -- ── GOJO — Lapse Blue -> 2 + R on the same beat. REAL KEYS now: the remote-only version was
                --    server-rejected out of context (the same story Auto Air already told), which is why
                --    "2 plus R doesn't work". 2 lands first (Reversal Red), then R bursts behind it. ──
                if airOK and airOpt.LapseRed and kc == Enum.KeyCode.One and (hasMove("Lapse Blue") or charIs("gojo","limitless")) then
                        _G.VX_BUSY = tick() + 1.6; dbgAir("Gojo 1 -> 2 + R (keyed)")
                        task.spawn(function()
                                task.wait(0.24)
                                if not autoAirOn then return end
                                tapKey(Enum.KeyCode.Two)
                                task.wait(0.10)
                                for _ = 1, 4 do
                                        if not autoAirOn then break end
                                        tapKey(Enum.KeyCode.R)
                                        task.wait(0.14)
                                end
                        end)
                end

                -- ── GOJO Twofold Kick — key 4 casts it; the R after the SECOND kick is fired by the anim hook. ──
                -- ═══ VESSEL (Itadori / Sukuna) — you JUMP -> auto-press 1 to carry them up ═══
                -- Recovered from commit b0034dc; kept CHARACTER-based because the launcher is the jump itself, not a
                -- named move, so hasMove()/moveObj() cannot express it.
                if airOK and airOpt.Vessel and kc == Enum.KeyCode.Space and charIs("vessel", "itadori", "sukuna", "black flash", "divergent") then
                        if tick() - (lastVesselAir or 0) > 0.9 then
                                lastVesselAir = tick(); _G.VX_BUSY = tick() + 1.2; dbgAir("Vessel: Jump -> 1")
                                task.delay(0.12, function() if autoAirOn then tapKey(Enum.KeyCode.One) end end)
                        end
                end
                -- ═══ SECOND HALF OF THE BLOCK REPORT ═══ The range gate passed and you pressed one of Auto Air's keys,
                -- but no branch claimed it. That means the character/move test failed, so print what your rig ACTUALLY
                -- has - that is the one piece of information needed to add or fix the branch. Throttled, once per key.
                if autoAirOn and airOK and kc and AIR_KEYS[kc] and (_G.VX_BUSY or 0) == _airBusyBefore then
                        if tick() - (_G.VX_AIRNOBRANCH_T or 0) > 2 or _G.VX_AIRNOBRANCH_K ~= kc then
                                _G.VX_AIRNOBRANCH_T = tick(); _G.VX_AIRNOBRANCH_K = kc
                                local chs = workspace:FindFirstChild("Characters")
                                local c = (chs and chs:FindFirstChild(LP.Name)) or LP.Character
                                local mv = c and c:FindFirstChild("Moveset")
                                local names = {}
                                if mv then for _, m in ipairs(mv:GetChildren()) do names[#names + 1] = m.Name end end
                                print("[DreamHub AutoAir] " .. tostring(kc.Name) .. ": no sequence for this character."
                                        .. "  rig=" .. tostring(c and c.Name)
                                        .. "  detected=" .. tostring(c and detectCharName(c))
                                        .. "  Moveset={ " .. table.concat(names, ", ") .. " }")
                        end
                end
        end
        -- Driven by BOTH the normal input event AND a raw key poll. If the game sinks an ability key, InputBegan
        -- never fires for it and every Auto Air sequence is silently dead - the poll sees the press regardless.
        -- A short per-key stamp stops the two paths from double-running the same press.
        local __airLast = {}
        local function __airOnce(kc)
                if not kc then return end
                if __airLast[kc] and tick() - __airLast[kc] < 0.05 then return end   -- ~3 frames: collapses one press seen by both paths, never a real follow-up
                __airLast[kc] = tick()
                __airHandler({ KeyCode = kc, UserInputType = Enum.UserInputType.Keyboard }, false)
        end
        UIS.InputBegan:Connect(function(input, gpe) if input and input.KeyCode and input.KeyCode ~= Enum.KeyCode.Unknown then __airOnce(input.KeyCode) else __airHandler(input, gpe) end end)
        if _G.VX_ON_KEY then _G.VX_ON_KEY("autoair", function(kc) __airOnce(kc) end) end
        if _G.VX_M1_SUB then _G.VX_M1_SUB("autoair_m1tgt", function() local m = landedM1Target(); if m then lastM1Tgt = m end end) end   -- real M1s only come from the poll
        -- AUTO AIR anim triggers: Twofold Kick (Gojo) kicks them UP -> click R (RightActivated at the target).
        -- Gambler: your landed M1 -> fire Rough Energy (the 'click 3 for you' launcher).
        AutoAirApi_set = function(v)
                autoAirOn = v == true
                -- ═══ SAY WHAT IT IS ABOUT TO DO ═══ Auto Air has been reported broken more than anything else in this
                -- file, and every time the answer was "it was never going to run for your character". Turning it on
                -- now reads your own moveset out loud: if it lists your four moves, the universal path is live and a
                -- key press will cast them airborne. If it says it found nothing, that is the bug, immediately, with
                -- no F9 and no guessing.
                if not autoAirOn then return end
                task.spawn(function()
                        local chs = workspace:FindFirstChild("Characters")
                        local c = (chs and chs:FindFirstChild(LP.Name)) or LP.Character
                        local mv = c and c:FindFirstChild("Moveset")
                        local names = {}
                        if mv then for i, m in ipairs(mv:GetChildren()) do if i <= 4 then names[#names + 1] = i .. "=" .. m.Name end end end
                        if #names > 0 then
                                local msg = "Auto Air ready: " .. table.concat(names, ", ")
                                print("[DreamHub AutoAir] " .. msg)
                                if VX_NOTIFY then VX_NOTIFY(msg, true) end
                        else
                                print("[DreamHub AutoAir] no Moveset found on your character - the universal path has nothing to cast")
                                if VX_NOTIFY then VX_NOTIFY("Auto Air: no Moveset found on your character", false) end
                        end
                end)
        end
        -- ═══ DIAGNOSTIC ═══ Force one Auto Air pass for a key with the enemy gate BYPASSED, and say what it saw.
        -- Auto Air has been patched against three different guessed gates and still reports as dead, so this proves
        -- which half is broken: if the branch fires here but not in a fight, the gate is the problem; if no branch
        -- claims the key even here, the character/move test is.
        AutoAirApi_test = function(keyName)
                local kc = Enum.KeyCode[keyName or "One"]
                local chs = workspace:FindFirstChild("Characters")
                local c = (chs and chs:FindFirstChild(LP.Name)) or LP.Character
                local mv = c and c:FindFirstChild("Moveset")
                local names = {}
                if mv then for _, m in ipairs(mv:GetChildren()) do names[#names + 1] = m.Name end end
                local hrp = myHRP(); local en = nearestEnemyChar(true)
                local er = en and en:FindFirstChild("HumanoidRootPart")
                print("[AutoAir TEST] key=" .. tostring(keyName)
                        .. "  autoAirOn=" .. tostring(autoAirOn)
                        .. "  rig=" .. tostring(c and c.Name)
                        .. "  detected=" .. tostring(c and detectCharName(c))
                        .. "  Moveset={ " .. table.concat(names, ", ") .. " }")
                print("[AutoAir TEST] you=" .. tostring(hrp ~= nil)
                        .. "  nearestEnemy=" .. tostring(en and en.Name or "NONE")
                        .. "  dist=" .. tostring((er and hrp) and math.floor((er.Position - hrp.Position).Magnitude) or "n/a"))
                local savedOn = autoAirOn
                autoAirOn = true
                _G.VX_AIR_FORCE = tick() + 1        -- __airHandler treats this as "range gate satisfied"
                __airOnce(kc)
                task.delay(1, function() autoAirOn = savedOn; _G.VX_AIR_FORCE = 0 end)
        end
        -- ANIM-DRIVEN backup (your captured ids): keeps aiming through Gojo's R (99920923658527), and the RED
        -- charge anim (137654778575373) auto-clicks R even if the key-3 press was missed/eaten.
        local GOJO_R_ANIM, RED_ANIM = "99920923658527", "137654778575373"
        -- Auto Air anim ids (user captures): Twofold Kick, and the two Locust fly-up anims.
        local TWOFOLD_ANIM = "104749346956269"
        local LOCUST_UP = { ["134777193523837"] = true, ["112223227323175"] = true }
        local twofoldCount, lastTwofold, lastLocustR = 0, 0, 0
        -- Gojo M1 landing anims (your capture) -> count them for the "After N M1s" TP-back mode
        local GOJO_M1 = { ["127851700400958"] = true, ["72548435296350"] = true, ["84547415708554"] = true }
        local gojoM1Count, lastGojoM1 = 0, 0
        local lastRedR = 0
        local hookedA = setmetatable({}, { __mode = "k" })
        local function hookSelfAnims()
                local chs = workspace:FindFirstChild("Characters"); local c = (chs and chs:FindFirstChild(LP.Name)) or LP.Character
                local h = c and c:FindFirstChildOfClass("Humanoid"); local a = h and h:FindFirstChildOfClass("Animator")
                if not a or hookedA[a] then return end
                hookedA[a] = a.AnimationPlayed:Connect(function(track)
                        local id = track.Animation and tostring(track.Animation.AnimationId):match("%d+"); if not id then return end
                        if id == GOJO_R_ANIM and gojoOn then                                          -- Gojo R started: keep AIMING at the target through the grab window
                                task.spawn(function() local mdl = currentTarget(); for _ = 1, 8 do if not (mdl and mdl.Parent) then break end faceTargetNow(mdl); task.wait(0.04) end end)
                        end
                        -- AFTER-M1s mode: count YOUR Gojo M1s; at the chosen count, TP behind. Reset the count if you stop M1ing.
                        if GOJO_M1[id] and gojoOn and (tostring(_G.VX_GOJO_MODE or "Q Dash") == "After M1s") then
                                if tick() - lastGojoM1 > 2 then gojoM1Count = 0 end   -- new combo
                                lastGojoM1 = tick(); gojoM1Count = gojoM1Count + 1
                                if gojoM1Count >= (tonumber(_G.VX_GOJO_COUNT) or 2) then
                                        gojoM1Count = 0
                                        if _G.VX_GOJO_TPBACK then task.spawn(_G.VX_GOJO_TPBACK) end
                                end
                        end
                        if id == RED_ANIM and redOn and tick() - lastRedR > 0.6 then                  -- Red charge anim: click R
                                lastRedR = tick()
                                task.spawn(function() pcall(function() VIM:SendKeyEvent(true, Enum.KeyCode.R, false, game); task.wait(0.12); VIM:SendKeyEvent(false, Enum.KeyCode.R, false, game) end) end)
                        end
                        -- ═══ AUTO AIR — ANIM-DRIVEN R PRESSES (user's captured ids) ═══
                        -- TWOFOLD KICK (104749346956269): press R after the SECOND kick. The anim plays once per kick, so we
                        -- count plays and act on the 2nd; the counter resets after 1.5s idle so a new cast starts clean.
                        if autoAirOn and airOpt.Twofold and id == TWOFOLD_ANIM then
                                if tick() - lastTwofold > 1.5 then twofoldCount = 0 end
                                lastTwofold = tick(); twofoldCount = twofoldCount + 1
                                if twofoldCount >= 2 then
                                        twofoldCount = 0
                                        dbgAir("Twofold: 2nd kick -> R")
                                        task.spawn(function()
                                                pcall(function() VIM:SendKeyEvent(true, Enum.KeyCode.R, false, game); task.wait(0.10); VIM:SendKeyEvent(false, Enum.KeyCode.R, false, game) end)
                                        end)
                                end
                        end
                end)
        end
        task.spawn(function() while true do if gojoOn or redOn or autoAirOn then pcall(hookSelfAnims) end task.wait(0.7) end end)
        GojoTpApi = { set = function(v) gojoOn = v == true; _G.VX_GOJO_TPBACK_ON = v == true end }
        ReversalRedApi = { set = function(v) redOn = v == true end }
end

-- ============================================================
-- Native move recipes. Air variants intercept the initial cast before jumping.
do
    local UIS=game:GetService("UserInputService")
    local VIM=game:GetService("VirtualInputManager")
    local CAS=game:GetService("ContextActionService")
    local options, versions={},{}
    local running=false
    local serial,lastInput=0,{}
    local initialRotation,initialMouse
    local legacySet=AutoAirOptSet
    AutoAirOptSet=function(name,value)
        options[name]=value==true
        -- ═══ ONE RECIPE PER KEY ═══ the dropdown used to just pile options on: pick "Lapse Blue -> 2 + R"
        -- once and "Gojo: 1 -> R" stayed armed underneath forever, so pressing 1 ran the WRONG recipe from
        -- then on ("Gojo 1 was working earlier, but it stopped working"). LapseRed and LapseBlue both listen
        -- on 1 - selecting one now deselects the other.
        if name=="LapseRed" and value==true then options.LapseBlue=false end
        if name=="LapseBlue" and value==true then options.LapseRed=false end
        versions[name]=(versions[name] or 0)+1
        table.clear(lastInput)
        if name=="Twofold" and legacySet then legacySet(name,false) end -- native 4 -> R burst owns this now
        -- ═══ LOCUST OWNS KEY 3 ═══ read by VXBF2's BF-trigger sink: with this flag up, a real 3 passes
        -- through to the game (Crushing Jaws casts) instead of being sunk into a Black Flash chain, while
        -- the R spam below handles the follow-up.
        -- The callable owner below also checks the current character.
    end
    local function body() return vxMyChar() end
    local function owns(name)
        local c=body(); local moves=c and c:FindFirstChild("Moveset")
        local function norm(s) return s:lower():gsub("[^%w]","") end
        if moves then
            for _,move in ipairs(moves:GetChildren()) do
                local actual=norm(move.Name); local expected=norm(name)
                if actual==expected or (name=="LapseBlue" or name=="ReversalRed") and actual==expected.."max" then return true end
            end
            -- Awakened/renamed moves may differ; still consult the character identity below.
        end
        local aliases={RoughEnergy={"hakari","gambler"},Nue={"megumi","fushiguro","shadows"},RabbitEscape={"megumi","fushiguro","shadows"},
            LapseBlue={"gojo","strongest","limitless"},ReversalRed={"gojo","strongest","limitless"},CrushingJaws={"locust"},CursedStrikes={"vessel","itadori"},FlowingRedScale={"choso","blood"}}
        local detected=c and detectCharName(c)
        local identity=norm(tostring(detected or ""))
        for _,alias in ipairs(aliases[name] or {}) do if identity:find(alias,1,true) then return true end end
        return false
    end
    local function blocked(key) return _G.VX_KEY_BLOCKED and _G.VX_KEY_BLOCKED(key) end
    local function family(expected)
        local groups={Gojo={"LapseBlue","ReversalRed","TwofoldKick"},Megumi={"Nue","RabbitEscape"},Locust={"CrushingJaws"}}
        for name,names in pairs(groups) do
            for _,move in ipairs(names) do if owns(move) then return name==expected end end
        end
        local ok,service=pcall(function() return vxMyCharSvc() end)
        if ok and service then return service==expected.."Service" end
        return true -- explicit toggle remains usable when no character identity is exposed
    end
    -- ═══ r15: YOUR 3 PASSES THROUGH WHEN THE LOCUST RECIPE IS ON ═══ "locust don't work." The BF chain
    -- sink (priority 3000) ate the real 3 whenever owns("CrushingJaws") hiccupped on a rename or a detection
    -- miss - Crushing Jaws never cast, the R burst ran at nothing. The Locust toggle is explicit user intent:
    -- 3 now passes whenever the recipe is on and we cannot DISPROVE you are on Locust (family() already allows
    -- the nothing-detected case; a positively-detected different character still sinks normally).
    _G.VX_NATIVE_THREE=function() return _G.VX_AUTOAIR_ALL_ON==true end
    local function target()
        local lock=_G.VX_LOCK; local chosen=lock and lock.get and lock.get()
        if chosen and chosen.Parent then return chosen end
        local c=body(); local r=c and c:FindFirstChild("HumanoidRootPart")
        local folder=workspace:FindFirstChild("Characters")
        if not r then return end
        local best,distance=nil,80
        for _,m in ipairs(_G.VX_LIVING_MODELS()) do
            local e=m:FindFirstChild("HumanoidRootPart"); local h=m:FindFirstChildOfClass("Humanoid")
            if m~=c and e and h and h.Health>0 and (e.Position-r.Position).Magnitude<distance then best,distance=m,(e.Position-r.Position).Magnitude end
        end
        return best
    end
    local function aim(t)
        local r=t and t.Parent and t:FindFirstChild("HumanoidRootPart")
        local camera=workspace.CurrentCamera
        if r and camera then
            camera.CFrame=CFrame.lookAt(camera.CFrame.Position,r.Position+Vector3.new(0,1,0))
            pcall(function()
                local p,visible=camera:WorldToScreenPoint(r.Position)
                if visible and p.Z>0 then VIM:SendMouseMoveEvent(p.X,p.Y,game) end
            end)
        end
    end
    -- ═══ R FIRES WHEN THE TARGET IS IN THE AIR ═══ "As soon as the target's in the air, that's when you
    -- press R." (Gojo 1 R, Gojo 2 / left blue R, the R after the two kicks - all the same sentence.) The
    -- fixed 0.15-0.30s waits tapped R while the target was still standing, so the follow-up whiffed and the
    -- whole recipe read as dead. This waits for the LAUNCH itself: off the ground AND either rising fast or
    -- clearly above where they started. Returns false on timeout so a missed launch signal can never stall
    -- a recipe - the R still fires on the clock as the fallback.
    local function waitAirborne(tgt,timeout)
        local tr=tgt and tgt.Parent and tgt:FindFirstChild("HumanoidRootPart")
        if not tr then return false end
        local startY=tr.Position.Y
        local t0=tick()
        while tick()-t0<(timeout or 1.1) do
            if not (tgt.Parent and tr.Parent) then return false end
            local th=tgt:FindFirstChildOfClass("Humanoid")
            if not th or th.Health<=0 then return false end
            local v=tr.AssemblyLinearVelocity
            if th.FloorMaterial==Enum.Material.Air and (v.Y>8 or tr.Position.Y-startY>2.2) then return true end
            task.wait()
        end
        return false
    end
    -- ═══ RIDE THE SECOND KICK (Twofold) ═══ counts Twofold Kick swings on MY animator (user's captured id);
    -- true = the 2nd kick landed and the R belongs NOW. This anim-count follow is the version that was
    -- reported working ("two full kick used to work") before the bare launch-wait replaced it.
    local function waitTwofoldKick(timeout)
        local c=body(); local h=c and c:FindFirstChildOfClass("Humanoid"); local a=h and h:FindFirstChildOfClass("Animator")
        if not a then task.wait(0.30) return false end
        local count,last=0,0
        local conn=a.AnimationPlayed:Connect(function(tr)
            local id=tostring(tr.Animation and tr.Animation.AnimationId or ""):match("%d+")
            if id=="104749346956269" then
                if tick()-last>1.5 then count=0 end
                last=tick(); count=count+1
            end
        end)
        local t0=tick()
        while tick()-t0<(timeout or 1.1) and count<2 do task.wait() end
        conn:Disconnect()
        return count>=2
    end
    -- which recipes time their follow-up R off the target's launch (everything else keeps the clock wait)
    -- (GojoR removed: the standalone R -> R feature is folded into Gojo 1's system, which already ends with
    -- the same aim + R burst - "just add it into the system of Gojo 1".)
    local AIR_R={LapseBlue=true,GojoTwo=true,LapseRed=true,Twofold=true}
    local function tap(key)
        if blocked(key) then return false end
        _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {}
        _G.VX_INJ_KEYS[key]=tick()+0.3
        local ok=pcall(function()
            VIM:SendKeyEvent(false,key,false,game)
            task.wait(0.025)
            VIM:SendKeyEvent(true,key,false,game); task.wait(0.08)
        end)
        pcall(function() VIM:SendKeyEvent(false,key,false,game) end)
        return ok
    end
    local function airPower(h)
        if not h or _G.VX_AIR_POWER_ON~=true then return function() end end
        local property=h.UseJumpPower and "JumpPower" or "JumpHeight"
        local old=h[property]
        if type(old)~="number" then return function() end end
        local value=old*math.clamp(tonumber(_G.VX_AIR_POWER) or 100,50,300)/100
        h[property]=value
        local restored=false
        local function restore()
            if restored then return end; restored=true
            if h.Parent and h[property]==value then h[property]=old end
        end
        task.delay(0.6,restore)
        return restore
    end

    local function run(option,key,jumpFirst,follow,delay,animationIds,airReplayLive,airTarget)
        if not running then
            local cam=workspace.CurrentCamera
            initialRotation=cam and cam.CFrame.Rotation
            pcall(function() initialMouse=UIS:GetMouseLocation() end)
        end
        serial+=1; local ticket=serial
        running=true
        local gen,character=versions[option],body()
        local aimedTarget=airTarget or target()
        local camera=workspace.CurrentCamera
        local rotation=initialRotation
        local needsAim=option=="LapseBlue" or option=="LapseRed" or option=="GojoTwo" or option=="Twofold" or option=="MegumiRabbit"
        if needsAim then aim(aimedTarget) end -- before the original R/1/2 reaches the game
        local function live()
            local hum=character and character:FindFirstChildOfClass("Humanoid")
            return ticket==serial and options[option] and versions[option]==gen and body()==character and hum and hum.Health>0 and not UIS:GetFocusedTextBox()
                and (not airReplayLive or airReplayLive())
        end
        -- Subscribe before returning the original input to the game.
        local connection,targetConnection,seen
        if animationIds then
            local h=character and character:FindFirstChildOfClass("Humanoid")
            local a=h and h:FindFirstChildOfClass("Animator")
            if a then connection=a.AnimationPlayed:Connect(function(track)
                local id=tostring(track.Animation and track.Animation.AnimationId or ""):match("%d+")
                if animationIds[id] then seen=true end
            end) end
            local th=aimedTarget and aimedTarget:FindFirstChildOfClass("Humanoid")
            local ta=th and th:FindFirstChildOfClass("Animator")
            if ta then targetConnection=ta.AnimationPlayed:Connect(function(track)
                local id=tostring(track.Animation and track.Animation.AnimationId or ""):match("%d+")
                if animationIds[id] then seen=true end
            end) end
        end
        task.defer(function()
            local ok,err=pcall(function()
                if not live() then return end
                if jumpFirst then
                    airPower(character:FindFirstChildOfClass("Humanoid"))
                    tap(Enum.KeyCode.Space)
                    local h=character:FindFirstChildOfClass("Humanoid")
                    local deadline=tick()+0.32
                    while live() and h.FloorMaterial~=Enum.Material.Air and tick()<deadline do task.wait() end
                    task.wait(0.08) -- allow the jump state to reach the ability handler
                    if live() then tap(key) end
                end
                -- ═══ CONFIRM THE CAST BEFORE THE FOLLOW-UP ═══ "Gojo 1 was working earlier, but it stopped
                -- working." The R/2 burst means nothing if the 1/2 itself never cast (an eaten key press, a
                -- cooldown edge) - the burst tapped R at nothing and the whole recipe read as dead. Watch for
                -- the cast (any Action track on me within 0.45s); if it never comes, press the key ONCE
                -- ourselves, wait a beat, and only then run the follow. This is also why "it worked earlier
                -- then stopped": every cast that got eaten was silently swallowed before.
                if option=="LapseBlue" or option=="GojoTwo" or option=="LapseRed" then
                    local castSeen=false
                    local h2=character and character:FindFirstChildOfClass("Humanoid")
                    local a2=h2 and h2:FindFirstChildOfClass("Animator")
                    local castConn=a2 and a2.AnimationPlayed:Connect(function(tr)
                        local okp,pr=pcall(function() return tostring(tr.Priority) end)
                        if okp and pr and string.find(pr,"Action",1,true) then castSeen=true end
                    end)
                    local function castPlaying()
                        if not a2 then return false end
                        local okt,trs=pcall(function() return a2:GetPlayingAnimationTracks() end)
                        if not okt or not trs then return false end
                        for _,tr in ipairs(trs) do
                            local okp,pr,tp2=pcall(function() return tostring(tr.Priority),tonumber(tr.TimePosition) or 0 end)
                            if okp and pr and string.find(pr,"Action",1,true) and tp2<0.3 then return true end
                        end
                        return false
                    end
                    local cdead=tick()+0.45
                    while live() and not castSeen and tick()<cdead do
                        if castPlaying() then castSeen=true break end
                        task.wait()
                    end
                    if live() and not castSeen and not airReplayLive then
                        print("[DreamHub Auto] recipe "..option..": cast not seen - retrying the key once")
                        tap(key)
                        local r2=tick()+0.35
                        while live() and not castSeen and tick()<r2 do
                            if castPlaying() then castSeen=true break end
                            task.wait()
                        end
                    end
                    if castConn then castConn:Disconnect() end
                    if not live() then return end
                end
                if not follow then return end
                if animationIds and option~="Locust" then
                    local deadline=tick()+1.5
                    while live() and not seen and tick()<deadline do task.wait() end
                    if not seen then return end
                end
                if follow==Enum.KeyCode.R and option=="Twofold" then
                    -- Twofold: the R rides the SECOND kick (see waitTwofoldKick); launch and clock fallbacks
                    -- keep the burst firing even if the anim ids change under us.
                    if not waitTwofoldKick(1.1) then waitAirborne(aimedTarget,0.4) end
                elseif follow==Enum.KeyCode.R and AIR_R[option] and option~="LapseRed" and option~="LapseBlue" then
                    -- launch-gated recipes: the R waits for the target to be IN THE AIR (see waitAirborne)
                    waitAirborne(aimedTarget,1.2)
                elseif option=="LapseBlue" then
                    -- ═══ BLUE IS A PULL, NOT A LAUNCHER ═══ Lapse Blue never puts the target in the air, so
                    -- the launch wait always burned its full 1.2s timeout and delivered the R burst long after
                    -- the cast window had closed - that is "Gojo 1, still do not work". The proven Auto Air
                    -- shape: R starts right after the cast commits.
                    task.wait(0.06)
                else
                    task.wait(delay or 0.1)
                end
                if live() then
                    if needsAim then aim(aimedTarget) end
                    if option=="LapseRed" then
                        -- ═══ 2 THEN R, NOT 2+R WELDED TOGETHER ═══ same-tick 2+R arrived as one garbled press
                        -- and the game ate it ("2 plus R doesn't work"). 2 lands first, R follows - and the R
                        -- now waits for the LAUNCH ("as soon as the target's in the air, that's when you press
                        -- R"), because 2 alone never lifts them; the R is the aerial that needs them up.
                        pcall(function()
                            if not blocked(Enum.KeyCode.Two) then
                                _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Two]=tick()+0.3
                                VIM:SendKeyEvent(false,Enum.KeyCode.Two,false,game); task.wait(0.025)
                                VIM:SendKeyEvent(true,Enum.KeyCode.Two,false,game); task.wait(0.07)
                                VIM:SendKeyEvent(false,Enum.KeyCode.Two,false,game)
                            end
                            task.wait(0.08)
                            waitAirborne(aimedTarget,1.1)
                            for _=1,5 do
                                if not live() then break end
                                if needsAim then aim(aimedTarget) end
                                _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.R]=tick()+0.3
                                VIM:SendKeyEvent(false,Enum.KeyCode.R,false,game); task.wait(0.025)
                                VIM:SendKeyEvent(true,Enum.KeyCode.R,false,game); task.wait(0.07)
                                VIM:SendKeyEvent(false,Enum.KeyCode.R,false,game)
                                task.wait(0.11)
                            end
                        end)
                    elseif follow==Enum.KeyCode.R then
                        -- ═══ A HUMAN-LOOKING BURST, NOT A MACHINE GUN ═══ the open-ended repeat hammered R for a
                        -- full 1.5s (~15 taps) - "all you're doing, you clicking 1 and then you're clicking R".
                        -- The launch-gated recipes now send a tight burst at a human cadence. Round 5: Gojo 1 R
                        -- (LapseBlue) uses the EXACT follow that proved itself inside Gojo 1 2 (LapseRed) -
                        -- "what really works inside Gojo 1 2 is Gojo 1 R... use that system inside of Gojo 1 R"
                        -- - a 5-tap burst with the aim re-locked before every tap. Locust 3 is PURE SPAM, no
                        -- anim gate, long enough to cover the whole Crushing Jaws fly-up window ("all you gotta
                        -- do, just spam R for Locust 3 when I press 3").
                        local maxTaps=(option=="LapseBlue" and 5) or (option=="Megumi" and 1) or (AIR_R[option] and 3 or 6)
                        local gap=(option=="LapseBlue") and 0.10 or (AIR_R[option] and 0.14 or 0.05)
                        local stop=tick()+1.5
                        local sent=0
                        repeat
                            if not live() then break end
                            if needsAim then aim(aimedTarget) end
                            -- ═══ REAL R, NOT THE REMOTE (GojoTwo) ═══ the remote-only follow was server-rejected
                            -- - "Gojo 2 don't work". The key press is what your hand does; the aim keeper above
                            -- holds the target through the burst.
                            if option=="GojoTwo" then
                                tap(Enum.KeyCode.R)
                            else
                                tap(follow)
                            end
                            sent+=1
                            if sent>=maxTaps then break end
                            task.wait(gap)
                        until tick()>=stop
                        -- ═══ GOJO 2 ALSO THROWS THE REVERSAL RED ═══ "Gojo 2 works... but it doesn't do the
                        -- reverse red." After the R follow, tap 2 again while they are still up - the
                        -- Reversal Red is what finishes the launch.
                        if option=="GojoTwo" and live() then
                            task.wait(0.10)
                            for _=1,2 do
                                if not live() then break end
                                if needsAim then aim(aimedTarget) end
                                pcall(function()
                                    if not blocked(Enum.KeyCode.Two) then
                                        _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[Enum.KeyCode.Two]=tick()+0.3
                                        VIM:SendKeyEvent(false,Enum.KeyCode.Two,false,game); task.wait(0.025)
                                        VIM:SendKeyEvent(true,Enum.KeyCode.Two,false,game); task.wait(0.07)
                                        VIM:SendKeyEvent(false,Enum.KeyCode.Two,false,game)
                                    end
                                end)
                                task.wait(0.12)
                            end
                        end
                    else tap(follow) end
                    if needsAim then
                        local deadline=tick()+0.25
                        while live() and tick()<deadline do aim(aimedTarget); task.wait() end
                    end
                end
            end)
            if connection then connection:Disconnect() end
            if targetConnection then targetConnection:Disconnect() end
            if ticket==serial then
                if camera and rotation then camera.CFrame=CFrame.new(camera.CFrame.Position)*rotation end
                if initialMouse then pcall(function() VIM:SendMouseMoveEvent(initialMouse.X,initialMouse.Y,game) end) end
                initialMouse,initialRotation=nil,nil; running=false
            end
            if not ok then warn("[DreamHub Auto] "..tostring(err)) end
        end)
        return true
    end
    _G.VX_LOCUST_CAST=nil -- Locust 3 was removed.

    local function handle(state,input,allowAir,airReplayLive,airTarget)
        local pass,sink=Enum.ContextActionResult.Pass,Enum.ContextActionResult.Sink
        if state~=Enum.UserInputState.Begin or UIS:GetFocusedTextBox() then return pass end
        local key=input.KeyCode
        if blocked(key) then return pass end -- the higher-priority selected-key binding owns this
        if not airReplayLive and _G.VX_INJ_KEYS and tick()<(_G.VX_INJ_KEYS[key] or 0) then return pass end
        if not airReplayLive and _G.VX_COMBAT_OWNER then return pass end
        -- Fallbacks cannot intercept an air cast; leave it for CAS without marking it handled.
        if not allowAir and ((key==Enum.KeyCode.Three and options.Hakari and owns("RoughEnergy"))
            or (key==Enum.KeyCode.One and options.Vessel and owns("CursedStrikes"))
            or (key==Enum.KeyCode.Two and options.Choso and owns("FlowingRedScale"))) then return pass end
        if not airReplayLive and tick()-(lastInput[key] or -math.huge)<0.12 then return pass end
        lastInput[key]=tick()
        local function recipe(option,slot,jumpFirst,follow,delay)
            -- Universal Air already owns the jump and original cast. Only attach the follow-up.
            if airReplayLive and jumpFirst then return false end
            return run(option,slot,jumpFirst,follow,delay,nil,airReplayLive,airTarget)
        end
        if key==Enum.KeyCode.Three and options.Hakari and owns("RoughEnergy") then
            if not allowAir then return pass end
            return recipe("Hakari",key,true) and sink or pass
        elseif key==Enum.KeyCode.One and options.Vessel and owns("CursedStrikes") then
            if not allowAir then return pass end
            return recipe("Vessel",key,true) and sink or pass
        elseif key==Enum.KeyCode.Two and options.Choso and owns("FlowingRedScale") then
            if not allowAir then return pass end
            return recipe("Choso",key,true) and sink or pass
        elseif key==Enum.KeyCode.Four and options.Twofold and family("Gojo") then
            recipe("Twofold",key,false,Enum.KeyCode.R,0.30)   -- R burst starts after the kicks arm (0s bounced off a cold window)
        elseif key==Enum.KeyCode.Two and options.Megumi and family("Megumi") then
            recipe("Megumi",key,false,Enum.KeyCode.R,0.1)
        elseif key==Enum.KeyCode.R and options.MegumiRabbit and family("Megumi") then
            recipe("MegumiRabbit",key,false,Enum.KeyCode.One,0.12)
        elseif key==Enum.KeyCode.One and (options.LapseRed or options.LapseBlue) and family("Gojo") then
            -- ═══ THE BURST STARTS AFTER BLUE COMMITS ═══ R at +0.04s landed before the game had armed the
            -- heavy-followup window - the first taps bounced, and 0.04 read as "Gojo R doesn't work". Your own
            -- spam starts a beat AFTER the 1; both recipes now do the same.
            if options.LapseRed then recipe("LapseRed",key,false,Enum.KeyCode.Two,0.30)
            elseif options.LapseBlue then recipe("LapseBlue",key,false,Enum.KeyCode.R,0.22) end
        elseif key==Enum.KeyCode.Two and options.GojoTwo and family("Gojo") then
            recipe("GojoTwo",key,false,Enum.KeyCode.R,0.15)   -- R a beat after YOUR 2 lands (0.04 was too early to register)
        end
        return pass
    end
    _G.VX_AUTOAIR_FOLLOW=function(key,owner,live,airTarget)
        if not owner or _G.VX_COMBAT_OWNER~=owner or type(live)~="function" or not live() then return end
        handle(Enum.UserInputState.Begin,{KeyCode=key},true,live,airTarget)
    end
    pcall(function()
        CAS:BindActionAtPriority("VX_NativeAutoMoves",function(_,state,input) return handle(state,input,true) end,
            false,4200,Enum.KeyCode.One,Enum.KeyCode.Two,Enum.KeyCode.Three,Enum.KeyCode.Four,Enum.KeyCode.R)
    end)
    UIS.InputBegan:Connect(function(input) handle(Enum.UserInputState.Begin,input,false) end)
    if _G.VX_ON_KEY then _G.VX_ON_KEY("nativeAutoFallback",function(key) handle(Enum.UserInputState.Begin,{KeyCode=key},false) end) end
    -- Twofold's existing two-kick animation recipe remains independently selectable.
    _G.VX_NATIVE_AUTO_OPTIONS=options
end

-- MODULE: UNIVERSAL AUTO AIR -- one jump, then the original slot key once.
do
    local UIS=game:GetService("UserInputService")
    local VIM=game:GetService("VirtualInputManager")
    local CAS=game:GetService("ContextActionService")
    local Players=game:GetService("Players")
    local on,busy,generation=false,false,0
    local queued,waiting={},{}
    local slots={[Enum.KeyCode.One]=true,[Enum.KeyCode.Two]=true,[Enum.KeyCode.Three]=true,[Enum.KeyCode.Four]=true}
    local function key(k,pressed)
        _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {}; _G.VX_INJ_KEYS[k]=tick()+0.25
        VIM:SendKeyEvent(pressed,k,false,game)
    end
    local function validTarget(t,c,root)
        local e=t and t.Parent and t:FindFirstChild("HumanoidRootPart")
        local h=t and t:FindFirstChildOfClass("Humanoid")
        return t~=c and e and h and h.Health>0 and (e.Position-root.Position).Magnitude<=40
    end
    local function aimTarget(c)
        local root=c:FindFirstChild("HumanoidRootPart"); if not root then return end
        local lock=_G.VX_LOCK; local chosen=lock and lock.get and lock.get()
        if validTarget(chosen,c,root) then return chosen end
        local best,distance=nil,25
        for _,t in ipairs(_G.VX_LIVING_MODELS()) do
            if validTarget(t,c,root) then
                local d=t:FindFirstChild("HumanoidRootPart").Position-root.Position
                if d.Magnitude<distance and (d.Magnitude<0.1 or d.Unit:Dot(root.CFrame.LookVector)>0.35) then
                    best,distance=t,d.Magnitude
                end
            end
        end
        return best
    end
    local function aimAt(t,c)
        local root=c:FindFirstChild("HumanoidRootPart")
        local camera=workspace.CurrentCamera
        if not root or not camera or not validTarget(t,c,root) then return end
        local e=t:FindFirstChild("HumanoidRootPart"); local point=e.Position+Vector3.new(0,1,0)
        local flat=Vector3.new(point.X,root.Position.Y,point.Z)
        if (flat-root.Position).Magnitude>0.1 then root.CFrame=CFrame.lookAt(root.Position,flat) end
        camera.CFrame=CFrame.lookAt(camera.CFrame.Position,point)
        pcall(function()
            local p,visible=camera:WorldToScreenPoint(point)
            if visible and p.Z>0 then VIM:SendMouseMoveEvent(p.X,p.Y,game) end
        end)
    end
    local function trigger(k)
        if busy or not on or UIS:GetFocusedTextBox() or (_G.VX_KEY_BLOCKED and _G.VX_KEY_BLOCKED(k)) then return false end
        local c=vxMyChar(); local h=c and c:FindFirstChildOfClass("Humanoid")
        if not h or h.Health<=0 or _G.VX_COMBAT_OWNER then return false end
        local aimedTarget=aimTarget(c)
        busy=true; local gen=generation; local owner={}; _G.VX_COMBAT_OWNER=owner
        local property=h.UseJumpPower and "JumpPower" or "JumpHeight"
        local original=h[property]; local boosted; local cancelled=false
        local function live() return not cancelled and on and gen==generation and vxMyChar()==c and h.Health>0 and not UIS:GetFocusedTextBox() end
        task.defer(function()
            local ok,err=pcall(function()
                if _G.VX_AIR_POWER_ON and type(original)=="number" then
                    boosted=original*math.clamp(tonumber(_G.VX_AIR_POWER) or 100,50,300)/100; h[property]=boosted
                end
                _G.VX_AUTOAIR_STATUS="jumping before "..tostring(k)
                key(Enum.KeyCode.Space,true)
                local deadline=tick()+0.45
                repeat h.Jump=true; task.wait(0.02) until not live() or h.FloorMaterial==Enum.Material.Air or tick()>=deadline
                key(Enum.KeyCode.Space,false)
                if not live() or (_G.VX_KEY_BLOCKED and _G.VX_KEY_BLOCKED(k)) then return end
                -- A rejected jump must not swallow the user's move; pass their slot once.
                _G.VX_AUTOAIR_STATUS=h.FloorMaterial==Enum.Material.Air and "airborne; casting "..tostring(k) or "jump unavailable; casting original slot"
                if _G.VX_AUTOAIR_FOLLOW then
                    local attached,why=pcall(_G.VX_AUTOAIR_FOLLOW,k,owner,function() local root=c:FindFirstChild("HumanoidRootPart"); return live() and (not aimedTarget or root and validTarget(aimedTarget,c,root)) end,aimedTarget)
                    if not attached then warn("[DreamHub Auto Air follow-up] "..tostring(why)) end
                end
                pcall(aimAt,aimedTarget,c)
                key(k,false); key(k,true); task.wait(0.035); key(k,false)
            end)
            pcall(function() key(Enum.KeyCode.Space,false); key(k,false) end)
            if boosted and h.Parent and h[property]==boosted then h[property]=original end
            if _G.VX_COMBAT_OWNER==owner then _G.VX_COMBAT_OWNER=nil end
            busy=false
            if not ok then cancelled=true; _G.VX_AUTOAIR_STATUS="input error: "..tostring(err); warn("[DreamHub Auto Air] "..tostring(err)) end
            if not ok or not live() then
                table.clear(queued); table.clear(waiting)
            else
                while #queued>0 do
                    local nextKey=table.remove(queued,1); waiting[nextKey]=nil
                    if trigger(nextKey) then break end
                end
            end
        end)
        return true
    end
    CAS:BindActionAtPriority("VX_UniversalAutoAir",function(_,state,input)
        local pass,sink=Enum.ContextActionResult.Pass,Enum.ContextActionResult.Sink
        if not on or state~=Enum.UserInputState.Begin or not slots[input.KeyCode] or UIS:GetFocusedTextBox() then return pass end
        if tick()<((_G.VX_INJ_KEYS or {})[input.KeyCode] or 0) or _G.VX_KEY_BLOCKED and _G.VX_KEY_BLOCKED(input.KeyCode) then return pass end
        if busy then
            if not waiting[input.KeyCode] then waiting[input.KeyCode]=true; queued[#queued+1]=input.KeyCode end
            return sink
        end
        return trigger(input.KeyCode) and sink or pass
    end,false,4400,Enum.KeyCode.One,Enum.KeyCode.Two,Enum.KeyCode.Three,Enum.KeyCode.Four)
    _G.VX_AUTOAIR_ALL={set=function(v) on=v==true; _G.VX_AUTOAIR_ALL_ON=on; generation+=1; table.clear(queued); table.clear(waiting) end}
    if UIS.TextBoxFocused then UIS.TextBoxFocused:Connect(function()
        generation+=1; table.clear(queued); table.clear(waiting)
    end) end
    Players.LocalPlayer.CharacterAdded:Connect(function() generation+=1; table.clear(queued); table.clear(waiting) end)
end

-- MODULE: LOCUST FLY -- wait for manual R movement to finish, then native back Q return.
do
    local UIS=game:GetService("UserInputService")
    local VIM=game:GetService("VirtualInputManager")
    local on,busy,generation,last=false,false,0,-math.huge
    local function key(k)
        if k~=Enum.KeyCode.R or not on or busy or tick()-last<0.15 or UIS:GetFocusedTextBox() or _G.VX_COMBAT_OWNER then return end
        if tick()<((_G.VX_INJ_KEYS or {})[k] or 0) or _G.VX_KEY_BLOCKED and _G.VX_KEY_BLOCKED(k) then return end
        local c=vxMyChar(); local moves=c and c:FindFirstChild("Moveset")
        local h=c and c:FindFirstChildOfClass("Humanoid"); local root=c and c:FindFirstChild("HumanoidRootPart")
        if not moves or not moves:FindFirstChild("Crushing Jaws") or not h or not root or h.Health<=0 then return end
        local target=_G.VX_LOCK and _G.VX_LOCK.get and _G.VX_LOCK.get()
        local function valid(t)
            local th=t and t.Parent and t:FindFirstChildOfClass("Humanoid")
            local r=t and t:FindFirstChild("HumanoidRootPart")
            return t~=c and th and th.Health>0 and r and (r.Position-root.Position).Magnitude<=50
        end
        if not valid(target) then
            target=nil; local gap=26
            for _,t in ipairs(_G.VX_LIVING_MODELS()) do
                if valid(t) then local d=(t.HumanoidRootPart.Position-root.Position).Magnitude; if d<gap then target=t; gap=d end end
            end
        end
        if not target or not _G.VXBF2 or not _G.VXBF2.approach then return end
        busy=true; last=tick(); local gen=generation
        local owner={}; _G.VX_COMBAT_OWNER=owner
        local began=tick(); local startPos=root.Position; local activeTrack
        local animator=h:FindFirstChildOfClass("Animator")
        local connection=animator and animator.AnimationPlayed:Connect(function(track)
            if tick()-began<0.5 and not track.Looped and tostring(track.Priority):find("Action",1,true) then activeTrack=track end
        end)
        task.defer(function()
            local function live() return on and generation==gen and vxMyChar()==c and h.Health>0 and valid(target) and not UIS:GetFocusedTextBox() end
            local ok,err=pcall(function()
                local deadline=tick()+3; local started=false; local settledAt
                repeat
                    if not live() then return end
                    local v=root.AssemblyLinearVelocity
                    local moving=Vector3.new(v.X,0,v.Z).Magnitude>math.max((h.WalkSpeed or 16)*1.2,20)
                    if activeTrack or moving or (root.Position-startPos).Magnitude>1 then started=true end
                    if started and not moving and (not activeTrack or not activeTrack.IsPlaying) then
                        settledAt=settledAt or tick()
                        if tick()-settledAt>=0.08 then break end
                    else settledAt=nil end
                    task.wait()
                until tick()>=deadline
                if not settledAt or tick()-settledAt<0.08 or not live() then _G.VX_LOCUST_FLY_STATUS="R movement did not finish before timeout"; return end
                if not _G.VXBF2.approach(target,true,live,true,false,{range=50,smooth=true}) or not live() then return end
                local r=target:FindFirstChild("HumanoidRootPart")
                if (r.Position-root.Position).Magnitude>8 then return end
                root.CFrame=CFrame.lookAt(root.Position,Vector3.new(r.Position.X,root.Position.Y,r.Position.Z))
                local camera=workspace.CurrentCamera
                if camera then camera.CFrame=CFrame.lookAt(camera.CFrame.Position,r.Position) end
                local vp=camera and camera.ViewportSize; local x,y=vp and vp.X/2 or 400,vp and vp.Y/2 or 300
                _G.VX_SYNTH_CLICK=tick()+0.2
                VIM:SendMouseButtonEvent(x,y,0,false,game,0)
                VIM:SendMouseButtonEvent(x,y,0,true,game,0); task.wait(0.04)
                VIM:SendMouseButtonEvent(x,y,0,false,game,0)
            end)
            if connection then connection:Disconnect() end
            pcall(function() VIM:SendMouseButtonEvent(0,0,0,false,game,0) end)
            if _G.VX_COMBAT_OWNER==owner then _G.VX_COMBAT_OWNER=nil end
            busy=false
            if not ok then warn("[DreamHub Locust Fly] "..tostring(err)) end
        end)
    end
    UIS.InputBegan:Connect(function(input) key(input.KeyCode) end)
    if _G.VX_ON_KEY then _G.VX_ON_KEY("locustFly",key) end
    _G.VX_LOCUST_FLY={set=function(v) on=v==true; generation+=1 end}
end

-- MODULE: DESYNC FREEZE  (experimental invis: the server keeps you at the frozen spot, YOU keep moving)
-- Anchoring your root LOCALLY stops your physics replication -> everyone sees you standing at the freeze
-- point while you actually move around (local WASD driver). Turning it off glides you back legit.
-- ============================================================
do
        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local UIS = game:GetService("UserInputService")
        local LP = Players.LocalPlayer
        local on = false
        local ghost, ghostRoot, freezeCF = nil, nil, nil
        local function myC() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
        local function myR() local c = myC(); return c and c:FindFirstChild("HumanoidRootPart") end
        -- GHOST method: your REAL body stays put (server + everyone genuinely sees you frozen, because you
        -- send no movement at all). YOU roam as a local see-through clone with full WASD/Space/Ctrl flight.
        local function makeGhost()
                local c = myC(); if not c then return end
                local ok, cl = pcall(function() c.Archivable = true; return c:Clone() end)
                if not (ok and cl) then return end
                cl.Name = "DreamGhost"
                for _, d in ipairs(cl:GetDescendants()) do
                        pcall(function()
                                if d:IsA("BasePart") then d.Transparency = math.clamp(d.Transparency + 0.6, 0, 1); d.CanCollide = false; d.Anchored = (d.Name == "HumanoidRootPart")
                                elseif d:IsA("Script") or d:IsA("LocalScript") then d:Destroy() end
                        end)
                end
                local h = cl:FindFirstChildOfClass("Humanoid"); if h then pcall(function() h.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None end) end
                cl.Parent = workspace
                ghost = cl; ghostRoot = cl:FindFirstChild("HumanoidRootPart")
                local r = myR(); if r and ghostRoot then pcall(function() ghost:PivotTo(r.CFrame) end) end
                pcall(function() workspace.CurrentCamera.CameraSubject = h or ghostRoot end)   -- your camera follows the ghost
        end
        RunService.RenderStepped:Connect(function(dt)
                if not on then return end
                local r = myR()
                if r then
                        if not freezeCF then freezeCF = r.CFrame end   -- capture the freeze point ONCE
                        -- ABSOLUTE pin: the real body NEVER moves while frozen - not for attacks, not for anything.
                        -- (Attacks you throw while ghosting fire from the frozen spot; the body stays exactly still.)
                        pcall(function() r.Anchored = true; r.AssemblyLinearVelocity = Vector3.zero; r.AssemblyAngularVelocity = Vector3.zero; r.CFrame = freezeCF end)
                end
                if not (ghost and ghost.Parent and ghostRoot) then makeGhost(); if not ghostRoot then return end end
                local cam = workspace.CurrentCamera; if not cam then return end
                local fwd = cam.CFrame.LookVector; fwd = Vector3.new(fwd.X, 0, fwd.Z); if fwd.Magnitude > 0 then fwd = fwd.Unit end
                local right = cam.CFrame.RightVector; right = Vector3.new(right.X, 0, right.Z); if right.Magnitude > 0 then right = right.Unit end
                local move = Vector3.zero
                if UIS:IsKeyDown(Enum.KeyCode.W) then move = move + fwd end
                if UIS:IsKeyDown(Enum.KeyCode.S) then move = move - fwd end
                if UIS:IsKeyDown(Enum.KeyCode.D) then move = move + right end
                if UIS:IsKeyDown(Enum.KeyCode.A) then move = move - right end
                if UIS:IsKeyDown(Enum.KeyCode.Space) then move = move + Vector3.new(0, 1, 0) end
                if UIS:IsKeyDown(Enum.KeyCode.LeftControl) then move = move - Vector3.new(0, 1, 0) end
                if move.Magnitude > 0 then
                        local dir = move.Unit
                        pcall(function() ghostRoot.CFrame = CFrame.new(ghostRoot.Position + dir * (30 * dt)) * (ghostRoot.CFrame - ghostRoot.CFrame.Position) end)
                end
        end)
        DesyncFreezeApi = { set = function(v)
                if v then
                        on = true
                else
                        on = false
                        freezeCF = nil
                        if ghost then pcall(function() ghost:Destroy() end) end
                        ghost, ghostRoot = nil, nil
                        local c = myC(); local r = myR(); local h = c and c:FindFirstChildOfClass("Humanoid")
                        if r then pcall(function() r.Anchored = false end) end
                        pcall(function() workspace.CurrentCamera.CameraSubject = h or r end)   -- camera back on your real body
                end
        end }
end

-- ============================================================
-- MODULE: CONTROL DUMMY  (take the wheel: WASD walks the dummy around, Space hops it)
-- ============================================================
do
        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local UIS = game:GetService("UserInputService")
        local LP = Players.LocalPlayer
        local on, dummy = false, nil
        local function myHRP() local chs = workspace:FindFirstChild("Characters"); local c = (chs and chs:FindFirstChild(LP.Name)) or LP.Character; return c and c:FindFirstChild("HumanoidRootPart") end
        local function findDummy()  -- nearest non-player model (Dummy) in workspace.Characters
                local mh = myHRP(); local chs = workspace:FindFirstChild("Characters"); if not (mh and chs) then return nil end
                local best, bd
                for _, m in ipairs(chs:GetChildren()) do
                        if m:IsA("Model") and m.Name ~= LP.Name and not Players:FindFirstChild(m.Name) then
                                local r = m:FindFirstChild("HumanoidRootPart")
                                if r then local d = (r.Position - mh.Position).Magnitude; if not bd or d < bd then best, bd = m, r and d end end
                        end
                end
                return best
        end
        local flyOn, attackOn, atkTarget = false, false, nil
        local function targetHRPOf(name)
                local p = Players:FindFirstChild(name); if p and p.Character then local r = p.Character:FindFirstChild("HumanoidRootPart"); if r then return r end end
                local chs = workspace:FindFirstChild("Characters"); local m = chs and chs:FindFirstChild(name); return m and m:FindFirstChild("HumanoidRootPart")
        end
        RunService.Heartbeat:Connect(function(dt)
                if not on then return end
                if not (dummy and dummy.Parent) then dummy = findDummy(); if not dummy then return end end
                local r = dummy:FindFirstChild("HumanoidRootPart"); if not r then return end
                pcall(function() r.Anchored = false end)   -- an ANCHORED dummy ignores everything ('nothing works') - free it first
                local cam = workspace.CurrentCamera; if not cam then return end
                local hum = dummy:FindFirstChildOfClass("Humanoid")
                -- ATTACK MODE (JoJo stand): the dummy chases the chosen player and body-slams through them
                if attackOn and atkTarget then
                        local tr = targetHRPOf(atkTarget)
                        if tr then
                                local to = tr.Position - r.Position
                                local dir = to.Magnitude > 0.1 and to.Unit or Vector3.zero
                                pcall(function()
                                        r.CFrame = CFrame.lookAt(r.Position + dir * (30 * dt), Vector3.new(tr.Position.X, r.Position.Y, tr.Position.Z))   -- ALWAYS moves (CFrame step)...
                                        r.AssemblyLinearVelocity = Vector3.new(dir.X * 42, math.clamp(to.Y * 2, -18, 26), dir.Z * 42)                      -- ...and velocity so it REPLICATES when you own its physics
                                end)
                                if hum then pcall(function() hum:Move(dir) end) end
                        end
                        return
                end
                -- WASD control (camera-relative). VELOCITY-driven, not CFrame: physics replicates -> everyone SEES it walk/fly.
                local fwd = cam.CFrame.LookVector; fwd = Vector3.new(fwd.X, 0, fwd.Z); if fwd.Magnitude > 0 then fwd = fwd.Unit end
                local right = cam.CFrame.RightVector; right = Vector3.new(right.X, 0, right.Z); if right.Magnitude > 0 then right = right.Unit end
                local move = Vector3.zero
                if UIS:IsKeyDown(Enum.KeyCode.W) then move = move + fwd end
                if UIS:IsKeyDown(Enum.KeyCode.S) then move = move - fwd end
                if UIS:IsKeyDown(Enum.KeyCode.D) then move = move + right end
                if UIS:IsKeyDown(Enum.KeyCode.A) then move = move - right end
                local vy = r.AssemblyLinearVelocity.Y
                if flyOn then
                        vy = 0
                        if UIS:IsKeyDown(Enum.KeyCode.Space) then vy = 26 end
                        if UIS:IsKeyDown(Enum.KeyCode.LeftControl) then vy = -26 end
                elseif UIS:IsKeyDown(Enum.KeyCode.Space) then vy = 30 end
                if move.Magnitude > 0 or flyOn then
                        local dir = move.Magnitude > 0 and move.Unit or Vector3.zero
                        if hum then pcall(function() hum:Move(dir) end) end   -- walk animation
                        pcall(function()
                                local stepV = Vector3.new(dir.X * 20 * dt, (flyOn and vy or 0) * dt, dir.Z * 20 * dt)
                                if dir.Magnitude > 0 or flyOn then r.CFrame = CFrame.lookAt(r.Position + stepV, r.Position + stepV + (dir.Magnitude > 0 and dir * 8 or r.CFrame.LookVector * 8)) end   -- ALWAYS moves
                                r.AssemblyLinearVelocity = Vector3.new(dir.X * 22, vy, dir.Z * 22)   -- and replicated physics when owned
                        end)
                elseif UIS:IsKeyDown(Enum.KeyCode.Space) then
                        pcall(function() r.AssemblyLinearVelocity = Vector3.new(r.AssemblyLinearVelocity.X, 30, r.AssemblyLinearVelocity.Z) end)
                end
        end)
        ControlDummyApi = {
                set = function(v) on = v == true; if not on then dummy = nil; attackOn = false end end,
                setFly = function(v) flyOn = v == true end,
                setAttack = function(v) attackOn = v == true end,
                setTarget = function(n) atkTarget = (n and n ~= "(none)") and n or nil end,
                blackFlash = function()   -- DUMMY BLACK FLASH: slam the dummy behind the chosen player and shove through their back
                        if not (dummy and dummy.Parent and atkTarget) then return end
                        local r = dummy:FindFirstChild("HumanoidRootPart"); local tr = targetHRPOf(atkTarget)
                        if not (r and tr) then return end
                        local look = tr.CFrame.LookVector; local flat = Vector3.new(look.X, 0, look.Z)
                        local dir = flat.Magnitude > 0.01 and flat.Unit or Vector3.new(0, 0, -1)
                        pcall(function()
                                r.CFrame = CFrame.lookAt(tr.Position - dir * 4 + Vector3.new(0, 1, 0), tr.Position)
                                r.AssemblyLinearVelocity = dir * 60   -- drive THROUGH their back
                        end)
                end,
        }
end

-- ============================================================
-- MODULE: REMOVE TREES  (hide the map trees so you can see the fight better)
-- ============================================================
do
        local on = false
        local hidden = setmetatable({}, { __mode = "k" })   -- part -> its original transparency (so we can restore)
        local function treesRoot()
                local map = workspace:FindFirstChild("Map"); local d = map and map:FindFirstChild("Destructible")
                if d then local t = d:FindFirstChild("Trees", true); if t then return t end end   -- workspace.Map.Destructible...Trees
                return nil
        end
        task.spawn(function()
                while true do
                        if on then
                                local t = treesRoot()
                                if t then
                                        for _, p in ipairs(t:GetDescendants()) do
                                                -- SAVE everything we hide (parts AND decals/textures). Decals were hidden WITHOUT being saved,
                                                -- so turning trees back on restored trunks but left leaves/bark invisible = "trees don't come back".
                                                if (p:IsA("BasePart") or p:IsA("Decal") or p:IsA("Texture")) and hidden[p] == nil then
                                                        hidden[p] = p.Transparency; pcall(function() p.Transparency = 1 end)
                                                end
                                        end
                                end
                        end
                        task.wait(0.6)   -- re-hide trees that stream back in
                end
        end)
        RemoveTreesApi = { set = function(v)
                on = v == true
                if not on then for p, tr in pairs(hidden) do if p and p.Parent then pcall(function() p.Transparency = tr end) end hidden[p] = nil end end   -- restore
        end }
end

-- ============================================================
-- MODULE: AIM ASSIST  (face the enemy the moment you cast ANY move - detected by every captured move anim id)
-- ============================================================
do
        local Players = game:GetService("Players")
        local LP = Players.LocalPlayer
        local Camera = workspace.CurrentCamera
        local on = false
        local function myChar() local chs = workspace:FindFirstChild("Characters"); return (chs and chs:FindFirstChild(LP.Name)) or LP.Character end
        local function myHRP() local c = myChar(); return c and c:FindFirstChild("HumanoidRootPart") end
        local function idOf(s) return tostring(s):match("%d+") end
        local function nearestEnemy()
                local hrp = myHRP(); if not hrp then return nil end
                local best, bd
                local function chk(m) if m and m.Name ~= LP.Name and m ~= LP.Character then local r = m:FindFirstChild("HumanoidRootPart"); local h = m:FindFirstChildOfClass("Humanoid"); if r and h and h.Health > 0 then local d = (r.Position - hrp.Position).Magnitude; if not bd or d < bd then best, bd = r, d end end end end
                for _, plr in ipairs(Players:GetPlayers()) do if plr ~= LP then chk(plr.Character) end end
                local chs = workspace:FindFirstChild("Characters"); if chs then for _, m in ipairs(chs:GetChildren()) do chk(m) end end
                return best
        end
        local function targetPart()
                local g = _G.VX_LOCK; local lt = (g and g.get) and g.get() or nil   -- prefer the LOCKED (clicked) enemy
                if lt and lt.Parent then return lt:FindFirstChild("HumanoidRootPart") or lt:FindFirstChildWhichIsA("BasePart") end
                return nearestEnemy()
        end
        -- IMPROVED AIM ASSIST: was a single hard snap on the frame the move started, which missed anyone moving and
        -- read as an obvious camera jerk. Now it TRACKS for a short window, LEADS the target using their velocity,
        -- and eases the camera instead of teleporting it - so it stays on a strafing enemy and looks hand-aimed.
        local aimGen = 0
        local function faceTarget()
                aimGen = aimGen + 1
                local myGen = aimGen
                task.spawn(function()
                        local t0 = tick()
                        while tick() - t0 < 0.45 and aimGen == myGen do          -- track through the cast, not one frame
                                local hrp = myHRP(); local tr = targetPart()
                                if not (hrp and tr and tr.Parent) then return end
                                local d = (tr.Position - hrp.Position).Magnitude
                                if d > 120 then return end                            -- do not swing the camera at someone across the map
                                -- LEAD the target: aim where they will be, scaled by distance (travel time), so a strafing
                                -- enemy is still hit instead of the shot trailing behind them.
                                local tv = Vector3.zero
                                pcall(function() tv = tr.AssemblyLinearVelocity end)
                                local lead = math.clamp(d / 180, 0, 0.16)
                                local tp = tr.Position + Vector3.new(tv.X, 0, tv.Z) * lead
                                pcall(function() hrp.CFrame = CFrame.lookAt(hrp.Position, Vector3.new(tp.X, hrp.Position.Y, tp.Z)) end)   -- body faces them so the move fires at them
                                pcall(function()                                       -- camera EASES onto them (no snap = looks aimed, not scripted)
                                        Camera.CFrame = Camera.CFrame:Lerp(CFrame.lookAt(Camera.CFrame.Position, tp), 0.45)
                                end)
                                task.wait()
                        end
                end)
        end
        local function isMove(track)  -- ANY of your captured MOVE anims (all skills/ults + M1 ids)
                if not track or not track.Animation then return false end
                local id = idOf(track.Animation.AnimationId)
                return (id and ((_G.VX_ADAPT_IDS and _G.VX_ADAPT_IDS[id]) or (_G.VX_M1_IDS and _G.VX_M1_IDS[id]))) and true or false
        end
        local hooked = setmetatable({}, { __mode = "k" })
        local function hook()
                local c = myChar(); local h = c and c:FindFirstChildOfClass("Humanoid"); local a = h and h:FindFirstChildOfClass("Animator")
                if not a or hooked[a] then return end
                hooked[a] = a.AnimationPlayed:Connect(function(track) if on and isMove(track) then faceTarget() end end)
        end
        task.spawn(function() while true do if on then hook() end task.wait(0.6) end end)
        AimAssistApi = { set = function(v) on = v == true end }
end

-- ============================================================
-- MODULE: INFINITE JUMP  (press Space in mid-air to jump again)
-- ============================================================
do
        local Players = game:GetService("Players")
        local UIS = game:GetService("UserInputService")
        local LP = Players.LocalPlayer
        local on = false
        UIS.InputBegan:Connect(function(input, gp)
                if not on or gp then return end
                if input.KeyCode == Enum.KeyCode.Space then
                        local c = LP.Character; local h = c and c:FindFirstChildOfClass("Humanoid")
                        if h then pcall(function() h:ChangeState(Enum.HumanoidStateType.Jumping) end) end
                end
        end)
        InfJumpApi = { set = function(v) on = v == true end }
end

-- ============================================================
-- MODULE: VISUALS  (world lighting: fullbright, no fog, FOV - held in RenderStepped so the game can't reset them)
-- ============================================================
do
        local Lighting = game:GetService("Lighting")
        local RunService = game:GetService("RunService")
        local saved = { Brightness = Lighting.Brightness, GlobalShadows = Lighting.GlobalShadows, Ambient = Lighting.Ambient, OutdoorAmbient = Lighting.OutdoorAmbient, FogEnd = Lighting.FogEnd, FogStart = Lighting.FogStart, ClockTime = Lighting.ClockTime }
        local fullbright, fov = false, 0
        RunService.RenderStepped:Connect(function()
                if fullbright then pcall(function()
                        Lighting.Brightness = 2; Lighting.ClockTime = 14; Lighting.GlobalShadows = false
                        Lighting.Ambient = Color3.fromRGB(178, 178, 178); Lighting.OutdoorAmbient = Color3.fromRGB(178, 178, 178)
                end) end
                if fov > 0 then local cam = workspace.CurrentCamera; if cam then pcall(function() cam.FieldOfView = fov end) end end
        end)
        VisualApi = {
                setFullbright = function(v)
                        fullbright = v == true
                        if not fullbright then pcall(function()
                                Lighting.Brightness = saved.Brightness; Lighting.GlobalShadows = saved.GlobalShadows
                                Lighting.Ambient = saved.Ambient; Lighting.OutdoorAmbient = saved.OutdoorAmbient; Lighting.ClockTime = saved.ClockTime
                        end) end
                end,
                setFov = function(v) fov = (type(v) == "number" and v >= 40 and v <= 120 and v ~= 70) and v or 0; if fov == 0 then local cam = workspace.CurrentCamera; if cam then pcall(function() cam.FieldOfView = 70 end) end end end,
                setNoFog = function(v)
                        pcall(function() if v then Lighting.FogEnd = 1e9; Lighting.FogStart = 1e9 else Lighting.FogEnd = saved.FogEnd; Lighting.FogStart = saved.FogStart end end)
                        for _, e in ipairs(Lighting:GetChildren()) do if e:IsA("Atmosphere") then pcall(function() e.Density = v and 0 or 0.3 end) end end
                end,
        }
end

-- ============================================================
-- Auto Meguna: react to the summon animation, then use awakened Vessel's Rush.
do
    local Players=game:GetService("Players")
    local UIS=game:GetService("UserInputService")
    local VIM=game:GetService("VirtualInputManager")
    local me=Players.LocalPlayer
    local on,busy,generation,last=false,false,0,-math.huge
    local notifyOn=false;local notified=setmetatable({}, {__mode="k"})
    local hooked=setmetatable({}, {__mode="k"})
    local function normalized(s) return tostring(s or ""):lower():gsub("[^%w]","") end
    local function ownModel() return vxMyChar() end
    local function hasMove(name)
        local c=ownModel(); local moves=c and c:FindFirstChild("Moveset")
        if moves then for _,v in ipairs(moves:GetChildren()) do if normalized(v.Name)==name then return true end end end
        return false
    end
    local function vessel()
        local c=ownModel();local n=c and detectCharName(c)
        return n=="Itadori" or n=="Sukuna" or hasMove("cursedstrikes") or hasMove("divergentfist")
    end
    local function rushAvailable()
        if hasMove("rush") then return true end
        local gui=me:FindFirstChildOfClass("PlayerGui")
        if gui then for _,v in ipairs(gui:GetDescendants()) do
            if v:IsA("TextLabel") and v.Visible and normalized(v.Text)=="rush" then return true end
        end end
        return false
    end
    local function press(key)
        if UIS:GetFocusedTextBox() or _G.VX_KEY_BLOCKED and _G.VX_KEY_BLOCKED(key) then return false end
        _G.VX_INJ_KEYS=_G.VX_INJ_KEYS or {};_G.VX_INJ_KEYS[key]=tick()+0.4
        local ok=pcall(function()
            VIM:SendKeyEvent(false,key,false,game);VIM:SendKeyEvent(true,key,false,game)
            task.wait(0.04);VIM:SendKeyEvent(false,key,false,game)
        end)
        pcall(function() VIM:SendKeyEvent(false,key,false,game) end)
        return ok
    end
    local function react(target,track)
        if not on or busy or tick()-last<4 or _G.VX_COMBAT_OWNER then return end
        local p=Players:FindFirstChild(target.Name)
        if not p or p==me or not vessel() then return end
        busy=true;last=tick();local gen=generation
        task.spawn(function()
            local owner={};local ok,err=pcall(function()
                _G.VX_COMBAT_OWNER=owner
                local function live()
                    local h=target.Parent and target:FindFirstChildOfClass("Humanoid")
                    return on and generation==gen and target.Parent and h and h.Health>0 and track.IsPlaying
                        and not UIS:GetFocusedTextBox()
                end
                if not live() then return end
                if not rushAvailable() then
                    _G.VX_MEGUNA_STATUS="summon detected; requesting Vessel awakening"
                    if not press(Enum.KeyCode.G) then return end
                    local untilTime=tick()+1.5
                    while live() and not rushAvailable() and tick()<untilTime do task.wait(0.05) end
                end
                if not live() or not rushAvailable() then _G.VX_MEGUNA_STATUS="Rush unavailable while summon was active";return end
                local enemy=target:FindFirstChild("HumanoidRootPart")
                if not enemy then return end
                local dest=enemy.Position+enemy.CFrame.LookVector*3
                if not safeTeleport(CFrame.new(dest),0.2) or not live() then _G.VX_MEGUNA_STATUS="approach failed or summon ended";return end
                local c=ownModel();local r=c and c:FindFirstChild("HumanoidRootPart")
                enemy=target:FindFirstChild("HumanoidRootPart")
                if not r or not enemy or (r.Position-enemy.Position).Magnitude>8 then _G.VX_MEGUNA_STATUS="target out of range";return end
                local look=Vector3.new(enemy.Position.X,r.Position.Y,enemy.Position.Z)
                if (look-r.Position).Magnitude>0.1 then r.CFrame=CFrame.lookAt(r.Position,look) end
                local camera=workspace.CurrentCamera
                if camera then camera.CFrame=CFrame.lookAt(camera.CFrame.Position,enemy.Position) end
                _G.VX_MEGUNA_STATUS=press(Enum.KeyCode.Three) and "Rush requested; transformation unconfirmed" or "Rush input blocked"
            end)
            if _G.VX_COMBAT_OWNER==owner then _G.VX_COMBAT_OWNER=nil end
            busy=false
            if not ok then warn("[DreamHub Meguna] "..tostring(err)) end
        end)
    end
    local function notifySummon(char)
        if not notifyOn or tick()-(notified[char] or -math.huge)<8 then return end
        local player=char==ownModel() and me or Players:FindFirstChild(char.Name)
        if not player then return end
        notified[char]=tick()
        local callback=Instance.new("BindableFunction")
        callback.OnInvoke=function(choice)
            if choice=="Teleport" and player~=me and notifyOn and player.Parent and _G.VX_TP_TO_PLAYER then
                task.spawn(function() _G.VX_TP_TO_PLAYER(player) end)
            end
            callback:Destroy()
        end
        local ok=pcall(function()
            local payload={Title="Summoning Mahoraga",Duration=8,Callback=callback}
            if player==me then payload.Text="You are summoning Mahoraga.";payload.Button1="OK"
            else payload.Text=player.Name.." is summoning Mahoraga. Teleport?";payload.Button1="Teleport";payload.Button2="No" end
            game:GetService("StarterGui"):SetCore("SendNotification",payload)
        end)
        if not ok then
            callback:Destroy()
            pcall(function()
                if _G.VX_MAHO_NOTICE_GUI then _G.VX_MAHO_NOTICE_GUI:Destroy() end
                local screen=Instance.new("ScreenGui");screen.Name="VX_MahoragaNotice";screen.ResetOnSpawn=false;screen.DisplayOrder=9900
                pcall(function() screen.Parent=(gethui and gethui()) or game:GetService("CoreGui") end)
                if not screen.Parent then screen.Parent=me:WaitForChild("PlayerGui") end
                _G.VX_MAHO_NOTICE_GUI=screen
                local box=Instance.new("Frame");box.Size=UDim2.fromOffset(300,115);box.Position=UDim2.new(1,-315,0,80)
                box.BackgroundColor3=Color3.fromRGB(20,20,25);box.Parent=screen
                local title=Instance.new("TextLabel");title.Size=UDim2.new(1,-16,0,40);title.Position=UDim2.fromOffset(8,8)
                title.BackgroundTransparency=1;title.TextColor3=Color3.new(1,1,1);title.TextWrapped=true
                title.Font=Enum.Font.GothamBold;title.TextSize=14
                title.Text=player==me and "You are summoning Mahoraga." or (player.Name.." is summoning Mahoraga. Teleport?");title.Parent=box
                local function button(text,x,accept)
                    local b=Instance.new("TextButton");b.Size=UDim2.fromOffset(125,34);b.Position=UDim2.fromOffset(x,65)
                    b.BackgroundColor3=Color3.fromRGB(80,55,110);b.TextColor3=Color3.new(1,1,1);b.Font=Enum.Font.GothamBold;b.TextSize=14;b.Text=text;b.Parent=box
                    b.Activated:Connect(function()
                        if accept and player~=me and notifyOn and player.Parent and _G.VX_TP_TO_PLAYER then
                            task.spawn(function() _G.VX_TP_TO_PLAYER(player) end)
                        end
                        if _G.VX_MAHO_NOTICE_GUI==screen then _G.VX_MAHO_NOTICE_GUI=nil end
                        screen:Destroy()
                    end)
                end
                if player==me then button("OK",88,false) else button("Teleport",16,true);button("No",159,false) end
                task.delay(10,function() if _G.VX_MAHO_NOTICE_GUI==screen then _G.VX_MAHO_NOTICE_GUI=nil end;pcall(function() screen:Destroy() end) end)
            end)
        end
        task.delay(10,function() pcall(function() callback:Destroy() end) end)
    end
    local function hook(char)
        if not char then return end
        local mine=char==ownModel() or char==me.Character or char.Name==me.Name
        if not mine and not Players:FindFirstChild(char.Name) then return end
        local h=char:FindFirstChildOfClass("Humanoid")
        local a=h and h:FindFirstChildOfClass("Animator")
        if a and not hooked[a] then
            hooked[a]=a.AnimationPlayed:Connect(function(track)
                local anim=track and track.Animation
                if anim and tostring(anim.AnimationId):match("%d+")=="127843796051633" then
                    if notifyOn then notifySummon(char) end
                    if on and not mine then react(char,track) end
                end
            end)
        end
    end
    local function scanSummoners()
        local folder=workspace:FindFirstChild("Characters")
        if folder then for _,c in ipairs(folder:GetChildren()) do hook(c) end end
        for _,p in ipairs(Players:GetPlayers()) do if p~=me or notifyOn then hook(p.Character) end end
        if notifyOn then hook(ownModel()) end
    end
    -- The game's summon chant is another observed signal if an animator is
    -- not streamed in. It carries a player identity; do not guess an owner.
    local chantHooked=setmetatable({}, {__mode="k"})
    local function summonChant(player,message)
        if not notifyOn or not player or not tostring(message):lower():find("with this treasure",1,true) then return end
        local folder=workspace:FindFirstChild("Characters")
        local body=(folder and folder:FindFirstChild(player.Name)) or player.Character
        if body then notifySummon(body) end
    end
    local function hookChant(player)
        if not player or chantHooked[player] then return end
        pcall(function() chantHooked[player]=player.Chatted:Connect(function(message) summonChant(player,message) end) end)
    end
    for _,player in ipairs(Players:GetPlayers()) do hookChant(player) end
    pcall(function() Players.PlayerAdded:Connect(hookChant) end)
    pcall(function()
        game:GetService("TextChatService").MessageReceived:Connect(function(message)
            local source=message and message.TextSource
            local player=source and Players:GetPlayerByUserId(source.UserId)
            if player then summonChant(player,message.Text) end
        end)
    end)
    -- Subscribe immediately when enabled and as animators stream in; retain the
    -- periodic scan for characters that construct their animator a little later.
    workspace.DescendantAdded:Connect(function(d)
        if (on or notifyOn) and d:IsA("Animator") and d.Parent and d.Parent.Parent then hook(d.Parent.Parent) end
    end)
    task.spawn(function()
        while true do if on or notifyOn then scanSummoners() end; task.wait(0.20) end
    end)
    _G.VX_AUTO_MEGUNA={set=function(v)
        on=v==true;generation+=1
        if on then scanSummoners() end
    end,notify=function(v)
        notifyOn=v==true
        if notifyOn then scanSummoners()
        elseif _G.VX_MAHO_NOTICE_GUI then pcall(function() _G.VX_MAHO_NOTICE_GUI:Destroy() end);_G.VX_MAHO_NOTICE_GUI=nil end
    end}
end

-- Halloween pumpkin-holder tools: only characters with a direct Pumpkin child qualify.
do
    if _G.VX_PUMPKIN and _G.VX_PUMPKIN.destroy then pcall(_G.VX_PUMPKIN.destroy) end
    local Players=game:GetService("Players")
    local UIS=game:GetService("UserInputService")
    local VIM=game:GetService("VirtualInputManager")
    local LP=Players.LocalPlayer
    _G.VX_HOLIDAY_DISTANCE=true
    local active,espOn,viewOn,farmOn,beamOn=true,false,false,false,false
