        for _,c in ipairs(list) do
            local r=c:FindFirstChild("HumanoidRootPart")
            if c~=body and c.Name~=LP.Name and r and (chosen=="Nearest" or c.Name==chosen) then
                local d=root and (r.Position-root.Position).Magnitude or math.huge
                if not dist or d<dist then best,dist=c,d end
            end
        end
        return best,dist
    end
