                local part=c:FindFirstChild("Head") or c:FindFirstChild("HumanoidRootPart")
                if part then
                    local bb=Instance.new("BillboardGui");bb.Name="Pumpkin Holder";bb.Adornee=part
                    bb.Size=UDim2.fromOffset(150,30);bb.StudsOffset=Vector3.new(0,3,0);bb.AlwaysOnTop=true;bb.Parent=layer
                    local lbl=Instance.new("TextLabel");lbl.BackgroundTransparency=1;lbl.Size=UDim2.fromScale(1,1)
                    lbl.Font=Enum.Font.GothamBold;lbl.TextSize=14;lbl.TextStrokeTransparency=0.35;lbl.TextColor3=tint
                    lbl.Text="🎃 "..c.Name;lbl.Parent=bb;markers[c]=bb
                end
