            if espOn and markers[c] then
                local lbl=markers[c]:FindFirstChildOfClass("TextLabel")
                local body=vxMyChar();local own=body and body:FindFirstChild("HumanoidRootPart")
                local other=c:FindFirstChild("HumanoidRootPart")
