                for c in pairs(keep) do if b:IsDescendantOf(c) then retained=true;break end end
                if not retained then pcall(function() b.Color=original end);beams[b]=nil end
            end
        elseif next(beams) then restoreBeams() end
        if viewOn then
            local c=target(list);local h=c and c:FindFirstChildOfClass("Humanoid");local cam=workspace.CurrentCamera
            if cam and h then
                if not oldSubject then oldSubject=cam.CameraSubject end
                cam.CameraSubject=h;viewSubject=h
