-- The user observed workspace.Effects.HalloweenDoor, with multiple same-named models.
do
    if _G.VX_HALLOWEEN_DOORS and _G.VX_HALLOWEEN_DOORS.destroy then pcall(_G.VX_HALLOWEEN_DOORS.destroy) end
    local LP=game:GetService("Players").LocalPlayer
    local active,on=true,false
    local entries={}
    local layer=Instance.new("Folder");layer.Name="VX_HalloweenDoorESP"
    pcall(function() layer.Parent=(gethui and gethui()) or game:GetService("CoreGui") end)
    if not layer.Parent then layer.Parent=LP:WaitForChild("PlayerGui") end
    local function doorPart(door)
        local candidate=door:FindFirstChild("Door",true)
        if candidate and candidate:IsA("BasePart") then return candidate end
        if candidate then local p=candidate:FindFirstChildWhichIsA("BasePart",true);if p then return p end end
        return door:IsA("BasePart") and door or door:FindFirstChildWhichIsA("BasePart",true)
    end
    local function doors()
        local effects=workspace:FindFirstChild("Effects");local found={}
        if effects then for _,d in ipairs(effects:GetChildren()) do
            if d.Name=="HalloweenDoor" and doorPart(d) then found[#found+1]=d end
        end end
        return found
    end
    local function clear()
        for _,e in pairs(entries) do if e.label then e.label:Destroy() end;if e.mark then e.mark:Destroy() end end;table.clear(entries)
    end
    local function nearest()
        local c=vxMyChar();local root=c and c:FindFirstChild("HumanoidRootPart");if not root then return end
        local best,bd
        for _,d in ipairs(doors()) do local p=doorPart(d);local dist=(p.Position-root.Position).Magnitude
            if not bd or dist<bd then best,bd=p,dist end
        end
        return best
    end
    task.spawn(function()
        while active do
            if on then pcall(function()
                local found={}
                for _,d in ipairs(doors()) do
                    found[d]=true
                    if not entries[d] then
                        local part=doorPart(d)
                        local bb=Instance.new("BillboardGui");bb.Name="Halloween Door";bb.Adornee=part;bb.Size=UDim2.fromOffset(145,24)
                        bb.StudsOffset=Vector3.new(0,2,0);bb.AlwaysOnTop=true;bb.Parent=layer
                        local label=Instance.new("TextLabel");label.BackgroundTransparency=1;label.Size=UDim2.fromScale(1,1)
                        label.Font=Enum.Font.GothamBold;label.TextSize=14;label.TextColor3=Color3.fromRGB(255,155,40);label.TextStrokeTransparency=0.3;label.Text="Halloween Door";label.Parent=bb
                        local hl=Instance.new("Highlight");hl.Adornee=d;hl.FillTransparency=0.8;hl.OutlineColor=Color3.fromRGB(255,145,35);hl.Parent=layer
                        entries[d]={label=bb,mark=hl,text=label,part=part}
                    end
                    local entry=entries[d];local body=vxMyChar();local root=body and body:FindFirstChild("HumanoidRootPart")
                    if entry and entry.text then
                        entry.text.Text="Halloween Door"..((_G.VX_HOLIDAY_DISTANCE and root and entry.part) and ("  "..math.floor((entry.part.Position-root.Position).Magnitude).." studs") or "")
                    end
                end
                for d,e in pairs(entries) do if not found[d] then e.label:Destroy();e.mark:Destroy();entries[d]=nil end end
            end) elseif next(entries) then clear() end
            task.wait(0.4)
        end
    end)
    _G.VX_HALLOWEEN_DOORS={
        set=function(v) on=v==true;if not on then clear() end end,
        teleport=function()
            local p=nearest();if not p then if VX_NOTIFY then VX_NOTIFY("No Halloween door found",false) end;return false end
            return vxGlide(p.Position+p.CFrame.LookVector*3+Vector3.new(0,2,0))
        end,
        destroy=function() active=false;on=false;clear();layer:Destroy() end,
    }
end

-- GUI  (VAULTIX v3.1 - samet / joestar._3 "esdeeeeee" library, EXACT; per-tier accent)
-- library credit: samet (joestar._3 on discord) https://discord.gg/VhvTd5HV8d
-- ============================================================
-- TIERS: free (trimmed) < premium (VIP) < plus (top). The Free loadstring sets _G.JJS_FREE=true; the Plus
-- loadstring sets _G.JJS_PLUS=true and unlocks everything premium has PLUS the plus-only extras.
-- TIER PRECEDENCE — order matters. `_G` PERSISTS between executions in most executors, so once you have run the
-- FREE loadstring in a session, `_G.JJS_FREE` stays true forever. With FREE tested first, a later PLUS run still
-- resolved to "free", which silently removed every premium-gated feature — including the Auto Air toggle, the
-- ONLY thing that can turn Auto Air on. That is why Auto Air "did not work" no matter what was fixed inside it.
-- An explicitly requested higher tier now wins, and we clear the stale lower flags so nothing can resurrect them.
-- Derived from the ONE tier resolved (and consumed) at the top of the file, so it always matches the flag you
-- set for this run. "full" (no flag at all) keeps the historical everything-unlocked behaviour.
-- ═══ "full" MUST OUTRANK "plus" ═══ This line used to map full -> "premium" (rank 2), and the rank
-- helper puts plus at 3. So a direct/dev load - YOUR load - failed every tier("plus") check: the Upper Cut
-- and Down Slam Assist toggles were never BUILT, on your screen specifically, while the label right where
-- they should be said "...are PLUS". That is the whole of "downslam/upper cut assi dont even work": the
-- module was fine, its switches did not exist. full is now its own rank above plus.
