    autoUpperToggle=acSec:Toggle({ Name = "Auto Upper Cut", Default = false, Callback = function(b) if b and autoSlamToggle and autoSlamToggle:Get() then autoSlamToggle:Set(false) end; if M1ComboApi and M1ComboApi.setUpper then M1ComboApi.setUpper(b) end; if FinisherAssistApi then FinisherAssistApi.setAutoUpper(b) end end })
    -- FINISHER ASSIST - PLUS only, as asked. Watches for a DOWNED enemy and punishes them: in reach it sends
    -- the finisher straight away, out of reach it side dashes in, throws three M1s and finishes on the fourth.
    -- tier("plus") not VX_TIER == "plus": a direct load of the dev file has tier key "full", which outranks
    -- plus but is not EQUAL to it - so the == test built neither toggle and the assists could not be turned
    -- on at all. The rank helper says full >= plus, which is what was meant.
    -- Upper Cut / Down Slam / Cursed Strike Assist moved to the Assistant tab.
    if unreleased() then
        -- ═══ AUTO CANCEL ═══ Pick the character and tick the slots you keep misclicking. While it is on those
        -- keys fire nothing: the cast is stopped in the hook before it reaches the server, so the move is not
        -- spent and does not go on cooldown. "Any" cancels on every character; naming one means the block
        -- switches itself off the moment you swap away from it.
        local cnSec = autoSub:Section({ Name = "Auto Cancel", Side = 2 })
        cnSec:Label("Only the selected keyboard keys are blocked. Clear a key to allow it again.")
        local cnNames = { "Any" }
        pcall(function() if CharSwapApi then for _, n in ipairs(CharSwapApi.names()) do if n ~= "Any" then cnNames[#cnNames + 1] = n end end end end)
        cnSec:Dropdown({ Name = "Cancel On Character", Items = cnNames, Default = cnNames[1], Callback = function(v) if AutoCancelApi then AutoCancelApi.setChar(v) end end })
        for i = 1, 4 do
            cnSec:Toggle({ Name = "Block Key " .. i, Default = false, Callback = function(b) if AutoCancelApi then AutoCancelApi.setSlot(i, b) end end })
        end
    end
    if unreleased() then   -- ═══ EVERYTHING BELOW THIS LINE (to the matching end) IS STILL IN TESTING ═══
    -- Twofold Kick Assist and Soul Combo moved to the Assistant tab.
    -- DOMAIN SAVIOR: pick a username; when a domain is about to swallow them, your grab pulls them out.
    -- Works as Megumi (Toad), Gojo (Lapse Blue) or Mahito/Essence (Body Disfigure).
    antiSec:Toggle({ Name = "Domain Savior (grab them out)", Default = false, Callback = function(b) if DomainSaviorApi then DomainSaviorApi.set(b) end end })
    -- "add the supported characters below to make it work" - the list only existed as a code comment, so
    -- there was no way to know from in-game which characters can actually perform the save.
    pcall(function() acSec:Label("Works as: Megumi (Toad) · Gojo (Lapse Blue) · Mahito/Essence (Body Disfigure)") end)
    do  -- dropdown instead of typing, with the training Dummy included
        local function saviorList()
            local out = {}
            for _, plr in ipairs(game:GetService("Players"):GetPlayers()) do
                if plr ~= game:GetService("Players").LocalPlayer then out[#out + 1] = plr.Name end
            end
            local chs = workspace:FindFirstChild("Characters")
            if chs then for _, m in ipairs(chs:GetChildren()) do
                if not game:GetService("Players"):FindFirstChild(m.Name) and m:FindFirstChild("HumanoidRootPart") then out[#out + 1] = m.Name end
            end end
            table.sort(out)
            if #out == 0 then out = { "Dummy" } end
            return out
        end
        local dd = acSec:Dropdown({ Name = "Savior: Who To Save", Items = saviorList(), Default = "", Callback = function(v)
            v = (type(v) == "table") and v[1] or v
            if DomainSaviorApi and type(v) == "string" then DomainSaviorApi.setName(v) end
        end })
        acSec:Button({ Name = "Refresh Savior List", Callback = function()
            pcall(function() if dd and dd.Refresh then dd:Refresh(saviorList()) end end)
        end })
    end
