    acSec:Toggle({ Name = "Auto Play Flight Game", Default = false, Callback = function(b) if FlightGameApi then FlightGameApi.set(b) end end })
    acSec:Slider({ Name = "Flight Flap Rate", Min = 0.15, Max = 1.2, Default = 0.42, Decimals = 0.01, Suffix = "s", Callback = function(v) if FlightGameApi then FlightGameApi.setRate(v) end end })
    -- AUTO THROWABLE: walk near a trash can / grave / arcade prop and it picks it up. Works on every
    -- throwable the map has - the remote takes the prop instance, so nothing is hardcoded to "Trash".
    acSec:Toggle({ Name = "Auto Throwable (pick up on walk-up)", Default = false, Callback = function(b) if ThrowableApi then ThrowableApi.set(b) end end })
    acSec:Slider({ Name = "Throwable Range", Min = 4, Max = 60, Default = 14, Decimals = 1, Callback = function(v) if ThrowableApi then ThrowableApi.setRange(v) end end })
    acSec:Button({ Name = "Grab Throwable Now", Callback = function() if ThrowableApi then ThrowableApi.grabNow() end end })
    acSec:Slider({ Name = "Hakari Rate", Min = 0.5, Max = 10, Default = 3, Decimals = 0.1, Suffix = "s", Callback = function(v) if HakariApi then HakariApi.setRate(v) end end })
    -- ═══ NO "AUTO AIR" MASTER TOGGLE ANY MORE ═══ Each of these is its own switch and does its own thing the
    -- moment you turn it on - there is no second switch above them to find first, and the label is gone.
    -- They are also no longer premium-only: the whole point is that using one does what it says.
    _G.VX_AIR_NEEDENEMY = false   -- the enemy-presence gate was the reason these kept doing nothing; off by default
    do
        for _, o in ipairs({
            { "Vessel",    "Vessel 1" },
            { "Twofold",   "Gojo 4" },
            { "LapseBlue", "Gojo 1" },
            -- (Gojo 2 / Gojo 1 2 REMOVED per round 6: "there should only be two Gojos: Gojo 1 and Gojo 4")
            { "Megumi", "Megumi 2" },
            { "MegumiRabbit", "Megumi R" },
            { "Hakari",    "Hakari 3" },
            { "Choso",     "Choso 2" },
        }) do
            acSec:Toggle({ Name = o[2], Default = false, Callback = function(b) if AutoAirOptSet then AutoAirOptSet(o[1], b) end end })
        end
        -- The universal path: any character, any moveset. Press 1/2/4 and it jumps and casts that slot.
        -- (3 is left alone while a flash mode is armed - it is the Black Flash input.)
        -- The hook version: your key press is blocked and re-sent with the airborne flag. Works on every
        -- character and every move, because the game itself supplies the move object and the service.
        acSec:Toggle({Name="Auto Air",Default=false,Callback=function(v) if _G.VX_AUTOAIR_ALL then _G.VX_AUTOAIR_ALL.set(v) end end})
        acSec:Label("Auto Air jumps and aims at your selected target or a nearby target ahead before 1, 2, 3 or 4. Turn it off to use slot-3 BF chains.")
        acSec:Toggle({Name="Air Cast Power",Default=false,Callback=function(v) _G.VX_AIR_POWER_ON=v==true end})
        -- Scales the launch the air cast gives you. 100% is a normal jump; higher throws you further up so a
        -- move that needs real height has it. It only touches the jump, never the move itself.
        _G.VX_AIR_POWER = 100
        acSec:Slider({ Name = "Air Cast Power %", Min = 50, Max = 300, Default = 100, Decimals = 1, Suffix = "%", Callback = function(v) _G.VX_AIR_POWER = math.clamp(tonumber(v) or 100, 25, 400) end })
    end
    end   -- ═══ end of the unreleased() block ═══
    -- (The "Uppercut Key" / "Uppercut On M1 #" dropdowns are gone - you asked for it to just work. The module
