    _G.VX_UPPER_KEY = Enum.KeyCode.Space
    -- "Slam / Uppercut on M1 #" dropdown REMOVED - it is automatic now (see the note in onSwing).
    -- (Removed the "Launcher after N hits" slider — the mechanic is now the FIXED real game rule per the wiki:
    -- Uppercut = 4 M1s with Space held, Down Slam = 3 M1s then jump+M1. No slider needed or accurate anymore.)
    if tier("premium") then antiSec:Toggle({ Name = "Auto Adapt", Callback = function(b) if AutoAdaptApi then AutoAdaptApi.set(b) end end }) end   -- FREE: no Auto Adapt (Auto Domain Adapt below is kept)
    antiSec:Toggle({ Name = "Auto Domain Adapt", Callback = function(b) if AutoDomainAdaptApi then AutoDomainAdaptApi.set(b) end end })
    acSec:Toggle({ Name = "Auto Earthquake", Callback = function(b) if AutoQuakeApi then AutoQuakeApi.set(b) end end })
    if _G.JJS_FREE then pcall(function() acSec:Label("Earthquake: turn on, then press 3 — it is held for you") end) end
    acSec:Slider({ Name = "Quake Hold", Min = 0.3, Max = 3, Default = 2, Decimals = 0.01, Suffix = "s", Callback = function(v) _G.VX_QUAKE_HOLD = tonumber(v) or 2 end })
    acSec:Toggle({ Name = "Quake Debug (print)", Default = false, Callback = function(b) _G.VX_QUAKE_DEBUG = (b == true) end })   -- prints one line per tap so you can confirm the hold + whether the windup was seen
    if not _G.JJS_FREE then acSec:Slider({ Name = "Quake Range", Min = 15, Max = 150, Default = 60, Decimals = 1, Suffix = "st", Callback = function(v) _G.VX_QUAKE_RANGE = tonumber(v) or 60 end }) end
    acSec:Toggle({ Name = "Auto Kill Emote", Callback = function(b) if KillEmoteApi then KillEmoteApi.set(b) end end })
    local keItems = {}   -- slot list with REAL emote names read from PlayerGui.Emotes.Emote.Page1/Page2 (the 'nan' slider is gone)
    for i = 1, 16 do
        local nm
        pcall(function()
            local pg = LocalPlayer:FindFirstChild("PlayerGui"); local em = pg and pg:FindFirstChild("Emotes"); em = em and em:FindFirstChild("Emote")
            for _, page in ipairs({ "Page1", "Page2" }) do
                local p = em and em:FindFirstChild(page); local b = p and p:FindFirstChild(tostring(i)); local t = b and b:FindFirstChild("EmoteName")
                if t and t:IsA("TextLabel") and t.Text ~= "" and t.Text ~= "EmoteName" then nm = t.Text end
            end
        end)
        keItems[i] = nm and (i .. " - " .. nm) or tostring(i)
    end
    acSec:Dropdown({ Name = "Kill-Emote Slot", Items = keItems, Default = keItems[1], Callback = function(v)
        local n = tonumber(tostring(v):match("^%d+")); if KillEmoteApi and n then KillEmoteApi.setSlot(n) end
    end })
    local askSec = autoSub:Section({ Name = "Auto Skills", Side = 2 })
    askSec:Toggle({ Name = "Auto Skills", Callback = function(b) if SkillsApi then SkillsApi.setEnabled(b) end end })
    askSec:Toggle({ Name = "Skill 1", Callback = function(b) if SkillsApi then SkillsApi.setKey(1, b) end end })
    askSec:Toggle({ Name = "Skill 2", Callback = function(b) if SkillsApi then SkillsApi.setKey(2, b) end end })
    askSec:Toggle({ Name = "Skill 3", Callback = function(b) if SkillsApi then SkillsApi.setKey(3, b) end end })
    askSec:Toggle({ Name = "Skill 4", Callback = function(b) if SkillsApi then SkillsApi.setKey(4, b) end end })
    askSec:Toggle({ Name = "Special R", Callback = function(b) if SkillsApi then SkillsApi.setKey(5, b) end end })
    askSec:Toggle({ Name = "Awakening G", Callback = function(b) if SkillsApi then SkillsApi.setKey(6, b) end end })
    if unreleased() then
    local charSec = autoSub:Section({ Name = "Character", Side = 2 })
    do
        -- ═══ THIS FLAG MUST BE LEXICAL, NOT GLOBAL ═══ It guards a one-click switch that KILLS you, and this
        -- UI library fires a dropdown's callback once while constructing it. As a bare global it would survive
        -- into the next execution of the hub, so re-injecting mid-fight would find a minutes-old timestamp,
        -- decide the guard had expired, and force reset you while the menu was still building. A local is nil
        -- on every fresh run, which is exactly the behaviour the guard is for.
        local uiReady = nil
        local names = { "Gojo" }
        pcall(function() if CharSwapApi then names = CharSwapApi.names() end end)
        if #names == 0 then names = { "Gojo" } end
        charSec:Toggle({ Name = "Auto Character On Death", Default = false, Callback = function(b) if CharSwapApi then CharSwapApi.setDeath(b) end end })
        local deathDD = charSec:Dropdown({ Name = "Character On Death", Items = names, Default = names[1], Callback = function(v) if CharSwapApi then CharSwapApi.setDeathChar(v) end end })
        pcall(function() if CharSwapApi then CharSwapApi.setDeathChar(names[1]) end end)   -- the UI lib does not always fire the build-time callback
        local pick = names[1]
        local switchDD = charSec:Dropdown({ Name = "Switch To", Items = names, Default = names[1], Callback = function(v)
            v = (type(v) == "table") and v[1] or v
            if type(v) ~= "string" then return end
            pick = v
            -- One-click switch, as asked - but NEVER during the first few seconds. Several UI libs fire a
            -- dropdown's callback once while building it, and without this guard simply opening the hub would
            -- force reset you on the spot.
            if uiReady and tick() - uiReady > 3 and CharSwapApi then CharSwapApi.switchNow(v) end
        end })
        charSec:Button({ Name = "Switch Now (force reset)", Callback = function() if CharSwapApi then CharSwapApi.switchNow(pick) end end })
        charSec:Button({ Name = "Refresh Character List", Callback = function()
            local fresh = (CharSwapApi and CharSwapApi.names()) or names
            if #fresh == 0 then return end
            names = fresh
            -- Refresh re-applies the default on some UI backends, which would re-enter the switch callback.
            -- Close the window for a beat so a list refresh can never reset you.
            uiReady = tick()
            pcall(function() if deathDD and deathDD.Refresh then deathDD:Refresh(fresh) end end)
            pcall(function() if switchDD and switchDD.Refresh then switchDD:Refresh(fresh) end end)
            if VX_NOTIFY then VX_NOTIFY("Characters: " .. #fresh .. " found", true) end
        end })
        uiReady = tick()   -- everything above is built; the one-click switch is armed 3s from now
    end
    end   -- end unreleased() (Character section)

    local auSec = autoSub:Section({ Name = "Auto Utility", Side = 2 })
