    antiSec:Slider({ Name = "Click Delay", Min = 0, Max = 100, Default = 0, Decimals = 1, Callback = function(v) if AutoQTEApi then AutoQTEApi.setDelay(v) end end })
    antiSec:Slider({ Name = "QTE Speed (presses/sec)", Min = 5, Max = 120, Default = 45, Decimals = 1, Callback = function(v) if AutoQTEApi then AutoQTEApi.setSpeed(v) end end })
    antiSec:Slider({ Name = "QTE Click Gap (ms)", Min = 0, Max = 100, Default = 20, Decimals = 1, Callback = function(v) if AutoQTEApi then AutoQTEApi.setTapGap(v) end end })
    antiSec:Toggle({ Name = "Anti Final Judgment", Callback = function(b) if AutoQTEApi_setAnti then AutoQTEApi_setAnti(b) end end })
